def hash_password(pw):
    salt = os.urandom(32)
    return salt.hex() + ":" + hashlib.pbkdf2_hmac("sha256", pw.encode(), salt, 100000).hex()


def verify_password(stored, given):
    try:
        if ":" not in stored:  # legacy plain text
            return stored == given
        s, h = stored.split(":")
        return hashlib.pbkdf2_hmac("sha256", given.encode(), bytes.fromhex(s), 100000).hex() == h
    except Exception:
        return False


def verify_manager_password(pw):
    if not pw:
        return False
    r = q("SELECT password FROM users WHERE role='Store Manager'")
    return verify_password(r[0]["password"], pw) if r else pw == "windy123"


def audit(action, details):
    run("INSERT INTO audit_logs (timestamp, username, action_type, details) VALUES (%s,%s,%s,%s)",
        (datetime.now().strftime("%Y-%m-%d %H:%M:%S"), st.session_state.get("user") or "SYSTEM", action, details))


@tx
def log_event(action, details):
    audit(action, details)


def done(msg):
    """Success message survives the rerun, so the screen refreshes cleanly."""
    st.session_state["flash"] = msg
    st.rerun()


def show_flash():
    msg = st.session_state.pop("flash", None)
    if msg:
        try:
            st.toast(msg, icon="✅")
        except Exception:
            st.success(msg)


def mgr_check(key):
    pw = st.text_input("🔐 Store Manager password", type="password", key=key)
    ok = bool(pw) and verify_manager_password(pw)
    if pw and not ok:
        st.caption("❌ Password vul")
    return ok


def confirm_box(key, text="⚠️ Ami confirm korchi - ei record permanently delete hobe."):
    """Explicit tick required before any destructive action."""
    return st.checkbox(text, key=key)


USERNAME_RE = re.compile(r"[A-Za-z0-9_.\-]{3,30}")


@tx
def register_user(username, full_name, pw, role="Store Officer"):
    """New accounts stay Pending until the Store Manager approves them (and may change the role there)."""
    role = role if role in set(REG_ROLE_CHOICES.values()) else "Store Officer"
    if q("SELECT 1 AS x FROM users WHERE LOWER(username)=LOWER(%s)", (username,)):
        st.error("Ei username already ache. Onno username din.")
        return False
    run("INSERT INTO users (username, password, role, full_name, status, created_at) VALUES (%s,%s,%s,%s,'Pending',%s)",
        (username, hash_password(pw), role, full_name, datetime.now().strftime("%Y-%m-%d %H:%M:%S")))
    audit("REGISTER_REQUEST", f"Registration request: {username} ({full_name}) as {role}")
    return True


@tx
def request_password_reset(username):
    """Queues a reset request for the Store Manager. Nothing is revealed about whether the user exists."""
    r = q("SELECT username FROM users WHERE LOWER(username)=LOWER(%s) AND COALESCE(status,'Active')='Active'", (username,))
    if r:
        uname = r[0]["username"]
        if not q("SELECT 1 AS x FROM password_resets WHERE username=%s AND status='Pending'", (uname,)):
            run("INSERT INTO password_resets (username, requested_at, status) VALUES (%s,%s,'Pending')",
                (uname, datetime.now().strftime("%Y-%m-%d %H:%M:%S")))
            audit("PASSWORD_RESET_REQUEST", f"Reset requested for {uname}")
    return True


@tx
def approve_user(uid, role, uname):
    run("UPDATE users SET status='Active', role=%s WHERE id=%s AND COALESCE(status,'Active')='Pending'", (role, uid))
    audit("APPROVE_USER", f"{uname} approved as {role}")
    return True


@tx
def reject_user(uid, uname):
    run("DELETE FROM users WHERE id=%s AND COALESCE(status,'Active')='Pending'", (uid,))
    audit("REJECT_USER", f"Registration of {uname} rejected")
    return True


@tx
def set_temp_password(rid, uname, new_pw):
    run("UPDATE users SET password=%s WHERE username=%s", (hash_password(new_pw), uname))
    run("UPDATE password_resets SET status='Done', handled_by=%s, handled_at=%s WHERE id=%s",
        (st.session_state.get("user", ""), datetime.now().strftime("%Y-%m-%d %H:%M:%S"), rid))
    audit("PASSWORD_RESET_DONE", f"Temporary password set for {uname}")
    return True


@tx
def change_password(uname, new_pw):
    run("UPDATE users SET password=%s WHERE username=%s", (hash_password(new_pw), uname))
    audit("PASSWORD_CHANGED", f"{uname} changed own password")
    return True


def user_admin_panel():
    """Store Manager only: approve registrations and answer password-reset requests."""
    pend = q_c("SELECT id, username, full_name, role FROM users WHERE COALESCE(status,'Active')='Pending' ORDER BY id")
    resets = q_c("SELECT id, username, requested_at FROM password_resets WHERE status='Pending' ORDER BY id")
    with st.expander(f"👥 User Admin ({len(pend) + len(resets)} pending)"):
        st.markdown("**New registrations**")
        if not pend:
            st.caption("Pending registration nei.")
        else:
            labels = {f"{r['username']} - {r['full_name']}": r for r in pend}
            sel = labels[st.selectbox("Registration request", list(labels), key="ua_reg_sel")]
            _ro = ["Store Officer", "Auditor", "Maintenance", "Admin", "Accounts"]
            role = st.selectbox("Assign role (Auditor = Audit; Maintenance / Admin / Accounts / Auditor shudhu dekhte parbe)", _ro,
                                index=_ro.index(sel["role"]) if sel.get("role") in _ro else 0, key=f"ua_reg_role_{sel['id']}")
            c1, c2 = st.columns(2)
            if c1.button("✔ Approve", key="ua_reg_ok"):
                if approve_user(sel["id"], role, sel["username"]):
                    done(f"{sel['username']} approved as {role}.")
            if c2.button("✖ Reject", key="ua_reg_no"):
                if reject_user(sel["id"], sel["username"]):
                    done(f"{sel['username']} rejected.")
        st.markdown("**Password reset requests**")
        if not resets:
            st.caption("Pending reset request nei.")
        else:
            labels2 = {f"{r['username']} ({r['requested_at']})": r for r in resets}
            sel2 = labels2[st.selectbox("Reset request", list(labels2), key="ua_rs_sel")]
            np_ = st.text_input("New temporary password (min 8 chars)", type="password", key="ua_rs_pw")
            if st.button("Set temporary password", key="ua_rs_btn"):
                if len(np_) < 8:
                    st.error("Password kom pokkhe 8 character hote hobe.")
                elif set_temp_password(sel2["id"], sel2["username"], np_):
                    done("Temporary password set. User-ke surakkhitovabe janan; login-er por password change korte bolun.")


# ---------- Stay logged in after a browser refresh ----------
# A browser refresh starts a brand-new Streamlit session, so st.session_state is empty. After a successful login a random
# token is stored (hashed) in the database and in a browser cookie; on refresh the cookie is checked and the login restored.
SESSION_COOKIE = "kcw_session"
SESSION_HOURS = 12


def _tok_hash(tok):
    return hashlib.sha256(tok.encode()).hexdigest()


def _cookie_token():
    try:
        return st.context.cookies.get(SESSION_COOKIE) or ""
    except Exception:   # Streamlit older than 1.37 has no st.context.cookies -> no auto re-login, nothing else changes
        return ""


@tx
def create_login_session(username):
    tok = secrets.token_urlsafe(32)
    now = datetime.now()
    run("DELETE FROM login_sessions WHERE expires_at < %s", (now.strftime("%Y-%m-%d %H:%M:%S"),))
    run("INSERT INTO login_sessions (token_hash, username, created_at, expires_at) VALUES (%s,%s,%s,%s)",
        (_tok_hash(tok), username, now.strftime("%Y-%m-%d %H:%M:%S"),
         (now + timedelta(hours=SESSION_HOURS)).strftime("%Y-%m-%d %H:%M:%S")))
    return tok


UNIT_LOCK_ROLES = ("Store Officer",)   # roles that must pick one unit after login; it stays locked until sign-out
# View-only roles: they can open every page and report but cannot add / edit / delete anything. Only Store Officer, Store Manager
# and Executive can write.  ("Auditor" is the old name of the Audit role.)
READ_ONLY_ROLES = ("Auditor", "Maintenance", "Admin", "Accounts")
NEW_RO_ROLES = ("Maintenance", "Admin", "Accounts")
_RO_TX_ALLOW = ("create_login_session", "save_session_factory", "end_login_session", "log_event", "change_password",
                "request_password_reset", "register_user")
REG_ROLE_CHOICES = {"Store Officer": "Store Officer", "Maintenance": "Maintenance", "Audit": "Auditor", "Admin": "Admin", "Accounts": "Accounts"}


@tx
def save_session_factory(fac):
    """Binds the chosen unit to this login session (survives a page reload through the session cookie)."""
    tok = st.session_state.get("_login_tok") or _cookie_token()
    if tok:
        run("ALTER TABLE login_sessions ADD COLUMN IF NOT EXISTS factory TEXT DEFAULT ''")
        run("UPDATE login_sessions SET factory=%s WHERE token_hash=%s", (fac, _tok_hash(tok)))
    return True


@tx
def end_login_session():
    for tok in {st.session_state.get("_login_tok") or "", _cookie_token()}:
        if tok:
            run("DELETE FROM login_sessions WHERE token_hash=%s", (_tok_hash(tok),))
    return True


def restore_login_from_cookie():
    """Runs at the start of every session: if nobody is logged in but a valid session cookie exists, log that user back in."""
    if st.session_state.get("user"):
        return
    tok = _cookie_token()
    if not tok:
        return
    try:
        r = q("""SELECT s.username, u.role, COALESCE(u.status,'Active') AS status
                 FROM login_sessions s JOIN users u ON u.username=s.username
                 WHERE s.token_hash=%s AND s.expires_at > %s""",
              (_tok_hash(tok), datetime.now().strftime("%Y-%m-%d %H:%M:%S")))
    except Exception:
        return
    if r and r[0]["status"] == "Active":
        st.session_state["user"] = r[0]["username"]
        st.session_state["role"] = r[0]["role"]
        st.session_state["_login_tok"] = tok
        if r[0]["role"] in UNIT_LOCK_ROLES:   # a reload must not release the unit lock
            try:
                f = q("SELECT COALESCE(factory,'') AS factory FROM login_sessions WHERE token_hash=%s", (_tok_hash(tok),))
                if f and f[0]["factory"] in FACTORIES:
                    st.session_state["locked_factory"] = f[0]["factory"]
            except Exception:
                pass


def render_session_cookie_js():
    """Writes (after login) or removes (after logout) the session cookie in the browser. Invisible, runs once."""
    tok = st.session_state.pop("_cookie_set", None)
    clear = st.session_state.pop("_cookie_clear", None)
    if tok:
        val, age = tok, SESSION_HOURS * 3600
    elif clear:
        val, age = "", 0
    else:
        return
    components.html(
        f"""<script>
        try {{
          const d = window.parent.document;
          const sec = window.parent.location.protocol === 'https:' ? '; Secure' : '';
          d.cookie = "{SESSION_COOKIE}={val}; path=/; max-age={age}; SameSite=Lax" + sec;
        }} catch (e) {{}}
        </script>""", height=0)


def render_login_control():
    """Compact top-bar account popover with Sign in, Register and Forgot password tabs."""
    logged_in = bool(st.session_state.get("user"))
    label = f"👤 {st.session_state.get('user', 'Account')}" if logged_in else "🔐 Secure Login"
    with st.popover(label, use_container_width=True):
        if logged_in:
            st.markdown(f"**{html_lib.escape(str(st.session_state.get('user', '')))}**")
            st.caption(html_lib.escape(str(st.session_state.get("role", ""))))
            if st.button("🚪 Sign out", key="top_logout_btn", use_container_width=True):
                log_event("LOGOUT", f"User {st.session_state['user']} logged out.")
                end_login_session()
                st.session_state.pop("user", None)
                st.session_state.pop("role", None)
                st.session_state.pop("locked_factory", None)   # unit lock ends with the login session
                st.session_state.pop("_login_tok", None)
                st.session_state.pop("_gate_pending", None)
                st.session_state["_cookie_clear"] = True
                done("Signed out successfully.")
            with st.expander("🔑 Change password"):
                with st.form("chg_pw_form", clear_on_submit=True):
                    cur_pw = st.text_input("Current password", type="password", key="cp_cur")
                    new_pw1 = st.text_input("New password (min 8 chars)", type="password", key="cp_new1")
                    new_pw2 = st.text_input("Confirm new password", type="password", key="cp_new2")
                    chg = st.form_submit_button("Update password", use_container_width=True)
                if chg:
                    row = q("SELECT password FROM users WHERE username=%s", (st.session_state["user"],))
                    if not row or not verify_password(row[0]["password"], cur_pw):
                        st.error("Current password is incorrect.")
                    elif len(new_pw1) < 8:
                        st.error("New password must be at least 8 characters.")
                    elif new_pw1 != new_pw2:
                        st.error("The passwords do not match.")
                    elif change_password(st.session_state["user"], new_pw1):
                        st.success("Password updated.")
            if st.session_state.get("role") == "Store Manager":
                user_admin_panel()
            return

        sign_in_tab, register_tab, forgot_tab = st.tabs(["Sign in", "Register", "Forgot password"])
        with sign_in_tab:
            st.caption("Use your approved account to access inventory operations.")
            with st.form("login_form", clear_on_submit=False):
                username = st.text_input("Username", placeholder="Enter your username", key="login_user")
                password = st.text_input("Password", type="password", placeholder="Enter your password", key="login_pass")
                submitted = st.form_submit_button("Sign in", use_container_width=True)
            if submitted:
                if not username.strip() or not password:
                    st.error("Enter both username and password.")
                else:
                    rows = q(
                        "SELECT password, role, COALESCE(status,'Active') AS status FROM users WHERE username=%s",
                        (username.strip(),)
                    )
                    if rows and verify_password(rows[0]["password"], password):
                        if rows[0]["status"] == "Pending":
                            st.warning("Your account is waiting for manager approval.")
                        elif rows[0]["status"] != "Active":
                            st.error("This account is not active. Contact the Store Manager.")
                        else:
                            st.session_state["user"] = username.strip()
                            st.session_state["role"] = rows[0]["role"]
                            st.session_state.pop("locked_factory", None)   # every new login must choose its unit
                            st.session_state.pop("_gate_pending", None)
                            token = create_login_session(username.strip())
                            if token:
                                st.session_state["_cookie_set"] = token
                                st.session_state["_login_tok"] = token
                            log_event("LOGIN", f"User {username.strip()} logged in as {rows[0]['role']}.")
                            done(f"Welcome, {username.strip()}!")
                    else:
                        st.error("Username or password is incorrect.")

        with register_tab:
            st.caption("New accounts require Store Manager approval.")
            with st.form("reg_form", clear_on_submit=True):
                reg_user = st.text_input("Username", key="reg_user", placeholder="3–30 letters, digits, _ . -")
                full_name = st.text_input("Full name", key="reg_name")
                reg_pw1 = st.text_input("Password (min 8 characters)", type="password", key="reg_pw1")
                reg_pw2 = st.text_input("Confirm password", type="password", key="reg_pw2")
                register_submit = st.form_submit_button("Request registration", use_container_width=True)
            if register_submit:
                if not USERNAME_RE.fullmatch(reg_user.strip()):
                    st.error("Username must be 3–30 characters using letters, numbers, _ . or -.")
                elif not full_name.strip():
                    st.error("Enter your full name.")
                elif len(reg_pw1) < 8:
                    st.error("Password must be at least 8 characters.")
                elif reg_pw1 != reg_pw2:
                    st.error("The passwords do not match.")
                elif register_user(reg_user.strip(), full_name.strip(), reg_pw1):
                    st.success("Registration request sent. The Store Manager must approve it before sign-in.")

        with forgot_tab:
            st.caption("Password recovery requests are reviewed by the Store Manager.")
            with st.form("fp_form", clear_on_submit=True):
                reset_user = st.text_input("Username", key="fp_user")
                reset_submit = st.form_submit_button("Request password reset", use_container_width=True)
            if reset_submit:
                if not reset_user.strip():
                    st.error("Enter your username.")
                else:
                    request_password_reset(reset_user.strip())
                    st.success("If the account is active, the reset request has been sent to the Store Manager.")

# ============================================================
#  HELPERS
# ============================================================
def num(v, default=None):
    try:
        if v is None or pd.isna(v):
            return default
    except (TypeError, ValueError):
        pass
    t = str(v).replace(",", "").strip()
    if t in ("", "nan", "None"):
        return default
    try:
        return float(t)
    except ValueError:
        return default


def txt(v):
    if v is None:
        return ""
    try:
        if pd.isna(v):
            return ""
    except (TypeError, ValueError):
        pass
    if isinstance(v, float) and v.is_integer():
        return str(int(v))
    t = str(v).strip()
    return "" if t.lower() == "nan" else t


def norm_col(s):
    return re.sub(r"[^a-z0-9]", "", str(s).lower())


def find_col(df, keys):
    m = {norm_col(c): c for c in df.columns}
    for k in keys:
        if norm_col(k) in m:
            return m[norm_col(k)]
    return None


def norm_name(s):
    return re.sub(r"[^a-z0-9]", "", str(s or "").lower())


def norm_size(s):
    return re.sub(r"[^a-z0-9.]", "", str(s or "").lower())


def is_blank_code(c):
    return str(c or "").strip().upper() in ("", "N/A", "NA", "NONE", "-", "NAN")


def code_base(prod_id, size):
    p, s = str(prod_id or "").strip(), str(size or "").strip()
    if s and len(p) > len(s) + 1 and p.lower().endswith("-" + s.lower()):
        return p[:-(len(s) + 1)]
    return ""


def parse_date(s):
    t = str(s or "").strip()
    if not t or t.lower() in ("none", "nan", "not received", "pending po", "not returned"):
        return None
    for f in ("%d-%b-%Y", "%d-%m-%Y", "%Y-%m-%d", "%d/%m/%Y"):
        try:
            return datetime.strptime(t, f)
        except ValueError:
            continue
    return None


def age_days(start_s, end_s=None):
    s = parse_date(start_s)
    if not s:
        return None
    e = parse_date(end_s) or datetime.now()
    return max((e - s).days, 0)


def other_factory(f):
    return "Windy Washing LTD" if f == "KC Washing Plant" else "KC Washing Plant"


# ---- UOM everywhere: the item's unit (Pcs / Pkt / Box / Yds ...) is shown next to its name in the item pickers and lists.
# ---- One lookup table of (factory, SL) -> unit, rebuilt only after a save (same data-version counter as q_c), so a label costs a dict lookup.
@st.cache_resource(show_spinner=False)
def _uom_box():
    return {"v": None, "m": {}}


def _uom_map():
    b, v = _uom_box(), _data_version()
    if b["v"] != v:
        _c, rows = fetch("SELECT factory_name, sl_no, COALESCE(NULLIF(TRIM(unit_name),''),'Pcs') FROM inventory", None)
        b["m"] = {(str(f), int(s)): u for f, s, u in rows if s is not None}
        b["v"] = v
    return b["m"]


def _uom_of(x):
    """Unit of the inventory item described by a dict / row / Series (needs sl_no or sl; factory_name or the current factory)."""
    try:
        sl = x.get("sl_no", x.get("sl"))
        if sl is None or sl != sl:
            return ""
        return _uom_map().get((str(x.get("factory_name") or FAC), int(sl)), "")
    except Exception:
        return ""


def _uom_tag(x):
    u = _uom_of(x)
    return f" ({u})" if u else ""


def item_label(r):
    return (f"SL {r['sl_no']} | S/N {r.get('serial') or '-'} | {r['factory_name']} | {r['item_name']} "
            f"[{r['size'] or '-'}]{_uom_tag(r)} | {r['prod_id']} | Stock {float(r['stock'] or 0):g}")


def next_free_temp(fac):
    used = {str(r["prod_id"]) for r in q("SELECT prod_id FROM inventory WHERE factory_name=%s", (fac,))}
    n = 1
    while f"TEMP-{n:04d}" in used:
        n += 1
    return f"TEMP-{n:04d}"


def insert_tx(fac, officer, sl, pid, name, qty, ttype, day, notes, date_s, time_s, verif, grn="Not Required",
              supplier="", challan="", po_flag="", po_date=None, unit_price_at_tx=None, req_no=""):
    run("""INSERT INTO transactions (factory_name, officer_name, sl_no, prod_id, item_name, qty, trans_type, day,
           notes, date, time, verification_status, erp_grn_status, supplier_name, challan_no,
           po_pending_flag, po_pending_date, unit_price_at_tx, req_no)
           VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
        (fac, officer, sl, pid, name, qty, ttype, day, notes, date_s, time_s, verif, grn, supplier, challan,
         po_flag, po_date, unit_price_at_tx, (req_no or "").strip()))


def _csv_bytes(df):
    return df.to_csv(index=False).encode("utf-8-sig")


def _xlsx_bytes(df):
    buf = io.BytesIO()
    df.to_excel(buf, index=False)
    return buf.getvalue()


def _lazy_download(col, label, builder, fname, mime, key):
    """Newer Streamlit: the file is built only when the person clicks Download, so a normal page run does no file work
    (a 3,000-row PDF alone took seconds on every single page run). Returns False if this Streamlit cannot do that."""
    for kw in ({"on_click": "ignore"}, {}):
        try:
            col.download_button(label, builder, fname, mime, key=key, **kw)
            return True
        except Exception:
            continue
    return False


def export_buttons(df, name, title=None):
    if df is None or df.empty:
        st.caption("Download korar moto data nei.")
        return
    c1, c2, c3 = st.columns(3)
    xlsx_mime = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    if _lazy_download(c1, "⬇️ CSV", lambda: _csv_bytes(df), f"{name}.csv", "text/csv", f"csv_{name}"):
        _lazy_download(c2, "⬇️ Excel", lambda: _xlsx_bytes(df), f"{name}.xlsx", xlsx_mime, f"xls_{name}")
        try:
            import reportlab  # noqa: F401
            _lazy_download(c3, "⬇️ PDF", lambda: to_pdf(df, title or name), f"{name}.pdf", "application/pdf", f"pdf_{name}")
        except ImportError:
            c3.caption("PDF: 'pip install reportlab'")
        return
    # Older Streamlit without deferred downloads: original behaviour (files built right away).
    c1.download_button("⬇️ CSV", _csv_bytes(df), f"{name}.csv", "text/csv", key=f"csv_{name}_b")
    c2.download_button("⬇️ Excel", _xlsx_bytes(df), f"{name}.xlsx", xlsx_mime, key=f"xls_{name}_b")
    pdf = to_pdf(df, title or name)
    if pdf:
        c3.download_button("⬇️ PDF", pdf, f"{name}.pdf", "application/pdf", key=f"pdf_{name}_b")
    else:
        c3.caption("PDF: 'pip install reportlab'")


def to_pdf(df, title):
    try:
        from reportlab.lib import colors
        from reportlab.lib.pagesizes import A4, landscape
        from reportlab.lib.styles import getSampleStyleSheet
        from reportlab.platypus import Paragraph, SimpleDocTemplate, Table, TableStyle
    except ImportError:
        return None
    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=landscape(A4), leftMargin=18, rightMargin=18, topMargin=18, bottomMargin=18)
    data = [[str(c) for c in df.columns]]
    for r in df.values.tolist():
        data.append(["" if (v is None or (isinstance(v, float) and math.isnan(v))) else str(v) for v in r])
    t = Table(data, repeatRows=1)
    t.setStyle(TableStyle([("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#E8590C")),
                           ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
                           ("FONTSIZE", (0, 0), (-1, -1), 7), ("GRID", (0, 0), (-1, -1), 0.3, colors.grey)]))
    doc.build([Paragraph(title, getSampleStyleSheet()["Title"]), t])
    return buf.getvalue()


def read_any(upload):
    if upload.name.lower().endswith(".csv"):
        return pd.read_csv(upload, dtype=object)
    return pd.read_excel(upload, dtype=object)


def backup_zip():
    """Every table as CSV inside one zip."""
    buf = io.BytesIO()
    tables = [r["table_name"] for r in q("SELECT table_name FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE'")]
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:
        for t in tables:
            z.writestr(f"{t}.csv", qdf(f'SELECT * FROM "{t}"').to_csv(index=False))
    return buf.getvalue()


def budget_bar_html(pct, label="Budget consumption"):
    """Dynamic bar: green below 70%, amber 70-85%, red above the alert limit."""
    width = min(max(pct, 0), 100)
    color = "#16A34A" if pct < 70 else ("#F59E0B" if pct <= BUDGET_ALERT_PCT else "#DC2626")
    return (f'<div class="bar-label"><span>{html_lib.escape(label)}</span><span>{pct:.1f}%</span></div>'
            f'<div class="bar-wrap"><div class="bar-fill" style="width:{width:.1f}%;background:{color};"></div></div>')


def status_badge(text):
    t = str(text or "")
    if t.startswith("Physically"):
        bg, fg, lab = "#DCFCE7", "#166534", "✔ Physically Verified"
    elif t == "Verified":
        bg, fg, lab = "#DBEAFE", "#1E40AF", "✔ Verified"
    elif t == "Not Required" or t == "N/A" or not t:
        bg, fg, lab = "#F1F5F9", "#475569", "• Normal"
    else:
        bg, fg, lab = "#FFF4E6", "#C2410C", t
    return f'<span class="status-badge" style="background:{bg};color:{fg}">{html_lib.escape(lab)}</span>'


# ============================================================
#  ITEM RESOLVING
# ============================================================
def resolve_item(fac, key, in_stock_only=False):
    """SL No (exact) -> Serial No (exact) -> ERP code -> name (exact) -> partial name/size/serial. Returns (row, candidates).
    in_stock_only=True hides items whose current stock is 0 or negative (used for issue-type transactions)."""
    k = str(key or "").strip()
    if not k:
        return None, []
    stages = []
    if k.isdigit():
        stages.append(("sl_no=%s", [int(k)]))
    stages.append(("LOWER(TRIM(COALESCE(serial_no,'')))=LOWER(%s)", [k]))
    stages.append(("LOWER(TRIM(prod_id))=LOWER(%s)", [k]))
    stages.append(("LOWER(TRIM(item_name))=LOWER(%s)", [k]))
    like = f"%{k.lower()}%"
    stages.append(("(LOWER(item_name) LIKE %s OR LOWER(COALESCE(size,'')) LIKE %s OR LOWER(COALESCE(serial_no,'')) LIKE %s)",
                   [like, like, like]))
    fsql, fp = fw(fac)
    stock_sql = " AND COALESCE(current_stock,0) > 0" if in_stock_only else ""
    for where, params in stages:
        rows = q_c(f"SELECT {INV_COLS} FROM inventory WHERE {where}{stock_sql}{fsql} ORDER BY factory_name, sl_no", params + fp)
        if len(rows) == 1:
            return rows[0], rows
        if len(rows) > 1:
            return None, rows
    return None, []


def search_items(fac, term, in_stock_only=False):
    like = f"%{term.lower()}%"
    fsql, fp = fw(fac)
    stock_sql = " AND COALESCE(current_stock,0) > 0" if in_stock_only else ""
    return q_c(f"""SELECT {INV_COLS} FROM inventory
                 WHERE (LOWER(item_name) LIKE %s OR LOWER(COALESCE(size,'')) LIKE %s OR LOWER(prod_id) LIKE %s
                        OR LOWER(COALESCE(serial_no,'')) LIKE %s OR CAST(sl_no AS TEXT)=%s){stock_sql}{fsql}
                 ORDER BY CASE WHEN LOWER(COALESCE(serial_no,''))=LOWER(%s) THEN 0 ELSE 1 END, sl_no LIMIT 100""",
             [like, like, like, like, term] + fp + [term])


def serial_owner(fac, serial, exclude_sl=None):
    """Item of this factory that already carries the serial number (or None)."""
    sn = (serial or "").strip()
    if not sn:
        return None
    rows = q("""SELECT sl_no, item_name, COALESCE(size,'') AS size FROM inventory
                WHERE factory_name=%s AND LOWER(TRIM(COALESCE(serial_no,'')))=LOWER(%s)""", (fac, sn))
    rows = [r for r in rows if exclude_sl is None or r["sl_no"] != exclude_sl]
    return rows[0] if rows else None


def is_duplicate_tx(fac, sl, ttype, qty, date_s, user, notes, req_no=""):
    """True when the newest transaction of this item is an identical one saved within the last 2 minutes
    (same type, qty, date, officer and remarks) - i.e. a repeated click / stale form."""
    last = q("""SELECT qty, trans_type, officer_name, date, time, notes, COALESCE(req_no,'') AS req_no FROM transactions
                WHERE factory_name=%s AND sl_no=%s ORDER BY id DESC LIMIT 1""", (fac, sl))
    if not last:
        return False
    t = last[0]
    if (req_no or "").strip() and str(t["req_no"] or "").strip() != (req_no or "").strip():
        return False      # a different requisition (SR) slip is never a repeated click
    if not (t["trans_type"] == ttype and abs(float(t["qty"] or 0) - float(qty)) < 1e-9
            and t["officer_name"] == user and t["date"] == date_s
            and str(t["notes"] or "").strip().startswith(str(notes or "").strip())):
        return False
    try:
        tm = datetime.strptime(str(t["time"]).strip(), "%I:%M %p").time()
    except ValueError:
        return False
    saved = datetime.combine(datetime.now().date(), tm)
    return 0 <= (datetime.now() - saved).total_seconds() < 120


def inv_options(fac):
    fsql, fp = fw(fac)
    rows = q_c(f"""SELECT sl_no, prod_id, factory_name, item_name, COALESCE(size,'') AS size, department, category,
                 COALESCE(serial_no,'') AS serial_no, COALESCE(erp_stock,0) AS erp_stock, COALESCE(current_stock,0) AS current_stock,
                 COALESCE(unit_price,0) AS unit_price, COALESCE(NULLIF(unit_name,''),'Pcs') AS unit_name
                 FROM inventory WHERE 1=1{fsql} ORDER BY factory_name, sl_no""", fp)
    return {f"SL {r['sl_no']} | {r['factory_name']} | {r['item_name']} [{r['size'] or '-'}]{_uom_tag(r)} | {r['prod_id']}"
            + (f" | S/N {r['serial_no']}" if r["serial_no"] else ""): r for r in rows}


def find_same_item(fac, name, size):
    nn, ns = norm_name(name), norm_size(size)
    for r in q("SELECT sl_no, prod_id, item_name, COALESCE(size,'') AS size FROM inventory WHERE factory_name=%s", (fac,)):
        if norm_name(r["item_name"]) == nn and norm_size(r["size"]) == ns:
            return r
    return None


XFER_NAME_MATCH = 0.80   # inter-factory auto-transfer: item names may differ a little (ERP names change at PO time); SIZE must still match


def _name_match_score(a, b):
    """0..1 name similarity for the inter-factory match. Ignores case/spaces/punctuation and word order
    ('Bearing 6205' = '6205 Bearing'). If both names carry numbers and the numbers differ (6205 vs 6206, 6205 ZZ vs 6205 2RS) -> 0."""
    ta = re.findall(r"\d+|[^\W\d_]+", str(a or "").lower())
    tb = re.findall(r"\d+|[^\W\d_]+", str(b or "").lower())
    na, nb = {t for t in ta if t.isdigit()}, {t for t in tb if t.isdigit()}
    if na and nb and na != nb:
        return 0.0
    ca, cb = norm_name(a), norm_name(b)
    if not ca or not cb:
        return 0.0
    if ca == cb or sorted(ta) == sorted(tb):
        return 1.0
    return max(difflib.SequenceMatcher(None, ca, cb).ratio(),
               difflib.SequenceMatcher(None, "".join(sorted(ta)), "".join(sorted(tb))).ratio())


def find_same_in_other(prod_id, name, other_fac, size, need=None):
    """Same product in the other factory. Order: exact NAME + SIZE -> same ERP code (any size) -> similar name (>= 80%, same size)
    -> exact name when one side has no size / the size only repeats the item name (only if it is unambiguous).
    `need` (optional) = shortage qty: among equally good matches, one that has enough stock is preferred."""
    ns, nn = norm_size(size), norm_name(name)
    all_rows = q(f"SELECT {INV_COLS} FROM inventory WHERE factory_name=%s", (other_fac,))
    rows = [r for r in all_rows if norm_size(r["size"]) == ns]
    exact = [r for r in rows if nn and norm_name(r["item_name"]) == nn]
    if exact:
        same = [r for r in exact if r["prod_id"] == prod_id]
        return {**max(same or exact, key=lambda r: r["stock"] or 0), "level": "exact", "score": 1.0}
    # the ERP code is the strongest sign of the same item - size spelling must not hide it (e.g. size blank in one unit)
    has_code = bool(prod_id) and not is_blank_code(prod_id) and not str(prod_id).upper().startswith("TEMP-")
    if has_code:
        bc = [r for r in all_rows if r["prod_id"] == prod_id]
        if bc:
            if need is not None:
                bc = [r for r in bc if float(r["stock"] or 0) >= need] or bc
            return {**max(bc, key=lambda r: float(r["stock"] or 0)), "level": "code", "score": 1.0}
    scored = [(_name_match_score(name, r["item_name"]), r) for r in rows]
    scored = [(s, r) for s, r in scored if s >= XFER_NAME_MATCH]
    if scored:
        top = max(s for s, _ in scored)
        close = [(s, r) for s, r in scored if top - s <= 0.05]
        if need is not None:
            enough = [(s, r) for s, r in close if float(r["stock"] or 0) >= need]
            close = enough or close
        s, r = max(close, key=lambda x: (x[0], float(x[1]["stock"] or 0)))
        return {**r, "level": "exact" if s >= 0.999 else "fuzzy", "score": s}

    def _size_free(r):          # no size at all, or the size is just the item name typed again
        rs = norm_size(r["size"])
        return (not rs) or rs == norm_name(r["item_name"])
    loose = [r for r in all_rows if nn and norm_name(r["item_name"]) == nn and _size_free(r)]
    if len(loose) == 1:
        return {**loose[0], "level": "fuzzy", "score": 0.9}
    return None


def recent_issue(fac, sl, ref_dt):
    for r in q("""SELECT date, time, qty, officer_name FROM transactions WHERE factory_name=%s AND sl_no=%s
                  AND trans_type IN ('Issued','Internal Issue') ORDER BY id DESC""", (fac, sl)):
        dt = None
        for s, f in ((f"{r['date']} {r['time']}", "%d-%b-%Y %I:%M %p"), (str(r["date"]), DATE_FMT)):
            try:
                dt = datetime.strptime(s.strip(), f)
                break
            except ValueError:
                continue
        if dt and 0 <= (ref_dt - dt).total_seconds() < COOLDOWN_DAYS * 86400:
            return dt, r["qty"], r["officer_name"]
    return None


def verification_needed(fac, sl, tx_dt):
    """Require physical verification on the 4th calendar day from the first unverified issue.

    Missing issue days do not reset the elapsed-day clock. A physically verified issue resets
    the cycle; the next unverified issue starts a new cycle.
    """
    target_date = tx_dt.date() if isinstance(tx_dt, datetime) else tx_dt
    rows = q_c("""SELECT date, verification_status
                 FROM transactions
                 WHERE factory_name=%s AND sl_no=%s
                   AND trans_type IN ('Issued','Internal Issue')
                   AND date IS NOT NULL""", (fac, sl))

    events = []
    for row in rows:
        parsed = parse_date(row.get("date"))
        if not parsed:
            continue
        event_date = parsed.date()
        if event_date < target_date:
            status = str(row.get("verification_status") or "")
            events.append((event_date, status))

    physical_dates = [event_date for event_date, status in events if status.startswith("Physically")]
    last_physical_date = max(physical_dates) if physical_dates else None
    pending_issue_dates = [
        event_date for event_date, status in events
        if not status.startswith("Physically")
        and (last_physical_date is None or event_date > last_physical_date)
    ]
    if not pending_issue_dates:
        return False, 0

    first_unverified_issue = min(pending_issue_dates)
    elapsed_days = (target_date - first_unverified_issue).days
    return elapsed_days >= VERIFY_AFTER_DAYS, elapsed_days
def opening_dates(fac, sls, fresh=True):
    """{sl_no: date of the LATEST Opening Balance row}. The Opening Balance is the FIRST balance of an item:
    nothing may be dated before it. fresh=False uses the cached read (for form display only)."""
    sls = tuple(sorted({int(x) for x in sls}))
    if not sls:
        return {}
    rows = (q if fresh else q_c)("SELECT sl_no, date FROM transactions WHERE factory_name=%s AND trans_type=%s AND sl_no IN %s",
                                 (fac, OPENING_TYPE, sls))
    out = {}
    for r in rows:
        d = parse_date(r.get("date"))
        if d:
            k = int(r["sl_no"])
            if k not in out or d.date() > out[k]:
                out[k] = d.date()
    return out


def pre_opening_msg(fac, sls, tx_dt, names=None):
    """Error text when tx_dt is EARLIER than the Opening Balance date of any item in sls, else ''."""
    if isinstance(tx_dt, str):
        tx_dt = parse_date(tx_dt)
    if tx_dt is None:
        return ""
    td = tx_dt.date() if isinstance(tx_dt, datetime) else tx_dt
    bad = []
    for sl, od in opening_dates(fac, sls).items():
        if td < od:
            nm = (names or {}).get(sl) or (names or {}).get(str(sl)) or f"SL {sl}"
            bad.append(f"{nm} (Opening Balance {od.strftime(DATE_FMT)})")
    if not bad:
        return ""
    return ("🚫 Opening Balance-er age-r tarikhe transaction deya jabe na — Opening-i item-er prothom balance. "
            f"Date {td.strftime(DATE_FMT)}: " + "; ".join(bad) + ". Opening-er tarikh ba tar por-er tarikh din.")


# ============================================================
#  IMPORT ENGINE (Master Inventory, in-memory index)
# ============================================================
def empty_index():
    return {"all": [], "name": {}, "code": {}, "codes": set(), "max_sl": 0, "temp": 0, "serials": {}}


def idx_add(idx, sl, code, name, size, serial=""):
    e = {"sl": sl, "code": str(code or ""), "name": name or "", "size": size or "",
         "nn": norm_name(name), "ns": norm_size(size), "serial": str(serial or "").strip()}
    idx["all"].append(e)
    if e["serial"]:
        idx["serials"][e["serial"].lower()] = sl
    if e["nn"]:
        idx["name"].setdefault(e["nn"], []).append(e)
    ck = e["code"].strip().lower()
    if ck:
        idx["code"].setdefault(ck, []).append(e)
        idx["codes"].add(ck)
        b = code_base(e["code"], e["size"]).lower()
        if b:
            idx["code"].setdefault(b, []).append(e)
    try:
        idx["max_sl"] = max(idx["max_sl"], int(sl))
    except (TypeError, ValueError):
        pass
    return e


def load_index(fac):
    idx = empty_index()
    for r in q("SELECT sl_no, prod_id, item_name, COALESCE(size,'') AS size, COALESCE(serial_no,'') AS serial_no "
               "FROM inventory WHERE factory_name=%s", (fac,)):
        idx_add(idx, r["sl_no"], r["prod_id"], r["item_name"], r["size"], r["serial_no"])
    mq = q("SELECT COALESCE(MAX(sl_no),0) AS m FROM import_queue WHERE factory_name=%s", (fac,))[0]["m"]
    idx["max_sl"] = max(idx["max_sl"], int(mq or 0))
    _inject_aliases(idx, q("SELECT alias_norm, sl_no FROM item_aliases WHERE factory_name=%s", (fac,)))
    return idx


def idx_find(idx, code, name, size, claim_blank=True, loose=True):
    ns, nn = norm_size(size), norm_name(name)
    ck = "" if is_blank_code(code) else str(code).strip().lower()
    pools = []
    if ck:
        pools.append(idx["code"].get(ck, []))
    if nn:
        pools.append(idx["name"].get(nn, []))
    for p in pools:
        for e in p:
            if e["ns"] == ns:
                return e
    if claim_blank and ns:
        for p in pools:
            for e in p:
                if not e["ns"]:
                    return e
    if loose and not ns:
        for p in pools:
            if len(p) == 1:
                return p[0]
    return None


def unique_code(idx, code, size):
    base = str(code).strip()
    if base.lower() not in idx["codes"]:
        return base
    s = str(size or "").strip()
    cand = f"{base}-{s}" if s else base
    n = 1
    while cand.lower() in idx["codes"]:
        n += 1
        cand = f"{base}-{s}-{n}" if s else f"{base}-{n}"
    return cand


def temp_code(idx):
    n = idx["temp"] + 1
    while f"temp-{n:04d}" in idx["codes"]:
        n += 1
    idx["temp"] = n
    return f"TEMP-{n:04d}"


def idx_insert(fac, idx, code, name, size, dept, cat, erp, stock, price, unit, serial="", product_cat=""):
    final = temp_code(idx) if is_blank_code(code) else unique_code(idx, code, size)
    idx["max_sl"] += 1
    sl = idx["max_sl"]
    run("""INSERT INTO inventory (sl_no, prod_id, factory_name, item_name, size, department, category,
           erp_stock, current_stock, unit_price, erp_status, unit_name, serial_no, product_category)
           VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,'ERP Pending',%s,%s,%s)""",
        (sl, final, fac, name, size or "", dept or "Maintenance", cat or "Uncategorized (Edit Later)",
         erp, stock, price or 0.0, unit or "Pcs", (serial or "").strip(), product_cat or ""))
    idx_add(idx, sl, final, name, size, serial)
    return final


def mirror_to_other(fac, code, name, size, dept, cat, price, unit="Pcs", product_cat=""):
    """New product is also created in the other unit with stock 0."""
    other = other_factory(fac)
    if find_same_item(other, name, size):
        return False
    idx_insert(other, load_index(other), code, name, size, dept, cat, 0.0, 0.0, price, unit or "Pcs", "", product_cat)
    return True


def import_rows(fac, rows):
    other = other_factory(fac)
    idx, oidx = load_index(fac), load_index(other)
    st_ = dict(updated=0, added=0, added_zero=0, mirrored=0, dup=0, no_size=0, size_fill=0, code_fix=0, queue_closed=0,
               serial_set=0, serial_conflict=0)
    touched = set()
    for r in rows:
        code = "" if is_blank_code(r["code"]) else str(r["code"]).strip()
        name = r["name"] or code
        size = r["size"] or ""
        serial = str(r.get("serial") or "").strip()
        e = idx_find(idx, code, name, size)
        if e:
            if e["sl"] in touched:
                st_["dup"] += 1
            touched.add(e["sl"])
            new_size = size if (size and not e["ns"]) else None
            new_code = unique_code(idx, code, size or e["size"]) if (code and e["code"].upper().startswith("TEMP-")) else None
            new_serial = None
            if serial and serial.lower() != str(e.get("serial") or "").lower():
                owner = idx["serials"].get(serial.lower())
                if owner is None or owner == e["sl"]:
                    new_serial = serial
                else:
                    st_["serial_conflict"] += 1
            run("""UPDATE inventory SET current_stock=COALESCE(%s,current_stock), erp_stock=COALESCE(%s,erp_stock),
                   unit_price=COALESCE(%s,unit_price), unit_name=COALESCE(%s,unit_name),
                   size=COALESCE(%s,size), prod_id=COALESCE(%s,prod_id), serial_no=COALESCE(%s,serial_no)
                   WHERE sl_no=%s AND factory_name=%s""",
                (r["phys"], r["erp"], r["price"], r["unit"], new_size, new_code, new_serial, e["sl"], fac))
            if new_serial:
                e["serial"] = new_serial
                idx["serials"][new_serial.lower()] = e["sl"]
                st_["serial_set"] += 1
            if new_size:
                e["size"], e["ns"] = new_size, norm_size(new_size)
                st_["size_fill"] += 1
            if new_code:
                run("UPDATE transactions SET prod_id=%s WHERE sl_no=%s AND factory_name=%s", (new_code, e["sl"], fac))
                run("UPDATE requisition_tracking SET prod_id=%s WHERE factory_name=%s AND prod_id=%s", (new_code, fac, e["code"]))
                e["code"] = new_code
                idx["code"].setdefault(new_code.lower(), []).append(e)
                idx["codes"].add(new_code.lower())
                st_["code_fix"] += 1
            st_["updated"] += 1
        else:
            phys0 = r["phys"] if r["phys"] is not None else 0.0
            erp0 = r["erp"] if r["erp"] is not None else phys0
            ins_serial = serial
            if serial and serial.lower() in idx["serials"]:
                ins_serial = ""
                st_["serial_conflict"] += 1
            idx_insert(fac, idx, code, name, size, r["dept"], r["cat"], erp0, phys0, r["price"], r["unit"], ins_serial)
            touched.add(idx["max_sl"])
            st_["added"] += 1
            st_["added_zero"] += int(phys0 == 0)
            st_["no_size"] += int(not size)
            if idx_find(oidx, code, name, size, claim_blank=False, loose=False) is None:
                idx_insert(other, oidx, code, name, size, r["dept"], r["cat"], 0.0, 0.0, r["price"], r["unit"])
                st_["mirrored"] += 1
    for qr in q("""SELECT id, prod_id, item_name, COALESCE(size,'') AS size FROM import_queue
                   WHERE factory_name=%s AND status='Pending Approval'""", (fac,)):
        if idx_find(idx, qr["prod_id"], qr["item_name"], qr["size"], claim_blank=False, loose=False):
            run("UPDATE import_queue SET status='Approved' WHERE id=%s", (qr["id"],))
            st_["queue_closed"] += 1
    audit("IMPORT_OPENING_STOCK", f"{fac}: added {st_['added']}, updated {st_['updated']}, mirrored {st_['mirrored']}")
    return st_


def detect_import_cols(df):
    c = {
        "code": find_col(df, ["erp code", "erp_code", "prod_id", "item code", "code"]),
        "name": find_col(df, ["item name", "item_name", "description", "product name", "item"]),
        "size": find_col(df, ["size", "item size", "product size"]),
        "phys": find_col(df, ["opening physical stock", "physical stock", "opening stock", "current stock", "qty", "stock"]),
        "erp": find_col(df, ["erp stock", "erp_stock", "erp balance"]),
        "price": find_col(df, ["unit price", "unit_price", "price"]),
        "unit": find_col(df, ["unit", "uom"]),
        "serial": find_col(df, ["serial no", "serial number", "serial_no", "serial", "s/n"]),
        "dept": find_col(df, ["department"]),
        "cat": find_col(df, ["category"]),
    }
    if not c["phys"] or (not c["code"] and not c["name"]):
        return None
    return c


def build_import_rows(df, c):
    rows, skipped = [], 0
    for _, r in df.iterrows():
        code = txt(r[c["code"]]) if c["code"] else ""
        name = txt(r[c["name"]]) if c["name"] else ""
        if is_blank_code(code) and not name:
            skipped += 1
            continue
        raw_phys = r[c["phys"]]
        if txt(raw_phys) != "" and num(raw_phys) is None:
            skipped += 1
            continue
        unit = txt(r[c["unit"]]) if c["unit"] else ""
        rows.append({
            "code": code, "name": name,
            "size": txt(r[c["size"]]) if c["size"] else "",
            "serial": txt(r[c["serial"]]) if c.get("serial") else "",
            "phys": num(raw_phys) if txt(raw_phys) != "" else None,
            "erp": num(r[c["erp"]]) if c["erp"] and txt(r[c["erp"]]) != "" else None,
            "price": num(r[c["price"]]) if c["price"] else None,
            "unit": unit if unit in UOM else None,
            "dept": txt(r[c["dept"]]) if c["dept"] else "",
            "cat": txt(r[c["cat"]]) if c["cat"] else "",
        })
    return rows, skipped


# ============================================================
#  ERP MATCH CHECK HELPERS
# ============================================================
def ec_index():
    out = {}
    for f in FACTORIES:
        idx = empty_index()
        for r in q_c("""SELECT sl_no, prod_id, item_name, COALESCE(size,'') AS size, COALESCE(erp_stock,0) AS erp,
                      COALESCE(current_stock,0) AS phys FROM inventory WHERE factory_name=%s""", (f,)):
            e = idx_add(idx, r["sl_no"], r["prod_id"], r["item_name"], r["size"])
            e["erp"], e["phys"] = r["erp"], r["phys"]
        _inject_aliases(idx, alias_rows(f))
        out[f] = idx
    return out


def ec_lookup(index, fac, name, size, code):
    idx = index[fac]
    nn, ns = norm_name(name), norm_size(size)
    ck = "" if is_blank_code(code) else str(code).strip().lower()
    name_rows = idx["name"].get(nn, []) if nn else []
    code_rows = idx["code"].get(ck, []) if ck else []
    base = name_rows or (code_rows if not nn else [])
    if base:
        sizes = ", ".join(sorted({e["size"] or "(no size)" for e in base}))
        if ns:
            hit = [e for e in base if e["ns"] == ns]
            if hit:
                return "FOUND", hit, f"Size exists. Sizes: {sizes}"
            return "SIZE_MISSING", base, f"Size '{size}' NOT in list. Sizes: {sizes}"
        return "FOUND", base, f"Product exists. Sizes: {sizes}"
    if code_rows:
        return "CODE_MATCH", code_rows, "Same ERP code, DIFFERENT name - please check"
    similar = []
    if nn and len(nn) >= 3:
        similar = [e for k, lst in idx["name"].items() if nn in k or k in nn for e in lst][:60]
    if similar:
        return "SIMILAR", similar, "Exact product not found - similar names"
    return "NOT_FOUND", [], "NOT in system - NEW product / size"


