def guard(write=True):
    if not st.session_state.get("user"):
        st.warning("🔑 Sidebar theke login korun.")
        return False
    if write and st.session_state.get("role") in READ_ONLY_ROLES:
        st.error(f"{st.session_state.get('role')} role read-only — shudhu dekhte parben, edit / delete korte parben na.")
        return False
    if write and "CONSOLIDATED" in FAC:
        st.error("CONSOLIDATED view-te edit kora jabe na. Specific factory select korun.")
        return False
    if write and st.session_state.get("role") in UNIT_LOCK_ROLES and FAC != st.session_state.get("locked_factory"):
        st.error("Age unit select korun - entry shudhu locked unit-e hobe.")
        return False
    return True


def inventory_count():
    return int(q_c(f"SELECT COUNT(*) AS n FROM inventory WHERE 1=1{FSQL}", FP)[0]["n"] or 0)


