#  TAB 6 - REQUISITION
# ============================================================
def req_calc(r):
    req, aud, rec = float(r["req_qty"] or 0), float(r["aud_qty"] or 0), float(r["rec_qty"] or 0)
    base = aud if aud > 0 else req
    pending = max(base - rec, 0)
    now = datetime.now()
    d_req, d_po = parse_date(r["req_date"]), parse_date(r["po_date"])
    age = max((now - d_req).days, 0) if d_req else 0
    delay = max((d_po - d_req).days, 0) if (d_req and d_po) else age
    since_po = max((now - d_po).days, 0) if d_po else 0
    if rec > 0 and pending <= 0:
        st_ = "Fully Received"
    elif rec > 0:
        st_ = "Partially Received"
    elif d_po:
        st_ = "PO Issued - Awaiting Delivery"
    elif aud > 0:
        st_ = "Audit Approved - PO Pending"
    else:
        st_ = "Req Created - Audit Pending"
    return {**r, "aud_qty": aud, "rec_qty": rec, "req_qty": req, "base": base, "pending": pending, "age": age,
            "delay": delay, "since_po": since_po, "calc_status": st_, "has_po": d_po is not None}


def load_requisitions():
    try:
        rows = _load_requisition_rows()
    except psycopg2.errors.UndefinedColumn:    # new Tracker columns not created yet: create them now (additive), then retry
        ensure_req_tracker_schema()
        _bump_data_version()
        rows = _load_requisition_rows()
    return [req_calc(r) for r in rows]


def _load_requisition_rows():
    rows = q_c(f"""SELECT id, factory_name, req_no, department, req_date, item_name, req_qty, audit_approved_qty AS aud_qty,
                 actual_received_qty AS rec_qty, po_date, received_date, COALESCE(prod_id,'') AS prod_id,
                 COALESCE(size,'') AS size, COALESCE(budget_category,'') AS budget_category,
                 COALESCE(uom,'') AS uom, COALESCE(sourcing_manager,'') AS sourcing_manager, COALESCE(handover_date,'') AS handover_date,
                 COALESCE(supplier_name,'') AS supplier_name, COALESCE(order_date,'') AS order_date, COALESCE(order_note,'') AS order_note
                 FROM requisition_tracking WHERE 1=1{FSQL} ORDER BY id DESC""", FP)
    return rows


@tx
def create_req_item(fac, code, name, dept, size="", uom="", cat="", inv_dept=""):
    mx = q("SELECT COALESCE(MAX(sl_no),0) AS m FROM inventory WHERE factory_name=%s", (fac,))[0]["m"]
    if is_blank_code(code):
        code = next_free_temp(fac)
    run("""INSERT INTO inventory (sl_no, prod_id, factory_name, item_name, department, category, erp_stock,
           current_stock, unit_price, erp_status, size, unit_name) VALUES (%s,%s,%s,%s,%s,%s,0,0,0,'ERP Pending',%s,%s)""",
        (int(mx) + 1, code, fac, name, (inv_dept or dept), (cat or "").strip() or "Uncategorized (Edit Later)",
         (size or "").strip(), (uom or "").strip() or "Pcs"))
    return code


def req_auto_receive(fac, sl, pid, qty, date_s):
    """Called inside save_transaction right after a Supplier Receipt is stored: the received qty is added to the
    OPEN requisition line(s) of the same item (oldest requisition first), never above what is still pending.
    Returns [(req_no, qty added)]. Writes req_receipt_links so a delete / qty edit of the receipt can undo it."""
    if is_blank_code(pid) or float(qty or 0) <= 0:
        return []
    last = q("SELECT id FROM transactions WHERE factory_name=%s AND sl_no=%s AND trans_type='Supplier. Rec' ORDER BY id DESC LIMIT 1",
             (fac, sl))
    if not last:
        return []
    return _req_alloc(fac, pid, float(qty), date_s, int(last[0]["id"]), sl)


def _req_size_key(sz):
    """'B-120' and '120' are the same size: compare without a leading letter prefix."""
    k = norm_size(sz)
    return re.sub(r"^[a-z]+", "", k) or k


def _req_line_matches(inv, r):
    """Does this inventory item (dict: prod_id, item_name, size) belong to this requisition line (dict: prod_id, item_name, size)?
    Sizes must agree when both are given; then the ERP code (also the code without a size suffix) or the item name decides.
    A name that only STARTS with the other (e.g. 'V-Belt-B 106' vs 'V Belt-B') is accepted only when both sizes are present and equal."""
    rs, isz = _req_size_key(r.get("size")), _req_size_key(inv.get("size"))
    if rs and isz and rs != isz:
        return False
    rp_ = str(r.get("prod_id") or "").strip().lower()
    ip_ = str(inv.get("prod_id") or "").strip().lower()
    if rp_ and not is_blank_code(rp_) and (rp_ == ip_ or rp_ == code_base(inv.get("prod_id"), inv.get("size")).lower()):
        return True
    ni, nr = norm_name(inv.get("item_name")), norm_name(r.get("item_name"))
    if not ni or not nr:
        return False
    if ni == nr:
        return True
    return bool(rs and isz and (ni.startswith(nr) or nr.startswith(ni)))


def _req_alloc(fac, pid, qty, date_s, tx_id, sl=None):
    if sl is not None:
        x = q("SELECT prod_id, item_name, COALESCE(size,'') AS size FROM inventory WHERE factory_name=%s AND sl_no=%s", (fac, int(sl)))
    else:
        x = q("SELECT prod_id, item_name, COALESCE(size,'') AS size FROM inventory WHERE factory_name=%s AND prod_id=%s LIMIT 1", (fac, pid))
    inv = dict(x[0]) if x else {"prod_id": pid, "item_name": "", "size": ""}
    key = norm_name(inv.get("item_name"))[:5]
    rows = q("""SELECT id, req_no, req_date, req_qty, COALESCE(audit_approved_qty,0) AS aud, COALESCE(actual_received_qty,0) AS rec,
                       COALESCE(prod_id,'') AS prod_id, COALESCE(item_name,'') AS item_name, COALESCE(size,'') AS size
                FROM requisition_tracking
                WHERE factory_name=%s AND (prod_id=%s OR (%s<>'' AND LOWER(REGEXP_REPLACE(COALESCE(item_name,''),'[^a-zA-Z0-9]','','g')) LIKE %s))""",
             (fac, pid, key, key + "%"))
    cand = []
    for r in rows:
        if not _req_line_matches(inv, dict(r)):
            continue
        aud, req, rec = float(r["aud"] or 0), float(r["req_qty"] or 0), float(r["rec"] or 0)
        pend = (aud if aud > 0 else req) - rec     # same rule as the Requisition tab's pending quantity
        if pend > 1e-9:
            cand.append((parse_date(r["req_date"]) or datetime.max, int(r["id"]), pend, r["req_no"]))
    cand.sort(key=lambda x: (x[0], x[1]))
    left, out = float(qty), []
    for _, rid, pend, req_no in cand:
        if left <= 1e-9:
            break
        take = min(left, pend)
        run("UPDATE requisition_tracking SET actual_received_qty=COALESCE(actual_received_qty,0)+%s, received_date=%s WHERE id=%s",
            (take, date_s, rid))
        run("INSERT INTO req_receipt_links (tx_id, req_id, qty) VALUES (%s,%s,%s)", (tx_id, rid, take))
        left -= take
        out.append((req_no, take))
    if out:
        audit("REQ_AUTO_RECEIVE", f"{fac}: receipt tx {tx_id} of {pid} qty {qty:g} -> " + ", ".join(f"{n} +{v:g}" for n, v in out))
    return out


def req_rematch_plan(fac, req_no):
    """Read-only: Supplier Receipts that were never linked to any requisition but belong to this requisition's open lines.
    Returns a list of dicts (req_id, tx_id, take, date, item, size, tx_qty)."""
    lines = q("""SELECT id, req_date, req_qty, COALESCE(audit_approved_qty,0) AS aud, COALESCE(actual_received_qty,0) AS rec,
                        COALESCE(prod_id,'') AS prod_id, COALESCE(item_name,'') AS item_name, COALESCE(size,'') AS size
                 FROM requisition_tracking WHERE factory_name=%s AND req_no=%s ORDER BY id""", (fac, req_no))
    plan, used = [], {}
    for ln in lines:
        ln = dict(ln)
        aud, req, rec = float(ln["aud"] or 0), float(ln["req_qty"] or 0), float(ln["rec"] or 0)
        pend = (aud if aud > 0 else req) - rec
        if pend <= 1e-9:
            continue
        key = norm_name(ln["item_name"])[:5]
        d0 = parse_date(ln["req_date"])
        cands = q("""SELECT t.id, t.date, COALESCE(t.qty,0) AS qty, i.prod_id, i.item_name, COALESCE(i.size,'') AS size
                     FROM transactions t JOIN inventory i ON i.sl_no=t.sl_no AND i.factory_name=t.factory_name
                     WHERE t.factory_name=%s AND t.trans_type='Supplier. Rec'
                       AND NOT EXISTS (SELECT 1 FROM req_receipt_links l WHERE l.tx_id=t.id)
                       AND (i.prod_id=%s OR (%s<>'' AND LOWER(REGEXP_REPLACE(COALESCE(i.item_name,''),'[^a-zA-Z0-9]','','g')) LIKE %s))
                     ORDER BY t.id""", (fac, ln["prod_id"], key, key + "%"))
        for c in cands:
            if pend <= 1e-9:
                break
            c = dict(c)
            td = parse_date(c["date"])
            if d0 and td and td < d0:
                continue
            if not _req_line_matches(c, ln):
                continue
            avail = float(c["qty"]) - used.get(c["id"], 0.0)
            if avail <= 1e-9:
                continue
            take = min(avail, pend)
            used[c["id"]] = used.get(c["id"], 0.0) + take
            pend -= take
            plan.append({"req_id": int(ln["id"]), "tx_id": int(c["id"]), "take": take, "date": c["date"],
                         "item": ln["item_name"], "size": ln["size"], "tx_item": c["item_name"], "tx_qty": float(c["qty"])})
    return plan


@tx
def req_rematch_apply(fac, req_no, plan):
    for p in plan:
        run("UPDATE requisition_tracking SET actual_received_qty=COALESCE(actual_received_qty,0)+%s, received_date=%s WHERE id=%s",
            (p["take"], p["date"], p["req_id"]))
        run("INSERT INTO req_receipt_links (tx_id, req_id, qty) VALUES (%s,%s,%s)", (p["tx_id"], p["req_id"], p["take"]))
    audit("REQ_RECEIPT_REMATCH", f"{fac}: Req {req_no} <- " + ", ".join(f"TX-{p['tx_id']} +{p['take']:g}" for p in plan))
    return True


def req_undo_receipt(tx_id, take_back=None):
    """Takes quantity back from the requisition lines a receipt had filled (newest line first). take_back=None -> all of it."""
    links = q("SELECT id, req_id, qty FROM req_receipt_links WHERE tx_id=%s ORDER BY id DESC", (tx_id,))
    left = None if take_back is None else float(take_back)
    for l in links:
        if left is not None and left <= 1e-9:
            break
        cut = float(l["qty"]) if left is None else min(float(l["qty"]), left)
        run("UPDATE requisition_tracking SET actual_received_qty=GREATEST(COALESCE(actual_received_qty,0)-%s,0) WHERE id=%s",
            (cut, l["req_id"]))
        if cut >= float(l["qty"]) - 1e-9:
            run("DELETE FROM req_receipt_links WHERE id=%s", (l["id"],))
        else:
            run("UPDATE req_receipt_links SET qty=qty-%s WHERE id=%s", (cut, l["id"]))
        if left is not None:
            left -= cut


def find_inv_for_req(fac, code, name, size=""):
    """ERP code first; then the exact name (a given size must agree, a blank inventory size is accepted); then learned aliases."""
    if not is_blank_code(code):
        r = q("SELECT sl_no, prod_id, item_name FROM inventory WHERE factory_name=%s AND prod_id=%s", (fac, code))
        if r:
            return r[0]
    if name:
        r = q("SELECT sl_no, prod_id, item_name, COALESCE(size,'') AS size FROM inventory "
              "WHERE factory_name=%s AND LOWER(item_name)=LOWER(%s)", (fac, name))
        if r and (size or "").strip():
            want = norm_size(size)
            exact = [x for x in r if norm_size(x["size"]) == want]
            blank = [x for x in r if not str(x["size"] or "").strip()]
            r = exact or blank
        if r:
            return r[0]
        nn = norm_name(name)
        for a in alias_rows(fac):
            if a["alias_norm"] == nn:
                r = q("SELECT sl_no, prod_id, item_name FROM inventory WHERE factory_name=%s AND sl_no=%s", (fac, a["sl_no"]))
                if r:
                    return r[0]
    return None


_UNCAT = "Uncategorized (Edit Later)"


def req_departments(fac=None):
    """Departments for the Requisition screens: the standard list + every department already used in a requisition
    (e.g. RND) + every department that has a Budget line. Nothing is removed from DEPARTMENTS."""
    fsql, fp = fw(fac)
    out, seen = list(DEPARTMENTS), {d.lower() for d in DEPARTMENTS}
    for sql in (f"SELECT DISTINCT department AS d FROM requisition_tracking WHERE COALESCE(department,'')<>''{fsql}",
                f"SELECT DISTINCT department_name AS d FROM category_budgets WHERE COALESCE(department_name,'')<>''{fsql}"):
        try:
            rows = q_c(sql, fp)
        except Exception:
            rows = []
        for r in rows:
            d = _clean(r["d"])
            if d and d.lower() not in seen:
                seen.add(d.lower())
                out.append(d)
    return out


def budget_line_map(fac=None):
    """{Budget category: Budget department} straight from the Budget tab (category_budgets)."""
    fsql, fp = fw(fac)
    try:
        rows = q_c(f"SELECT category_name, department_name FROM category_budgets WHERE 1=1{fsql} "
                   "ORDER BY department_name, category_name", fp)
    except Exception:
        return {}
    out = {}
    for r in rows:
        c = _clean(r["category_name"])
        if c and c not in out:
            out[c] = _clean(r["department_name"])
    return out


_BC_STOP = {"item", "items", "goods", "and", "others", "other", "the", "of"}


def _bc_words(t):
    return {w for w in re.sub(r"[^a-z0-9]+", " ", str(t or "").lower()).split() if w and w not in _BC_STOP}


def guess_budget_category(cats, *hints):
    """'Production Consumable' (PDF line 'Category : ...') -> 'Production Consumable Items'. Returns '' when nothing
    matches or when two Budget lines match equally (the person then picks)."""
    for h in hints:
        hw = _bc_words(h)
        if not hw:
            continue
        hit = [c for c in cats if hw <= _bc_words(c)]
        if len(hit) == 1:
            return hit[0]
    return ""


def inv_budget_category(fac, sl=None, code=""):
    """Current Budget category (inventory.category) of an existing item; '' if none / not found."""
    try:
        if sl is not None:
            r = q("SELECT COALESCE(category,'') AS c FROM inventory WHERE factory_name=%s AND sl_no=%s", (fac, int(sl)))
        elif not is_blank_code(code):
            r = q("SELECT COALESCE(category,'') AS c FROM inventory WHERE factory_name=%s AND prod_id=%s", (fac, code))
        else:
            return ""
    except Exception:
        return ""
    return _clean(r[0]["c"]) if r else ""


@tx
def import_requisition(fac, rows, create_items):
    new_items = 0
    bmap = budget_line_map(fac)
    for p in rows:
        inv = None
        if p.get("use_sl"):   # the person chose an existing (similar) item for this line -> no new item; remember the name
            r = q("SELECT sl_no, prod_id, item_name FROM inventory WHERE factory_name=%s AND sl_no=%s", (fac, int(p["use_sl"])))
            if r:
                inv = r[0]
                if norm_name(p["item"]) and norm_name(p["item"]) != norm_name(inv["item_name"]):
                    run("""INSERT INTO item_aliases (factory_name, alias_name, alias_norm, sl_no, created_by, created_at)
                           VALUES (%s,%s,%s,%s,%s,%s) ON CONFLICT (factory_name, alias_norm, sl_no) DO NOTHING""",
                        (fac, p["item"].strip(), norm_name(p["item"]), int(inv["sl_no"]), st.session_state.get("user", ""),
                         local_now().strftime("%d-%b-%Y %I:%M %p")))
        if inv is None:
            inv = find_inv_for_req(fac, p["code"], p["item"], p.get("size", ""))
        bcat = _clean(p.get("bud_cat"))
        if inv:
            code = inv["prod_id"]
            cur_cat = inv_budget_category(fac, sl=inv["sl_no"])
            if cur_cat and cur_cat != _UNCAT:
                bcat = cur_cat              # Budget always follows the ITEM's own Budget line - never overwritten here
            elif bcat:                      # item had no Budget line yet -> give it the one chosen on this requisition
                run("UPDATE inventory SET category=%s WHERE factory_name=%s AND sl_no=%s", (bcat, fac, int(inv["sl_no"])))
                audit("SET_BUDGET_CAT", f"{fac}: {inv['item_name']} category '{cur_cat}' -> '{bcat}' (requisition import)")
        elif create_items:
            code = create_req_item(fac, p["code"], p["item"], p["dept"], p.get("size", ""), p.get("uom", ""),
                                   cat=bcat, inv_dept=bmap.get(bcat, ""))
            new_items += 1
        else:
            code = p["code"]
        run("""INSERT INTO requisition_tracking (factory_name, req_no, department, req_date, item_name, req_qty,
               audit_approved_qty, actual_received_qty, status, po_delay_days, prod_id, size, uom, budget_category)
               VALUES (%s,%s,%s,%s,%s,%s,0,0,'Req Created - Audit Pending',0,%s,%s,%s,%s)""",
            (fac, p["req_no"], p["dept"], p["date"], p["item"], p["qty"], code,
             (p.get("size") or "").strip(), (p.get("uom") or "").strip(), bcat))
    audit("IMPORT_REQUISITION", f"Imported {len(rows)} line(s) into {fac}, new items {new_items}")
    return new_items


@tx
def set_req_line_budget(fac, lines):
    """lines = [(req_no, item, size, budget category)] -> sets the Budget category of ALREADY imported requisition lines.
    The item itself only gets it when it has no real Budget line yet."""
    n = 0
    for req_no, item, size, cat in lines:
        sql = "SELECT id, COALESCE(prod_id,'') AS prod_id FROM requisition_tracking WHERE factory_name=%s AND req_no=%s AND LOWER(item_name)=LOWER(%s)"
        prm = [fac, req_no, item]
        if (size or "").strip():
            sql += " AND (COALESCE(size,'')='' OR LOWER(size)=LOWER(%s))"
            prm.append(size.strip())
        for r in q(sql, tuple(prm)):
            run("UPDATE requisition_tracking SET budget_category=%s WHERE id=%s", (cat, r["id"]))
            if not is_blank_code(r["prod_id"]):
                run("""UPDATE inventory SET category=%s WHERE factory_name=%s AND prod_id=%s
                       AND (COALESCE(category,'')='' OR category=%s)""", (cat, fac, r["prod_id"], _UNCAT))
            n += 1
    audit("SET_REQ_BUDGET_CAT", f"{fac}: Budget category set on {n} imported requisition line(s)")
    return n or None


def find_header_row(raw):
    allk = {k for ks in REQ_KEYS.values() for k in ks}
    best, bi = 0, 0
    for i in range(min(25, len(raw))):
        s = sum(1 for v in raw.iloc[i] if norm_col(txt(v)) in allk)
        if s > best:
            best, bi = s, i
    return bi


def auto_map(heads):
    norm = [norm_col(h) for h in heads]
    mp, used = {}, set()
    for field, keys in REQ_KEYS.items():
        for k in keys:
            hit = next((i for i, n in enumerate(norm) if n == k and i not in used), None)
            if hit is not None:
                mp[field] = hit
                used.add(hit)
                break
    return mp


_PDF_UNITS = (r"(?:METERS?|MTRS?|MTR|PCS|PC|PIECES?|KGS?|LTRS?|LITERS?|LITRES?|SETS?|NOS|NO|ROLLS?|BOX(?:ES)?|PAIRS?|FEET|FT|DRUMS?|"
              r"COILS?|BAGS?|CARTONS?|CTNS?|DOZEN|GMS?|TONS?|SQM|SFT|YARDS?|BUNDLES?|PACKETS?|PKT|CAN|BOTTLES?|TUBES?)")
_PDF_ITEM_RE = re.compile(r"^(?:(?P<sl>\d{1,3})[.)]?\s+)?(?P<item>(?=.*[A-Za-z]).+?)\s+(?P<qty>\d+(?:,\d{3})*(?:\.\d+)?)\s+(?P<unit>"
                          + _PDF_UNITS + r")\b\s*(?P<rem>.*)$", re.I)


def _pdf_item_lines(text):
    """Challan / PO / requisition PDFs that are not ruled tables (e.g. a scanned challan): finds lines shaped like
    '<item name>  <qty>  <unit>  <remarks>' and returns grid rows [SL, Item, Qty, Unit, Remarks]."""
    out, seen = [], set()
    for ln in str(text or "").splitlines():
        m = _PDF_ITEM_RE.match(ln.strip())
        if not m:
            continue
        item = re.sub(r"\s+", " ", m.group("item")).strip(" :-")
        qty = m.group("qty").replace(",", "")
        key = (re.sub(r"[^a-z0-9]", "", item.lower()), qty)
        if len(item) < 3 or key in seen:
            continue
        seen.add(key)
        out.append([str(len(out) + 1), item, qty, m.group("unit").upper(), m.group("rem").strip()])
    return out


def pdf_to_raw(upload):
    """Reads a requisition PDF into a plain grid (list of rows) so the normal Excel/CSV import steps can be used on it.
    Tables are read with pdfplumber when installed; otherwise (or when the PDF has no ruled table) the text lines are split
    on 2+ spaces with pypdf. Returns (DataFrame or None, {'req_no':..., 'date':...}, error text)."""
    data = upload.getvalue()
    rows, text, ltext = [], "", ""
    try:
        import pdfplumber
        with pdfplumber.open(io.BytesIO(data)) as pdf:
            for pg in pdf.pages:
                text += (pg.extract_text() or "") + "\n"
                try:   # layout text keeps the gaps between columns (used when the PDF has no ruled table)
                    ltext += (pg.extract_text(layout=True) or "") + "\n"
                except Exception:
                    pass
                for tb in pg.extract_tables() or []:
                    rows += [[("" if c is None else str(c).replace("\n", " ").strip()) for c in r] for r in tb if r]
    except ImportError:
        rows = []
    except Exception as e:
        return None, {}, f"PDF পড়া যায়নি: {e}"
    if len(rows) < 2:   # no ruled table found: use the text lines
        rows = []
        try:
            if not ltext:
                from pypdf import PdfReader
                for pg in PdfReader(io.BytesIO(data)).pages:
                    try:   # layout mode keeps the column gaps, so each line can be split into cells
                        ltext += (pg.extract_text(extraction_mode="layout") or "") + "\n"
                    except TypeError:
                        ltext += (pg.extract_text() or "") + "\n"
                text = text or ltext
        except ImportError:
            return None, {}, "PDF পড়ার লাইব্রেরি নেই — requirements.txt-এ `pdfplumber` (বা `pypdf`) যোগ করে redeploy করুন।"
        except Exception as e:
            return None, {}, f"PDF পড়া যায়নি: {e}"
        found = _pdf_item_lines(text or ltext)
        if found:
            rows = [["SL#", "Item Description", "Quantity", "Unit", "Remarks"]] + found
        else:
            for ln in ltext.splitlines():
                parts = [p.strip() for p in re.split(r"\s{2,}|\t", ln) if p.strip()]
                if len(parts) >= 2:
                    rows.append(parts)
    if not rows:
        return None, {}, "PDF থেকে কোনো লেখা/টেবিল পাওয়া যায়নি (স্ক্যান করা ছবির PDF হতে পারে) — Excel/CSV ব্যবহার করুন।"
    w = max(len(r) for r in rows)
    raw = pd.DataFrame([r + [""] * (w - len(r)) for r in rows])
    meta = {}
    m = re.search(r"(?:requisition|req\.?)\s*(?:no\.?|number|#)\s*[:\-]?\s*#?\s*([A-Za-z0-9][A-Za-z0-9\-/]*)", text, re.I)
    if m:
        meta["req_no"] = m.group(1)
    m = re.search(r"department\s*:\s*(.+?)\s+(?:section|store\s*name)\s*:", text.replace("\n", " "), re.I) \
        or re.search(r"department\s*:\s*([^\n]+)", text, re.I)
    if m and _clean(m.group(1)):
        meta["dept"] = _clean(m.group(1))
    m = re.search(r"date\s*[:\-]?\s*(\d{1,2}[-/ ][A-Za-z]{3}[-/ ]\d{4}|\d{1,2}[-/]\d{1,2}[-/]\d{4}|\d{4}-\d{2}-\d{2})", text, re.I)
    if m:
        d = parse_date(m.group(1).replace(" ", "-"))
        if d:
            meta["date"] = d.date()
    return raw, meta, ""


def req_missing_items(fac):
    """Requisition lines whose item is NOT in Inventory (no inventory row with the line's ERP code). Read-only.
    Each row gets 'inv' = an existing inventory item found by name / size / alias (then it only needs linking) or None (then it needs creating)."""
    rows = q("""SELECT r.id, r.req_no, COALESCE(r.department,'') AS dept, r.item_name, COALESCE(r.size,'') AS size, COALESCE(r.uom,'') AS uom,
                       COALESCE(r.prod_id,'') AS prod_id, COALESCE(r.budget_category,'') AS bcat
                FROM requisition_tracking r
                WHERE r.factory_name=%s AND NOT EXISTS (SELECT 1 FROM inventory i WHERE i.factory_name=r.factory_name
                                                        AND COALESCE(r.prod_id,'')<>'' AND i.prod_id=r.prod_id)
                ORDER BY r.id DESC LIMIT 200""", (fac,))
    out = []
    for r in rows:
        r = dict(r)
        r["inv"] = find_inv_for_req(fac, "", r["item_name"], r["size"])
        out.append(r)
    return out


@tx
def req_sync_missing_items(fac, rows):
    """Creates the missing inventory items (ERP Pending, stock 0) for the requisition lines, or links the line to the existing item it matches."""
    bmap = budget_line_map(fac)
    made, linked, seen = 0, 0, {}
    for r in rows:
        k = (norm_name(r["item_name"]), norm_size(r["size"]))
        code = seen.get(k)
        if code is None:
            inv = find_inv_for_req(fac, "", r["item_name"], r["size"])
            if inv:
                code = inv["prod_id"]
                linked += 1
            else:
                bcat = _clean(r.get("bcat"))
                code = create_req_item(fac, "", r["item_name"], r["dept"], r["size"], r["uom"], cat=bcat, inv_dept=bmap.get(bcat, ""))
                made += 1
            seen[k] = code
        run("UPDATE requisition_tracking SET prod_id=%s WHERE id=%s", (code, r["id"]))
    audit("REQ_SYNC_ITEMS", f"{fac}: {made} new inventory item(s) created, {linked} requisition item(s) linked to existing items")
    return made, linked


def req_item_check_ui():
    if "CONSOLIDATED" in str(FAC):
        return
    miss = req_missing_items(FAC)
    if not miss:
        return
    with st.expander(f"🔎 Requisition-er {len({(norm_name(m['item_name']), norm_size(m['size'])) for m in miss})}ti item Inventory-te nei — check / add korun", expanded=True):
        st.caption("Ei item-gulo requisition-e ache kintu Inventory-te ERP code diye khuje paoa jayni, tai Stock / Stock Movement report-e ashche na. "
                   "Button chaple notun item (ERP Pending, stock 0) toiri hobe, ba ager moto nam-er item thakle seitar sathe link hobe.")
        st.dataframe(pd.DataFrame([{"Req No": m["req_no"], "Item": m["item_name"], "Size": m["size"], "Qty/UOM": m["uom"],
                                    "Inventory-te": (f"Ache: {m['inv']['item_name']} ({m['inv']['prod_id']}) - link hobe" if m["inv"] else "Nei - notun toiri hobe")}
                                   for m in miss]), hide_index=True, use_container_width=True, height=min(80 + 35 * len(miss), 300))
        if st.button("➕ Inventory-te add / link korun", type="primary", key="req_sync_btn") and guard():
            res = req_sync_missing_items(FAC, miss)
            if res is not None:
                done(f"Inventory update hoyeche: notun item {res[0]}, ager item-er sathe link {res[1]}.")


def req_import_view():
    f = st.file_uploader("ERP Requisition file (Excel / CSV / PDF)", type=["xlsx", "xls", "csv", "pdf"], key="req_file")
    if not f:
        return
    if f.name.lower().endswith(".pdf"):
        raw, meta, err = pdf_to_raw(f)
        if raw is None:
            st.error(err)
            return
        sig = f"{f.name}:{f.size}"
        if st.session_state.get("_req_pdf_sig") != sig:   # new PDF -> pre-fill Requisition No / date found in its text
            st.session_state["_req_pdf_sig"] = sig
            if meta.get("req_no"):
                st.session_state["req_fx_no"] = meta["req_no"]
            if meta.get("date"):
                st.session_state["req_fx_date"] = meta["date"]
            _dd = meta.get("dept", "")
            if _dd:   # keep the spelling of an existing department (RND == rnd); otherwise it is a new department
                _dd = next((d for d in req_departments(FAC) if d.lower() == _dd.lower()), _dd)
                st.session_state["req_fx_dept"] = _dd
            st.session_state["_req_pdf_dept"] = _dd
        st.caption("📄 PDF থেকে টেবিল পড়া হয়েছে — নিচে Header row ও কলাম মিলিয়ে নিন (PDF-এর ওপরের লেখা থেকে পাওয়া Requisition No / তারিখ নিচে বসানো হয়েছে, ভুল হলে বদলান)। "
                   "মিললে ‘Import requisition’ চাপুন।")
        with st.expander("PDF থেকে পড়া কাঁচা টেবিল"):
            st.dataframe(raw.head(80), hide_index=True, use_container_width=True)
    elif f.name.lower().endswith(".csv"):
        raw = pd.read_csv(f, header=None, dtype=object, keep_default_na=False)
    else:
        xls = pd.ExcelFile(f)
        raw = xls.parse(st.selectbox("Sheet", xls.sheet_names, key="req_sheet"), header=None, dtype=object)
    raw = raw.fillna("")
    hdr = st.number_input("Header row no. (column names ache je row-e)", 1, max(len(raw), 1),
                          find_header_row(raw) + 1, key="req_hdr")
    hi = int(hdr) - 1
    heads = [txt(v) for v in raw.iloc[hi]]
    labels = ["(none)"] + [f"{i + 1}: {h or '(blank)'}" for i, h in enumerate(heads)]
    auto = auto_map(heads)
    mp = {}
    cols = st.columns(3)
    for i, (key, label) in enumerate(REQ_FIELDS):
        default = labels[auto[key] + 1] if key in auto else "(none)"
        sel = cols[i % 3].selectbox(label, labels, index=labels.index(default), key=f"rmap_{key}_{hi}")
        mp[key] = int(sel.split(":")[0]) - 1 if sel != "(none)" else None
    c1, c2, c3 = st.columns(3)
    fx_no = c1.text_input("Requisition No (fallback)", f"RQSN-{datetime.now():%m%d-%H%M}", key="req_fx_no")
    _dopts = req_departments(FAC)
    _pd = st.session_state.get("_req_pdf_dept", "") if f.name.lower().endswith(".pdf") else ""
    if _pd and _pd.lower() not in {d.lower() for d in _dopts}:
        _dopts.append(_pd)
    if st.session_state.get("req_fx_dept") not in _dopts:
        st.session_state.pop("req_fx_dept", None)
    fx_dept = c2.selectbox("Department (fallback)", _dopts, key="req_fx_dept")
    _nd = c2.text_input("Notun Department (list-e na thakle likhun)", key="req_new_dept",
                        help="Requisition-er department (jemon RND). Budget category alada - ta line-wise niche bachai korben.")
    if _nd.strip():
        fx_dept = _nd.strip()
    fx_date = c3.date_input("Req date (fallback)", value=date.today(), key="req_fx_date")
    create = st.checkbox("Inventory-te na thaka item auto create korun", value=True, key="req_create")

    parsed, last, ncols = [], {"req_no": "", "dept": "", "date": ""}, raw.shape[1]
    cur_cat = ""

    def cell(row, field):
        ci = mp.get(field)
        return txt(row.iloc[ci]) if ci is not None and ci < ncols else ""

    for ridx in range(hi + 1, len(raw)):
        row = raw.iloc[ridx]
        item, code, qty_t = cell(row, "item"), cell(row, "code"), cell(row, "qty")
        size_t, uom_t = cell(row, "size"), cell(row, "uom")
        _cells = [txt(v) for v in row if txt(v)]
        _cm = re.match(r"^category\s*[:\-]\s*(.+)$", _cells[0], re.I) if _cells else None
        if _cm and not re.search(r"\d", qty_t):   # ERP group header row, e.g. "Category : Production Consumable"
            cur_cat = _clean(_cm.group(1))
            continue
        if code.upper() in ("N/A", "NA", "NONE", "-"):
            code = ""
        vals = {}
        for fld in ("req_no", "dept", "date"):
            if mp.get(fld) is not None and cell(row, fld):
                last[fld] = cell(row, fld)
            vals[fld] = last[fld] if mp.get(fld) is not None else ""
        if not item and not code and not qty_t:
            continue
        m = re.search(r"\d+(?:\.\d+)?", qty_t.replace(",", ""))
        qty = float(m.group()) if m else 0.0
        d = parse_date(vals["date"]) or datetime.combine(fx_date, datetime.min.time())
        p = {"line": ridx + 1, "req_no": vals["req_no"] or fx_no, "item": item, "code": code, "qty": qty,
             "size": size_t, "uom": uom_t,
             "dept": vals["dept"] or fx_dept, "date": d.strftime(DATE_FMT), "ok": False, "result": "",
             "cat_hint": cell(row, "cat") or cur_cat}
        if not item:
            p["result"] = "Skipped: item description nei"
        elif qty <= 0:
            p["result"] = "Skipped: Req Qty nei"
        elif q("SELECT 1 AS x FROM requisition_tracking WHERE factory_name=%s AND req_no=%s AND LOWER(item_name)=LOWER(%s)"
               + (" AND (COALESCE(size,'')='' OR LOWER(size)=LOWER(%s))" if size_t.strip() else ""),
               (FAC, p["req_no"], item) + ((size_t.strip(),) if size_t.strip() else ())):
            p["result"] = "Already imported"
        else:
            p["ok"] = True
            p["result"] = "OK"
        parsed.append(p)
    ok_rows = [p for p in parsed if p["ok"]]
    # ---- Similar-name check: a line that is NOT found in inventory but looks like an existing item ----
    sim_lines, sim_ack = [], True
    if create and ok_rows and "CONSOLIDATED" not in str(FAC):
        for p in ok_rows:
            try:
                if find_inv_for_req(FAC, p["code"], p["item"], p.get("size", "")) is None:
                    hits = similar_items(FAC, p["item"], p.get("size", ""), limit=4, threshold=0.75)
                    if hits:
                        sim_lines.append((p, hits))
            except Exception:
                pass
    if sim_lines:
        st.warning(f"⚠️ {len(sim_lines)} ti line-er nam inventory-r kono item-er proray hubohu mile gese. "
                   "Notun item toiri korar age niche dekhe nin - eta ki ager-i item? Ager item hole oita select korun "
                   "(notun duplicate item hobe na, ar ei nam pore auto-chinbe).")
        for p, hits in sim_lines:
            opts = {"➕ Notun item create korun": None}
            for sc, h in hits:
                opts[f"Use: {h['item_name']} [{h['size'] or '-'}]{_uom_tag(h)} · {h['prod_id']} · stock {float(h['stock']):g} · mil {int(round(sc * 100))}%"] = int(h["sl_no"])
            pick = st.selectbox(f"Line {p['line']}: {p['item']}" + (f" [{p['size']}]" if p.get("size") else ""), list(opts),
                                key=f"req_sim_{hi}_{p['line']}")
            p["use_sl"] = opts[pick]
            p["result"] = "OK (existing item chosen)" if opts[pick] else "OK (new item)"
        sim_ack = st.checkbox("Kachakachi item gulo dekhe nilam - jegulo notun, shegulo sotti-i alada item.", key=f"req_sim_ack_{hi}")
    # ---- Budget category per line: one requisition can hold lines of different Budget lines (e.g. Consumable + Electrical) ----
    bc_ok = True
    bmap = budget_line_map(FAC) if "CONSOLIDATED" not in str(FAC) else {}
    if ok_rows and bmap:
        bcats = list(bmap)
        ed_rows, locked = [], {}
        for p in ok_rows:
            cur = ""
            try:
                if p.get("use_sl"):
                    cur = inv_budget_category(FAC, sl=p["use_sl"])
                else:
                    _iv = find_inv_for_req(FAC, p["code"], p["item"], p.get("size", ""))
                    cur = inv_budget_category(FAC, sl=_iv["sl_no"]) if _iv else ""
                    status = "Inventory item" if _iv else "New item"
                if p.get("use_sl"):
                    status = "Inventory item"
            except Exception:
                status = "New item"
            is_lock = bool(cur) and cur != _UNCAT and cur in bmap
            locked[p["line"]] = cur if is_lock else ""
            ed_rows.append({"Line": p["line"], "Item": p["item"], "Size": p.get("size", ""), "Qty": p["qty"], "Item status": status,
                            "Budget Category": cur if is_lock else guess_budget_category(bcats, p.get("cat_hint", ""))})
        st.markdown("**💰 Budget Category (line-wise)** — Department: "
                    f"**{ok_rows[0]['dept']}** (requisition-er department). Budget category line-wise alada hote pare.")
        st.caption("Inventory-te thaka item-er Budget line oi item-er category theke ashe (ekhane bodlano jabe na — Budget line "
                   "fixer use korun). Notun / category-hin item-er jonno nijer Budget category bachai korun.")
        ed_in = pd.DataFrame(ed_rows)
        ed_out = st.data_editor(ed_in, hide_index=True, use_container_width=True,
                                height=min(80 + 35 * len(ed_in), 420),
                                key=f"req_bc_{hi}_{FAC}_{ok_rows[0]['req_no']}_{len(ok_rows)}",
                                disabled=["Line", "Item", "Size", "Qty", "Item status"],
                                column_config={"Budget Category": st.column_config.SelectboxColumn(
                                    "Budget Category", options=[""] + bcats)})
        picked = {int(r["Line"]): _clean(r["Budget Category"]) for _, r in ed_out.iterrows()}
        for p in ok_rows:
            p["bud_cat"] = locked[p["line"]] or picked.get(p["line"], "")
        need = [p for p in ok_rows if not p["bud_cat"] and (create or locked[p["line"]])]
        need = [p for p in need if not locked[p["line"]]]
        if need:
            bc_ok = False
            st.warning(f"⚠️ {len(need)} ti line-er Budget Category bachai kora hoyni (Line: "
                       + ", ".join(str(p["line"]) for p in need) + ").")
        summ = {}
        for p in ok_rows:
            g = summ.setdefault(p["bud_cat"] or "(bachai hoyni)", [0, 0.0])
            g[0] += 1
            g[1] += p["qty"]
        st.caption("Budget-wise: " + " | ".join(f"{k}: {v[0]} line, qty {v[1]:g}" for k, v in summ.items()))
    # ---- Lines that were imported earlier: their Budget category can still be set / changed here ----
    dup_rows = [p for p in parsed if p["result"] == "Already imported"]
    if dup_rows and bmap:
        bcats = list(bmap)
        st.info(f"ℹ️ {len(dup_rows)} ti line age-i import kora ache. Tader Budget Category ekhan theke bachai / thik korte parben.")
        d_rows, d_lock = [], {}
        for p in dup_rows:
            ex = q("SELECT COALESCE(budget_category,'') AS b, COALESCE(prod_id,'') AS pid FROM requisition_tracking "
                   "WHERE factory_name=%s AND req_no=%s AND LOWER(item_name)=LOWER(%s) ORDER BY id DESC LIMIT 1",
                   (FAC, p["req_no"], p["item"]))
            ic = inv_budget_category(FAC, code=ex[0]["pid"]) if ex else ""
            lk = bool(ic) and ic != _UNCAT and ic in bmap
            d_lock[p["line"]] = ic if lk else ""
            cur = ic if lk else ((ex[0]["b"] if ex else "") or guess_budget_category(bcats, p.get("cat_hint", "")))
            d_rows.append({"Line": p["line"], "Item": p["item"], "Size": p.get("size", ""), "Qty": p["qty"],
                           "Item status": "Budget line fixed by item" if lk else "Choose", "Budget Category": cur})
        d_in = pd.DataFrame(d_rows)
        d_out = st.data_editor(d_in, hide_index=True, use_container_width=True, height=min(80 + 35 * len(d_in), 320),
                               key=f"req_dup_{hi}_{FAC}_{dup_rows[0]['req_no']}_{len(dup_rows)}",
                               disabled=["Line", "Item", "Size", "Qty", "Item status"],
                               column_config={"Budget Category": st.column_config.SelectboxColumn("Budget Category", options=[""] + bcats)})
        d_pick = {int(r["Line"]): _clean(r["Budget Category"]) for _, r in d_out.iterrows()}
        if st.button("💾 Budget Category save (age import kora line)", key="req_dup_bc_btn"):
            chg = [(p["req_no"], p["item"], p.get("size", ""), d_lock[p["line"]] or d_pick.get(p["line"], "")) for p in dup_rows]
            chg = [c for c in chg if c[3]]
            if not chg:
                st.error("Kono Budget Category bachai kora hoyni.")
            elif set_req_line_budget(FAC, chg):
                done(f"Budget Category save hoyeche ({len(chg)} line).")
    _new_names = []
    if "CONSOLIDATED" not in str(FAC):
        for p in parsed:
            if not p["ok"]:
                continue
            try:
                inv_ = find_inv_for_req(FAC, p["code"], p["item"], p.get("size", ""))
            except Exception:
                inv_ = None
            if p.get("use_sl"):
                p["inventory"] = "Existing item chosen"
            elif inv_:
                p["inventory"] = f"In inventory: {inv_['prod_id']}"
            elif create:
                p["inventory"] = "NEW - will be added to inventory (ERP Pending)"
                _new_names.append(p["item"] + (f" [{p['size']}]" if p.get("size") else ""))
            else:
                p["inventory"] = "NOT in inventory - NOT created (tick the box above)"
    st.caption(f"Lines to import: {len(ok_rows)} | Skipped/already: {len(parsed) - len(ok_rows)}"
               + (f" | New inventory items: {len(_new_names)}" if _new_names else ""))
    st.dataframe(pd.DataFrame(parsed).drop(columns=["cat_hint"], errors="ignore"), hide_index=True, use_container_width=True)
    if st.button("✅ Import requisition", type="primary", disabled=not (ok_rows and sim_ack and bc_ok), key="req_import_btn"):
        n = import_requisition(FAC, ok_rows, create)
        if n is not None:
            done(f"Requisition import done: {len(ok_rows)} line(s), new inventory items {n}"
                 + (f" ({', '.join(_new_names[:6])}{'...' if len(_new_names) > 6 else ''})" if _new_names else "")
                 + ". Audit approved qty 0 - Officer / Manager approve korbe.")


def sourcing_email(rows, fac_label, sender, role):
    a = [r for r in rows if r["pending"] > 0 and not r["has_po"] and r["aud_qty"] > 0]
    b = [r for r in rows if r["pending"] > 0 and r["has_po"]]
    if not a and not b:
        return None

    def block(items, mode):
        out = []
        for n, r in enumerate(sorted(items, key=lambda x: -x["age"]), 1):
            code = r["prod_id"] if r["prod_id"] and not r["prod_id"].upper().startswith("TEMP-") else "ERP code awaited"
            aging = (f"Pending for {r['age']} day(s) since requisition" if mode == "A"
                     else f"PO Date: {r['po_date']} | Waiting {r['since_po']} day(s) since PO")
            out.append(f"{n}. {r['item_name']} (ERP: {code})\n   Req No: {r['req_no']} | Req Date: {r['req_date']}\n"
                       f"   Approved: {r['aud_qty']:g} | Received: {r['rec_qty']:g} | PENDING: {r['pending']:g}\n   {aging}")
        return "\n\n".join(out)

    lines = ["Dear Sourcing Manager,", "", f"Greetings from {fac_label} Store.", ""]
    if a:
        lines += [f"The following {len(a)} audit-approved requisition item(s) are still waiting for Purchase Order (PO) issuance. "
                  "Material delivery and GRN are on hold due to the PO delay.", "", "A. PO NOT YET RECEIVED",
                  "-" * 40, block(a, "A"), ""]
    if b:
        lines += [("Additionally, " if a else "") + f"the following {len(b)} item(s) have PO issued but delivery/GRN is pending:",
                  "", "B. PO ISSUED - DELIVERY / GRN PENDING", "-" * 40, block(b, "B"), ""]
    total = sum(r["pending"] for r in a + b)
    lines += [f"Total items: {len(a) + len(b)} | Total pending qty: {total:g}", "",
              "We would appreciate it if you could expedite the PO process and share the expected PO date and delivery schedule.",
              "", "Thank you for your kind support.", "", "Best regards,", sender, f"{role}, {fac_label}",
              f"Date: {datetime.now().strftime(DATE_FMT)}"]
    return "\n".join(lines)


@tx
def can_set_audit_qty():
    """Any working officer / manager / executive may enter the Audit Approved Qty; the view-only roles may not."""
    return st.session_state.get("role") not in NEW_RO_ROLES


def set_audit_qty(rid, new_q, old_q, name, req_no):
    run("UPDATE requisition_tracking SET audit_approved_qty=%s WHERE id=%s", (new_q, rid))
    audit("EDIT_AUDIT_APPROVED", f"Req {req_no} / {name}: approved {old_q:g} -> {new_q:g}")
    return True


@tx
def set_po_receiving(rid, po_s, rec_q, rec_s, req_no, name):
    run("UPDATE requisition_tracking SET po_date=%s, actual_received_qty=%s, received_date=%s WHERE id=%s",
        (po_s, rec_q, rec_s, rid))
    audit("UPDATE_REQ_TRACKING", f"Req {req_no} / {name}: PO={po_s}, received={rec_q:g}")
    return True


@tx
def edit_requisition(rid, req_no, dept, req_date, req_qty, item, code, old_code, bud_cat=None):
    if code and code != old_code:
        if q("SELECT item_name FROM inventory WHERE factory_name=%s AND prod_id=%s", (FAC, code)):
            st.error(f"ERP Code '{code}' already used in {FAC}.")
            return False
        run("UPDATE inventory SET prod_id=%s WHERE factory_name=%s AND prod_id=%s", (code, FAC, old_code))
        run("UPDATE transactions SET prod_id=%s WHERE factory_name=%s AND prod_id=%s", (code, FAC, old_code))
    run("""UPDATE requisition_tracking SET req_no=%s, department=%s, req_date=%s, req_qty=%s, item_name=%s, prod_id=%s
           WHERE id=%s""", (req_no, dept, req_date, req_qty, item, code or old_code, rid))
    if bud_cat is not None:
        run("UPDATE requisition_tracking SET budget_category=%s WHERE id=%s", (bud_cat, rid))
        if bud_cat:   # only an item that has no real Budget line yet gets this one
            run("""UPDATE inventory SET category=%s WHERE factory_name=%s AND prod_id=%s
                   AND (COALESCE(category,'')='' OR category=%s)""", (bud_cat, FAC, code or old_code, _UNCAT))
    audit("EDIT_REQUISITION", f"Req ID {rid}: {req_no} / {item}")
    return True


@tx
def delete_requisition(rid, req_no, name):
    run("DELETE FROM requisition_tracking WHERE id=%s", (rid,))
    audit("DELETE_REQUISITION", f"Deleted requisition {req_no} - {name}")
    return True


def _req_item_summary(rows):
    """Item-wise view: for every item, how much was requested, approved, received and what is still pending."""
    cons = "CONSOLIDATED" in str(FAC)
    groups = {}
    for r in rows:
        code = str(r["prod_id"] or "").strip()
        key = (r["factory_name"] if cons else "", code or ("name:" + str(r["item_name"]).strip().lower()))
        g = groups.setdefault(key, {"Unit": r["factory_name"], "Item": r["item_name"], "Size": r.get("size") or "", "ERP Code": code, "Requisitions": 0,
                                    "Req Qty": 0.0, "Approved": 0.0, "Received": 0.0, "Pending": 0.0, "base": 0.0, "age": 0})
        g["Requisitions"] += 1
        g["Req Qty"] += r["req_qty"]
        g["Approved"] += r["aud_qty"]
        g["Received"] += r["rec_qty"]
        g["Pending"] += r["pending"]
        g["base"] += r["base"]
        if r["pending"] > 0:
            g["age"] = max(g["age"], r["age"])
    items = list(groups.values())
    for g in items:
        g["Received %"] = min(g["Received"] / g["base"] * 100.0, 100.0) if g["base"] > 0 else 0.0
        g["Oldest pending (days)"] = g["age"] if g["Pending"] > 0 else 0
        g["Status"] = ("✅ Fully received" if g["Pending"] <= 0 and g["Received"] > 0
                       else "🟠 Partly received" if g["Received"] > 0 else "🔴 Nothing received yet")
    show = st.radio("Show", ["Pending ache emon item", "Shob item", "Fully received"], horizontal=True, key="req_item_filter")
    if show.startswith("Pending"):
        items = [g for g in items if g["Pending"] > 0]
    elif show.startswith("Fully"):
        items = [g for g in items if g["Pending"] <= 0]
    if not items:
        st.info("Ei filter-e kono item nei.")
        return
    items.sort(key=lambda g: (-g["Pending"], g["Item"]))
    st.caption(f"Items: {len(items):,} | Requested: {sum(g['Req Qty'] for g in items):,.0f} | "
               f"Approved: {sum(g['Approved'] for g in items):,.0f} | Received: {sum(g['Received'] for g in items):,.0f} | "
               f"Pending: {sum(g['Pending'] for g in items):,.0f}")
    cols = ["Item", "Size", "ERP Code", "Requisitions", "Req Qty", "Approved", "Received", "Pending", "Received %", "Oldest pending (days)", "Status"]
    if cons:
        cols = ["Unit"] + cols
    df = pd.DataFrame(items)[cols]
    st.dataframe(df, hide_index=True, use_container_width=True, height=min(80 + 35 * len(df), 460),
                 column_config={"Received %": st.column_config.ProgressColumn("Received %", min_value=0, max_value=100, format="%.0f%%"),
                                "Req Qty": st.column_config.NumberColumn(format="%.2f"),
                                "Approved": st.column_config.NumberColumn(format="%.2f"),
                                "Received": st.column_config.NumberColumn(format="%.2f"),
                                "Pending": st.column_config.NumberColumn(format="%.2f")})
    export_buttons(df, "requisition_item_summary")
    names = [f"{g['Item']} · {g['ERP Code'] or 'no code'}" + (f" · {g['Unit']}" if cons else "") for g in items]
    pick = st.selectbox("🔎 Kon item-er requisition gulo dekhben?", names, key="req_item_pick")
    g = items[names.index(pick)]
    detail = [r for r in rows
              if (not cons or r["factory_name"] == g["Unit"])
              and ((str(r["prod_id"] or "").strip() == g["ERP Code"] and g["ERP Code"])
                   or (not g["ERP Code"] and str(r["item_name"]).strip().lower() == str(g["Item"]).strip().lower()))]
    detail.sort(key=lambda r: parse_date(r["req_date"]) or datetime.max)
    st.dataframe(pd.DataFrame([{"Req No": r["req_no"], "Req Date": r["req_date"], "Department": r["department"], "Size": r.get("size") or "",
                                "Req Qty": r["req_qty"], "Approved": r["aud_qty"], "Received": r["rec_qty"], "Pending": r["pending"],
                                "PO Date": r["po_date"] or "Pending PO", "Last received": r["received_date"] or "",
                                "Status": r["calc_status"]} for r in detail]),
                 hide_index=True, use_container_width=True, height=min(80 + 35 * len(detail), 320))
    st.caption("Approve / PO date / Edit korte upore '🧾 Requisition-wise' view-e jan.")


