def guess_uom(name, stock):
    n = " " + str(name or "").lower()
    if "filter" not in n and any(k in n for k in DS_KG_KEYWORDS):
        return "Kg"
    try:
        if stock is not None and abs(float(stock) - round(float(stock))) > 1e-9:
            return "Kg"
    except (TypeError, ValueError):
        pass
    return "Pcs"


def autoset_uom_once():
    if st.session_state.get("_uom_checked") or _once_flags().get("uom_autoset"):
        st.session_state["_uom_checked"] = True
        return
    if q("SELECT 1 AS x FROM req_settings WHERE setting_key='uom_autoset_v1' AND setting_value='done'"):
        st.session_state["_uom_checked"] = True
        _once_flags()["uom_autoset"] = True
        return

    @tx
    def _do():
        for r in q("""SELECT sl_no, factory_name, item_name, COALESCE(current_stock,0) AS stock,
                      COALESCE(NULLIF(unit_name,''),'Pcs') AS unit FROM inventory"""):
            if r["unit"] == "Pcs" and guess_uom(r["item_name"], r["stock"]) == "Kg":
                run("UPDATE inventory SET unit_name='Kg' WHERE sl_no=%s AND factory_name=%s", (r["sl_no"], r["factory_name"]))
        run("""INSERT INTO req_settings (setting_key, setting_value) VALUES ('uom_autoset_v1','done')
               ON CONFLICT (setting_key) DO UPDATE SET setting_value='done'""")
        return True
    if _do():
        st.session_state["_uom_checked"] = True


def daily_rows(d, fac, show_all):
    # the day may have been saved in any of the date formats the app accepts
    ds_all = [d.strftime(f) for f in ("%d-%b-%Y", "%d-%m-%Y", "%Y-%m-%d", "%d/%m/%Y")]
    rows = q_c("""SELECT i.sl_no, COALESCE(i.serial_no,'') AS serial, i.item_name, COALESCE(i.size,'') AS size,
                COALESCE(NULLIF(i.unit_name,''),'Pcs') AS unit,
                COALESCE(i.current_stock,0) AS cur, COALESCE(i.erp_stock,0) AS erp,
                COALESCE(d.issue,0) AS issue, COALESCE(d.recv,0) AS recv
                FROM inventory i
                LEFT JOIN (SELECT sl_no,
                                  SUM(CASE WHEN trans_type IN ('Issued','Internal Issue') THEN qty ELSE 0 END) AS issue,
                                  SUM(CASE WHEN trans_type IN ('Supplier. Rec','Internal Rec') THEN qty ELSE 0 END) AS recv
                           FROM transactions WHERE factory_name=%s AND date IN %s GROUP BY sl_no) d ON d.sl_no=i.sl_no
                WHERE i.factory_name=%s ORDER BY i.sl_no""", (fac, tuple(ds_all), fac))
    out = []
    for r in rows:
        cur, erp = float(r["cur"] or 0), float(r["erp"] or 0)
        diff = round(cur - erp, 4)
        short, exc = (abs(diff) if diff < 0 else 0.0), (diff if diff > 0 else 0.0)
        if not show_all and abs(cur) < 1e-9 and short == 0 and exc == 0 and float(r["issue"] or 0) <= 0 and float(r["recv"] or 0) <= 0:
            continue
        out.append({"SL No.": r["sl_no"], "Serial No": r["serial"], "Item Name": r["item_name"], "Size": r["size"], "Unit": r["unit"],
                    "Current Stock": cur, "Daily Issue": float(r["issue"] or 0), "Daily Received": float(r["recv"] or 0),
                    "Short Qty": short, "Excess Qty": exc})
    return pd.DataFrame(out)


@tx
def set_uom(fac, sl, name, unit, same_name):
    if same_name:
        run("UPDATE inventory SET unit_name=%s WHERE LOWER(TRIM(item_name))=LOWER(TRIM(%s))", (unit, name))
    else:
        run("UPDATE inventory SET unit_name=%s WHERE sl_no=%s AND factory_name=%s", (unit, sl, fac))
    audit("EDIT_UOM", f"{name}: UOM -> {unit}")
    return True


def sheet_html(d, fac, df, auto):
    esc = html_lib.escape
    body = ""
    for _, r in df.iterrows():
        cls = "short" if r["Short Qty"] > 0 else ("excess" if r["Excess Qty"] > 0 else "")
        issue_txt = f"{r['Daily Issue']:g}" if auto else ""
        recv_txt = f"{r['Daily Received']:g}" if auto else ""
        body += (f"<tr class='{cls}'><td>{r['SL No.']}</td>"
                 f"<td>{esc(str(r['Serial No'] or '-'))}</td>"
                 f"<td style='text-align:left'>{esc(str(r['Item Name']))}</td>"
                 f"<td>{esc(str(r['Size'] or '-'))}</td><td>{esc(str(r['Unit']))}</td>"
                 f"<td>{r['Current Stock']:g}</td><td>{issue_txt}</td><td>{recv_txt}</td>"
                 f"<td>{r['Short Qty']:g}</td><td>{r['Excess Qty']:g}</td></tr>")
    return f"""<!DOCTYPE html><html><head><meta charset="utf-8"><title>Daily Work Sheet</title>
<style>@page {{ size: A4 portrait; margin: 10mm; }} body {{ font-family: Arial; font-size: 11px; }}
h2 {{ text-align:center; color:#C2410C; margin:0; }} p {{ text-align:center; margin:4px 0 10px; }}
table {{ width:100%; border-collapse:collapse; }}
th {{ background:#E8590C; color:#fff; padding:4px; border:1px solid #333; }}
td {{ border:1px solid #333; padding:3px 4px; text-align:center; }}
tr.short td {{ background:#fde8e8; }} tr.excess td {{ background:#fff3e0; }}</style></head><body>
<h1 style="text-align:center;margin:0 0 2px;font-size:20px">{esc(fac)}</h1>
<h2>Daily Issue Status For Month: {d.strftime('%B-%Y')}</h2>
<p style="font-size:13px"><b>Date:</b> {d.strftime(DATE_FMT)} &nbsp; <b>Unit:</b> {esc(fac)}</p>
<table><thead><tr><th>SL No.</th><th>Serial No</th><th>Item Name</th><th>Size</th><th>Unit</th><th>Current Stock</th>
<th>Daily Issue</th><th>Daily Received</th><th>Short Qty</th><th>Excess Qty</th></tr></thead>
<tbody>{body}</tbody></table>
</body></html>"""


def _tab_daily_sheet_inner():
    with st.container(border=True):
        c1, c2, c3, c4 = st.columns([1, 2, 1, 1])
        d = c1.date_input("Date", value=local_now().date(), key="ds_date")
        ds_opts = [FAC] if unit_lock_active() and FAC in FACTORIES else FACTORIES   # an officer's sheet stays on the locked unit
        fac = c2.selectbox("Factory", ds_opts, index=ds_opts.index(FAC) if FAC in ds_opts else 0, key="ds_fac")
        show_all = c3.checkbox("Include zero-stock", key="ds_all")
        auto = c4.checkbox("Auto-fill issue/received", key="ds_auto")
    ds_term = st.text_input("🔍 Search (Serial No / Item / Size / SL No)", key="ds_search",
                            placeholder="Serial No likhe khujun, e.g. KW-001")
    df = daily_rows(d, fac, show_all or bool(ds_term.strip()))
    shown = df
    if ds_term.strip() and not df.empty:
        tl = ds_term.strip().lower()
        m = df[["Serial No", "Item Name", "Size"]].astype(str).apply(
            lambda c: c.str.lower().str.contains(tl, regex=False)).any(axis=1)
        shown = df[m | (df["SL No."].astype(str) == tl)]
    st.markdown(f'<div class="section-title">{html_lib.escape(fac)} — Daily Issue Status — Date: {d.strftime(DATE_FMT)} '
                f'(Month: {d.strftime("%B-%Y")})</div>', unsafe_allow_html=True)
    n_short = int((df["Short Qty"] > 0).sum()) if not df.empty else 0
    n_exc = int((df["Excess Qty"] > 0).sum()) if not df.empty else 0
    st.caption(f"Date: {d.strftime(DATE_FMT)} | Factory: {fac} | SL No = Master Inventory SL (same as Transactions). "
               f"Items: {len(df)} | Short: {n_short} | Excess: {n_exc}")
    view = shown.copy()
    if not auto and not view.empty:
        view["Daily Issue"] = ""
        view["Daily Received"] = ""
    st.dataframe(view, hide_index=True, use_container_width=True, height=420)
    exp = view.copy()
    if not exp.empty:
        exp.insert(0, "Date", d.strftime(DATE_FMT))
        exp.insert(0, "Factory", fac)   # the sheet already has a "Unit" (UOM) column, so this one is called Factory
    export_buttons(exp, f"daily_work_sheet_{short_fac(fac)}_{d:%Y%m%d}",
                   title=f"Daily Work Sheet - {fac} - Date: {d.strftime(DATE_FMT)}")
    st.download_button("🖨️ Download print sheet (HTML → open & Print)", sheet_html(d, fac, df, auto),
                       f"Daily_Work_Sheet_{d:%Y%m%d}.html", "text/html")
    with st.expander("✏️ Edit UOM"):
        if guard():
            opts = inv_options(fac)
            if opts:
                r = opts[st.selectbox("Item", list(opts), key="uom_item")]
                uom_list = get_uoms()
                cur_unit = r["unit_name"] if r["unit_name"] in uom_list else uom_list[0]
                unit = st.selectbox("UOM", uom_list, index=uom_list.index(cur_unit), key="uom_val")
                same = st.checkbox("Apply to every item with this name (both factories)", value=True, key="uom_same")
                if st.button("Save UOM", key="uom_btn"):
                    if set_uom(fac, r["sl_no"], r["item_name"], unit, same):
                        done("UOM updated.")


def tab_daily_sheet():
    """Wrapper: a problem inside the Daily Work Sheet is shown here with its real reason instead of crashing the page."""
    try:
        _tab_daily_sheet_inner()
    except Exception as e:   # Streamlit's own rerun/stop signals are not Exceptions, so they pass straight through
        import traceback
        st.error(f"Daily Work Sheet-এ সমস্যা: {type(e).__name__}: {e}")
        with st.expander("Technical details"):
            st.code(traceback.format_exc())


# ============================================================
#  PHYSICAL COUNT - spot check done in the store, entered on a phone, reviewed in the office
# ============================================================
def ensure_count_tables():
    """Creates the two count tables on first use (additive; no existing table is touched)."""
    if st.session_state.get("_count_tables_ready") or _once_flags().get("count_tables"):
        return
    conn = get_conn()
    try:
        with conn.cursor() as cur:
            cur.execute("""CREATE TABLE IF NOT EXISTS stock_counts (
                id SERIAL PRIMARY KEY, factory_name TEXT, counted_by TEXT, counted_at TEXT,
                status TEXT DEFAULT 'Waiting', note TEXT DEFAULT '', reviewed_by TEXT, reviewed_at TEXT,
                review_note TEXT DEFAULT '')""")
            cur.execute("""CREATE TABLE IF NOT EXISTS stock_count_items (
                id SERIAL PRIMARY KEY, count_id INTEGER, factory_name TEXT, sl_no INTEGER, prod_id TEXT,
                item_name TEXT, size TEXT, serial_no TEXT, unit TEXT, system_qty REAL, counted_qty REAL,
                remarks TEXT DEFAULT '')""")
            cur.execute("CREATE INDEX IF NOT EXISTS ix_sci_count ON stock_count_items(count_id)")
        conn.commit()
        st.session_state["_count_tables_ready"] = True
        _once_flags()["count_tables"] = True
    except Exception:
        conn.rollback()
        raise


@tx
def save_stock_count(fac, user, items, note):
    """Stores one count. System stock is read again here, at the moment of submitting, and saved with the count.
    Inventory itself is NOT changed - the count only waits for review."""
    when = local_now().strftime("%d-%b-%Y %I:%M %p")
    cid = run("""INSERT INTO stock_counts (factory_name, counted_by, counted_at, status, note)
                 VALUES (%s,%s,%s,'Waiting',%s) RETURNING id""", (fac, user, when, note or ""))[0][0]
    for it in items:
        r = q("""SELECT prod_id, item_name, COALESCE(size,'') AS size, COALESCE(serial_no,'') AS serial_no,
                 COALESCE(NULLIF(unit_name,''),'Pcs') AS unit, COALESCE(current_stock,0) AS stock
                 FROM inventory WHERE sl_no=%s AND factory_name=%s""", (it["sl_no"], fac))
        if not r:
            raise ValueError(f"Item SL {it['sl_no']} is not in {fac}.")
        r = r[0]
        run("""INSERT INTO stock_count_items (count_id, factory_name, sl_no, prod_id, item_name, size, serial_no,
               unit, system_qty, counted_qty, remarks) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
            (cid, fac, it["sl_no"], r["prod_id"], r["item_name"], r["size"], r["serial_no"], r["unit"],
             float(r["stock"]), float(it["qty"]), it.get("remark", "")))
    audit("STOCK_COUNT", f"{fac}: count #{cid} by {user}, {len(items)} item(s)")
    return cid


@tx
def review_stock_count(cid, user, review_note):
    run("""UPDATE stock_counts SET status='Reviewed', reviewed_by=%s, reviewed_at=%s, review_note=%s
           WHERE id=%s AND status='Waiting'""",
        (user, local_now().strftime("%d-%b-%Y %I:%M %p"), review_note or "", cid))
    audit("STOCK_COUNT_REVIEWED", f"Count #{cid} reviewed by {user}")
    return True


def _pck(name):
    """Entry-box keys carry a counter. After every successful add the counter goes up, so the browser gets brand-new
    empty boxes (old item / quantity / remark can never stay behind and be added twice by mistake)."""
    return f"{name}_{st.session_state.get('pc_gen', 0)}"


def _pc_add():
    """Button callback: put the picked item + counted quantity on the list, then clear the entry boxes."""
    ss = st.session_state
    row = ss.get("pc_opts", {}).get(ss.get(_pck("pc_pick")))
    qty = ss.get(_pck("pc_qty"))
    if row is None:
        ss["pc_msg"] = ("error", "Search and select an item first.")
    elif qty is None:
        ss["pc_msg"] = ("error", "Enter the counted quantity (type 0 if nothing is found).")
    elif row["sl_no"] in ss.get("pc_list", {}):
        old = ss["pc_list"][row["sl_no"]]
        ss["pc_msg"] = ("error", f"{row['item_name']} is already in the count list (counted {old['qty']:g}). "
                                 "Tap ✖ Remove on it first if you want to enter it again.")
    else:
        ss.setdefault("pc_list", {})[row["sl_no"]] = {
            "sl_no": row["sl_no"], "label": f"{row['item_name']} [{row['size'] or '-'}]",
            "code": row["prod_id"], "qty": float(qty), "remark": str(ss.get(_pck("pc_rem")) or "").strip()}
        ss["pc_msg"] = ("ok", f"Added: {row['item_name']} = {float(qty):g}")
        for k in ("pc_qty", "pc_rem", "pc_term", "pc_pick"):
            ss.pop(_pck(k), None)
        ss["pc_gen"] = ss.get("pc_gen", 0) + 1   # fresh empty boxes


def _pc_remove(sl):
    st.session_state.get("pc_list", {}).pop(sl, None)


def _pc_item_info(fac, row):
    """Shows the picked item's live system stock and, if it was counted before, the last count's Short / Excess."""
    try:
        sl = row["sl_no"]
        inv = q("SELECT COALESCE(current_stock,0) AS stock, COALESCE(NULLIF(unit_name,''),'Pcs') AS unit "
                "FROM inventory WHERE sl_no=%s AND factory_name=%s", (sl, fac))
        if not inv:
            return
        stock, unit = float(inv[0]["stock"]), inv[0]["unit"]
        last = q("""SELECT i.count_id, i.counted_qty, c.counted_at, c.counted_by FROM stock_count_items i
                    JOIN stock_counts c ON c.id=i.count_id
                    WHERE i.sl_no=%s AND i.factory_name=%s ORDER BY i.id DESC LIMIT 1""", (sl, fac))
        m = st.columns(3)
        m[0].metric("System stock now", f"{stock:g} {unit}")
        if not last:
            m[1].metric("Last count", "Not counted yet")
            return
        lc = last[0]
        counted = float(lc["counted_qty"])
        diff = counted - stock
        m[1].metric("Last counted", f"{counted:g} {unit}")
        if abs(diff) < 1e-9:
            m[2].metric("Result", "✅ Match")
        elif diff < 0:
            m[2].metric("Result", f"🔻 Short {abs(diff):g}")
        else:
            m[2].metric("Result", f"🔺 Excess {diff:g}")
        st.caption(f"Last count #{lc['count_id']} by {lc['counted_by']} on {lc['counted_at']}. "
                   f"Short / Excess = last counted qty − system stock now.")
    except Exception:
        pass


@_fragment
def pc_entry():
    """Phone-friendly entry. A fragment: typing / selecting here does not reload the whole application."""
    if not st.session_state.get("user"):
        st.info("🔑 Sign in first to record a count.")
        return
    st.markdown(f"**🏭 Counting in: {FAC}**")
    st.caption("Select an item to see its current system stock and any Short / Excess from its last count. "
               "The count appears in the Waiting / Results tab after you submit.")
    term = st.text_input("🔍 Item name / serial / ERP code", key=_pck("pc_term"), placeholder="Type and select the item")
    opts = {}
    if term.strip():
        for r in search_items(FAC, term.strip())[:30]:
            lbl = f"{r['item_name']} [{r['size'] or '-'}]{_uom_tag(r)} · {r['prod_id']}" + (f" · S/N {r['serial']}" if r["serial"] else "")
            opts[lbl] = r
    st.session_state["pc_opts"] = opts
    if term.strip() and not opts:
        st.warning("No item found.")
    if opts:
        st.selectbox("Select item", list(opts), key=_pck("pc_pick"))
        _pk = opts.get(st.session_state.get(_pck("pc_pick")))
        if _pk is not None:
            if _pk["sl_no"] in st.session_state.get("pc_list", {}):
                st.error("⛔ Ei item already count list-e ache. Abar add kora jabe na - age list theke ✖ Remove korun.")
            else:
                try:
                    _today_n = q("""SELECT COUNT(*) AS n FROM stock_count_items i JOIN stock_counts c ON c.id=i.count_id
                                    WHERE i.sl_no=%s AND i.factory_name=%s AND c.counted_at LIKE %s""",
                                 (_pk["sl_no"], FAC, f"{local_now():%d-%b-%Y}%"))[0]["n"]
                except Exception:
                    _today_n = 0
                if int(_today_n):
                    st.warning("⚠️ Ei item ajke already count kora hoyeche. Abar count korle notun entry hoye jabe - sure hole add korun.")
            _pc_item_info(FAC, _pk)
    try:
        st.number_input("Counted quantity", min_value=0.0, step=1.0, value=None, placeholder="How many did you count?",
                        key=_pck("pc_qty"))
    except TypeError:   # very old Streamlit without an empty number box
        st.number_input("Counted quantity", min_value=0.0, step=1.0, key=_pck("pc_qty"))
    st.text_input("Remarks (optional)", key=_pck("pc_rem"), placeholder="e.g. 2 damaged, kept in rack B")
    st.button("➕ Add to count list", key="pc_add_btn", on_click=_pc_add, use_container_width=True)
    msg = st.session_state.pop("pc_msg", None)
    if msg:
        (st.success if msg[0] == "ok" else st.error)(msg[1])

    lst = st.session_state.get("pc_list", {})
    st.markdown(f"#### 📝 Count list ({len(lst)} item{'s' if len(lst) != 1 else ''})")
    if not lst:
        st.caption("Nothing added yet.")
    for sl, it in list(lst.items()):
        with st.container(border=True):
            st.markdown(f"**{html_lib.escape(it['label'])}** · {html_lib.escape(str(it['code']))}  \n"
                        f"Counted: **{it['qty']:g}**" + (f" · {html_lib.escape(it['remark'])}" if it["remark"] else ""))
            st.button("✖ Remove", key=f"pc_rm_{sl}", on_click=_pc_remove, args=(sl,))
    note = st.text_input("Note for the whole count (optional)", key="pc_note")
    if st.button(f"✅ Submit count ({len(lst)})", key="pc_submit", type="primary", use_container_width=True):
        if not lst:
            st.error("Add at least one item first.")
        elif guard():
            cid = save_stock_count(FAC, st.session_state["user"], list(lst.values()), note.strip())
            if cid:
                st.session_state["pc_list"] = {}
                st.session_state.pop("pc_note", None)
                done(f"Count #{cid} submitted - waiting for review.")


def _pc_result_df(items):
    rows = []
    for r in items:
        diff = float(r["counted_qty"]) - float(r["system_qty"])
        rows.append({"SL No": r["sl_no"], "Serial No": r["serial_no"], "Item": r["item_name"], "Size": r["size"],
                     "UOM": r["unit"], "System stock": float(r["system_qty"]), "Counted qty": float(r["counted_qty"]),
                     "Difference": diff,
                     "Result": "✅ Match" if abs(diff) < 1e-9 else ("🔻 Short" if diff < 0 else "🔺 Excess"),
                     "Remarks": r["remarks"] or ""})
    return pd.DataFrame(rows)


def pc_results_view():
    status = st.radio("Show", ["Waiting", "Reviewed", "All"], horizontal=True, key="pc_status")
    where = "" if status == "All" else " AND status=%s"
    params = list(FP) + ([] if status == "All" else [status])
    counts = q_c(f"SELECT * FROM stock_counts WHERE 1=1{FSQL}{where} ORDER BY id DESC LIMIT 30", params)
    if not counts:
        st.info("No counts here yet.")
        return
    items = q_c("SELECT * FROM stock_count_items WHERE count_id = ANY(%s) ORDER BY id", ([c["id"] for c in counts],))
    by_count = {}
    for it in items:
        by_count.setdefault(it["count_id"], []).append(it)
    n_wait = sum(1 for c in counts if c["status"] == "Waiting")
    n_diff = sum(1 for it in items if abs(float(it["counted_qty"]) - float(it["system_qty"])) >= 1e-9)
    m1, m2, m3 = st.columns(3)
    m1.metric("Counts shown", len(counts))
    m2.metric("Waiting for review", n_wait)
    m3.metric("Items with a difference", n_diff)
    compact = st.checkbox("\U0001F4F1 Compact view (phone)", key="pc_compact",
                          help="Shows only Item, Size, System stock, Counted qty, Difference and Result.")
    for i, c in enumerate(counts):
        df = _pc_result_df(by_count.get(c["id"], []))
        n_bad = int((df["Difference"].abs() >= 1e-9).sum()) if not df.empty else 0
        badge = "⏳ Waiting" if c["status"] == "Waiting" else "✔ Reviewed"
        title = (f"{badge} · Count #{c['id']} · {c['factory_name']} · {c['counted_by']} · {c['counted_at']} · "
                 f"{len(df)} item(s)" + (f" · ⚠ {n_bad} different" if n_bad else " · all match"))
        with st.expander(title, expanded=(i == 0 and c["status"] == "Waiting")):
            if c["note"]:
                st.caption(f"Note: {c['note']}")
            _shown = df[["Item", "Size", "System stock", "Counted qty", "Difference", "Result"]] if (compact and not df.empty) else df
            st.dataframe(_shown, hide_index=True, use_container_width=True,
                         column_config={"System stock": st.column_config.NumberColumn(format="%.2f"),
                                        "Counted qty": st.column_config.NumberColumn(format="%.2f"),
                                        "Difference": st.column_config.NumberColumn(format="%+.2f")})
            st.caption("System stock = physical stock in the software at the time the count was submitted. "
                       "Inventory is not changed by a count.")
            if c["status"] == "Reviewed":
                st.caption(f"Reviewed by {c['reviewed_by']} on {c['reviewed_at']}"
                           + (f" - {c['review_note']}" if c["review_note"] else ""))
            elif st.session_state.get("role") == "Store Manager":
                rn = st.text_input("Review note (optional)", key=f"pc_rn_{c['id']}")
                if st.button("✔ Mark as reviewed", key=f"pc_rv_{c['id']}"):
                    if review_stock_count(c["id"], st.session_state["user"], rn.strip()):
                        done(f"Count #{c['id']} marked as reviewed.")


