# ---- Physical Count v2 (additive): verify count against system, trace every movement, fix from this tab ----
def _pc_dt(d, t):
    """Date + time text -> datetime (for ordering the history). Unreadable dates sort first."""
    base = parse_date(d)
    if not base:
        return datetime.min
    try:
        tt = datetime.strptime(str(t or "").strip(), "%I:%M %p")
        return base.replace(hour=tt.hour, minute=tt.minute)
    except Exception:
        return base


@tx
def pc_edit_tx(tid, new_qty, date_s, notes):
    """Edit quantity / date / remarks of one transaction from the Physical Count tab. Stock moves by the difference."""
    rows = q("SELECT * FROM transactions WHERE id=%s FOR UPDATE", (tid,))
    if not rows:
        raise ValueError("Transaction paoa jay nai.")
    t = rows[0]
    old_qty, ttype = float(t["qty"] or 0), t["trans_type"]
    delta = float(new_qty) - old_qty
    if abs(delta) > 1e-9:
        if ttype == OPENING_TYPE:
            raise ValueError("Opening Balance-er quantity ekhane change kora jabe na (Stock Adjustment / Opening Balance notun kore din).")
        if "Auto-transferred" in (t["notes"] or ""):
            raise ValueError("Ei Issue-te auto-transfer jukto ache - quantity change korle transfer-o mile na. "
                             "Age niche 'Transfer' theke thik korun ba delete kore notun kore din.")
        cur = q("SELECT COALESCE(current_stock,0) AS s FROM inventory WHERE sl_no=%s AND factory_name=%s FOR UPDATE",
                (t["sl_no"], t["factory_name"]))
        if not cur:
            raise ValueError("Inventory item paoa jay nai.")
        stock = float(cur[0]["s"])
        if ttype in RECEIPT_TYPES:
            eff = delta
        elif ttype in ISSUE_TYPES + (ADJ_OUT,):
            eff = -delta
        else:
            raise ValueError(f"'{ttype}' type-er quantity ekhane edit kora jay na.")
        if stock + eff < -1e-9:
            raise ValueError(f"Ei change-e stock negative ({stock + eff:g}) hoye jabe.")
        run("UPDATE inventory SET current_stock=current_stock+%s WHERE sl_no=%s AND factory_name=%s",
            (eff, t["sl_no"], t["factory_name"]))
        if ttype == "Supplier. Rec":
            if delta < 0:
                req_undo_receipt(tid, -delta)
            else:
                _req_alloc(t["factory_name"], t["prod_id"], delta, date_s, tid)
    d = parse_date(date_s)
    if d and ttype != OPENING_TYPE:
        _pm = pre_opening_msg(t["factory_name"], [t["sl_no"]], d, {int(t["sl_no"]): t["item_name"]})
        if _pm and (parse_date(t["date"]) is None or d.date() != parse_date(t["date"]).date()):
            raise ValueError(_pm)   # only when the date is being moved; qty-only edits of old rows stay possible
    run("UPDATE transactions SET qty=%s, date=%s, day=%s, notes=%s WHERE id=%s",
        (float(new_qty), date_s, d.day if d else t["day"], notes, tid))
    audit("EDIT_TRANS_PC", f"Physical Count tab: transaction {tid} {t['factory_name']} {ttype} of {t['prod_id']} ({t['item_name']}) "
                           f"SL {t['sl_no']}: qty {old_qty:g}->{float(new_qty):g}, date '{t['date']}'->'{date_s}'")
    return True


@tx
def pc_adjust_to_count(fac, sl, counted, count_id, note):
    """Sets the software physical stock equal to the counted quantity, recorded as a Stock Adjustment transaction."""
    r = q("SELECT prod_id, item_name, COALESCE(current_stock,0) AS stock FROM inventory "
          "WHERE sl_no=%s AND factory_name=%s FOR UPDATE", (sl, fac))
    if not r:
        raise ValueError("Inventory item paoa jay nai.")
    r = r[0]
    stock, counted = float(r["stock"]), float(counted)
    delta = counted - stock
    if abs(delta) < 1e-9:
        raise ValueError("Stock ager-i counted qty-r soman.")
    ttype = "Stock Adjustment (+)" if delta > 0 else ADJ_OUT
    run("UPDATE inventory SET current_stock=%s WHERE sl_no=%s AND factory_name=%s", (counted, sl, fac))
    now = local_now()
    insert_tx(fac, st.session_state.get("user", ""), sl, r["prod_id"], r["item_name"], abs(delta), ttype, now.day,
              f"Physical Count #{count_id}: system {stock:g} -> counted {counted:g}" + (f" | {note}" if note else ""),
              now.strftime(DATE_FMT), now.strftime("%I:%M %p"), "Physically Verified")
    audit("PC_ADJUST", f"{fac}: {r['prod_id']} ({r['item_name']}) SL {sl} stock {stock:g}->{counted:g} by count #{count_id}")
    return True


def _pc_timeline(fac, txs, trfs):
    """Transactions + inter-unit transfers of one item in time order, with a running balance (guide only)."""
    ev = []
    for t in txs:
        ev.append((_pc_dt(t["date"], t["time"]), 1, t["id"], "Transaction", t))
    for f in trfs:
        ev.append((_pc_dt(f["transfer_date"], f["transfer_time"]), 0, f["id"], "Transfer", f))
    ev.sort(key=lambda e: (e[0], e[1], e[2]))
    bal, out = 0.0, []
    for _dt, _o, _id, kind, r in ev:
        if kind == "Transaction":
            ty, qty = r["trans_type"], float(r["qty"] or 0)
            if ty == OPENING_TYPE:
                eff, bal = None, qty
            elif ty in RECEIPT_TYPES:
                eff = qty
            elif ty in ISSUE_TYPES + (ADJ_OUT,):
                eff = -qty
            else:
                eff = 0.0
            if eff is not None:
                bal += eff
            out.append({"Source": "Transaction", "ID": r["id"], "Date": r["date"], "Time": r["time"], "Type": ty,
                        "Qty": qty, "Effect": (qty if eff is None else eff), "Balance after": bal,
                        "By": r["officer_name"], "Req/SR": r.get("req_no") or "", "Notes": r["notes"]})
        else:
            qty = float(r["qty"] or 0)
            incoming = (r["dest_factory"] == fac)
            eff = qty if incoming else -qty
            bal += eff
            out.append({"Source": "Transfer", "ID": r["id"], "Date": r["transfer_date"], "Time": r["transfer_time"],
                        "Type": (f"🔁 Transfer IN from {r['source_factory']}" if incoming else f"🔁 Transfer OUT to {r['dest_factory']}"),
                        "Qty": qty, "Effect": eff, "Balance after": bal, "By": r["initiated_by"], "Req/SR": "",
                        "Notes": r["notes"] or ""})
    out.reverse()   # newest first
    return out, bal


def pc_trace_panel(rec):
    """Everything that happened to one item, plus the tools to correct it - all inside the Physical Count tab."""
    fac, sl = rec["factory_name"], rec["sl_no"]
    inv = q(f"SELECT {INV_COLS} FROM inventory WHERE sl_no=%s AND factory_name=%s", (sl, fac))
    if not inv:
        st.warning("Ei item ekhon inventory-te nei.")
        return
    inv = inv[0]
    stock, counted = float(inv["stock"]), float(rec["counted_qty"])
    diff = counted - stock
    st.markdown(f"### 🔎 {html_lib.escape(str(inv['item_name']))} [{html_lib.escape(str(inv['size'] or '-'))}] · SL {sl} · {html_lib.escape(str(inv['prod_id']))}")
    m = st.columns(4)
    m[0].metric("System stock now", f"{stock:g}")
    m[1].metric("Counted (physical)", f"{counted:g}")
    m[2].metric("Difference (Counted − System)", f"{diff:+g}")
    m[3].metric("System at count time", f"{float(rec['system_qty']):g}")
    if abs(float(rec["system_qty"]) - stock) > 1e-9:
        st.info(f"Count-er por system stock {float(rec['system_qty']):g} theke {stock:g} hoyeche (kono entry edit/add/delete hoyeche). "
                f"Upore Difference ekhon-kar stock-er sathe dekhano hocche.")
    if abs(diff) < 1e-9:
        st.success("✅ Ekhon software stock ar physical count mile geche.")

    run_once_per_process("transfer_size_column", ensure_transfer_size_column)
    txs = q("""SELECT id, date, time, trans_type, qty, officer_name, COALESCE(notes,'') AS notes,
                      COALESCE(req_no,'') AS req_no, day
               FROM transactions WHERE factory_name=%s AND sl_no=%s ORDER BY id DESC LIMIT 2000""", (fac, sl))
    trfs = q("""SELECT * FROM inter_factory_transfers
                WHERE prod_id=%s AND (source_factory=%s OR dest_factory=%s)
                  AND (LOWER(item_name)=LOWER(%s) OR COALESCE(notes,'') ILIKE %s)
                  AND (COALESCE(size,'')='' OR LOWER(size)=LOWER(%s))
                ORDER BY id DESC LIMIT 500""",
             (inv["prod_id"], fac, fac, inv["item_name"], f"%{inv['item_name']}%", inv["size"] or ""))
    tl, calc_bal = _pc_timeline(fac, txs, trfs)

    n_issue = sum(1 for t in txs if t["trans_type"] in ISSUE_TYPES)
    n_rec = sum(1 for t in txs if t["trans_type"] in RECEIPT_TYPES)
    n_adj = sum(1 for t in txs if t["trans_type"] in ("Stock Adjustment (+)", ADJ_OUT, OPENING_TYPE))
    st.markdown(f"**📜 Full history** — {n_issue} Issue · {n_rec} Receive · {n_adj} Adjustment/Opening · {len(trfs)} Inter-unit transfer")
    if tl:
        tdf = pd.DataFrame(tl)
        types = sorted(tdf["Type"].unique())
        pick = st.multiselect("Filter by type (khali = sob)", types, key=f"pcv_f_{fac}_{sl}")
        if pick:
            tdf = tdf[tdf["Type"].isin(pick)]
        st.dataframe(tdf, hide_index=True, use_container_width=True, height=360,
                     column_config={"Qty": st.column_config.NumberColumn(format="%.2f"),
                                    "Effect": st.column_config.NumberColumn("Effect (+/−)", format="%+.2f"),
                                    "Balance after": st.column_config.NumberColumn(format="%.2f")})
        st.caption(f"History theke hishab: **{calc_bal:g}** · System stock: **{stock:g}**"
                   + (" — ✅ mile" if abs(calc_bal - stock) < 1e-9 else
                      " — ⚠ mile na: history-r baire stock change hoyeche (jemon Inventory-te direct edit) ba kono entry/tarikh vul. "
                      "Eta shudhu guide; Balance column date/time onujayi hishab kora."))
    else:
        st.caption("Ei item-er kono transaction nei.")

    st.markdown("**🛠 Fix from here**")
    pw_ok = mgr_check("pcv_pw")

    # 1) one-click: make the software stock equal to the count
    with st.expander("⚖️ Software stock-ke counted qty-te milie din (Stock Adjustment)", expanded=False):
        if abs(diff) < 1e-9:
            st.caption("Already mile ache.")
        else:
            st.write(f"System **{stock:g}** → Counted **{counted:g}**  (Stock Adjustment {'(+)' if diff > 0 else '(-)'} **{abs(diff):g}** hobe)")
            adj_note = st.text_input("Karon / remarks", key=f"pcv_an_{fac}_{sl}", placeholder="e.g. entry bhul chhilo")
            adj_conf = st.checkbox("Ami confirm korchi - ei adjustment transaction-e record hobe", key=f"pcv_ac_{fac}_{sl}")
            if st.button("⚖️ Adjust stock to counted qty", key=f"pcv_ab_{fac}_{sl}"):
                if not pw_ok:
                    st.error("Manager password thik nei.")
                elif not adj_conf:
                    st.error("Confirm tick korun.")
                elif guard() and pc_adjust_to_count(fac, sl, counted, rec["count_id"], adj_note.strip()):
                    done("Stock adjusted to counted quantity.")

    # 2) edit / delete a transaction
    with st.expander("✏️ Transaction edit / delete (Issue, Receive, Adjustment)"):
        if not txs:
            st.caption("Transaction nei.")
        else:
            rows = {int(t["id"]): t for t in txs[:300]}
            tid = int(st.selectbox("Transaction", list(rows), key=f"pcv_t_{fac}_{sl}",
                                   format_func=lambda i: f"ID {i} | {rows[i]['date']} | {rows[i]['trans_type']} | qty {float(rows[i]['qty'] or 0):g} | {rows[i]['officer_name']}"))
            t = rows[tid]
            c1, c2 = st.columns(2)
            nq = c1.number_input("Quantity", min_value=0.0, value=float(t["qty"] or 0), step=1.0, key=f"pcv_q_{tid}")
            pd_ = parse_date(t["date"])
            nd = c2.date_input("Date", value=pd_.date() if pd_ else local_now().date(), key=f"pcv_d_{tid}")
            nn = st.text_input("Remarks", value=t["notes"] or "", key=f"pcv_n_{tid}")
            b1, b2 = st.columns(2)
            if b1.button("💾 Save edit", key=f"pcv_save_{tid}"):
                if not pw_ok:
                    st.error("Manager password thik nei.")
                elif guard() and pc_edit_tx(tid, nq, nd.strftime(DATE_FMT), nn.strip()):
                    done("Transaction updated, stock adjusted.")
            dconf = st.checkbox("⚠️ Delete confirm - stock revert hobe", key=f"pcv_dc_{tid}")
            if b2.button("🗑 Delete & revert stock", key=f"pcv_del_{tid}"):
                if not pw_ok:
                    st.error("Manager password thik nei.")
                elif not dconf:
                    st.error("Delete confirm tick korun.")
                elif guard() and delete_transaction(tid):
                    done("Transaction deleted, stock reverted.")
            if t["trans_type"] == OPENING_TYPE:
                st.caption("Note: Opening Balance delete korle shudhu record jay, stock change hoy na.")

    # 3) edit / delete an inter-unit transfer
    with st.expander("🔁 Inter-unit transfer edit / delete"):
        if not trfs:
            st.caption("Ei item-er kono transfer nei.")
        else:
            trows = {int(f["id"]): f for f in trfs}
            fid = int(st.selectbox("Transfer", list(trows), key=f"pcv_tf_{fac}_{sl}",
                                   format_func=lambda i: f"{trows[i]['transfer_ref']} | {trows[i]['transfer_date']} | {trows[i]['source_factory']} → {trows[i]['dest_factory']} | qty {float(trows[i]['qty'] or 0):g}"))
            f = trows[fid]
            c1, c2 = st.columns(2)
            fq = c1.number_input("Transfer quantity", min_value=0.0, value=float(f["qty"] or 0), step=1.0, key=f"pcv_fq_{fid}")
            fpd = parse_date(f["transfer_date"])
            fd = c2.date_input("Transfer date", value=fpd.date() if fpd else local_now().date(), key=f"pcv_fd_{fid}")
            fn = st.text_input("Notes", value=f["notes"] or "", key=f"pcv_fn_{fid}")
            _s, _d = transfer_items(f)
            reverse = bool(_s and _d)
            if not reverse:
                st.warning("Dui factory-r item paoa jay nai - delete korle shudhu record jabe, stock change hobe na.")
            g1, g2 = st.columns(2)
            if g1.button("💾 Save transfer edit", key=f"pcv_fsave_{fid}"):
                if not pw_ok:
                    st.error("Manager password thik nei.")
                elif guard() and edit_transfer(f, fq, fd.strftime(DATE_FMT), f["transfer_time"], fn.strip()):
                    done("Transfer updated.")
            fconf = st.checkbox("⚠️ Transfer delete confirm", key=f"pcv_fdc_{fid}")
            if g2.button("🗑 Delete transfer", key=f"pcv_fdel_{fid}"):
                if not pw_ok:
                    st.error("Manager password thik nei.")
                elif not fconf:
                    st.error("Delete confirm tick korun.")
                elif guard() and delete_transfer(f, reverse):
                    done("Transfer deleted" + (" and balances reversed." if reverse else "."))

    # 4) add a missing entry
    with st.expander("➕ Missing entry add korun (Issue / Receive / Adjustment)"):
        add_types = ["Supplier. Rec", "Issued", "Internal Rec", "Internal Issue", "Stock Adjustment (+)", ADJ_OUT]
        a1, a2, a3 = st.columns([2, 1, 1])
        a_type = a1.selectbox("Type", add_types, format_func=lambda k: TRANS_LABELS.get(k, k), key=f"pcv_at_{fac}_{sl}")
        a_qty = a2.number_input("Quantity", min_value=0.0, value=0.0, step=1.0, key=f"pcv_aq_{fac}_{sl}")
        a_date = a3.date_input("Date", value=local_now().date(), key=f"pcv_ad_{fac}_{sl}")
        a_note = st.text_input("Remarks", key=f"pcv_anote_{fac}_{sl}")
        if st.button("➕ Save entry", key=f"pcv_asave_{fac}_{sl}"):
            if a_qty <= 0:
                st.error("Quantity 0-r beshi hote hobe.")
            elif guard():
                item = dict(inv)
                if save_transaction(fac, item, float(a_qty), a_type, datetime.combine(a_date, datetime.min.time()),
                                    (a_note.strip() + " | Added from Physical Count").strip(" |"), True, False):
                    done("Entry saved.")


@_fragment
def pc_verify_view():
    st.caption("Count-er por software-er closing balance-er sathe physical balance milano hoy. Je item mile ni segulo khule "
               "tar Issue / Receive / Transfer / Adjustment sob dekhe ekhan thekei thik korun.")
    c1, c2 = st.columns(2)
    d = c1.date_input("Count-er tarikh", value=local_now().date(), key="pc_vdate")
    only_diff = c2.checkbox("Shudhu jegulo mile nai", value=True, key="pc_vonly")
    cf, cp = fw(FAC, "c.")
    rows = q(f"""SELECT i.count_id, i.factory_name, i.sl_no, i.prod_id, i.item_name, COALESCE(i.size,'') AS size,
                        COALESCE(i.serial_no,'') AS serial_no, i.unit, i.system_qty, i.counted_qty, i.remarks,
                        c.counted_by, c.counted_at
                 FROM stock_count_items i JOIN stock_counts c ON c.id=i.count_id
                 WHERE c.counted_at LIKE %s{cf} ORDER BY i.id""", [d.strftime(DATE_FMT) + "%"] + cp)
    if not rows:
        st.info(f"{d.strftime(DATE_FMT)} tarikhe kono count nei. Age '➕ New count' theke count submit korun.")
        return
    latest = {}
    for r in rows:
        latest[(r["factory_name"], r["sl_no"])] = r   # same item counted twice: the last count wins
    inf, ip = fw(FAC)
    live = {(x["factory_name"], x["sl_no"]): float(x["stock"]) for x in q(
        f"SELECT sl_no, factory_name, COALESCE(current_stock,0) AS stock FROM inventory WHERE sl_no = ANY(%s){inf}",
        [sorted({k[1] for k in latest})] + ip)}
    recs, table = [], []
    for k, r in latest.items():
        if k not in live:
            continue
        now_s = live[k]
        diff = float(r["counted_qty"]) - now_s
        r = dict(r, stock_now=now_s, diff=diff)
        recs.append(r)
        table.append({"SL No": r["sl_no"], "Item": r["item_name"], "Size": r["size"], "UOM": r["unit"],
                      "System now": now_s, "Counted": float(r["counted_qty"]), "Difference": diff,
                      "Result": "✅ Match" if abs(diff) < 1e-9 else ("🔻 Short" if diff < 0 else "🔺 Excess"),
                      "Count #": r["count_id"], "Counted by": r["counted_by"], "Remarks": r["remarks"] or ""})
    df = pd.DataFrame(table)
    n_ok = int((df["Difference"].abs() < 1e-9).sum())
    n_short = int((df["Difference"] < -1e-9).sum())
    n_exc = int((df["Difference"] > 1e-9).sum())
    m = st.columns(4)
    m[0].metric("Items counted", len(df))
    m[1].metric("✅ Match", n_ok)
    m[2].metric("🔻 Short", n_short)
    m[3].metric("🔺 Excess", n_exc)
    view = df[df["Difference"].abs() >= 1e-9] if only_diff else df
    if view.empty:
        st.success("🎉 Sob counted item software-er sathe mile geche.")
        return
    st.dataframe(view, hide_index=True, use_container_width=True, height=min(60 + 35 * len(view), 340),
                 column_config={"System now": st.column_config.NumberColumn(format="%.2f"),
                                "Counted": st.column_config.NumberColumn(format="%.2f"),
                                "Difference": st.column_config.NumberColumn(format="%+.2f")})
    pool = [r for r in recs if (not only_diff or abs(r["diff"]) >= 1e-9)]
    pool.sort(key=lambda r: (-abs(r["diff"]), str(r["item_name"])))
    labels = {f"SL {r['sl_no']} | {r['item_name']} [{r['size'] or '-'}]{_uom_tag(r)} | System {r['stock_now']:g} vs Counted {float(r['counted_qty']):g} ({r['diff']:+g})": r
              for r in pool}
    st.markdown("---")
    sel = st.selectbox("🔎 Kon item-er history check korben", list(labels), key="pc_vsel")
    pc_trace_panel(labels[sel])


@_fragment
def pc_uncounted_view():
    st.caption("Software-e stock ache kintu physical count hoyni emon item. Je item-er stock software-e ache ar store-e nei, "
               "segulo ekhane dhora porbe.")
    c1, c2 = st.columns([2, 1])
    days = c1.slider("Koto din dhore count hoyni  (0 = kokhono-i count hoyni)", 0, 365, 30, key="pc_unc_days")
    inc_idle = c2.checkbox("Kokhono Issue/Receive hoyni segulo-o dekhao", value=False, key="pc_unc_idle")
    term = st.text_input("🔍 Item / serial / code", key="pc_unc_term").strip().lower()
    fsql, fp = fw(FAC)
    inv = q_c(f"""SELECT factory_name, sl_no, prod_id, item_name, COALESCE(size,'') AS size, COALESCE(serial_no,'') AS serial,
                         COALESCE(NULLIF(unit_name,''),'Pcs') AS unit, COALESCE(current_stock,0) AS stock,
                         COALESCE(unit_price,0) AS price
                  FROM inventory WHERE COALESCE(current_stock,0)<>0{fsql}""", fp)
    cf, cp = fw(FAC, "c.")
    cnts = q_c(f"""SELECT i.factory_name, i.sl_no, MAX(c.id) AS last_id
                   FROM stock_count_items i JOIN stock_counts c ON c.id=i.count_id WHERE 1=1{cf} GROUP BY 1,2""", cp)
    last_ids = {(r["factory_name"], r["sl_no"]): r["last_id"] for r in cnts}
    when = {}
    if last_ids:
        for r in q_c("SELECT id, counted_at FROM stock_counts WHERE id = ANY(%s)", (sorted(set(last_ids.values())),)):
            when[r["id"]] = parse_date(str(r["counted_at"] or "")[:11])
    moves = {(r["factory_name"], r["sl_no"]): int(r["n"]) for r in q_c(
        f"""SELECT factory_name, sl_no, COUNT(*) AS n FROM transactions WHERE trans_type<>%s{fsql} GROUP BY 1,2""",
        [OPENING_TYPE] + fp)}
    today = local_now().date()
    out = []
    for r in inv:
        key = (r["factory_name"], r["sl_no"])
        n_mv = moves.get(key, 0)
        if n_mv == 0 and not inc_idle:
            continue
        lc = when.get(last_ids.get(key))
        age = (today - lc.date()).days if lc else None
        if days == 0 and key in last_ids:
            continue
        if days > 0 and age is not None and age <= days:
            continue
        if term and term not in f"{r['item_name']} {r['size']} {r['prod_id']} {r['serial']} {r['sl_no']}".lower():
            continue
        out.append({"Factory": r["factory_name"], "SL No": r["sl_no"], "Serial No": r["serial"], "ERP Code": r["prod_id"],
                    "Item": r["item_name"], "Size": r["size"], "UOM": r["unit"], "System stock": float(r["stock"]),
                    "Value (৳)": float(r["stock"]) * float(r["price"]),
                    "Last counted": lc.strftime(DATE_FMT) if lc else "Never", "Days ago": age, "Issue/Receive entries": n_mv})
    if not out:
        st.success("✅ Kono item baki nei - sob stock-ed item count hoye geche (ba filter-e kichu mile ni).")
        return
    df = pd.DataFrame(out).sort_values("Value (৳)", ascending=False).reset_index(drop=True)
    if not FAC or "CONSOLIDATED" not in FAC:
        df = df.drop(columns=["Factory"])
    m = st.columns(3)
    m[0].metric("Count baki item", len(df))
    m[1].metric("Never counted", int((df["Last counted"] == "Never").sum()))
    m[2].metric("Stock value (৳)", f"{df['Value (৳)'].sum():,.0f}")
    st.dataframe(df, hide_index=True, use_container_width=True, height=440,
                 column_config={"System stock": st.column_config.NumberColumn(format="%.2f"),
                                "Value (৳)": st.column_config.NumberColumn(format="৳ %,.0f")})
    export_buttons(df, "not_counted_items", title="Items in software but not physically counted")


# ---- Physical Count: delete a wrongly entered count (added; touches only the two count tables) ----
@tx
def delete_stock_counts(ids, user):
    """Deletes whole counts (header + items). Inventory and transactions are NOT touched."""
    ids = [int(i) for i in ids]
    hdr = q("SELECT id, factory_name, counted_by, counted_at FROM stock_counts WHERE id = ANY(%s)", (ids,))
    n_items = q("SELECT COUNT(*) AS n FROM stock_count_items WHERE count_id = ANY(%s)", (ids,))[0]["n"]
    run("DELETE FROM stock_count_items WHERE count_id = ANY(%s)", (ids,))
    run("DELETE FROM stock_counts WHERE id = ANY(%s)", (ids,))
    audit("STOCK_COUNT_DELETED",
          f"{user} deleted {len(hdr)} count(s) / {n_items} item row(s): "
          + "; ".join(f"#{h['id']} {h['factory_name']} {h['counted_by']} {h['counted_at']}" for h in hdr))
    return True


@tx
def delete_stock_count_items(item_ids, user):
    """Deletes only the chosen item rows of a count; a count left with no items is removed too."""
    item_ids = [int(i) for i in item_ids]
    rows = q("SELECT id, count_id, factory_name, item_name, sl_no FROM stock_count_items WHERE id = ANY(%s)", (item_ids,))
    cids = sorted({r["count_id"] for r in rows})
    run("DELETE FROM stock_count_items WHERE id = ANY(%s)", (item_ids,))
    run("""DELETE FROM stock_counts WHERE id = ANY(%s)
           AND NOT EXISTS (SELECT 1 FROM stock_count_items i WHERE i.count_id = stock_counts.id)""", (cids,))
    audit("STOCK_COUNT_ITEM_DELETED",
          f"{user} deleted {len(rows)} count item(s): "
          + "; ".join(f"count #{r['count_id']} {r['factory_name']} SL {r['sl_no']} {r['item_name']}" for r in rows[:30]))
    return True


def _pc_del_select_all(all_labels):
    st.session_state["pc_del_pick"] = list(all_labels)


@_fragment
def pc_delete_view():
    st.caption("Vul unit-e (jemon KC) count entry hoye gele ekhan theke delete korun. "
               "Delete korle shudhu count record muche jabe - Inventory stock ba Transactions kichu change hobe na.")
    if st.session_state.get("role") != "Store Manager":
        st.info("Count delete korar permission shudhu Store Manager-er.")
        return
    cf, cp = fw(FAC, "c.")
    c1, c2 = st.columns([1, 2])
    all_dates = c1.checkbox("Sob tarikh", value=False, key="pc_del_all")
    d = c2.date_input("Tarikh", value=local_now().date(), key="pc_del_date", disabled=all_dates)
    where = "" if all_dates else " AND c.counted_at LIKE %s"
    params = list(cp) + ([] if all_dates else [d.strftime(DATE_FMT) + "%"])
    rows = q_c(f"""SELECT c.id, c.factory_name, c.counted_by, c.counted_at, c.status, COUNT(i.id) AS n
                   FROM stock_counts c LEFT JOIN stock_count_items i ON i.count_id=c.id
                   WHERE 1=1{cf}{where} GROUP BY c.id ORDER BY c.id DESC LIMIT 200""", params)
    if not rows:
        st.info("Ei filter-e kono count nei.")
        return
    st.markdown(f"**{len(rows)} count / {sum(int(r['n']) for r in rows)} item** (unit: {FAC})")
    labels = {f"Count #{r['id']} · {r['factory_name']} · {r['counted_by']} · {r['counted_at']} · {int(r['n'])} item · {r['status']}": r["id"]
              for r in rows}
    mode = st.radio("Ki delete korben", ["Pura count (sob item)", "Shudhu kichu item"], horizontal=True, key="pc_del_mode")
    if mode.startswith("Pura"):
        pick = st.multiselect("Count select korun", list(labels), key="pc_del_pick")
        ids = [labels[k] for k in pick]
        st.button("Select all shown", key="pc_del_selall", on_click=_pc_del_select_all, args=(list(labels),))
        if ids:
            items = q_c("SELECT count_id, sl_no, item_name, size, counted_qty FROM stock_count_items "
                        "WHERE count_id = ANY(%s) ORDER BY count_id, id", (ids,))
            st.dataframe(pd.DataFrame([{"Count #": r["count_id"], "SL No": r["sl_no"], "Item": r["item_name"],
                                        "Size": r["size"], "Counted": float(r["counted_qty"])} for r in items]),
                         hide_index=True, use_container_width=True, height=min(60 + 35 * len(items), 320))
            ok = st.checkbox(f"Ami {len(ids)} ti count ({len(items)} item) delete korte chai - eta ar ferot ana jabe na",
                             key="pc_del_ok")
            if st.button("🗑 Delete selected count(s)", type="primary", key="pc_del_go", disabled=not ok):
                if guard() and delete_stock_counts(ids, st.session_state["user"]):
                    st.session_state.pop("pc_del_pick", None)
                    st.session_state.pop("pc_del_ok", None)
                    done(f"{len(ids)} ti count delete hoyeche.")
    else:
        items = q_c(f"""SELECT i.id, i.count_id, i.sl_no, i.item_name, COALESCE(i.size,'') AS size, i.counted_qty
                        FROM stock_count_items i JOIN stock_counts c ON c.id=i.count_id
                        WHERE 1=1{cf}{where} ORDER BY i.count_id DESC, i.id""", params)
        ilabels = {f"Count #{r['count_id']} · SL {r['sl_no']} · {r['item_name']} [{r['size'] or '-'}]{_uom_tag(r)} · counted {float(r['counted_qty']):g}": r["id"]
                   for r in items}
        pick = st.multiselect("Item select korun", list(ilabels), key="pc_del_ipick")
        ids = [ilabels[k] for k in pick]
        if ids:
            ok = st.checkbox(f"Ami {len(ids)} ti item delete korte chai - eta ar ferot ana jabe na", key="pc_del_iok")
            if st.button("🗑 Delete selected item(s)", type="primary", key="pc_del_igo", disabled=not ok):
                if guard() and delete_stock_count_items(ids, st.session_state["user"]):
                    st.session_state.pop("pc_del_ipick", None)
                    st.session_state.pop("pc_del_iok", None)
                    done(f"{len(ids)} ti item delete hoyeche.")


# ---- Physical Count: Fresh Start (reset month data -> count -> apply count as opening). Added; reversible via archive tables ----
def _fs_ensure():
    if st.session_state.get("_fs_tables_ready") or _once_flags().get("fs_tables"):
        st.session_state["_fs_tables_ready"] = True
        return
    conn = get_conn()
    try:
        with conn.cursor() as cur:
            cur.execute("CREATE TABLE IF NOT EXISTS transactions_archive (LIKE transactions)")
            cur.execute("ALTER TABLE transactions_archive ADD COLUMN IF NOT EXISTS fs_batch TEXT")
            cur.execute("CREATE TABLE IF NOT EXISTS issue_returns_archive (LIKE issue_returns)")
            cur.execute("ALTER TABLE issue_returns_archive ADD COLUMN IF NOT EXISTS fs_batch TEXT")
            cur.execute("CREATE TABLE IF NOT EXISTS fresh_start_stock (fs_batch TEXT, factory_name TEXT, sl_no INTEGER, "
                        "current_stock REAL, erp_stock REAL)")
            cur.execute("CREATE TABLE IF NOT EXISTS fresh_start_log (fs_batch TEXT PRIMARY KEY, factory_name TEXT, "
                        "created_at TEXT, created_by TEXT, scope TEXT, tx_count INTEGER, max_tx_id INTEGER, "
                        "status TEXT DEFAULT 'Done')")
        conn.commit()
        st.session_state["_fs_tables_ready"] = True
        _once_flags()["fs_tables"] = True
    except Exception:
        conn.rollback()
        raise


def _fs_common(t1, t2):
    def cols(t):
        return [r["column_name"] for r in q("SELECT column_name FROM information_schema.columns "
                                            "WHERE table_schema='public' AND table_name=%s ORDER BY ordinal_position", (t,))]
    c2 = set(cols(t2))
    return [c for c in cols(t1) if c in c2 and c != "fs_batch"]


@tx
def fresh_start_reset(fac, user, d1, d2, scope):
    """Archives then removes the unit's transactions (+ issue returns) and sets Physical & ERP stock to 0.
    Item master (names, sizes, prices, serials) is untouched."""
    psql, pp = period_sql("date", d1, d2)
    tc = ", ".join(f'"{c}"' for c in _fs_common("transactions", "transactions_archive"))
    rc = ", ".join(f'"{c}"' for c in _fs_common("issue_returns", "issue_returns_archive"))
    batch = local_now().strftime("%Y%m%d%H%M%S") + "-" + "".join(ch for ch in fac if ch.isalnum())[:6]
    max_id = int(q("SELECT COALESCE(MAX(id),0) AS m FROM transactions")[0]["m"])
    sub = f"SELECT id FROM transactions WHERE factory_name=%s{psql}"
    sp = [fac] + pp
    n = int(q(f"SELECT COUNT(*) AS n FROM transactions WHERE factory_name=%s{psql}", sp)[0]["n"])
    run(f"INSERT INTO issue_returns_archive (fs_batch, {rc}) SELECT %s, {rc} FROM issue_returns WHERE tx_id IN ({sub})", [batch] + sp)
    run(f"INSERT INTO transactions_archive (fs_batch, {tc}) SELECT %s, {tc} FROM transactions WHERE factory_name=%s{psql}", [batch] + sp)
    run("INSERT INTO fresh_start_stock (fs_batch, factory_name, sl_no, current_stock, erp_stock) "
        "SELECT %s, factory_name, sl_no, COALESCE(current_stock,0), COALESCE(erp_stock,0) FROM inventory WHERE factory_name=%s",
        (batch, fac))
    run(f"DELETE FROM issue_returns WHERE tx_id IN ({sub})", sp)
    run(f"DELETE FROM transactions WHERE factory_name=%s{psql}", sp)
    run("UPDATE inventory SET current_stock=0, erp_stock=0 WHERE factory_name=%s", (fac,))
    run("INSERT INTO fresh_start_log (fs_batch, factory_name, created_at, created_by, scope, tx_count, max_tx_id) "
        "VALUES (%s,%s,%s,%s,%s,%s,%s)",
        (batch, fac, local_now().strftime("%d-%b-%Y %I:%M %p"), user, scope, n, max_id))
    audit("FRESH_START_RESET", f"{user} reset {fac}: {n} transaction(s) archived ({scope}), all stock set to 0, batch {batch}")
    return n


@tx
def fresh_start_undo(batch, user):
    lg = q("SELECT * FROM fresh_start_log WHERE fs_batch=%s AND status='Done'", (batch,))
    if not lg:
        return False
    fac, max_id = lg[0]["factory_name"], int(lg[0]["max_tx_id"])
    tc = ", ".join(f'"{c}"' for c in _fs_common("transactions", "transactions_archive"))
    rc = ", ".join(f'"{c}"' for c in _fs_common("issue_returns", "issue_returns_archive"))
    run("DELETE FROM transactions WHERE factory_name=%s AND id > %s AND trans_type=%s", (fac, max_id, OPENING_TYPE))
    run(f"INSERT INTO transactions ({tc}) SELECT {tc} FROM transactions_archive WHERE fs_batch=%s", (batch,))
    run(f"INSERT INTO issue_returns ({rc}) SELECT {rc} FROM issue_returns_archive WHERE fs_batch=%s", (batch,))
    run("""UPDATE inventory i SET current_stock=f.current_stock, erp_stock=f.erp_stock
           FROM fresh_start_stock f WHERE f.fs_batch=%s AND f.factory_name=i.factory_name AND f.sl_no=i.sl_no""", (batch,))
    run("UPDATE fresh_start_log SET status='Undone' WHERE fs_batch=%s", (batch,))
    audit("FRESH_START_UNDO", f"{user} restored {fac} to the state before batch {batch}")
    return True


@tx
def apply_count_as_opening(fac, user, rows, date_s, day):
    """Sets Physical stock = counted qty for every counted item and logs an Opening Balance transaction each.
    ERP stock is left as it is (update it later from the ERP update screen)."""
    _tags = sorted({f"Opening from Physical Count #{r['count_id']}" for r in rows})
    _have = {(int(x["sl_no"]), x["notes"]) for x in q(
        "SELECT sl_no, notes FROM transactions WHERE factory_name=%s AND trans_type=%s AND notes = ANY(%s)", (fac, OPENING_TYPE, _tags))}
    _skipped = 0
    for r in rows:
        if (int(r["sl_no"]), f"Opening from Physical Count #{r['count_id']}") in _have:
            _skipped += 1      # this count was already applied to this item: applying it again only duplicates the row and resets stock again
            continue
        run("UPDATE inventory SET current_stock=%s WHERE sl_no=%s AND factory_name=%s", (float(r["counted_qty"]), r["sl_no"], fac))
        r_date = r.get("count_date") or date_s          # the item's own count date
        _pd = parse_date(r_date)
        r_day = _pd.day if _pd else day
        insert_tx(fac, user, r["sl_no"], r["prod_id"], r["item_name"], float(r["counted_qty"]), OPENING_TYPE, r_day,
                  f"Opening from Physical Count #{r['count_id']}", r_date, local_now().strftime("%I:%M %p"), "Verified")
    audit("OPENING_FROM_COUNT", f"{user} applied {len(rows) - _skipped} counted item(s) as opening for {fac} ({date_s})"
          + (f" ({_skipped} already applied, skipped)" if _skipped else ""))
    if _skipped:
        st.warning(f"{_skipped}টি item-এ এই count আগেই Opening হিসেবে বসানো ছিল — আবার বসানো হয়নি (duplicate আটকানো হলো)।")
    return len(rows) - _skipped


@tx
def fresh_start_clear_transfers(fac, user, d1, d2):
    """Archives then removes transfer RECORDS touching this unit. Stock is not changed."""
    run("CREATE TABLE IF NOT EXISTS inter_factory_transfers_archive (LIKE inter_factory_transfers)")
    run("ALTER TABLE inter_factory_transfers_archive ADD COLUMN IF NOT EXISTS fs_at TEXT")
    cols = ", ".join(f'"{c}"' for c in _fs_common("inter_factory_transfers", "inter_factory_transfers_archive") if c != "fs_at")
    psql, pp = period_sql("transfer_date", d1, d2)
    w = f"(source_factory=%s OR dest_factory=%s){psql}"
    wp = [fac, fac] + pp
    n = int(q(f"SELECT COUNT(*) AS n FROM inter_factory_transfers WHERE {w}", wp)[0]["n"])
    run(f"INSERT INTO inter_factory_transfers_archive (fs_at, {cols}) SELECT %s, {cols} FROM inter_factory_transfers WHERE {w}",
        [local_now().strftime("%d-%b-%Y %I:%M %p")] + wp)
    run(f"DELETE FROM inter_factory_transfers WHERE {w}", wp)
    audit("FRESH_START_CLEAR_TRANSFERS", f"{user} removed {n} transfer record(s) touching {fac} (record only, stock unchanged)")
    return n


@_fragment
def pc_fresh_view():
    st.caption("Notun kore shuru korar jonno: (1) backup, (2) ei unit-er transaction muche sob stock 0, "
               "(3) physical count kora, (4) count-ke opening balance hishabe boshano. Item-er nam/size/price kichu muchbe na.")
    if st.session_state.get("role") != "Store Manager":
        st.info("Fresh Start shudhu Store Manager-er permission-e.")
        return
    if "CONSOLIDATED" in FAC:
        st.warning("Specific unit select korun (jemon KC Washing Plant). CONSOLIDATED-e ei option cholbe na.")
        return
    user = st.session_state.get("user", "")
    try:
        _fs_ensure()
    except Exception as e:
        st.error(f"Archive table toiri hoy nai: {e}")
        return

    st.markdown(f"### Unit: **{FAC}**")
    # ---------- Step 1 + 2 : backup and reset ----------
    st.markdown("#### 1️⃣ Backup  →  2️⃣ Reset")
    if st.button("📦 Backup toiri korun", key="pc_fs_bk"):
        st.session_state["pc_fs_backup"] = backup_zip()
    if st.session_state.get("pc_fs_backup"):
        st.download_button("💾 Backup download (zip)", st.session_state["pc_fs_backup"],
                           f"windy_backup_{local_now().strftime('%Y%m%d_%H%M')}.zip", "application/zip", key="pc_fs_dl")
    scope = st.radio("Kon transaction muchben", ["Ei mash-er (1 tarikh theke ajke porjonto)", "Sob transaction (shuru theke)"],
                     key="pc_fs_scope")
    today = local_now().date()
    if scope.startswith("Ei mash"):
        d1, d2 = today.replace(day=1), today
    else:
        d1 = d2 = None
    psql, pp = period_sql("date", d1, d2)
    summ = q(f"SELECT trans_type, COUNT(*) AS n FROM transactions WHERE factory_name=%s{psql} GROUP BY trans_type ORDER BY 2 DESC",
             [FAC] + pp)
    inv = q("SELECT COUNT(*) AS n, COALESCE(SUM(CASE WHEN COALESCE(current_stock,0)<>0 OR COALESCE(erp_stock,0)<>0 THEN 1 END),0) AS s "
            "FROM inventory WHERE factory_name=%s", (FAC,))[0]
    c1, c2 = st.columns(2)
    c1.metric("Transaction muchbe", sum(int(r["n"]) for r in summ))
    c2.metric("Stock 0 hobe (item)", int(inv["s"]))
    if summ:
        st.caption(" · ".join(f"{r['trans_type']}: {int(r['n'])}" for r in summ))
    st.caption("Reset-er age sob muchar jinis archive-e jomaa hoy, tai niche 'Undo' diye ferot ana jabe "
               "(jodi reset-er por kono Issue/Receipt na hoy). Requisition, Transfer, Repair, Hold Bill-er kichu change hobe na.")
    ok_bk = st.checkbox("Backup download koreci", key="pc_fs_ok1")
    word = st.text_input("Confirm korte RESET likhun", key="pc_fs_word")
    pw = st.text_input("Store Manager Password", type="password", key="pc_fs_pw")
    if st.button("🧹 Reset: transaction muche sob stock 0 korun", type="primary", key="pc_fs_go",
                 disabled=not (ok_bk and word.strip() == "RESET")):
        if not verify_manager_password(pw):
            st.error("Manager password thik noy.")
        elif guard():
            n = fresh_start_reset(FAC, user, d1, d2, "this month" if d1 else "all")
            for k in ("pc_fs_ok1", "pc_fs_word", "pc_fs_pw", "pc_fs_backup"):
                st.session_state.pop(k, None)
            done(f"Reset hoyeche: {n} ti transaction archive hoye muche geche, sob stock 0.")

    # ---------- Undo ----------
    last = q("SELECT * FROM fresh_start_log WHERE factory_name=%s AND status='Done' ORDER BY fs_batch DESC LIMIT 1", (FAC,))
    if last:
        lg = last[0]
        later = int(q("SELECT COUNT(*) AS n FROM transactions WHERE factory_name=%s AND id > %s AND trans_type<>%s",
                      (FAC, int(lg["max_tx_id"]), OPENING_TYPE))[0]["n"])
        with st.expander(f"↩️ Undo last reset ({lg['created_at']} · {lg['tx_count']} tx · {lg['created_by']})"):
            if later:
                st.warning(f"Reset-er por {later} ti notun Issue/Receipt hoyeche, tai auto-undo off. "
                           "Backup zip theke manually ferot anun.")
            else:
                st.caption("Undo korle purano transaction ar purano stock (Physical + ERP) ferot ashbe; "
                           "reset-er por boshano Opening Balance gulo muche jabe.")
                pw2 = st.text_input("Store Manager Password", type="password", key="pc_fs_pw2")
                ok2 = st.checkbox("Ami undo korte chai", key="pc_fs_ok2")
                if st.button("↩️ Undo", key="pc_fs_undo", disabled=not ok2):
                    if not verify_manager_password(pw2):
                        st.error("Manager password thik noy.")
                    elif guard() and fresh_start_undo(lg["fs_batch"], user):
                        done("Reset undo hoyeche - ager transaction ar stock ferot esheche.")

    # ---------- Transfer history (record only) ----------
    with st.expander("🧾 Transfer History clear (shudhu record - stock change hobe na)"):
        tscope = st.radio("Kon transfer record", ["Ei mash-er", "Sob"], horizontal=True, key="pc_fs_tscope")
        t1, t2 = (today.replace(day=1), today) if tscope.startswith("Ei") else (None, None)
        tps, tpp = period_sql("transfer_date", t1, t2)
        tn = int(q(f"SELECT COUNT(*) AS n FROM inter_factory_transfers WHERE (source_factory=%s OR dest_factory=%s){tps}",
                   [FAC, FAC] + tpp)[0]["n"])
        st.metric("Muchbe (ei unit source ba destination)", tn)
        st.caption("Shudhu history record muche jay (archive table-e copy thake). Stock kom/besh hobe na. "
                   "Dui unit-er shob transfer jodi muchte chan, duita unit-e alada kore korun.")
        tok = st.checkbox("Ami transfer record muchte chai (stock change hobe na)", key="pc_fs_tok")
        tpw = st.text_input("Store Manager Password", type="password", key="pc_fs_tpw")
        if st.button("🧾 Transfer records muchun", key="pc_fs_tgo", disabled=not (tok and tn)):
            if not verify_manager_password(tpw):
                st.error("Manager password thik noy.")
            elif guard():
                n = fresh_start_clear_transfers(FAC, user, t1, t2)
                st.session_state.pop("pc_fs_tok", None)
                st.session_state.pop("pc_fs_tpw", None)
                done(f"{n} ti transfer record muche geche (stock change hoyni).")

    # ---------- Step 3 + 4 : count -> opening ----------
    st.markdown("---")
    st.markdown("#### 3️⃣ Count  →  4️⃣ Count-ke Opening boshan")
    st.caption("Age 'New count' tab-e physical count korun. Je item gulo count korben sob ekhane chole asbe (date lagbe na). "
               "Opening boshale oi item ekhan theke soriye jabe. Prottek item-er shesh count-er qty Physical stock hobe. ERP stock change hobe na.")
    # Every counted item that is NOT yet set as opening shows here - no date needed. Once it is set as opening it leaves this list.
    rows_all = q("""SELECT x.* FROM (
                      SELECT DISTINCT ON (i.sl_no) i.sl_no, i.prod_id, i.item_name, COALESCE(i.size,'') AS size, i.counted_qty,
                             i.count_id, c.counted_by, c.counted_at
                      FROM stock_count_items i JOIN stock_counts c ON c.id=i.count_id
                      WHERE c.factory_name=%s AND i.sl_no IS NOT NULL
                      ORDER BY i.sl_no, i.id DESC) x
                    WHERE NOT EXISTS (SELECT 1 FROM transactions t
                                      WHERE t.factory_name=%s AND t.sl_no=x.sl_no AND t.trans_type=%s
                                        AND t.notes = 'Opening from Physical Count #' || x.count_id)
                    ORDER BY x.count_id, x.sl_no""", (FAC, FAC, OPENING_TYPE))
    # counts made before the last Reset belong to the old data - hide them unless asked
    items = rows_all
    cut = None
    if last:
        try:
            cut = datetime.strptime(str(last[0]["created_at"]), "%d-%b-%Y %I:%M %p")
        except Exception:
            cut = None
    if cut and rows_all:
        def _after(r):
            try:
                return datetime.strptime(str(r["counted_at"]), "%d-%b-%Y %I:%M %p") >= cut
            except Exception:
                return True
        newer = [r for r in rows_all if _after(r)]
        older = len(rows_all) - len(newer)
        if older and st.checkbox(f"Reset-er age-er {older} ti purano count-o dekhao", key="pc_fs_old"):
            items = rows_all
        else:
            items = newer
    if not items:
        st.success("Opening boshanor moto kono count baki nei. Notun item physical count korle ekhane chole asbe.")
        return
    for r in items:
        r["count_date"] = str(r["counted_at"] or "")[:11]
    st.dataframe(pd.DataFrame([{"SL No": r["sl_no"], "Item": r["item_name"], "Size": r["size"],
                                "Opening (counted)": float(r["counted_qty"]), "Count #": r["count_id"],
                                "Counted at": r["counted_at"]} for r in items]),
                 hide_index=True, use_container_width=True, height=min(60 + 35 * len(items), 360))
    pend_sl = [r["sl_no"] for r in items]
    mind = min((parse_date(r["count_date"]) for r in items if parse_date(r["count_date"])), default=None)
    other = 0
    if mind:
        d_from = mind.date() if hasattr(mind, "date") else mind
        other = int(q(f"SELECT COUNT(*) AS n FROM transactions WHERE factory_name=%s AND trans_type<>%s AND sl_no = ANY(%s)"
                      f"{period_sql('date', d_from, today)[0]}", [FAC, OPENING_TYPE, pend_sl] + period_sql('date', d_from, today)[1])[0]["n"])
    force = True
    if other:
        st.warning(f"Ei item gulor count-er tarikh ba tar por {other} ti Issue/Receipt ache. Opening boshale stock count-er "
                   "number-e overwrite hobe, oi transaction-er effect hariye jabe.")
        force = st.checkbox("Tobuo opening boshabo", key="pc_fs_force")
    ok3 = st.checkbox(f"{len(items)} ti item-er Physical stock count-er number-e set hobe", key="pc_fs_ok3")
    if st.button("✅ Count-ke Opening Balance hishabe boshan", type="primary", key="pc_fs_apply", disabled=not (ok3 and force)):
        if guard():
            n = apply_count_as_opening(FAC, user, items, today.strftime(DATE_FMT), today.day)
            st.session_state.pop("pc_fs_ok3", None)
            done(f"{n} ti item-er Opening Balance boshano hoyeche. Ekhon ERP balance update korte paren.")


