# ------------------------------------------------------------------
#  4. Similar-name warning (Add New Item)
# ------------------------------------------------------------------
@st.cache_data(ttl=45, show_spinner=False)
def _item_name_index(fac):
    rows = q("SELECT sl_no, prod_id, item_name, COALESCE(size,'') AS size, COALESCE(current_stock,0) AS stock "
             "FROM inventory WHERE factory_name=%s", (fac,))
    for r in rows:
        r["tokens"] = tuple(sorted(_name_tokens(r["item_name"], r["size"])))
    return rows


def _name_tokens(name, size=""):
    s = f"{name} {size}".lower()
    toks = re.findall(r"\d+|[^\W\d_]+", s)
    return {t for t in toks if t not in ("pcs", "pc", "no", "nos", "the", "of", "for", "and", "with")}


def similar_items(fac, name, size, limit=5, threshold=0.8):
    """'Bearing 6205' vs '6205 Bearing' -> same words in another order. Different numbers (6205 vs 6206) never match."""
    a = _name_tokens(name, size)
    if len(a) == 0:
        return []
    a_nums = {t for t in a if t.isdigit()}
    found = []
    for r in _item_name_index(fac):
        b = set(r["tokens"])
        if not (a & b):
            continue
        b_nums = {t for t in b if t.isdigit()}
        if a_nums and b_nums and not (a_nums & b_nums):
            continue
        jac = len(a & b) / len(a | b)
        if jac < 0.4:
            continue
        sim = 1.0 if a == b else max(jac, difflib.SequenceMatcher(None, " ".join(sorted(a)), " ".join(sorted(b))).ratio())
        if sim >= threshold:
            found.append((sim, r))
    found.sort(key=lambda x: -x[0])
    return found[:limit]


def similar_item_alert(fac, name, size):
    """Soft warning only (never blocks saving): different-but-similar items such as '6205 ZZ' and '6205 2RS' are legitimate."""
    if "CONSOLIDATED" in str(fac) or len(str(name or "").strip()) < 3:
        return
    try:
        hits = similar_items(fac, name, size)
    except Exception:
        return
    if not hits:
        return
    lines = "\n".join(f"- **{h['item_name']}** [{h['size'] or '-'}]{_uom_tag(h)} · ERP {h['prod_id']} · SL {h['sl_no']} · "
                      f"stock {float(h['stock']):g} · মিল {int(round(s * 100))}%" for s, h in hits)
    st.warning(f"⚠️ এই নামের কাছাকাছি আইটেম আগে থেকেই আছে — এটাই কি?\n\n{lines}\n\n"
               "এটাই হলে নতুন আইটেম না বানিয়ে Transactions-এ গিয়ে ওই আইটেমে stock যোগ করুন। সত্যিই আলাদা আইটেম হলে নিচে চালিয়ে যান।")
    top = hits[0][1]
    if st.button("📝 এটাই — Transactions-এ যাই", key="sim_go_tx"):
        g = st.session_state.get("tx_gen", 0)
        st.session_state[f"tx_search_{g}"] = str(top["item_name"])
        st.session_state[NAV_KEY] = NAV_TRANSACTIONS
        _full_rerun()


# ------------------------------------------------------------------
#  8. Item one-page history  (Stock Cover -> "📄 আইটেমের ইতিহাস")
# ------------------------------------------------------------------
def _ih_label(r):
    return (f"{r['item_name']} [{r['size'] or '-'}]{_uom_tag(r)} · {r['prod_id'] or '-'} · "
            f"{short_fac(r['factory_name'])} · SL {r['sl_no']}")


def item_history_view(df):
    """Pick one item -> stock, ERP balance, every Issue/Receipt, who issued how much, total cost, earlier mismatches."""
    d = df if "CONSOLIDATED" in str(FAC) else df[df["factory_name"] == FAC]
    st.markdown('<div class="section-title">📄 আইটেমের এক পাতার ইতিহাস</div>', unsafe_allow_html=True)
    st.caption("একটি আইটেম বেছে নিন — স্টক, ERP ব্যালেন্স, সব Issue/Receipt, কে কত Issue করেছে, মোট খরচ ও আগের অমিল এক স্ক্রিনে।")
    term = st.text_input("🔍 আইটেম খুঁজুন (নাম / ERP code / serial / size)", key="ih_search")
    t = term.strip().lower()
    if not t:
        st.info("ওপরের বক্সে আইটেমের নাম বা code লিখুন।")
        return
    m = d[["item_name", "prod_id", "serial_no", "size"]].astype(str).apply(
        lambda c: c.str.lower().str.contains(t, regex=False)).any(axis=1)
    v = d[m].sort_values(["item_name", "size"]).head(200)
    if v.empty:
        st.warning("এই নামে কোনো আইটেম পাওয়া যায়নি।")
        return
    recs = v.to_dict("records")
    labels = {_ih_label(r): r for r in recs}
    choice = st.selectbox("আইটেম বেছে নিন", list(labels), key="ih_pick_box")
    row = labels.get(choice) or recs[0]
    fac, sl = row["factory_name"], int(row["sl_no"])
    price, unit = float(row["price"] or 0), row["unit"]
    pid = str(row["prod_id"] or "").strip()

    tx_df = qdf_c("""SELECT id, date, time, trans_type, qty, COALESCE(officer_name,'') AS officer,
                     COALESCE(notes,'') AS notes, COALESCE(verification_status,'') AS verif
                     FROM transactions WHERE factory_name=%s AND sl_no=%s ORDER BY id DESC""", (fac, sl))
    if not tx_df.empty:
        tx_df["qty"] = pd.to_numeric(tx_df["qty"], errors="coerce").fillna(0.0)
        tx_df["d"] = _parse_dates(tx_df["date"])
        iss = tx_df[tx_df["trans_type"].isin(ISSUE_TYPES)]
        rec = tx_df[tx_df["trans_type"].isin(RECEIPT_TYPES)]
    else:
        iss = rec = tx_df
    iss_q, rec_q = (float(iss["qty"].sum()), float(rec["qty"].sum())) if not tx_df.empty else (0.0, 0.0)
    gap = float(row["stock"]) - float(row["erp"])

    st.markdown(f"### {html_lib.escape(str(row['item_name']))} [{html_lib.escape(str(row['size'] or '-'))}]")
    st.caption(f"{fac} · ERP code {pid or '-'} · SL {sl} · Serial {row['serial_no'] or '-'} · UOM {unit} · একক দাম ৳{price:,.2f}")
    k = st.columns(4)
    k[0].metric("Physical stock", f"{float(row['stock']):g} {unit}")
    k[1].metric("ERP balance", f"{float(row['erp']):g} {unit}")
    k[2].metric("Physical − ERP", f"{gap:+g}", "মিলে আছে" if abs(gap) < 1e-9 else ("Excess" if gap > 0 else "Short"),
                delta_color="off")
    k[3].metric("কত দিন চলবে", cover_label(float(row["stock"]), float(row["avg_daily"]), float(row["cover_days"])))
    k2 = st.columns(4)
    k2[0].metric("মোট Issue", f"{iss_q:g} {unit}", f"{len(iss)} বার", delta_color="off")
    k2[1].metric("মোট Issue খরচ", f"৳{iss_q * price:,.0f}")
    k2[2].metric("মোট Receipt", f"{rec_q:g} {unit}", f"{len(rec)} বার", delta_color="off")
    last_iss = iss["d"].max() if (not tx_df.empty and not iss.empty) else pd.NaT
    k2[3].metric("সর্বশেষ Issue", "-" if pd.isna(last_iss) else last_iss.strftime(DATE_FMT))

    cL, cR = st.columns([1, 1], gap="large")
    with cL:
        st.markdown('<div class="section-title">কে কত Issue করেছে</div>', unsafe_allow_html=True)
        if iss.empty:
            st.caption("এই আইটেমে এখনো কোনো Issue নেই।")
        else:
            by = iss.groupby("officer").agg(বার=("qty", "size"), পরিমাণ=("qty", "sum"), শেষ_Issue=("d", "max")).reset_index()
            by["খরচ (৳)"] = by["পরিমাণ"] * price
            by["শেষ_Issue"] = by["শেষ_Issue"].dt.strftime(DATE_FMT)
            by = by.sort_values("পরিমাণ", ascending=False).rename(columns={"officer": "Officer", "শেষ_Issue": "শেষ Issue"})
            st.dataframe(by, hide_index=True, use_container_width=True, height=min(60 + 35 * len(by), 300),
                         column_config={"পরিমাণ": st.column_config.NumberColumn(format="%.2f"),
                                        "খরচ (৳)": st.column_config.NumberColumn(format="%.0f")})
    with cR:
        st.markdown('<div class="section-title">মাসওয়ারি Issue (পরিমাণ)</div>', unsafe_allow_html=True)
        ok = iss[iss["d"].notna()] if not iss.empty else iss
        if ok.empty:
            st.caption("দেখানোর মতো তারিখসহ Issue নেই।")
        else:
            mo = ok.assign(মাস=ok["d"].dt.strftime("%Y-%m")).groupby("মাস")["qty"].sum()
            st.bar_chart(mo, use_container_width=True, height=240)

    st.markdown('<div class="section-title">সব লেনদেনের টাইমলাইন (নতুন আগে)</div>', unsafe_allow_html=True)
    if tx_df.empty:
        st.caption("কোনো লেনদেন নেই।")
    else:
        flt = st.radio("দেখান", ["সব", "শুধু Issue", "শুধু Receipt"], horizontal=True, key="ih_filter", label_visibility="collapsed")
        tv = tx_df
        if flt == "শুধু Issue":
            tv = tx_df[tx_df["trans_type"].isin(ISSUE_TYPES + (ADJ_OUT,))]
        elif flt == "শুধু Receipt":
            tv = tx_df[tx_df["trans_type"].isin(RECEIPT_TYPES)]
        sign = tv["trans_type"].map(lambda x: -1.0 if x in ISSUE_TYPES + (ADJ_OUT,) else (1.0 if x in RECEIPT_TYPES else 0.0))
        out = pd.DataFrame({"Date": tv["date"], "Time": tv["time"],
                            "Type": tv["trans_type"].map(lambda x: TRANS_LABELS.get(x, x)),
                            "Qty": [(q_ * s_ if s_ else q_) for q_, s_ in zip(tv["qty"], sign)],
                            "Officer": tv["officer"], "Verification": tv["verif"], "Notes": tv["notes"]})
        st.dataframe(out, hide_index=True, use_container_width=True, height=360,
                     column_config={"Qty": st.column_config.NumberColumn(format="%+.2f")})
        export_buttons(out, f"item_history_{sl}")

    st.markdown('<div class="section-title">আগের অমিল</div>', unsafe_allow_html=True)
    try:
        ensure_count_tables()
        cnt = qdf_c("""SELECT sc.counted_at, sc.counted_by, sc.status, sci.system_qty, sci.counted_qty
                       FROM stock_count_items sci JOIN stock_counts sc ON sc.id=sci.count_id
                       WHERE sci.factory_name=%s AND sci.sl_no=%s ORDER BY sc.id DESC""", (fac, sl))
    except Exception:
        cnt = pd.DataFrame()
    if cnt.empty:
        st.caption("📱 Physical Count: এই আইটেম এখনো গোনা হয়নি।")
    else:
        cnt["system_qty"] = pd.to_numeric(cnt["system_qty"], errors="coerce").fillna(0.0)
        cnt["counted_qty"] = pd.to_numeric(cnt["counted_qty"], errors="coerce").fillna(0.0)
        cnt["পার্থক্য"] = cnt["counted_qty"] - cnt["system_qty"]
        n_bad = int((cnt["পার্থক্য"].abs() >= 1e-9).sum())
        st.caption(f"📱 Physical Count: {len(cnt)} বার গোনা হয়েছে, তার মধ্যে {n_bad} বার সিস্টেমের সাথে অমিল।")
        st.dataframe(cnt.rename(columns={"counted_at": "গণনার সময়", "counted_by": "গণনাকারী", "status": "Status",
                                         "system_qty": "System", "counted_qty": "গোনা"}),
                     hide_index=True, use_container_width=True, height=min(60 + 35 * len(cnt), 260))
    if pid and not is_blank_code(pid) and not pid.upper().startswith("TEMP-"):
        try:
            tasks = qdf_c("""SELECT task_date, variance_type, variance_qty, variance_value, root_cause, corrective_action, status
                             FROM audit_correction_tasks WHERE factory_name=%s AND prod_id=%s ORDER BY id DESC""", (fac, pid))
        except Exception:
            tasks = pd.DataFrame()
        if tasks.empty:
            st.caption("🔍 ERP Audit: এই আইটেমে আগের Short/Excess task নেই।")
        else:
            st.caption(f"🔍 ERP Audit: আগে {len(tasks)}টি Short/Excess correction task হয়েছে।")
            st.dataframe(tasks, hide_index=True, use_container_width=True, height=min(60 + 35 * len(tasks), 260))
        try:
            xf = qdf_c("""SELECT transfer_date, transfer_time, source_factory, dest_factory, qty, status
                          FROM inter_factory_transfers WHERE prod_id=%s AND (source_factory=%s OR dest_factory=%s)
                          ORDER BY id DESC""", (pid, fac, fac))
        except Exception:
            xf = pd.DataFrame()
        if not xf.empty:
            st.caption(f"🔁 Inter-factory transfer: {len(xf)} বার।")
            st.dataframe(xf, hide_index=True, use_container_width=True, height=min(60 + 35 * len(xf), 240))


# ------------------------------------------------------------------
#  9. Unusual-issue detector (Dashboard, for the manager)
# ------------------------------------------------------------------
RECENT_ANOM_DAYS = 7     # how many recent days are checked
SAME_DAY_MIN = None      # বার-ভিত্তিক নিয়ম বন্ধ: Requisition অনুযায়ী একই আইটেম দিনে ১০ বারও Issue হতে পারে (সংখ্যা দিলে আবার চালু হবে, যেমন 3)
MONTH_WINDOW = 30        # মাসিক পরিমাণ যাচাইয়ের জন্য কত দিনের rolling যোগফল দেখা হবে
MONTH_FACTOR = 2.5       # গত ৩০ দিনের মোট Qty আইটেমের স্বাভাবিক মাসিক Qty-র এর বেশি গুণ হলে চিহ্নিত
BN_MONTHS = ["জানুয়ারি", "ফেব্রুয়ারি", "মার্চ", "এপ্রিল", "মে", "জুন", "জুলাই", "আগস্ট", "সেপ্টেম্বর", "অক্টোবর", "নভেম্বর", "ডিসেম্বর"]


def bn_date(d):
    return f"{bn(d.day)} {BN_MONTHS[d.month - 1]}"


@st.cache_data(ttl=300, show_spinner=False)
def _issue_hist(stamp, today_s, days=120):
    """Issues of the last ~120 days with item price/category (shared by the unusual-issue detector and the budget forecast)."""
    today = datetime.strptime(today_s, "%Y-%m-%d").date()
    since = today - timedelta(days=days)
    years = sorted({today.year, since.year})
    cond = " OR ".join(["t.date LIKE %s OR t.date LIKE %s OR t.date LIKE %s"] * len(years))
    pats = []
    for y in years:
        pats += [f"%-{y}", f"{y}-%", f"%/{y}"]
    df = qdf_c(f"""SELECT t.factory_name, t.sl_no, t.date, t.qty, COALESCE(t.officer_name,'') AS officer,
                  COALESCE(t.item_name,'') AS item_name, COALESCE(t.prod_id,'') AS prod_id,
                  COALESCE(i.size,'') AS size, COALESCE(i.unit_price,0) AS price, COALESCE(i.category,'') AS category,
                  COALESCE(NULLIF(i.unit_name,''),'Pcs') AS unit
                  FROM transactions t LEFT JOIN inventory i ON i.sl_no=t.sl_no AND i.factory_name=t.factory_name
                  WHERE t.trans_type IN ('Issued','Internal Issue') AND t.factory_name = ANY(%s) AND ({cond})""",
               [FACTORIES] + pats)
    if df.empty:
        return df
    df["d"] = _parse_dates(df["date"])
    df["qty"] = pd.to_numeric(df["qty"], errors="coerce").fillna(0.0)
    df["price"] = pd.to_numeric(df["price"], errors="coerce").fillna(0.0)
    return df[df["d"].notna() & (df["d"] >= pd.Timestamp(since)) & (df["d"] <= pd.Timestamp(today))].reset_index(drop=True)


def _anomalies_from_df(iss, today, recent_days=RECENT_ANOM_DAYS, same_day_min=SAME_DAY_MIN):
    """Quantity-based detector (Issue কতবার হয়েছে সেটা নয়, কতটুকু Qty গেছে সেটাই দেখা হয়).
    Rule 1 (দৈনিক): ওই দিনের মোট Qty আইটেমের নিজের স্বাভাবিক দিনের চেয়ে অনেক বেশি
            (5+ আগের Issue-দিন লাগে; median-এর 3 গুণের বেশি এবং স্বাভাবিক ওঠানামার বাইরে).
    Rule 2 (মাসিক): গত MONTH_WINDOW দিনের মোট Qty আইটেমের নিজের স্বাভাবিক মাসিক Qty-র MONTH_FACTOR গুণের বেশি
            (আইটেমের কমপক্ষে ~২ মাসের ইতিহাস লাগে).
    Rule 3 (ঐচ্ছিক, এখন বন্ধ): একই দিনে `same_day_min`+ বার Issue — SAME_DAY_MIN = None থাকলে প্রযোজ্য নয়."""
    if iss is None or iss.empty:
        return []
    import numpy as np
    daily = iss.groupby(["factory_name", "sl_no", "d"]).agg(
        n=("qty", "size"), q=("qty", "sum"), item=("item_name", "first"), size=("size", "first"), prod=("prod_id", "first"),
        price=("price", "first"), unit=("unit", "first"),
        officers=("officer", lambda s: ", ".join(sorted({str(x) for x in s if str(x).strip()})))).reset_index()
    start = pd.Timestamp(today) - pd.Timedelta(days=recent_days - 1)
    win0 = pd.Timestamp(daily["d"].min())
    n_days = int((pd.Timestamp(today) - win0).days) + 1
    start_idx = int((start - win0).days)
    flags = []
    for (fac, sl), g in daily.groupby(["factory_name", "sl_no"]):
        recent = g[g["d"] >= start]
        if recent.empty:
            continue
        base = g[g["d"] < start]["q"]
        med = mad = None
        if len(base) >= 5:
            med = float(base.median())
            mad = float((base - med).abs().median())
        # ---- মাসিক: গত MONTH_WINDOW দিনের rolling মোট Qty বনাম আইটেমের নিজের আগের মাসিক মোট ----
        m_hit = None      # (index of latest recent issue-day over the limit, rolling total, usual monthly)
        if len(base) >= 5 and n_days > MONTH_WINDOW and start_idx > MONTH_WINDOW:
            idx = (g["d"] - win0).dt.days.to_numpy().astype(int)
            arr = np.bincount(idx, weights=g["q"].to_numpy(dtype=float), minlength=n_days)[:n_days]
            cs = np.concatenate(([0.0], np.cumsum(arr)))
            first_i = int(idx.min())
            lo = max(MONTH_WINDOW - 1, first_i + MONTH_WINDOW - 1)    # full windows, only after the item's first issue
            hi = start_idx - 1
            if hi - lo + 1 >= 30:                                      # about a month of earlier rolling samples at least
                pts = cs[lo + 1:hi + 2] - cs[lo + 1 - MONTH_WINDOW:hi + 2 - MONTH_WINDOW]
                m_med = float(np.median(pts))
                if m_med > 0:
                    m_mad = float(np.median(np.abs(pts - m_med)))
                    m_thr = max(MONTH_FACTOR * m_med, m_med + 3.0 * 1.4826 * m_mad)
                    for i in sorted(set(int(x) for x in idx if x >= start_idx), reverse=True):
                        tot = float(cs[i + 1] - cs[i + 1 - MONTH_WINDOW])
                        if tot > m_thr and (tot - m_med) >= 2:
                            m_hit = (i, tot, m_med)
                            break
        m_day = (win0 + pd.Timedelta(days=m_hit[0])) if m_hit else None
        for r in recent.itertuples():
            reasons = []
            if same_day_min and r.n >= same_day_min:
                reasons.append(f"একই দিনে {bn(int(r.n))} বার Issue")
            usual = None
            if med is not None:
                thr = max(3.0 * med, med + 3.0 * 1.4826 * mad)
                if r.q > thr and (r.q - med) >= 2:
                    usual = med
                    reasons.append(f"স্বাভাবিকের চেয়ে অনেক বেশি: ওই দিন মোট {r.q:g} {r.unit}, সাধারণত দিনে ~{med:g}")
            if m_hit is not None and r.d == m_day:
                reasons.append(f"মাসিক পরিমাণ বেশি: গত {bn(MONTH_WINDOW)} দিনে মোট {m_hit[1]:g} {r.unit}, সাধারণত মাসে ~{m_hit[2]:g}")
            if reasons:
                flags.append({"factory": fac, "sl_no": int(sl), "item": r.item, "size": r.size, "prod_id": r.prod,
                              "date": r.d, "times": int(r.n), "qty": float(r.q), "usual": usual, "unit": r.unit,
                              "value": float(r.q) * float(r.price), "officers": r.officers, "reasons": reasons})
    flags.sort(key=lambda f: (f["date"], f["value"]), reverse=True)
    return flags


@st.cache_data(ttl=300, show_spinner=False)
def compute_issue_anomalies(stamp, today_s):
    today = datetime.strptime(today_s, "%Y-%m-%d").date()
    return _anomalies_from_df(_issue_hist(stamp, today_s), today)


def render_issue_anomaly_card(stamp=None):
    """Manager / Auditor only. Isolated: never blocks the dashboard."""
    if st.session_state.get("role") not in ("Store Manager", "Auditor"):
        return
    today = local_now().date()
    flags = compute_issue_anomalies(stamp or data_stamp(), today.strftime("%Y-%m-%d"))
    if "CONSOLIDATED" not in str(FAC):
        flags = [f for f in flags if f["factory"] == FAC]
    st.markdown(f'<div class="section-title">⚠️ অস্বাভাবিক Issue — গত {bn(RECENT_ANOM_DAYS)} দিন (ম্যানেজারের জন্য)</div>',
                unsafe_allow_html=True)
    if not flags:
        st.success("গত কয়েক দিনে কোনো অস্বাভাবিক Issue ধরা পড়েনি।")
        return
    st.warning(f"{len(flags)}টি Issue যাচাই করার মতো — বড় ভুল এন্ট্রি বা অপচয় হতে পারে।")
    with st.expander(f"তালিকা দেখুন ({len(flags)})", expanded=True):
        rows = [{"Date": f["date"].strftime(DATE_FMT), "Factory": short_fac(f["factory"]), "Item": f["item"], "Size": f["size"],
                 "ERP Code": f["prod_id"], "বার": f["times"], "মোট Qty": round(f["qty"], 2),
                 "সাধারণত/দিন": None if f["usual"] is None else round(f["usual"], 2), "মূল্য (৳)": round(f["value"]),
                 "Officer": f["officers"], "কেন চিহ্নিত": " · ".join(f["reasons"])} for f in flags[:100]]
        st.dataframe(pd.DataFrame(rows), hide_index=True, use_container_width=True, height=min(60 + 35 * len(rows), 380))
        st.caption("Stock Cover → 📄 আইটেমের ইতিহাস-এ গিয়ে আইটেম খুঁজলে পুরো টাইমলাইন দেখা যাবে।")


# ------------------------------------------------------------------
#  10. Budget run-out forecast (Budget page + a one-line hint on the Dashboard)
# ------------------------------------------------------------------
def _runout_from(iss, bud, today):
    """Budget is treated as a MONTHLY budget (same as the Dashboard's default period).  Daily rate = this month's Issue cost so far
    / days gone.  If that pace continues, which date does the remaining budget finish?"""
    if bud is None or bud.empty:
        return []
    month_end = date(today.year, today.month, calendar.monthrange(today.year, today.month)[1])
    month_start = date(today.year, today.month, 1)
    spent = {}
    if iss is not None and not iss.empty:
        cur = iss[(iss["d"] >= pd.Timestamp(month_start)) & (iss["d"] <= pd.Timestamp(today))].copy()
        cur["cost"] = cur["qty"] * cur["price"]
        spent = cur.groupby(["factory_name", "category"])["cost"].sum().to_dict()
    g = bud.groupby(["factory_name", "category_name"]).agg(
        alloc=("allocated_budget", "sum"),
        dept=("department_name", lambda s: ", ".join(sorted({str(x) for x in s if str(x).strip()})))).reset_index()
    out = []
    for r in g.itertuples():
        alloc = float(r.alloc or 0)
        if alloc <= 0:
            continue
        sp = float(spent.get((r.factory_name, r.category_name), 0.0))
        rate = sp / float(today.day)
        rem = alloc - sp
        row = {"factory": r.factory_name, "dept": r.dept, "category": r.category_name, "budget": alloc, "spent": sp,
               "rate": rate, "remaining": rem, "runout": None, "days_left": None, "projected": rate * month_end.day}
        if rem <= 0:
            row["status"] = "over"
        elif rate <= 0:
            row["status"] = "nouse"
        else:
            dl = rem / rate
            ro = today + timedelta(days=int(math.floor(dl)))
            row["days_left"] = dl
            if ro <= month_end:
                row["status"], row["runout"] = "runout", ro
            else:
                row["status"] = "safe"
        out.append(row)
    order = {"over": 0, "runout": 1, "safe": 2, "nouse": 3}
    out.sort(key=lambda x: (order[x["status"]], x["runout"] or date(9999, 1, 1), -x["projected"]))
    return out


@st.cache_data(ttl=300, show_spinner=False)
def compute_budget_runout(stamp, today_s):
    today = datetime.strptime(today_s, "%Y-%m-%d").date()
    bud = qdf_c("""SELECT factory_name, department_name, category_name, COALESCE(allocated_budget,0) AS allocated_budget
                   FROM category_budgets WHERE factory_name = ANY(%s)""", (FACTORIES,))
    return _runout_from(_issue_hist(stamp, today_s), bud, today)


def _runout_text(r):
    if r["status"] == "over":
        return f"🔴 বাজেট ইতিমধ্যে ছাড়িয়েছে (৳{-r['remaining']:,.0f} বেশি)"
    if r["status"] == "runout":
        return f"🟠 {bn_date(r['runout'])} নাগাদ শেষ হবে"
    if r["status"] == "safe":
        return "🟢 এই গতিতে মাস শেষেও চলবে"
    return "⚪ এই মাসে খরচ নেই"


def render_budget_forecast(stamp=None):
    today = local_now().date()
    rows = compute_budget_runout(stamp or data_stamp(), today.strftime("%Y-%m-%d"))
    if "CONSOLIDATED" not in str(FAC):
        rows = [r for r in rows if r["factory"] == FAC]
    st.markdown('<div class="section-title">📅 বাজেট কবে শেষ হবে — আগাম হিসাব</div>', unsafe_allow_html=True)
    if not rows:
        st.caption("হিসাব করার মতো বাজেট লাইন নেই।")
        return
    n_over = sum(1 for r in rows if r["status"] == "over")
    n_run = sum(1 for r in rows if r["status"] == "runout")
    k = st.columns(3)
    k[0].metric("🔴 ইতিমধ্যে ছাড়িয়েছে", n_over)
    k[1].metric("🟠 মাসের মধ্যেই শেষ হবে", n_run)
    k[2].metric("🟢 নিরাপদ", len(rows) - n_over - n_run)
    show = pd.DataFrame([{"Factory": short_fac(r["factory"]), "Category": r["category"], "Budget (৳)": r["budget"],
                          "এ মাসে খরচ (৳)": r["spent"], "গড় খরচ / দিন (৳)": r["rate"], "বাকি (৳)": r["remaining"],
                          "অনুমান": _runout_text(r),
                          "দিন বাকি": None if r["days_left"] is None else round(r["days_left"], 1)} for r in rows])
    st.dataframe(show, hide_index=True, use_container_width=True, height=min(80 + 35 * len(show), 420), column_config={
        "Budget (৳)": st.column_config.NumberColumn(format="%.0f"), "এ মাসে খরচ (৳)": st.column_config.NumberColumn(format="%.0f"),
        "গড় খরচ / দিন (৳)": st.column_config.NumberColumn(format="%.0f"), "বাকি (৳)": st.column_config.NumberColumn(format="%.0f")})
    st.caption(f"হিসাব: এ মাসের এখন পর্যন্ত Issue খরচ ÷ {bn(today.day)} দিন = গড় দৈনিক খরচ; বাজেটকে মাসিক ধরা হয়েছে (Dashboard-এর মতো)। "
               "মাসের প্রথম কয়েক দিনে অনুমান কম নির্ভরযোগ্য।")


def render_budget_runout_hint(stamp=None):
    """One compact line on the Dashboard: only shown when something will run out this month."""
    today = local_now().date()
    rows = compute_budget_runout(stamp or data_stamp(), today.strftime("%Y-%m-%d"))
    if "CONSOLIDATED" not in str(FAC):
        rows = [r for r in rows if r["factory"] == FAC]
    risky = [r for r in rows if r["status"] in ("over", "runout")]
    if not risky:
        return
    st.markdown('<div class="section-title">📅 বাজেট আগাম সতর্কতা</div>', unsafe_allow_html=True)
    lines = "\n".join(f"- **{r['category']}** ({short_fac(r['factory'])}) — {_runout_text(r)}" for r in risky[:6])
    st.warning(f"{len(risky)}টি ক্যাটাগরির বাজেট এই মাসেই শেষ হয়ে যাবে (বা শেষ):\n\n{lines}\n\n💰 Budget পেজে পুরো তালিকা আছে।")


# ------------------------------------------------------------------
#  11. Requisition Audit Reconciliation  (Requisition tab -> "🧾 Audit Reconciliation")
#  The auditor arrives days after the requisition (e.g. req 1st, audit 20th): stock has moved since. This view rebuilds, per item,
#  Opening (on requisition date) + Received - Issued = Balance on the AUDIT date, day by day; the auditor types the physical count;
#  match -> "Audit Done".  PDF / Excel / e-mail text for the auditor.  Stock itself is never changed here.
# ------------------------------------------------------------------
AUDIT_TOL = 1e-6
_TT_SHORT = {"Issued": "Issue", "Internal Issue": "Internal Issue", "Supplier. Rec": "Supplier Receipt", "Internal Rec": "Internal Receipt",
             "Stock Adjustment (+)": "Adjustment (+)", "Stock Adjustment (-)": "Adjustment (-)", "Opening Balance": "Stock set"}


def ensure_req_audit_table():
    if st.session_state.get("_req_audit_ready") or _once_flags().get("req_audit_table"):
        st.session_state["_req_audit_ready"] = True
        return
    conn = get_conn()
    try:
        with conn.cursor() as cur:
            cur.execute("""CREATE TABLE IF NOT EXISTS req_audit_checks (
                id SERIAL PRIMARY KEY, factory_name TEXT, req_no TEXT, req_date TEXT, audit_date TEXT, sl_no INTEGER,
                prod_id TEXT, item_name TEXT, size TEXT, unit TEXT, opening_qty REAL, received_qty REAL, issued_qty REAL,
                system_balance REAL, counted_qty REAL, diff_qty REAL, status TEXT, auditor TEXT, recorded_by TEXT,
                recorded_at TEXT, remarks TEXT DEFAULT '')""")
        conn.commit()
        st.session_state["_req_audit_ready"] = True
        _once_flags()["req_audit_table"] = True
    except Exception:
        conn.rollback()
        raise


def _audit_events(fac, inv, tx_rows, xf_rows, ret_rows=None):
    """Every stock movement of one item as +/- events (receipts, issues, adjustments, stock-set, inter-factory transfers)."""
    ev, flags = [], set()
    returned = {}
    for rr in ret_rows or []:
        returned[rr["tx_id"]] = returned.get(rr["tx_id"], 0.0) + float(rr["qty"] or 0)
    for t in tx_rows:
        dt = parse_date(t["date"])
        if not dt:
            flags.add("কিছু লেনদেনের তারিখ পড়া যায়নি — হিসাবে ধরা হয়নি।")
            continue
        qty, tt = float(t["qty"] or 0), t["trans_type"]
        if tt in RECEIPT_TYPES:
            delta = qty
        elif tt in ISSUE_TYPES or tt == ADJ_OUT:
            qty += returned.get(t.get("id"), 0.0)      # the issue as originally made; the return is its own +event below
            delta = -qty
        elif tt == OPENING_TYPE:
            m = re.search(r"Physical\s*(-?[\d.]+)\s*->\s*(-?[\d.]+)", t.get("notes") or "")
            if m:
                delta = float(m.group(2)) - float(m.group(1))
            else:
                delta = 0.0
                flags.add("Opening/Stock-set লেনদেনের পরিবর্তন পড়া যায়নি — balance সামান্য অমিল হতে পারে।")
        else:
            delta = 0.0
        who = f" by {t['officer']}" if t.get("officer") else ""
        ev.append({"d": dt.date(), "delta": delta, "label": f"{_TT_SHORT.get(tt, tt)} {qty:g}{who}"})
    have = {t.get("id") for t in tx_rows}
    for rr in ret_rows or []:
        dt = parse_date(rr["return_date"])
        if dt and rr["tx_id"] in have:
            ev.append({"d": dt.date(), "delta": float(rr["qty"] or 0), "label": f"Return to store {float(rr['qty'] or 0):g}"})
    nn = norm_name(inv["item_name"])
    for x in xf_rows:
        if str(x.get("status") or "Completed") != "Completed":
            continue
        dt = parse_date(x["transfer_date"])
        if not dt:
            continue
        qty = float(x["qty"] or 0)
        if x["dest_factory"] == fac and norm_name(x["item_name"]) == nn and str(x["prod_id"] or "") == str(inv["prod_id"] or ""):
            ev.append({"d": dt.date(), "delta": qty, "label": f"Transfer in {qty:g} from {short_fac(x['source_factory'])}"})
        elif x["source_factory"] == fac:
            m = re.search(r"source item:\s*(.+?)\s*\[([^\]]*)\]", x.get("notes") or "")
            if m and norm_name(m.group(1)) == nn and m.group(2).strip() == str(inv["prod_id"] or "").strip():
                ev.append({"d": dt.date(), "delta": -qty, "label": f"Transfer out {qty:g} to {short_fac(x['dest_factory'])}"})
    return ev, flags


def _audit_build(current, events, start, end):
    """Balance on the audit date = current stock minus every movement AFTER the audit date.  Opening = balance before the requisition
    date's movements.  Returns the day-by-day table in between."""
    after = sum(e["delta"] for e in events if e["d"] > end)
    closing = float(current) - after
    inr = sorted((e for e in events if start <= e["d"] <= end), key=lambda e: e["d"])
    opening = closing - sum(e["delta"] for e in inr)
    daily, bal = [], opening
    i = 0
    while i < len(inr):
        d = inr[i]["d"]
        grp = []
        while i < len(inr) and inr[i]["d"] == d:
            grp.append(inr[i])
            i += 1
        rec = sum(e["delta"] for e in grp if e["delta"] > 0)
        iss = sum(-e["delta"] for e in grp if e["delta"] < 0)
        bal += rec - iss
        daily.append({"date": d, "received": rec, "issued": iss, "balance": bal, "details": "; ".join(e["label"] for e in grp)})
    return {"opening": opening, "closing": closing, "received": sum(x["received"] for x in daily),
            "issued": sum(x["issued"] for x in daily), "daily": daily}


def _audit_status(system, counted):
    if counted is None or (isinstance(counted, float) and math.isnan(counted)):
        return "PENDING", None
    diff = float(counted) - float(system)
    return ("VERIFIED" if abs(diff) <= AUDIT_TOL else "MISMATCH"), diff


def _status_label(code, diff):
    if code == "VERIFIED":
        return "✅ Verified — Audit Done"
    if code == "MISMATCH":
        return f"❌ Mismatch ({diff:+g})"
    return "⏳ Pending count"


@tx
def save_req_audit(rows):
    now_s = local_now().strftime("%d-%b-%Y %I:%M %p")
    user = st.session_state.get("user", "")
    for r in rows:
        run("""INSERT INTO req_audit_checks (factory_name, req_no, req_date, audit_date, sl_no, prod_id, item_name, size, unit,
               opening_qty, received_qty, issued_qty, system_balance, counted_qty, diff_qty, status, auditor, recorded_by,
               recorded_at, remarks) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
            (r["fac"], r["req_no"], r["req_date"], r["audit_date"], r["sl_no"], r["prod_id"], r["item"], r["size"], r["unit"],
             r["opening"], r["received"], r["issued"], r["system"], r["counted"], r["diff"], r["status"], r["auditor"], user,
             now_s, r["remarks"]))
    audit("REQ_AUDIT", f"{rows[0]['fac']}: Req {rows[0]['req_no']} audit {rows[0]['audit_date']} - {len(rows)} item(s) recorded")
    return True


def _pdf_txt(s):
    return html_lib.escape(str("" if s is None else s).encode("latin-1", "replace").decode("latin-1"))


def req_audit_pdf(meta, summary, details):
    """Audit-friendly PDF: unit, requisition, dates, month, physical-verification status, item summary, day-by-day movements, signatures."""
    try:
        from reportlab.lib import colors
        from reportlab.lib.pagesizes import A4, landscape
        from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
        from reportlab.platypus import KeepTogether, Paragraph, SimpleDocTemplate, Spacer, Table, TableStyle
    except ImportError:
        return None
    ss = getSampleStyleSheet()
    sm = ParagraphStyle("sm", parent=ss["BodyText"], fontSize=7.2, leading=8.8)
    smb = ParagraphStyle("smb", parent=sm, fontName="Helvetica-Bold")
    h2 = ParagraphStyle("h2", parent=ss["Heading3"], spaceBefore=8, spaceAfter=3)
    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=landscape(A4), leftMargin=24, rightMargin=24, topMargin=24, bottomMargin=28,
                            title="Requisition Audit Verification Report")
    P = lambda t, st_=sm: Paragraph(_pdf_txt(t), st_)
    story = [Paragraph("Requisition Audit Verification Report", ss["Title"])]
    head = [[P("Unit / Factory", smb), P(meta["unit"]), P("Requisition No", smb), P(meta["req_no"])],
            [P("Department", smb), P(meta["dept"]), P("Audit month", smb), P(meta["month"])],
            [P("Requisition date", smb), P(meta["req_date"]), P("Audit date", smb), P(meta["audit_date"])],
            [P("Auditor", smb), P(meta["auditor"] or "-"), P("Prepared by", smb), P(meta["prepared_by"])],
            [P("Physical verification", smb), P(meta["overall"], smb), P("Items verified", smb), P(meta["counts"])]]
    ht = Table(head, colWidths=[110, 270, 110, 270])
    ht.setStyle(TableStyle([("GRID", (0, 0), (-1, -1), 0.4, colors.grey), ("BACKGROUND", (0, 0), (0, -1), colors.HexColor("#FFF4E6")),
                            ("BACKGROUND", (2, 0), (2, -1), colors.HexColor("#FFF4E6")), ("VALIGN", (0, 0), (-1, -1), "MIDDLE")]))
    story += [ht, Spacer(1, 8)]
    cols = ["Item", "ERP Code", "Size", "UOM", "Req Qty", "Opening (req date)", "Received", "Issued", "Balance (audit date)",
            "Physical count", "Difference", "Verification"]
    data = [[P(c, smb) for c in cols]]
    style = [("GRID", (0, 0), (-1, -1), 0.3, colors.grey), ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#E8590C")),
             ("VALIGN", (0, 0), (-1, -1), "MIDDLE")]
    for i, r in enumerate(summary, start=1):
        data.append([P(r[c]) for c in cols])
        bg = {"VERIFIED": "#DCFCE7", "MISMATCH": "#FEE2E2"}.get(r["_code"], "#FEF9C3")
        style.append(("BACKGROUND", (-1, i), (-1, i), colors.HexColor(bg)))
    hdr_white = ParagraphStyle("hw", parent=smb, textColor=colors.white)
    data[0] = [P(c, hdr_white) for c in cols]
    t = Table(data, repeatRows=1, colWidths=[150, 62, 48, 36, 42, 58, 48, 44, 62, 52, 50, 100])
    t.setStyle(TableStyle(style))
    story += [t, Spacer(1, 6),
              P("Balance (audit date) = system stock at the end of the audit date, rebuilt from every Issue / Receipt / transfer / adjustment "
                "since the requisition date. A physical count equal to this balance is marked Verified.")]
    for d in details:
        rows = [[P(c, hdr_white) for c in ("Date", "Received", "Issued", "Balance (end of day)", "Details")]]
        rows.append([P("Opening"), P(""), P(""), P(f"{d['opening']:g}", smb), P(f"Balance before {meta['req_date']}")])
        for x in d["daily"]:
            rows.append([P(x["date"].strftime(DATE_FMT)), P(f"{x['received']:g}" if x["received"] else ""),
                         P(f"{x['issued']:g}" if x["issued"] else ""), P(f"{x['balance']:g}"), P(x["details"])])
        rows.append([P("Audit date", smb), P(f"{d['received']:g}", smb), P(f"{d['issued']:g}", smb), P(f"{d['closing']:g}", smb),
                     P(f"System balance on {meta['audit_date']} | Physical: {d['counted_txt']} | {d['status_txt']}", smb)])
        mt = Table(rows, repeatRows=1, colWidths=[62, 52, 52, 86, 520])
        mt.setStyle(TableStyle([("GRID", (0, 0), (-1, -1), 0.3, colors.grey), ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#334155")),
                                ("BACKGROUND", (0, -1), (-1, -1), colors.HexColor("#FFF4E6")), ("VALIGN", (0, 0), (-1, -1), "MIDDLE")]))
        story.append(KeepTogether([Paragraph(_pdf_txt(f"{d['item']}  [{d['size'] or '-'}]  ·  {d['code'] or '-'}  ·  UOM {d['unit']}"), h2), mt]))
    sig = Table([[P("Prepared by (Store)", smb), P("Auditor", smb), P("Store Manager", smb)], ["", "", ""]],
                colWidths=[250, 250, 250], rowHeights=[14, 34])
    sig.setStyle(TableStyle([("LINEABOVE", (0, 1), (-1, 1), 0.5, colors.black), ("BOX", (0, 0), (-1, -1), 0.4, colors.grey)]))
    story += [Spacer(1, 14), sig, Spacer(1, 4), P(f"Generated {meta['generated']} · KC & Windy Smart Inventory")]

    def _page(canvas, _doc):
        canvas.saveState()
        canvas.setFont("Helvetica", 7)
        canvas.drawRightString(landscape(A4)[0] - 24, 14, f"Page {canvas.getPageNumber()}")
        canvas.restoreState()
    doc.build(story, onFirstPage=_page, onLaterPages=_page)
    return buf.getvalue()


def _rq(x):
    try:
        v = x.get("req_qty")
        return None if v is None else float(v)
    except Exception:
        return None


def _audit_core(fac, req_no, dept, start, items, kid, audit_d, auditor, remarks):
    """Shared by both entry points: items = [(req_row_or_{}, inventory_row)]."""
    sls = [int(i["sl_no"]) for _, i in items]
    txs = q_c("""SELECT id, sl_no, date, trans_type, qty, COALESCE(notes,'') AS notes, COALESCE(officer_name,'') AS officer
                 FROM transactions WHERE factory_name=%s AND sl_no = ANY(%s)""", (fac, sls))
    rets = q_c("SELECT tx_id, sl_no, qty, return_date FROM issue_returns WHERE factory_name=%s AND sl_no = ANY(%s)", (fac, sls))
    ret_by_sl = {}
    for rr in rets:
        ret_by_sl.setdefault(int(rr["sl_no"]), []).append(rr)
    xfs = q_c("""SELECT source_factory, dest_factory, prod_id, item_name, qty, transfer_date, COALESCE(notes,'') AS notes,
                 COALESCE(status,'Completed') AS status FROM inter_factory_transfers
                 WHERE source_factory=%s OR dest_factory=%s""", (fac, fac))
    by_sl = {}
    for t in txs:
        by_sl.setdefault(int(t["sl_no"]), []).append(t)
    built, flags = [], set()
    for x, inv in items:
        ev, fl = _audit_events(fac, inv, by_sl.get(int(inv["sl_no"]), []), xfs, ret_by_sl.get(int(inv["sl_no"]), []))
        flags |= fl
        b = _audit_build(inv["stock"], ev, start, audit_d)
        built.append((x, inv, b))
    for f in sorted(flags):
        st.warning(f)

    base = pd.DataFrame([{"Item": inv["item_name"], "ERP Code": inv["prod_id"], "Size": inv["size"], "UOM": inv["unit"],
                          "Req Qty": _rq(x), "Opening (req date)": round(b["opening"], 4),
                          "Received": round(b["received"], 4), "Issued": round(b["issued"], 4),
                          "System balance (audit date)": round(b["closing"], 4), "Physical count (auditor)": None}
                         for x, inv, b in built])
    base["Physical count (auditor)"] = base["Physical count (auditor)"].astype("float64")
    st.markdown("**✍️ Auditor-এর গোনা সংখ্যা এই কলামে লিখুন**")
    edited = st.data_editor(
        base, hide_index=True, use_container_width=True, key=f"ra_ed_{kid}_{start:%Y%m%d}_{audit_d:%Y%m%d}_" + "-".join(str(i["sl_no"]) for _, i in items),
        disabled=[c for c in base.columns if c != "Physical count (auditor)"],
        column_config={"Physical count (auditor)": st.column_config.NumberColumn("Physical count (auditor) ✍️", min_value=0.0)})

    summary, res_rows = [], []
    for (x, inv, b), cnt in zip(built, edited["Physical count (auditor)"].tolist()):
        code, diff = _audit_status(b["closing"], cnt)
        counted = None if code == "PENDING" else float(cnt)
        summary.append({"Item": inv["item_name"], "ERP Code": inv["prod_id"] or "-", "Size": inv["size"] or "-", "UOM": inv["unit"],
                        "Req Qty": ("-" if _rq(x) is None else f"{_rq(x):g}"), "Opening (req date)": f"{b['opening']:g}", "Received": f"{b['received']:g}",
                        "Issued": f"{b['issued']:g}", "Balance (audit date)": f"{b['closing']:g}",
                        "Physical count": "-" if counted is None else f"{counted:g}",
                        "Difference": "-" if diff is None else f"{diff:+g}",
                        "Verification": {"VERIFIED": "VERIFIED - Audit Done", "MISMATCH": "MISMATCH", "PENDING": "PENDING"}[code],
                        "_code": code})
        res_rows.append({"fac": fac, "req_no": req_no, "req_date": start.strftime(DATE_FMT), "audit_date": audit_d.strftime(DATE_FMT),
                         "sl_no": int(inv["sl_no"]), "prod_id": inv["prod_id"], "item": inv["item_name"], "size": inv["size"],
                         "unit": inv["unit"], "opening": b["opening"], "received": b["received"], "issued": b["issued"],
                         "system": b["closing"], "counted": counted, "diff": diff, "status": code, "auditor": auditor.strip(),
                         "remarks": remarks.strip(), "_label": _status_label(code, diff)})
    n_ok = sum(1 for s in summary if s["_code"] == "VERIFIED")
    n_bad = sum(1 for s in summary if s["_code"] == "MISMATCH")
    n_pend = sum(1 for s in summary if s["_code"] == "PENDING")
    k = st.columns(4)
    k[0].metric("✅ Verified", n_ok)
    k[1].metric("❌ Mismatch", n_bad)
    k[2].metric("⏳ Pending", n_pend)
    overall = ("AUDIT DONE - all items verified" if n_ok == len(summary) else
               "MISMATCH FOUND" if n_bad else "AUDIT IN PROGRESS")
    k[3].metric("Physical verification", "Audit Done ✅" if n_ok == len(summary) else ("Mismatch ❌" if n_bad else "In progress ⏳"))

    show = pd.DataFrame({"Item": [s["Item"] for s in summary], "System balance": [s["Balance (audit date)"] for s in summary],
                         "Physical": [s["Physical count"] for s in summary], "Difference": [s["Difference"] for s in summary],
                         "Verification": [rr["_label"] for rr in res_rows]})
    bgs = ["#DCFCE7" if s["_code"] == "VERIFIED" else "#FEE2E2" if s["_code"] == "MISMATCH" else "#FEF9C3" for s in summary]
    st.dataframe(show.style.apply(lambda col: [f"background-color:{c};font-weight:700" for c in bgs] if col.name == "Verification"
                                  else [""] * len(col), axis=0), hide_index=True, use_container_width=True)

    st.markdown('<div class="section-title">📅 আইটেম বেছে দিনভিত্তিক Issue / Receipt দেখুন</div>', unsafe_allow_html=True)
    names = [f"{inv['item_name']} [{inv['size'] or '-'}] · {inv['prod_id'] or '-'}" for _, inv, _ in built]
    pick = st.selectbox("Item", names, key=f"ra_item_{kid}")
    x, inv, b = built[names.index(pick)]
    m1, m2, m3, m4 = st.columns(4)
    m1.metric("Opening (req date)", f"{b['opening']:g} {inv['unit']}")
    m2.metric("Received", f"{b['received']:g}")
    m3.metric("Issued", f"{b['issued']:g}")
    m4.metric(f"Balance {audit_d:%d-%b}", f"{b['closing']:g} {inv['unit']}")
    if b["daily"]:
        dd = pd.DataFrame([{"Date": e["date"].strftime(DATE_FMT), "Received": e["received"] or None, "Issued": e["issued"] or None,
                            "Balance (end of day)": e["balance"], "Details": e["details"]} for e in b["daily"]])
        st.dataframe(dd, hide_index=True, use_container_width=True, height=min(80 + 35 * len(dd), 380))
    else:
        st.caption("এই সময়ের মধ্যে এই আইটেমে কোনো Issue/Receipt হয়নি।")

    st.markdown('<div class="section-title">💾 Save · 📄 PDF · 📧 Email</div>', unsafe_allow_html=True)
    can_save = n_pend < len(summary) and bool(auditor.strip())
    if st.button("💾 Audit result save করুন", key=f"ra_save_{kid}", type="primary", disabled=not can_save,
                 help="অন্তত একটি আইটেমের গোনা সংখ্যা ও Auditor name লাগবে"):
        if guard(write=False):
            payload = [{k_: v for k_, v in rr.items() if k_ != "_label"} for rr in res_rows if rr["status"] != "PENDING"]
            if save_req_audit(payload):
                done(f"{len(payload)}টি আইটেমের Audit result save হয়েছে।")
    if not can_save:
        st.caption("Save করতে Auditor name ও অন্তত একটি আইটেমের physical count লিখুন।")

    meta = {"unit": fac, "req_no": req_no, "dept": str(dept or "-"), "month": f"{audit_d:%B %Y}",
            "req_date": start.strftime(DATE_FMT), "audit_date": audit_d.strftime(DATE_FMT), "auditor": auditor.strip(),
            "prepared_by": st.session_state.get("user", "") or "-", "overall": overall, "counts": f"{n_ok} / {len(summary)}",
            "generated": local_now().strftime("%d-%b-%Y %I:%M %p")}
    details = []
    for (x_, inv_, b_), s, rr in zip(built, summary, res_rows):
        details.append({**b_, "item": inv_["item_name"], "size": inv_["size"], "code": inv_["prod_id"], "unit": inv_["unit"],
                        "counted_txt": s["Physical count"], "status_txt": s["Verification"]})
    sum_df = pd.DataFrame([{k_: v for k_, v in s.items() if k_ != "_code"} for s in summary])
    mov_df = pd.DataFrame([{"Item": d_["item"], "Date": e["date"].strftime(DATE_FMT), "Received": e["received"], "Issued": e["issued"],
                            "Balance (end of day)": e["balance"], "Details": e["details"]} for d_ in details for e in d_["daily"]])

    def _xlsx():
        buf = io.BytesIO()
        with pd.ExcelWriter(buf) as w:
            pd.DataFrame([[k_, v] for k_, v in meta.items()], columns=["Field", "Value"]).to_excel(w, sheet_name="Header", index=False)
            sum_df.to_excel(w, sheet_name="Summary", index=False)
            mov_df.to_excel(w, sheet_name="Daily movements", index=False)
        return buf.getvalue()

    fname = f"Requisition_Audit_{short_fac(fac)}_{req_no}_{audit_d:%d%b%Y}".replace(" ", "_").replace("/", "-")
    d1, d2, d3 = st.columns(3)
    try:
        import reportlab  # noqa: F401
        if not _lazy_download(d1, "⬇️ PDF Report", lambda: req_audit_pdf(meta, summary, details), f"{fname}.pdf", "application/pdf", f"ra_pdf_{kid}"):
            pdf = req_audit_pdf(meta, summary, details)
            if pdf:
                d1.download_button("⬇️ PDF Report", pdf, f"{fname}.pdf", "application/pdf", key=f"ra_pdf_b_{kid}")
    except ImportError:
        d1.caption("PDF: 'pip install reportlab'")
    xlsx_mime = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    if not _lazy_download(d2, "⬇️ Excel", _xlsx, f"{fname}.xlsx", xlsx_mime, f"ra_xls_{kid}"):
        d2.download_button("⬇️ Excel", _xlsx(), f"{fname}.xlsx", xlsx_mime, key=f"ra_xls_b_{kid}")
    with d3.popover("📧 Auditor-কে Email"):
        to = st.text_input("Auditor email", key=f"ra_to_{kid}")
        from urllib.parse import quote
        subj = f"Requisition Audit - {fac} - Req {req_no} - {audit_d:%d-%b-%Y}"
        body = (f"Unit: {fac}\nRequisition No: {req_no}\nRequisition date: {meta['req_date']}\nAudit date: {meta['audit_date']}\n"
                f"Physical verification: {overall} ({n_ok}/{len(summary)} verified, {n_bad} mismatch, {n_pend} pending)\n\n"
                "Attached: audit report (PDF).\n")
        st.markdown(f"[📧 Email খুলুন](mailto:{quote(to.strip())}?subject={quote(subj)}&body={quote(body)})")
        st.caption("ব্রাউজার নিজে ফাইল attach করতে পারে না — আগে ‘PDF Report’ download করে email-এ attach করুন।")

    try:
        hist = qdf_c("""SELECT audit_date, item_name, size, system_balance, counted_qty, diff_qty, status, auditor, recorded_by, recorded_at
                        FROM req_audit_checks WHERE factory_name=%s AND req_no=%s ORDER BY id DESC""", (fac, req_no))
    except Exception:
        hist = pd.DataFrame()
    if not hist.empty:
        with st.expander(f"🗂 আগের saved audit ({len(hist)})"):
            st.dataframe(hist, hide_index=True, use_container_width=True, height=min(80 + 35 * len(hist), 320))


def req_audit_view(rows, r):
    ensure_req_audit_table()
    fac, req_no = r["factory_name"], str(r["req_no"] or "")
    group = [x for x in rows if x["factory_name"] == fac and str(x["req_no"] or "") == req_no]
    dates = [parse_date(x["req_date"]) for x in group if parse_date(x["req_date"])]
    st.markdown('<div class="section-title">🧾 Audit Reconciliation — Requisition তৈরির দিন থেকে Audit-এর দিন পর্যন্ত</div>',
                unsafe_allow_html=True)
    st.caption("Audit দেরিতে হলে স্টক বদলে যায়। এখানে প্রতিটি আইটেমের Requisition-এর তারিখ থেকে Audit-এর তারিখ পর্যন্ত কোন দিন কত Issue/Receipt হয়েছে, "
               "আর Audit-এর দিনে system balance কত ছিল — সেটা দেখা যাবে। Auditor নিজে গুনে সংখ্যা লিখবেন; মিললে ‘Audit Done’।")
    if not dates:
        st.error("এই Requisition-এর Req Date পাওয়া যায়নি। ‘✏️ Edit’ থেকে Req Date (DD-Mon-YYYY) ঠিক করুন।")
        return
    start = min(dates).date()
    today = local_now().date()
    c1, c2, c3 = st.columns([1, 1.2, 1.4])
    audit_d = c1.date_input("Audit date", value=min(max(today, start), max(today, start)), min_value=start,
                            max_value=max(today, start), key=f"ra_date_{r['id']}")
    auditor = c2.text_input("Auditor name", key=f"ra_aud_{r['id']}")
    remarks = c3.text_input("Remarks (optional)", key=f"ra_rem_{r['id']}")
    if audit_d < today:
        st.info(f"Balance = {audit_d:%d-%b-%Y} দিনের শেষে system-এ যা ছিল (এর পরের Issue/Receipt বাদ দিয়ে হিসাব করা)।")

    inv_all = q_c("""SELECT sl_no, COALESCE(prod_id,'') AS prod_id, item_name, COALESCE(size,'') AS size,
                     COALESCE(current_stock,0) AS stock, COALESCE(NULLIF(unit_name,''),'Pcs') AS unit
                     FROM inventory WHERE factory_name=%s""", (fac,))
    by_code, by_name = {}, {}
    for i in inv_all:
        by_code.setdefault(str(i["prod_id"]).strip(), i)
        by_name.setdefault(str(i["item_name"]).strip().lower(), i)
    items, missing = [], []
    for x in group:
        inv = None
        if not is_blank_code(x["prod_id"]):
            inv = by_code.get(str(x["prod_id"]).strip())
        if inv is None and x["item_name"]:
            inv = by_name.get(str(x["item_name"]).strip().lower())
        if inv is None and x["item_name"]:
            nn_ = norm_name(x["item_name"])
            for a_ in alias_rows(fac):
                if a_["alias_norm"] == nn_:
                    inv = next((i for i in inv_all if int(i["sl_no"]) == int(a_["sl_no"])), None)
                    break
        if inv is None:
            missing.append(str(x["item_name"]))
        else:
            items.append((x, inv))
    if missing:
        st.warning("Inventory-তে পাওয়া যায়নি (হিসাবে নেই): " + ", ".join(missing[:10]))
    if not items:
        return
    _audit_core(fac, req_no, str(r["department"] or "-"), start, items, str(r["id"]), audit_d, auditor, remarks)


def _ram_add():
    res = st.session_state.get("ram_res") or {}
    lst = st.session_state.setdefault("ram_items", [])
    for lb in st.session_state.get("ram_pick") or []:
        if lb in res and res[lb] not in lst:
            lst.append(res[lb])
    st.session_state["ram_pick"] = []


def _ram_remove(sl):
    lst = st.session_state.get("ram_items") or []
    if sl in lst:
        lst.remove(sl)


def audit_manual_view():
    """Audit without an imported requisition: ERP requisition names rarely match this software's names, so the auditor/officer searches the
    item here, enters the requisition date and the audit date, and gets the same day-by-day reconciliation."""
    ensure_req_audit_table()
    st.markdown('<div class="section-title">🧾 Audit Reconciliation — item খুঁজে, তারিখ দিয়ে</div>', unsafe_allow_html=True)
    st.caption("Office ERP-র requisition-এর নাম এই software-এর নামের সাথে না মিললেও সমস্যা নেই: এখানে item খুঁজে নিন, Requisition date ও Audit date দিন — "
               "ওই সময়ের Issue/Receipt ও Audit-এর দিনের balance এই software-এর data থেকে আসবে।")
    if "CONSOLIDATED" in str(FAC):
        fac = st.selectbox("Unit", FACTORIES, key="ram_fac")
    else:
        fac = FAC
    today = local_now().date()
    c1, c2, c3 = st.columns([1.2, 1.2, 1])
    req_no = c1.text_input("Requisition No (ERP থেকে, না লিখলেও চলবে)", key="ram_no").strip()
    dept = c2.selectbox("Department", ["-"] + list(DEPARTMENTS), key="ram_dept")
    start = c3.date_input("Requisition date", value=today, max_value=today, key="ram_start")
    d1, d2, d3 = st.columns([1, 1.2, 1.4])
    audit_d = d1.date_input("Audit date", value=today, min_value=start, max_value=today, key=f"ram_aud_date_{start:%Y%m%d}")
    auditor = d2.text_input("Auditor name", key="ram_auditor")
    remarks = d3.text_input("Remarks (optional)", key="ram_remarks")

    key_items = "ram_items"
    chosen = st.session_state.setdefault(key_items, [])
    if st.session_state.get("ram_items_fac") != fac:      # switching unit clears the list (sl_no is per unit)
        chosen.clear()
        st.session_state["ram_items_fac"] = fac
    term = st.text_input("🔍 Item খুঁজুন (নাম / ERP code / size — একাধিক শব্দ লিখতে পারেন)", key="ram_search")
    toks = [t.lower() for t in term.split() if t.strip()][:6]
    if toks:
        hay = "LOWER(COALESCE(item_name,'') || ' ' || COALESCE(size,'') || ' ' || COALESCE(prod_id,'') || ' ' || COALESCE(serial_no,''))"
        sql = (f"SELECT sl_no, COALESCE(prod_id,'') AS prod_id, item_name, COALESCE(size,'') AS size, COALESCE(current_stock,0) AS stock "
               f"FROM inventory WHERE factory_name=%s AND " + " AND ".join([f"{hay} LIKE %s"] * len(toks)) + " ORDER BY item_name, size LIMIT 100")
        res = q_c(sql, [fac] + [f"%{t}%" for t in toks])
        labels = {f"{r['item_name']} [{r['size'] or '-'}]{_uom_tag(r)} · {r['prod_id'] or '-'} · stock {float(r['stock']):g}": int(r["sl_no"]) for r in res}
        st.session_state["ram_res"] = labels
        if not labels:
            st.warning("এই নামে কোনো item পাওয়া যায়নি। ছোট/অন্য শব্দ দিয়ে খুঁজে দেখুন।")
        else:
            cc1, cc2 = st.columns([4, 1])
            cc1.multiselect("Search result — যেগুলো Audit-এ নেবেন সেগুলো select করুন", list(labels), key="ram_pick")
            cc2.button("➕ যোগ করুন", key="ram_add_btn", on_click=_ram_add, use_container_width=True)
    if not chosen:
        st.info("ওপরে item খুঁজে ‘➕ যোগ করুন’ চাপুন। একাধিক item একসাথে Audit করা যাবে।")
        return
    inv_rows = q_c("""SELECT sl_no, COALESCE(prod_id,'') AS prod_id, item_name, COALESCE(size,'') AS size,
                      COALESCE(current_stock,0) AS stock, COALESCE(NULLIF(unit_name,''),'Pcs') AS unit
                      FROM inventory WHERE factory_name=%s AND sl_no = ANY(%s)""", (fac, list(chosen)))
    by_sl = {int(r["sl_no"]): r for r in inv_rows}
    st.markdown("**Audit-এ থাকা item:**")
    for sl in list(chosen):
        r_ = by_sl.get(sl)
        if not r_:
            continue
        cA, cB = st.columns([6, 1])
        cA.markdown(f"• {r_['item_name']} [{r_['size'] or '-'}]{_uom_tag(r_)} · {r_['prod_id'] or '-'}")
        cB.button("❌", key=f"ram_rm_{sl}", on_click=_ram_remove, args=(sl,))
    items = [({"req_qty": None}, by_sl[sl]) for sl in chosen if sl in by_sl]
    if not items:
        return
    _audit_core(fac, req_no or "NO-REQ-NO", dept, start, items, f"m_{short_fac(fac)}", audit_d, auditor, remarks)


# ------------------------------------------------------------------
#  12. Name alias (ERP name != software name), Return to Store, Morning summary share
#  (tables item_aliases / issue_returns are created once in init_db)
# ------------------------------------------------------------------
def alias_rows(fac):
    try:
        return q_c("SELECT alias_name, alias_norm, sl_no FROM item_aliases WHERE factory_name=%s", (fac,))
    except Exception:
        return []


def _inject_aliases(idx, rows):
    """Every learned ERP name points at the real item's index entry, so all imports / lookups match it with no further change."""
    by_sl = {e["sl"]: e for e in idx["all"]}
    for a in rows:
        e, k = by_sl.get(a["sl_no"]), a["alias_norm"]
        if e and k:
            lst = idx["name"].setdefault(k, [])
            if not any(x is e for x in lst):
                lst.append(e)


def _search_inventory(fac, term, limit=100):
    toks = [t.lower() for t in str(term or "").split() if t.strip()][:6]
    if not toks:
        return []
    hay = "LOWER(COALESCE(item_name,'') || ' ' || COALESCE(size,'') || ' ' || COALESCE(prod_id,'') || ' ' || COALESCE(serial_no,''))"
    sql = ("SELECT sl_no, COALESCE(prod_id,'') AS prod_id, item_name, COALESCE(size,'') AS size, COALESCE(current_stock,0) AS stock, "
           "COALESCE(erp_stock,0) AS erp FROM inventory WHERE factory_name=%s AND " + " AND ".join([f"{hay} LIKE %s"] * len(toks))
           + f" ORDER BY item_name, size LIMIT {int(limit)}")
    return q_c(sql, [fac] + [f"%{t}%" for t in toks])


def _inv_label(r):
    return f"{r['item_name']} [{r['size'] or '-'}]{_uom_tag(r)} · {r['prod_id'] or '-'} · ERP {float(r['erp']):g} · Physical {float(r['stock']):g}"


@tx
def save_alias(fac, alias_name, sl_no):
    run("""INSERT INTO item_aliases (factory_name, alias_name, alias_norm, sl_no, created_by, created_at)
           VALUES (%s,%s,%s,%s,%s,%s) ON CONFLICT (factory_name, alias_norm, sl_no) DO NOTHING""",
        (fac, alias_name.strip(), norm_name(alias_name), int(sl_no), st.session_state.get("user", ""),
         local_now().strftime("%d-%b-%Y %I:%M %p")))
    audit("ALIAS_ADDED", f"{fac}: ERP name '{alias_name.strip()}' -> SL {sl_no}")
    return True


@tx
def delete_alias(aid):
    run("DELETE FROM item_aliases WHERE id=%s", (aid,))
    audit("ALIAS_DELETED", f"alias id {aid}")
    return True


@tx
def link_queue_to_item(qr, sl):
    fac = qr["factory_name"]
    if not q("SELECT 1 AS x FROM inventory WHERE factory_name=%s AND sl_no=%s", (fac, sl)):
        raise ValueError("Master item পাওয়া যায়নি")
    run("UPDATE inventory SET erp_stock=%s WHERE sl_no=%s AND factory_name=%s", (qr["erp_stock"] or 0, sl, fac))
    run("""INSERT INTO item_aliases (factory_name, alias_name, alias_norm, sl_no, created_by, created_at)
           VALUES (%s,%s,%s,%s,%s,%s) ON CONFLICT (factory_name, alias_norm, sl_no) DO NOTHING""",
        (fac, qr["item_name"], norm_name(qr["item_name"]), int(sl), st.session_state.get("user", ""),
         local_now().strftime("%d-%b-%Y %I:%M %p")))
    run("UPDATE import_queue SET status='Linked' WHERE id=%s", (qr["id"],))
    audit("QUEUE_LINKED", f"{fac}: queue '{qr['item_name']}' [{qr['size']}] linked to SL {sl}; ERP stock {qr['erp_stock']} set")
    return True


def queue_link_panel(r):
    """Unmatched ERP row -> link to the real item (same item, different name): sets its ERP balance and remembers the name."""
    k = str(r["id"])
    if not st.toggle("🔗 Master-এ একই আইটেম আছে (শুধু নাম আলাদা)? লিঙ্ক করুন", key=f"ql_on_{k}"):
        return
    fac = r["factory_name"]
    ns = norm_size(r["size"])
    inv = q_c("""SELECT sl_no, COALESCE(prod_id,'') AS prod_id, item_name, COALESCE(size,'') AS size,
                 COALESCE(current_stock,0) AS stock, COALESCE(erp_stock,0) AS erp FROM inventory WHERE factory_name=%s""", (fac,))
    scored = []
    for i in inv:
        if ns and norm_size(i["size"]) != ns:
            continue
        s = _name_match_score(r["item_name"], i["item_name"])
        if s >= 0.55:
            scored.append((s, i))
    scored.sort(key=lambda x: -x[0])
    opts = {f"{int(round(s * 100))}% · {_inv_label(i)}": int(i["sl_no"]) for s, i in scored[:8]}
    term = st.text_input("অথবা নিজে খুঁজুন (নাম / code)", key=f"ql_term_{k}")
    for i in _search_inventory(fac, term, 30):
        opts.setdefault(f"🔎 {_inv_label(i)}", int(i["sl_no"]))
    if not opts:
        st.caption("কাছাকাছি কোনো আইটেম পাওয়া যায়নি। নিজে খুঁজে দেখুন, অথবা নিচে নতুন আইটেম হিসেবে Approve করুন।")
        return
    pick = st.selectbox("কোন আইটেমের সাথে মিল?", list(opts), key=f"ql_pick_{k}")
    st.caption(f"লিঙ্ক করলে: ওই আইটেমের ERP balance = {float(r['erp_stock'] or 0):g} হবে, আর ‘{r['item_name']}’ নামটি alias হিসেবে মনে থাকবে।")
    pw = mgr_check(f"ql_pw_{k}")
    if st.button("🔗 Link করুন", key=f"ql_btn_{k}", type="primary"):
        if not guard():
            return
        if not pw:
            st.error("Manager password দিন।")
        elif link_queue_to_item(r, opts[pick]):
            done("লিঙ্ক হয়েছে — ERP balance বসেছে ও alias সংরক্ষিত।")


def alias_view():
    st.markdown('<div class="section-title">🔗 Name Alias — ERP-র নাম ↔ সফটওয়্যারের নাম</div>', unsafe_allow_html=True)
    st.caption("ERP-তে যে নামে আইটেম আছে আর এখানে যে নামে আছে তা আলাদা হলে একবার জুড়ে দিন। পরে ERP Balance import, Requisition import ও Audit-এ ওই নাম নিজে মিলে যাবে।")
    fac = st.selectbox("Unit", FACTORIES, key="al_fac") if "CONSOLIDATED" in str(FAC) else FAC
    c1, c2 = st.columns(2)
    alias = c1.text_input("ERP-তে আইটেমের নাম (alias)", key="al_name")
    term = c2.text_input("এই সফটওয়্যারের আইটেম খুঁজুন", key="al_term")
    res = _search_inventory(fac, term, 60)
    if term.strip() and not res:
        st.warning("এই নামে আইটেম পাওয়া যায়নি।")
    if res:
        labels = {_inv_label(r): int(r["sl_no"]) for r in res}
        pick = st.selectbox("কোন আইটেম?", list(labels), key="al_pick")
        if st.button("💾 Alias সংরক্ষণ", key="al_save", type="primary"):
            if not guard():
                pass
            elif not norm_name(alias):
                st.error("ERP-র নাম লিখুন।")
            elif save_alias(fac, alias, labels[pick]):
                done("Alias সংরক্ষিত হয়েছে।")
    ad = qdf_c("""SELECT a.id, a.alias_name AS "ERP নাম", i.item_name AS "সফটওয়্যারের নাম", COALESCE(i.size,'') AS "Size",
                  COALESCE(i.prod_id,'') AS "ERP Code", a.created_by AS "কে", a.created_at AS "কখন"
                  FROM item_aliases a LEFT JOIN inventory i ON i.sl_no=a.sl_no AND i.factory_name=a.factory_name
                  WHERE a.factory_name=%s ORDER BY a.id DESC""", (fac,))
    if ad.empty:
        st.caption("এখনো কোনো alias নেই।")
        return
    st.dataframe(ad.drop(columns=["id"]), hide_index=True, use_container_width=True, height=min(80 + 35 * len(ad), 360))
    with st.expander("🗑 Alias মুছুন"):
        lab = {f"{r['ERP নাম']}  →  {r['সফটওয়্যারের নাম']} [{r['Size'] or '-'}]": int(r["id"]) for r in ad.to_dict("records")}
        sel = st.selectbox("কোনটি?", list(lab), key="al_del_sel")
        pw = mgr_check("al_del_pw")
        if st.button("🗑 মুছুন", key="al_del_btn"):
            if not guard():
                pass
            elif not pw:
                st.error("Manager password দিন।")
            elif delete_alias(lab[sel]):
                done("Alias মুছে গেছে।")


# ---------------- Return to Store ----------------
RETURN_REASONS = ["অব্যবহৃত — ফেরত", "ভুল Issue হয়েছিল", "ভুল আইটেম/মাপ", "অন্যান্য"]


@tx
def return_to_store(tid, qty, reason, note):
    rows = q("SELECT * FROM transactions WHERE id=%s FOR UPDATE", (tid,))
    if not rows:
        raise ValueError("Issue রেকর্ড পাওয়া যায়নি")
    t = rows[0]
    if t["trans_type"] != "Issued":
        raise ValueError("শুধু সাধারণ Issue ফেরত নেওয়া যায়")
    cur_q = float(t["qty"] or 0)
    if qty <= 0 or qty > cur_q + 1e-9:
        raise ValueError(f"ফেরতের পরিমাণ ০-র বেশি এবং {cur_q:g}-এর মধ্যে হতে হবে")
    now = local_now()
    d_s = now.strftime(DATE_FMT)
    run("UPDATE transactions SET qty=qty-%s, notes=COALESCE(notes,'') || %s WHERE id=%s",
        (qty, f" [Returned {qty:g} to store on {d_s} by {st.session_state.get('user', '')}: {reason}]", tid))
    run("UPDATE inventory SET current_stock=COALESCE(current_stock,0)+%s WHERE sl_no=%s AND factory_name=%s",
        (qty, t["sl_no"], t["factory_name"]))
    run("""INSERT INTO issue_returns (tx_id, factory_name, sl_no, prod_id, item_name, qty, original_qty, officer_name,
           return_date, return_time, reason, note, returned_by) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
        (tid, t["factory_name"], t["sl_no"], t["prod_id"], t["item_name"], qty, cur_q, t["officer_name"], d_s,
         now.strftime("%I:%M %p"), reason, note, st.session_state.get("user", "")))
    audit("RETURN_TO_STORE", f"{t['factory_name']}: {t['item_name']} - {qty:g} returned (issue #{tid} by {t['officer_name']}, was {cur_q:g})")
    return True


def return_to_store_view():
    st.markdown('<div class="section-title">↩️ Return to Store — Issue হওয়া মাল ফেরত</div>', unsafe_allow_html=True)
    st.caption("Issue-র মাল ফেরত এলে মূল Issue থেকে ওই পরিমাণ কমে যায় আর স্টকে ফিরে আসে — তাই খরচ, Budget ও Issue Ledger নিজে ঠিক থাকে। শুধু সাধারণ Issue ফেরত নেওয়া যায়।")
    c1, c2 = st.columns([2, 1])
    term = c1.text_input("🔍 Item / Officer / Notes খুঁজুন", key="rts_term").strip().lower()
    days = c2.selectbox("কত দিন আগের Issue", [7, 15, 30, 60, 90], index=2, key="rts_days")
    today = local_now().date()
    since = today - timedelta(days=int(days))
    years = sorted({today.year, since.year})
    cond = " OR ".join(["date LIKE %s OR date LIKE %s OR date LIKE %s"] * len(years))
    pats = []
    for y in years:
        pats += [f"%-{y}", f"{y}-%", f"%/{y}"]
    fsql, fp = fw(FAC)
    df = qdf_c(f"""SELECT id, date, time, factory_name, item_name, qty, officer_name, COALESCE(notes,'') AS notes
                   FROM transactions WHERE trans_type='Issued' AND qty>0{fsql} AND ({cond}) ORDER BY id DESC LIMIT 1500""", fp + pats)
    if not df.empty:
        df["d"] = _parse_dates(df["date"])
        df = df[df["d"].notna() & (df["d"] >= pd.Timestamp(since))]
        if term:
            m = df[["item_name", "officer_name", "notes"]].astype(str).apply(
                lambda c: c.str.lower().str.contains(term, regex=False)).any(axis=1)
            df = df[m]
    if df.empty:
        st.info("এই সময়ে কোনো Issue পাওয়া যায়নি।")
    else:
        view = df.head(150)
        st.dataframe(view[["id", "date", "time", "factory_name", "item_name", "qty", "officer_name"]], hide_index=True,
                     use_container_width=True, height=min(80 + 35 * len(view), 330))
        lab = {f"#{r['id']} · {r['date']} · {r['item_name']} · {float(r['qty']):g} · {r['officer_name']}": r for r in view.to_dict("records")}
        r = lab[st.selectbox("কোন Issue থেকে ফেরত?", list(lab), key="rts_sel")]
        k = str(r["id"])
        cur_q = float(r["qty"])
        q1, q2 = st.columns([1, 1.5])
        rq = q1.number_input(f"ফেরতের পরিমাণ (সর্বোচ্চ {cur_q:g})", min_value=0.0, max_value=cur_q, value=min(1.0, cur_q), key=f"rts_q_{k}")
        reason = q2.selectbox("কারণ", RETURN_REASONS, key=f"rts_r_{k}")
        note = st.text_input("মন্তব্য (ঐচ্ছিক)", key=f"rts_n_{k}")
        st.caption("⚠️ ERP-তেও ফেরতের এন্ট্রি দিতে ভুলবেন না, নইলে ERP balance আর Physical মিলবে না।")
        ok = st.checkbox("নিশ্চিত — এই ফেরত স্টকে যোগ হবে", key=f"rts_ok_{k}")
        if st.button("↩️ ফেরত নিন", key=f"rts_btn_{k}", type="primary"):
            if not guard():
                pass
            elif not ok:
                st.error("নিশ্চিত করার টিক দিন।")
            elif rq <= 0:
                st.error("পরিমাণ ০-র বেশি হতে হবে।")
            elif return_to_store(int(r["id"]), float(rq), reason, note.strip()):
                done(f"{rq:g} ফেরত নেওয়া হয়েছে, স্টকে যোগ হয়েছে।")
    with st.expander("🗂 আগের ফেরতের তালিকা"):
        hist = qdf_c(f"""SELECT return_date, return_time, factory_name, item_name, qty, original_qty AS issue_qty_before, officer_name AS issued_to,
                         reason, note, returned_by FROM issue_returns WHERE 1=1{fsql} ORDER BY id DESC LIMIT 300""", fp)
        if hist.empty:
            st.caption("এখনো কোনো ফেরত নেই।")
        else:
            st.dataframe(hist, hide_index=True, use_container_width=True, height=min(80 + 35 * len(hist), 340))
            export_buttons(hist, "issue_returns")


# ---------------- Morning summary (WhatsApp / Email share) ----------------
@tx
def save_summary_number(num):
    run("""INSERT INTO req_settings (setting_key, setting_value) VALUES ('summary_wa_number', %s)
           ON CONFLICT (setting_key) DO UPDATE SET setting_value=EXCLUDED.setting_value""", (num,))
    return True


def _nv(v):
    return "-" if v is None else str(v)


def render_daily_summary_share(stamp=None):
    """Manager only, off by default (no extra work until switched on). One tap opens WhatsApp / the mail app with the text ready."""
    if st.session_state.get("role") != "Store Manager":
        return
    if not st.toggle("📤 সকালের সারাংশ পাঠান (WhatsApp / Email)", key="dash_sum_on"):
        return
    from urllib.parse import quote
    c = dash_work_counts()
    today = local_now().date()
    today_s = today.strftime("%Y-%m-%d")
    flags = compute_issue_anomalies(c["stamp"], today_s)
    brows = compute_budget_runout(c["stamp"], today_s)
    if "CONSOLIDATED" not in str(FAC):
        flags = [f for f in flags if f["factory"] == FAC]
        brows = [r for r in brows if r["factory"] == FAC]
    risky = [r for r in brows if r["status"] in ("over", "runout")]
    L = [f"📊 {FAC} — {today:%d-%b-%Y}", "", "🗂 আজকের কাজ:",
         f"• ERP আপডেট বাকি: {_nv(c['erp_n'])} আইটেম",
         f"• Issue PO Pending: {c['po_issue_n']} (Received PO Pending: {c['po_recv_n']})",
         f"• ফিজিক্যাল যাচাই বাকি: {_nv(c['verif_n'])} আইটেম",
         f"• রিভিউয়ের অপেক্ষায় গণনা: {_nv(c['review_n'])}", "", f"⚠️ অস্বাভাবিক Issue (গত {RECENT_ANOM_DAYS} দিন): {len(flags)}"]
    for f in flags[:3]:
        L.append(f"• {f['item']} [{f['size'] or '-'}] {f['date']:%d-%b} — {f['reasons'][0]}")
    L += ["", f"📅 বাজেট সতর্কতা: {len(risky)}"]
    for r in risky[:5]:
        L.append(f"• {r['category']}: {_runout_text(r)}")
    text = "\n".join(L)
    saved = ""
    try:
        s = q_c("SELECT setting_value FROM req_settings WHERE setting_key='summary_wa_number'")
        saved = s[0]["setting_value"] if s else ""
    except Exception:
        pass
    n1, n2 = st.columns([3, 1])
    num = n1.text_input("WhatsApp নম্বর (দেশ কোডসহ, যেমন 8801XXXXXXXXX; ফাঁকা রাখলে পরে বেছে নেবেন)", value=saved, key="dash_sum_num")
    if n2.button("নম্বর সেভ", key="dash_sum_save") and guard(write=False):
        if save_summary_number(re.sub(r"\D", "", num)):
            done("নম্বর সংরক্ষিত।")
    digits = re.sub(r"\D", "", num)
    st.text_area("সারাংশ (কপি করা যাবে)", text, height=230, key="dash_sum_txt")
    st.markdown(f"[🟢 WhatsApp-এ পাঠান](https://wa.me/{digits}?text={quote(text)})  ·  "
                f"[📧 Email-এ পাঠান](mailto:?subject={quote(f'Daily summary - {FAC} - {today:%d-%b-%Y}')}&body={quote(text)})")
    st.caption("বোতামে চাপলে WhatsApp / Email app নিজে খুলে লেখা বসিয়ে দেবে, আপনাকে শুধু Send চাপতে হবে। নিজে থেকে রোজ সকালে পাঠাতে হলে "
               "আলাদা WhatsApp Business API বা Email (SMTP) সেটআপ লাগবে।")


# ------------------------------------------------------------------
#  13. Budget Issue Check, zero-price warning, set price
# ------------------------------------------------------------------
@tx
def set_item_price(fac, sl, price):
    old = q("SELECT COALESCE(unit_price,0) AS p, item_name FROM inventory WHERE sl_no=%s AND factory_name=%s", (sl, fac))
    if not old:
        raise ValueError("Item পাওয়া যায়নি")
    run("UPDATE inventory SET unit_price=%s WHERE sl_no=%s AND factory_name=%s", (price, sl, fac))
    audit("SET_PRICE", f"{fac}: {old[0]['item_name']} unit price {float(old[0]['p']):g} -> {price:g}")
    return True


@tx
def set_items_budget_category(fac, sl_list, cat):
    """Moves items onto an existing Budget line: only inventory.category changes (the field the Budget joins on)."""
    n = 0
    for sl in sl_list:
        old = q("SELECT item_name, COALESCE(category,'') AS c FROM inventory WHERE sl_no=%s AND factory_name=%s", (int(sl), fac))
        if not old:
            continue
        run("UPDATE inventory SET category=%s WHERE sl_no=%s AND factory_name=%s", (cat, int(sl), fac))
        audit("SET_BUDGET_CAT", f"{fac}: {old[0]['item_name']} category '{old[0]['c']}' -> '{cat}'")
        n += 1
    return n or None


def _price_budget_warning(fac, item):
    """Shown on the Issue form: a zero price (or an unbudgeted category) means the issue will not show up in the budget."""
    if float(item.get("price") or 0) <= 0:
        st.warning("⚠️ এই আইটেমের দাম 0, তাই বাজেটে ধরা পড়বে না। Manager দিয়ে Inventory → Edit থেকে Unit Price বসান, "
                   "অথবা Supplier Receipt-এ Purchase Rate দিন।")
    try:
        lines = {str(r["category_name"]).strip() for r in
                 q_c("SELECT category_name FROM category_budgets WHERE factory_name=%s", (fac,))}
        if lines:
            r = q_c("SELECT COALESCE(category,'') AS category FROM inventory WHERE sl_no=%s AND factory_name=%s", (item["sl_no"], fac))
            cat = str(r[0]["category"]).strip() if r else ""
            if cat not in lines:
                st.info(f"ℹ️ আইটেমের Category ‘{cat or 'ফাঁকা'}’-এর কোনো Budget লাইন নেই — টাকা শুধু মোট বাজেটে ধরা পড়বে, কোনো Category কার্ডে নয়।")
    except Exception:
        pass


def _issue_budget_rows(period):
    fsql, fp = fw(FAC, "t.")
    today = local_now().date()
    base = f"""SELECT t.id, t.factory_name, t.sl_no, t.date, t.time, t.item_name, COALESCE(i.size,'') AS size, t.qty,
               COALESCE(i.unit_price,0) AS price, COALESCE(i.category,'') AS category
               FROM transactions t LEFT JOIN inventory i ON i.sl_no=t.sl_no AND i.factory_name=t.factory_name
               WHERE t.trans_type IN ('Issued','Internal Issue') AND t.qty>0{fsql}"""
    if period == "আজ":
        return qdf_c(base + " AND t.date=%s ORDER BY t.id DESC", fp + [today.strftime(DATE_FMT)])
    since = today - timedelta(days=6) if period == "গত ৭ দিন" else today.replace(day=1)
    years = sorted({today.year, since.year})
    cond = " OR ".join(["t.date LIKE %s OR t.date LIKE %s OR t.date LIKE %s"] * len(years))
    pats = []
    for y in years:
        pats += [f"%-{y}", f"{y}-%", f"%/{y}"]
    df = qdf_c(base + f" AND ({cond}) ORDER BY t.id DESC LIMIT 3000", fp + pats)
    if not df.empty:
        d = _parse_dates(df["date"])
        df = df[d.notna() & (d >= pd.Timestamp(since))]
    return df


def render_budget_issue_check():
    """Budget page: every Issue of the chosen period with price, category and whether the money reached a budget line."""
    st.markdown('<div class="section-title">🔎 Budget Issue Check — Issue বাজেটে ধরা পড়ছে কি?</div>', unsafe_allow_html=True)
    period = st.radio("সময়", ["আজ", "গত ৭ দিন", "এই মাস"], horizontal=True, key="bic_period", label_visibility="collapsed")
    df = _issue_budget_rows(period)
    if df is None or df.empty:
        st.info(f"{period}-এর মধ্যে কোনো Issue পাওয়া যায়নি।")
        return
    fsql, fp = fw(FAC)
    bud = q_c(f"SELECT factory_name, category_name FROM category_budgets WHERE 1=1{fsql}", fp)
    exact = {(r["factory_name"], str(r["category_name"]).strip()) for r in bud}
    loose = {(r["factory_name"], str(r["category_name"]).strip().lower()) for r in bud}
    df = df.copy()
    df["qty"] = pd.to_numeric(df["qty"], errors="coerce").fillna(0.0)
    df["price"] = pd.to_numeric(df["price"], errors="coerce").fillna(0.0)
    df["amount"] = df["qty"] * df["price"]

    def _status(r):
        cat = str(r["category"] or "").strip()
        if r["price"] <= 0:
            return "❌ দাম 0 — টাকা 0, বাজেটে ধরা পড়েনি"
        if (r["factory_name"], cat) in exact:
            return f"✅ বাজেটে ধরা পড়েছে ({cat})"
        if (r["factory_name"], cat.lower()) in loose:
            return "⚠️ Category নামে বানান/বড়-ছোট হাতের পার্থক্য — কার্ডে ধরা পড়েনি"
        return f"⚠️ ‘{cat or 'ফাঁকা'}’-এর Budget লাইন নেই — শুধু মোট বাজেটে"
    df["status"] = df.apply(_status, axis=1)
    n0 = int((df["price"] <= 0).sum())
    nm = int((~df["status"].str.startswith("✅") & (df["price"] > 0)).sum())
    k = st.columns(4)
    k[0].metric("Issue এন্ট্রি", len(df))
    k[1].metric("মোট মূল্য", f"৳{df['amount'].sum():,.0f}")
    k[2].metric("❌ দাম 0", n0)
    k[3].metric("⚠️ Category মেলেনি", nm)
    show = pd.DataFrame({"Date": df["date"], "Time": df["time"], "Factory": df["factory_name"].map(short_fac), "Item": df["item_name"],
                         "Size": df["size"], "Qty": df["qty"], "Unit price (৳)": df["price"], "Amount (৳)": df["amount"].round(2),
                         "Category": df["category"], "বাজেটে ধরা পড়েছে?": df["status"]})
    st.dataframe(show, hide_index=True, use_container_width=True, height=min(80 + 35 * len(show), 380),
                 column_config={"Unit price (৳)": st.column_config.NumberColumn(format="%.2f"),
                                "Amount (৳)": st.column_config.NumberColumn(format="%.0f")})
    export_buttons(show, "budget_issue_check")
    zero = df[df["price"] <= 0].drop_duplicates(["factory_name", "sl_no"])
    if not zero.empty:
        with st.expander(f"💲 দাম 0 আইটেমে দাম বসান ({len(zero)}টি) — Manager"):
            lab = {f"{r['item_name']} [{r['size'] or '-'}]{_uom_tag(r)} · {short_fac(r['factory_name'])}": r for r in zero.to_dict("records")}
            pick = lab[st.selectbox("আইটেম", list(lab), key="bic_pick")]
            newp = st.number_input("Unit Price (৳ প্রতি একক)", min_value=0.0, step=1.0, key=f"bic_price_{pick['factory_name']}_{pick['sl_no']}")
            pw = mgr_check("bic_pw")
            if st.button("💾 দাম সংরক্ষণ", key="bic_save", type="primary"):
                if not guard(write=False):
                    pass
                elif not pw:
                    st.error("Manager password দিন।")
                elif newp <= 0:
                    st.error("দাম 0-র বেশি হতে হবে।")
                elif set_item_price(pick["factory_name"], int(pick["sl_no"]), float(newp)):
                    done("দাম সংরক্ষিত — বাজেটে এখন থেকে এই আইটেমের Issue ধরা পড়বে।")
            st.caption("দাম বদলালে ওই আইটেমের আগের Issue-র টাকাও নতুন দামে হিসাব হবে (বাজেট হিসাব বর্তমান দামের ওপর দাঁড়িয়ে)।")
    unm = df[(df["price"] > 0) & (~df["status"].str.startswith("✅"))].drop_duplicates(["factory_name", "sl_no"])
    if not unm.empty:
        with st.expander(f"🧩 Budget লাইন বেছে দিন — Category মেলেনি ({len(unm)}টি আইটেম) — Manager"):
            facs = sorted(unm["factory_name"].unique())
            fsel = facs[0] if len(facs) == 1 else st.selectbox("Factory", facs, key="bic_cat_fac")
            sub = unm[unm["factory_name"] == fsel]
            lines = q_c("""SELECT department_name, category_name, COALESCE(allocated_budget,0) AS b FROM category_budgets
                           WHERE factory_name=%s ORDER BY department_name, category_name""", [fsel])
            if not lines:
                st.info("এই Factory-র কোনো Budget লাইন নেই। আগে Budget যোগ করুন।")
            else:
                ilab = {f"{r['item_name']} [{r['size'] or '-'}]{_uom_tag(r)} · এখনকার Category: {r['category'] or 'ফাঁকা'}": int(r["sl_no"])
                        for r in sub.to_dict("records")}
                picks = st.multiselect("কোন আইটেমগুলো", list(ilab), default=list(ilab), key=f"bic_cat_items_{fsel}")
                llab = {f"{r['category_name']}  ·  {r['department_name']}  ·  বাজেট ৳{float(r['b']):,.0f}": r["category_name"] for r in lines}
                target = llab[st.selectbox("কোন Budget লাইনে ধরবেন", list(llab), key=f"bic_cat_line_{fsel}")]
                pw2 = mgr_check("bic_cat_pw")
                if st.button("💾 Budget লাইনে সংরক্ষণ", key="bic_cat_save", type="primary"):
                    if not guard(write=False):
                        pass
                    elif not pw2:
                        st.error("Manager password দিন।")
                    elif not picks:
                        st.error("অন্তত একটি আইটেম বাছুন।")
                    elif set_items_budget_category(fsel, [ilab[x] for x in picks], target):
                        done(f"{len(picks)}টি আইটেম এখন ‘{target}’ Budget লাইনে ধরা পড়বে।")
                st.caption("শুধু আইটেমের Budget Category বদলায় (স্টক, দাম বা Department নয়)। আগের Issue-গুলোও নতুন Category-তে হিসাব হবে।")


# ------------------------------------------------------------------
#  7. Short / Excess resolution plan (ERP Audit)
# ------------------------------------------------------------------
PLAN_PHASES = {1: "Phase 1 · Quick fix (ERP update / PO-GRN entry)", 2: "Phase 2 · High-value Short/Excess (recount + documents)",
               3: "Phase 3 · Remaining Short/Excess"}


def _workdays(start, count, skip_friday=True):
    """First `count` working dates from `start` (Friday off by default)."""
    out, d = [], start
    while len(out) < count:
        if not (skip_friday and d.weekday() == 4):
            out.append(d)
        d += timedelta(days=1)
    return out


def active_store_officers():
    """Registered, approved accounts that can be given Short/Excess work (Store Officers first, then the Store Manager)."""
    try:
        return q_c("""SELECT username, COALESCE(NULLIF(TRIM(full_name),''), username) AS full_name, role FROM users
                      WHERE LOWER(COALESCE(status,'Active')) IN ('active','approved') AND role IN ('Store Officer','Store Manager')
                      ORDER BY CASE WHEN role='Store Officer' THEN 0 ELSE 1 END, full_name""")
    except Exception:
        return []


def build_short_excess_plan(base, officers, per_officer, start, skip_friday=True):
    """base: one row per mismatched item with phase / weight already set. Returns (plan df, phase summary df, work days).
    Every working day holds at most len(officers) x per_officer units of work, shared round-robin between the officers of that day."""
    if base.empty:
        return base, pd.DataFrame(), 0
    cap = max(len(officers) * float(per_officer), 0.5)
    base = base.sort_values(["phase", "abs_value"], ascending=[True, False]).reset_index(drop=True)
    day, used, day_idx = 0, 0.0, []
    for w in base["weight"]:
        if used > 0 and used + w > cap + 1e-9:
            day += 1
            used = 0.0
        used += w
        day_idx.append(day)
    base["day_no"] = [i + 1 for i in day_idx]
    n_days = max(day_idx) + 1
    dates = _workdays(start, n_days + 1, skip_friday)   # +1 working day: manager verification & closing buffer
    base["target"] = [dates[i] for i in day_idx]
    base["officer"] = officers[0]
    for _d, ix in base.groupby("day_no").groups.items():
        for j, i in enumerate(ix):
            base.at[i, "officer"] = officers[j % len(officers)]
    summ = []
    for ph, g in base.groupby("phase"):
        summ.append({"Phase": PLAN_PHASES[ph], "Items": str(len(g)), "Short": str(int((g["variance"] < 0).sum())),
                     "Excess": str(int((g["variance"] > 0).sum())), "Value (৳)": f"{float(g['abs_value'].sum()):,.0f}",
                     "Work days": f"Day {int(g['day_no'].min())}–{int(g['day_no'].max())}",
                     "Deadline": g["target"].max().strftime(DATE_FMT)})
    summ.append({"Phase": "✅ Manager verification & close", "Items": str(len(base)), "Short": "", "Excess": "", "Value (৳)": "",
                 "Work days": f"Day {n_days + 1}", "Deadline": dates[n_days].strftime(DATE_FMT)})
    return base, pd.DataFrame(summ), n_days + 1


@tx
def save_plan_tasks(rows):
    n = 0
    today_s = local_now().strftime(DATE_FMT)
    for r in rows:
        run("""INSERT INTO audit_correction_tasks (factory_name, prod_id, item_name, variance_type, variance_qty, variance_value,
               root_cause, corrective_action, assigned_officer, task_date, target_date, status, manager_remarks, priority,
               verification_status) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,'Open',%s,%s,'Pending')""",
            (r["factory_name"], r["prod_id"], r["item_name"], r["type"], r["variance"], r["value"], r["cause"], r["action"],
             r["officer"], today_s, r["target"], f"Short/Excess Plan - {PLAN_PHASES[r['phase']].split(' · ')[0]}", r["priority"]))
        n += 1
    audit("PLAN_TASKS", f"{n} Short/Excess plan task(s) created")
    return n


def _pdf_clean(s):
    """reportlab's built-in fonts cannot draw Bangla / emoji: keep Latin text only so nothing prints as black boxes."""
    t = str("" if s is None else s)
    for a_, b_ in (("\u2013", "-"), ("\u2014", "-"), ("\u2019", "'"), ("\u2018", "'"), ("\u201c", '"'), ("\u201d", '"')):
        t = t.replace(a_, b_)
    return html_lib.escape(t.encode("latin-1", "ignore").decode("latin-1").strip())


def short_excess_plan_pdf(meta, plan, summ, off_df):
    """Professional landscape PDF of the Short/Excess Correction Plan: items with UOM, quantities and values, assigned officer,
    working days allowed and target date for every item, officer-wise task lists and signature boxes."""
    try:
        from reportlab.lib import colors
        from reportlab.lib.pagesizes import A4, landscape
        from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
        from reportlab.platypus import PageBreak, Paragraph, SimpleDocTemplate, Spacer, Table, TableStyle
    except ImportError:
        return None
    ss = getSampleStyleSheet()
    sm = ParagraphStyle("sm", parent=ss["BodyText"], fontSize=7, leading=8.6)
    smb = ParagraphStyle("smb", parent=sm, fontName="Helvetica-Bold")
    hw = ParagraphStyle("hw", parent=smb, textColor=colors.white)
    h2 = ParagraphStyle("h2", parent=ss["Heading3"], spaceBefore=10, spaceAfter=4, textColor=colors.HexColor("#0F172A"))
    P = lambda t, st_=sm: Paragraph(_pdf_clean(t), st_)
    # a name written only in Bangla cannot be drawn by the built-in PDF fonts -> use the login username instead of leaving it blank
    fix = {n_: (n_ if _pdf_clean(n_) else u_) for n_, u_ in zip(plan["officer_name"], plan["officer"])}
    plan = plan.copy()
    plan["officer_name"] = plan["officer_name"].map(fix)
    off_df = off_df.copy()
    off_df["Officer"] = off_df["Officer"].map(lambda n_: fix.get(n_, n_))
    ORG, DARK = colors.HexColor("#E8590C"), colors.HexColor("#334155")
    W = landscape(A4)[0] - 36
    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=landscape(A4), leftMargin=18, rightMargin=18, topMargin=22, bottomMargin=26,
                            title="Short / Excess Correction Plan")

    def grid(data, widths, head_bg=ORG, extra=None):
        t = Table(data, colWidths=widths, repeatRows=1)
        style = [("GRID", (0, 0), (-1, -1), 0.3, colors.HexColor("#94A3B8")), ("BACKGROUND", (0, 0), (-1, 0), head_bg),
                 ("VALIGN", (0, 0), (-1, -1), "MIDDLE"), ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#F8FAFC")])]
        t.setStyle(TableStyle(style + (extra or [])))
        return t

    story = [Paragraph("Short / Excess Correction Plan", ss["Title"]),
             P(f"Audit Department report - generated {meta['generated']} by {meta['prepared_by']}")]
    head = [[P("Unit / Factory", smb), P(meta["unit"]), P("Plan start date", smb), P(meta["start"]), P("Final target date", smb), P(meta["finish"])],
            [P("Short items", smb), P(f"{meta['n_short']}  (BDT {meta['v_short']:,.0f})"), P("Excess items", smb),
             P(f"{meta['n_exc']}  (BDT {meta['v_exc']:,.0f})"), P("Total working days", smb), P(f"{meta['n_days']}  (Friday off: {meta['fri']})")],
            [P("Assigned officers", smb), P(meta["officers"]), P("Capacity", smb), P(f"{meta['per_off']:g} item(s) per officer per day"),
             P("Items in plan", smb), P(str(meta["n_items"]))]]
    ht = Table(head, colWidths=[78, 190, 78, 190, 90, W - 626])
    ht.setStyle(TableStyle([("GRID", (0, 0), (-1, -1), 0.4, colors.grey), ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
                            ("BACKGROUND", (0, 0), (0, -1), colors.HexColor("#FFF4E6")), ("BACKGROUND", (2, 0), (2, -1), colors.HexColor("#FFF4E6")),
                            ("BACKGROUND", (4, 0), (4, -1), colors.HexColor("#FFF4E6"))]))
    story += [Spacer(1, 6), ht, Spacer(1, 6),
              P("How to read the deadlines: every item shows the number of working days within which it must be resolved, counted from the plan start date "
                "(Friday is a weekend day when 'Friday off' is Yes), and the target date is the last day for that item. The last working day is reserved for "
                "Manager verification and closing.", sm)]

    story.append(Paragraph("1. Phase-wise plan", h2))
    sh = ["Phase", "Items", "Short", "Excess", "Value (BDT)", "Work days", "Deadline"]
    rows = [[P(c, hw) for c in sh]]
    for r in summ.to_dict("records"):
        rows.append([P(r["Phase"]), P(r["Items"]), P(r["Short"]), P(r["Excess"]), P(r["Value (৳)"]), P(r["Work days"]), P(r["Deadline"], smb)])
    story.append(grid(rows, [300, 50, 50, 55, 85, 90, W - 630]))

    story.append(Paragraph("2. Officer-wise workload", h2))
    oc = ["Officer", "Items", "Short", "Excess", "Value (BDT)", "First target", "Last target"]
    rows = [[P(c, hw) for c in oc]]
    for r in off_df.to_dict("records"):
        rows.append([P(r["Officer"], smb), P(str(r["Items"])), P(str(r["Short"])), P(str(r["Excess"])), P(f"{r['Value']:,.0f}"),
                     P(r["First"]), P(r["Last"])])
    story.append(grid(rows, [250, 50, 50, 55, 90, 100, W - 595]))

    story.append(Paragraph("3. Item-wise plan with deadlines", h2))
    ic = ["#", "Day", "Item", "Size", "UOM", "Type", "Short/Excess Qty", "Value (BDT)", "Priority", "Assigned officer", "Deadline", "Action"]
    wid = [20, 26, 128, 46, 30, 38, 52, 50, 40, 82, 150, 0]
    wid[-1] = W - sum(wid)
    rows, extra = [[P(c, hw) for c in ic]], []
    for n, r in enumerate(plan.to_dict("records"), start=1):
        dl = f"Resolve within {r['day_no']} working day{'s' if r['day_no'] != 1 else ''} - target date: {r['target'].strftime(DATE_FMT)}"
        rows.append([P(str(n)), P(str(r["day_no"])), P(r["item_name"], smb), P(r["size"] or "-"), P(r["unit"]), P("Short" if r["type"] == "Shortage" else "Excess"),
                     P(f"{r['variance']:+g}"), P(f"{r['abs_value']:,.0f}"), P(r["priority"]), P(r["officer_name"]), P(dl), P(r["action_en"])])
        extra.append(("BACKGROUND", (5, n), (5, n), colors.HexColor("#FEE2E2" if r["variance"] < 0 else "#FEF3C7")))
    story.append(grid(rows, wid, DARK, extra))

    story.append(PageBreak())
    story.append(Paragraph("4. Officer-wise task lists", h2))
    for off, g in plan.groupby("officer_name", sort=False):
        story.append(P(f"{off} - {len(g)} item(s), final target {g['target'].max().strftime(DATE_FMT)}", smb))
        rows = [[P(c, hw) for c in ("Item", "Size", "UOM", "Type", "Qty", "Value (BDT)", "Target date", "Deadline instruction")]]
        for r in g.sort_values(["day_no", "abs_value"], ascending=[True, False]).to_dict("records"):
            rows.append([P(r["item_name"]), P(r["size"] or "-"), P(r["unit"]), P("Short" if r["type"] == "Shortage" else "Excess"), P(f"{r['variance']:+g}"),
                         P(f"{r['abs_value']:,.0f}"), P(r["target"].strftime(DATE_FMT), smb),
                         P(f"This item must be resolved within {r['day_no']} working day{'s' if r['day_no'] != 1 else ''}, target date: "
                           f"{r['target'].strftime(DATE_FMT)}")])
        story += [grid(rows, [190, 55, 32, 45, 48, 62, 70, W - 502], DARK), Spacer(1, 8)]

    sig = Table([[P("Prepared by (Store)", smb), P("Store Manager", smb), P("Audit Department", smb)], ["", "", ""]],
                colWidths=[W / 3] * 3, rowHeights=[14, 36])
    sig.setStyle(TableStyle([("BOX", (0, 0), (-1, -1), 0.4, colors.grey), ("LINEABOVE", (0, 1), (-1, 1), 0.5, colors.black)]))
    story += [Spacer(1, 12), sig]

    def _page(canvas, _doc):
        canvas.saveState()
        canvas.setFont("Helvetica", 7)
        canvas.drawString(18, 12, "KC & Windy Smart Inventory - Short / Excess Correction Plan")
        canvas.drawRightString(landscape(A4)[0] - 18, 12, f"Page {canvas.getPageNumber()}")
        canvas.restoreState()
    doc.build(story, onFirstPage=_page, onLaterPages=_page)
    return buf.getvalue()


def short_excess_plan_view(aud, tasks):
    st.markdown('<div class="section-title">🗓 Short / Excess সমাধান পরিকল্পনা (Audit Department-এর জন্য)</div>', unsafe_allow_html=True)
    if aud is None or aud.empty or not (aud["variance"] != 0).any():
        st.success("সব আইটেম ERP-র সাথে মিলেছে — কোনো Short/Excess নেই।")
        return
    mm = aud[aud["variance"] != 0].copy()
    mm["abs_value"] = (mm["variance"] * mm["unit_price"]).abs()
    erp_set, po_set = set(), set()
    try:
        ensure_erp_track_columns()
        fsql_i, fp_i = fw(FAC, "i.")
        for r in q(f"""SELECT i.factory_name, i.sl_no FROM inventory i WHERE EXISTS (SELECT 1 FROM transactions t
                       WHERE t.factory_name=i.factory_name AND t.sl_no=i.sl_no AND t.trans_type IN ('Issued','Internal Issue')
                       AND t.id > COALESCE(i.erp_upto_tx,0)){fsql_i}""", fp_i):
            erp_set.add((r["factory_name"], r["sl_no"]))
    except Exception:
        pass
    try:
        fsql_t, fp_t = fw(FAC, "t.")
        for r in q(f"SELECT DISTINCT t.factory_name, t.sl_no {PO_FROM} WHERE {PO_WHERE}{fsql_t}", fp_t):
            po_set.add((r["factory_name"], r["sl_no"]))
    except Exception:
        pass
    units = {}
    try:
        for r in q_c(f"SELECT factory_name, sl_no, COALESCE(NULLIF(unit_name,''),'Pcs') AS unit FROM inventory WHERE 1=1{FSQL}", FP):
            units[(r["factory_name"], r["sl_no"])] = r["unit"]
    except Exception:
        pass
    ranks = mm["abs_value"].rank(ascending=False, method="first") / max(len(mm), 1)
    rows = []
    for (idx, r), rk in zip(mm.iterrows(), ranks):
        key = (r["factory_name"], r["sl_no"])
        short = r["variance"] < 0
        tier = "Critical" if rk <= 0.10 else ("High" if rk <= 0.30 else ("Medium" if rk <= 0.60 else "Low"))
        if key in erp_set:
            cause, action, phase, weight = ("Issue-এর পর ERP balance আপডেট হয়নি",
                                            "Issue Ledger → ERP Balance Update-এ ERP balance বসান", 1, 0.5)
            action_en = "Update the ERP balance after issue (Issue Ledger > ERP Balance Update)"
        elif key in po_set:
            cause, action, phase, weight = ("ERP PO/GRN এন্ট্রি বাকি", "ERP-তে PO/GRN এন্ট্রি সম্পূর্ণ করুন", 1, 0.5)
            action_en = "Complete the pending ERP PO / GRN entry"
        else:
            cause = ("অজানা — Physical গণনা ও ডকুমেন্ট যাচাই দরকার" if short
                     else "Receipt/GRN বাদ পড়া বা ভুল Issue entry হতে পারে")
            action = "Recount → Issue/Receipt ledger মেলান → ERP/Physical adjust (Manager)"
            action_en = "Recount, reconcile Issue/Receipt ledger, then adjust ERP/Physical (Manager)"
            phase, weight = (2 if tier in ("Critical", "High") else 3), 1.0
        rows.append({"factory_name": r["factory_name"], "sl_no": r["sl_no"], "prod_id": r["prod_id"], "item_name": r["item_name"],
                     "size": r["size"], "unit": units.get(key, "Pcs"), "type": "Shortage" if short else "Excess",
                     "variance": float(r["variance"]), "abs_value": float(r["abs_value"]), "priority": tier, "cause": cause,
                     "action": action, "action_en": action_en, "phase": phase, "weight": weight})
    _short_excess_plan_panel(pd.DataFrame(rows), tasks)


@_fragment
def _short_excess_plan_panel(base, tasks):
    n_short, n_exc = int((base["variance"] < 0).sum()), int((base["variance"] > 0).sum())
    v_short = float(base.loc[base["variance"] < 0, "abs_value"].sum())
    v_exc = float(base.loc[base["variance"] > 0, "abs_value"].sum())
    quick = int((base["phase"] == 1).sum())
    k = st.columns(4)
    k[0].metric("Short items", n_short, f"৳{v_short:,.0f}")
    k[1].metric("Excess items", n_exc, f"৳{v_exc:,.0f}")
    k[2].metric("Quick fix (ERP entry)", quick)
    k[3].metric("Recount দরকার", len(base) - quick)

    # ---- Step 1: who works, how fast, from when --------------------------------------------------
    pool = active_store_officers()
    by_user = {r["username"]: r for r in pool}
    with st.container(border=True):
        st.markdown("**① পরিকল্পনা সাজান** — সংখ্যা বদলালে তারিখ নিজে থেকে বদলাবে।")
        if not pool:
            st.warning("Users টেবিলে কোনো Active অফিসার পাওয়া যায়নি। Manager অ্যাকাউন্ট approve করার পর আবার দেখুন।")
        default = [r["username"] for r in pool if r["role"] == "Store Officer"][:6] or [r["username"] for r in pool][:1]
        officers = st.multiselect("কারা কাজ করবেন (নিবন্ধিত Active অফিসার)", [r["username"] for r in pool], default=default,
                                  format_func=lambda u: f"{by_user[u]['full_name']} ({u}) · {by_user[u]['role']}",
                                  key="sep_officers_v2", help="Users টেবিল থেকে নিজে আসে — নতুন অফিসার approve হলেই এখানে দেখা যাবে।")
        p2, p3, p4 = st.columns(3)
        per_off = p2.number_input("প্রতিদিন প্রতি জন (আইটেম)", min_value=1.0, max_value=60.0, value=8.0, step=1.0, key="sep_per")
        start = p3.date_input("শুরুর তারিখ", value=local_now().date(), key="sep_start")
        skip_fri = p4.checkbox("শুক্রবার ছুটি", value=True, key="sep_fri")
    if not officers:
        st.warning("অন্তত একজন অফিসার select করুন।")
        return
    plan, summ, n_days = build_short_excess_plan(base, officers, per_off, start, skip_fri)
    plan["officer_name"] = plan["officer"].map(lambda u: by_user[u]["full_name"] if u in by_user else u)
    final = plan["target"].max()                              # date of the last item
    finish = _workdays(start, n_days, skip_fri)[-1]           # + 1 working day for Manager verification / closing
    daily_units = len(officers) * per_off
    total_units = float(plan["weight"].sum())

    # ---- Step 2: result --------------------------------------------------------------------------
    r1, r2, r3 = st.columns(3)
    r1.metric("মোট কার্যদিবস", n_days)
    r2.metric("শেষ তারিখ", finish.strftime(DATE_FMT))
    r3.metric("দৈনিক ক্ষমতা", f"{daily_units:g} আইটেম")
    st.success(f"✅ এই ক্ষমতায় সব Short/Excess সমাধানে লাগবে **{n_days} কার্যদিবস** — সর্বশেষ আইটেম {final.strftime(DATE_FMT)}, "
               f"তারপর ১ দিন Manager verification, অর্থাৎ **{finish.strftime(DATE_FMT)}**-এর মধ্যে সব শেষ।")
    want = st.number_input("নির্দিষ্ট দিনের মধ্যে শেষ করতে চান? (কার্যদিবস, ঐচ্ছিক — 0 = না)", min_value=0, max_value=120, value=0, step=1, key="sep_target")
    if want and want > 1:
        need_cap = total_units / (want - 1)
        need_off = math.ceil(need_cap / per_off)
        if daily_units + 1e-9 >= need_cap:
            st.info(f"{want} কার্যদিবসে শেষ করা সম্ভব — বর্তমান ক্ষমতাই যথেষ্ট।")
        else:
            st.warning(f"{want} কার্যদিবসে শেষ করতে দৈনিক প্রায় {need_cap:.0f} একক কাজ লাগবে → প্রতিজন {per_off:g} আইটেম হলে "
                       f"**{need_off} জন অফিসার** লাগবে (এখন {len(officers)} জন)।")

    st.markdown("**ধাপ অনুযায়ী পরিকল্পনা**")
    st.dataframe(summ, hide_index=True, use_container_width=True)

    og = plan.groupby("officer_name", sort=False)
    off_df = pd.DataFrame([{"Officer": n, "Items": len(g), "Short": int((g["variance"] < 0).sum()), "Excess": int((g["variance"] > 0).sum()),
                            "Value": float(g["abs_value"].sum()), "First": g["target"].min().strftime(DATE_FMT),
                            "Last": g["target"].max().strftime(DATE_FMT)} for n, g in og])
    st.markdown("**অফিসার অনুযায়ী কাজ**")
    st.dataframe(off_df.rename(columns={"Value": "Value (৳)", "First": "প্রথম target", "Last": "শেষ target"}), hide_index=True,
                 use_container_width=True, column_config={"Value (৳)": st.column_config.NumberColumn(format="%.0f")})

    # ---- Step 3: PDF / Excel / tasks -------------------------------------------------------------
    st.markdown("**② রিপোর্ট ডাউনলোড ও সংরক্ষণ**")
    meta = {"unit": str(FAC), "start": start.strftime(DATE_FMT), "finish": finish.strftime(DATE_FMT), "n_days": n_days,
            "fri": "Yes" if skip_fri else "No", "n_short": n_short, "v_short": v_short, "n_exc": n_exc, "v_exc": v_exc,
            "officers": ", ".join((by_user[u]["full_name"] if (u in by_user and _pdf_clean(by_user[u]["full_name"])) else u) for u in officers),
            "per_off": float(per_off),
            "n_items": len(plan), "prepared_by": st.session_state.get("user") or "-", "generated": local_now().strftime("%d-%b-%Y %I:%M %p")}
    show = plan.copy()
    show["Target date"] = show["target"].apply(lambda d: d.strftime(DATE_FMT))
    show["Deadline"] = show.apply(lambda r: f"This item must be resolved within {r['day_no']} working day{'s' if r['day_no'] != 1 else ''}, "
                                            f"target date: {r['target'].strftime(DATE_FMT)}", axis=1)
    out = pd.DataFrame({"Day": show["day_no"], "Phase": show["phase"].map(lambda p: PLAN_PHASES[p].split(" · ")[0]),
                        "Factory": show["factory_name"], "ERP Code": show["prod_id"], "Item": show["item_name"], "Size": show["size"],
                        "UOM": show["unit"], "Type": show["type"], "Short/Excess Qty": show["variance"], "Value (৳)": show["abs_value"].round(0),
                        "Priority": show["priority"], "সম্ভাব্য কারণ": show["cause"], "করণীয়": show["action"],
                        "Officer": show["officer_name"], "Working days allowed": show["day_no"], "Target date": show["Target date"],
                        "Deadline": show["Deadline"]})
    fname = f"Short_Excess_Plan_{local_now():%d%b%Y}".replace(" ", "")
    b1, b2, b3 = st.columns(3)
    if not _lazy_download(b1, "📄 PDF Report ডাউনলোড", lambda: short_excess_plan_pdf(meta, plan, summ, off_df), f"{fname}.pdf",
                          "application/pdf", "sep_pdf_dl"):
        pdf_now = short_excess_plan_pdf(meta, plan, summ, off_df)
        if pdf_now:
            b1.download_button("📄 PDF Report ডাউনলোড", pdf_now, f"{fname}.pdf", "application/pdf", key="sep_pdf_dl_b")
        else:
            b1.caption("PDF: 'pip install reportlab'")
    xl_mime = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    if not _lazy_download(b2, "⬇️ Excel", lambda: _xlsx_bytes(out), f"{fname}.xlsx", xl_mime, "sep_xls_dl"):
        b2.download_button("⬇️ Excel", _xlsx_bytes(out), f"{fname}.xlsx", xl_mime, key="sep_xls_dl_b")
    open_keys = set()
    if tasks is not None and not tasks.empty:
        for r in tasks[tasks["status"] != "Closed"].to_dict("records"):
            open_keys.add((r["factory_name"], str(r["prod_id"]), r["item_name"]))
    fresh = [r for r in plan.to_dict("records") if (r["factory_name"], str(r["prod_id"]), r["item_name"]) not in open_keys]
    if "CONSOLIDATED" in str(FAC):
        b3.caption("Task সেভ করতে নির্দিষ্ট একটি factory select করুন।")
    elif b3.button(f"💾 {len(fresh)}টি Correction Task তৈরি করুন", key="sep_save", type="primary", disabled=not fresh):
        if guard():
            trows = [{**r, "target": r["target"].strftime(DATE_FMT), "value": (r["abs_value"] if r["variance"] > 0 else -r["abs_value"])}
                     for r in fresh]
            n = save_plan_tasks(trows)
            if n:
                done(f"{n}টি Correction task তৈরি হয়েছে।")
    st.caption(f"{len(fresh)}টি আইটেমের জন্য নতুন task হবে ({len(plan) - len(fresh)}টির open task আগে থেকেই আছে — সেগুলো বাদ)। "
               "PDF-এ প্রতিটি আইটেমের নাম, Size, UOM, Short/Excess পরিমাণ ও মূল্য, দায়িত্বপ্রাপ্ত অফিসার, কত কার্যদিবসের মধ্যে ও কোন তারিখের মধ্যে সমাধান করতে হবে — সব থাকে।")

    summary_txt = (f"Short/Excess সমাধান পরিকল্পনা ({local_now():%d-%b-%Y}): মোট {n_short}টি Short (৳{v_short:,.0f}) ও {n_exc}টি Excess "
                   f"(৳{v_exc:,.0f}) আইটেম। {quick}টি আইটেম শুধু ERP এন্ট্রি/আপডেটের কারণে (দ্রুত সমাধান), বাকি {len(base) - quick}টিতে "
                   f"Physical recount ও ডকুমেন্ট যাচাই লাগবে। {len(officers)} জন অফিসার দৈনিক {per_off:g}টি করে কাজ করলে "
                   f"{n_days} কার্যদিবসে, অর্থাৎ {finish.strftime(DATE_FMT)}-এর মধ্যে সব আইটেমের সমাধান ও Manager verification সম্পন্ন হবে।")
    with st.expander("📝 Audit Department-কে জানানোর সারাংশ (কপি করে পাঠান)"):
        st.code(summary_txt, language=None)
    with st.expander(f"📋 আইটেম-ভিত্তিক বিস্তারিত পরিকল্পনা ({len(out)})", expanded=False):
        st.dataframe(out, hide_index=True, use_container_width=True, height=420,
                     column_config={"Short/Excess Qty": st.column_config.NumberColumn(format="%+.2f")})
        st.caption("'সম্ভাব্য কারণ' সিস্টেমের অনুমান (ERP update / PO-GRN pending আছে কি না দেখে) — Physical যাচাই ছাড়া চূড়ান্ত নয়।")

    st.markdown("**পরিকল্পনা কতদূর এগিয়েছে (Correction Task থেকে)**")
    if tasks is None or tasks.empty:
        st.caption("এখনো কোনো Correction task নেই।")
    else:
        t = tasks.copy()
        total, closed = len(t), int((t["status"] == "Closed").sum())
        due = t["target_date"].apply(parse_date)
        today = datetime.combine(local_now().date(), datetime.min.time())
        overdue = int(sum(1 for s, d in zip(t["status"], due) if s != "Closed" and d is not None and d < today))
        g = st.columns(4)
        g[0].metric("মোট task", total)
        g[1].metric("Closed", closed, f"{closed / total * 100:.0f}%")
        g[2].metric("Open", total - closed)
        g[3].metric("⏰ সময় পেরিয়েছে", overdue)
        st.progress(closed / total if total else 0.0)


