def _ls_tz_offset():
    """Audit rows were stamped with the server clock, the transactions with Dhaka time - bring both to Dhaka time."""
    diff = local_now().replace(tzinfo=None) - datetime.now()
    return pd.Timedelta(minutes=int(round(diff.total_seconds() / 1800.0)) * 30)


def _ls_audit_frame(rows):
    df = pd.DataFrame(rows)
    if df.empty:
        return pd.DataFrame(columns=["id", "when", "username", "action_type", "details"])
    df["when"] = pd.to_datetime(df["timestamp"], errors="coerce") + _ls_tz_offset()
    return df


def _ls_when_text(ts, fallback=""):
    return [t.strftime("%d-%b-%Y %I:%M %p") if pd.notna(t) else f for t, f in zip(ts, fallback)]


def _ls_item_log():
    st.caption("একটা আইটেম বেছে নিন — তার সব Transaction আর কে কখন কী এডিট/মুছেছে/দাম বা Category বদলেছে, এক টাইমলাইনে।")
    term = st.text_input("🔍 আইটেম খুঁজুন (নাম / ERP code / serial / size)", key="ls_search").strip()
    if not term:
        st.info("ওপরের বক্সে আইটেমের নাম বা ERP code লিখুন।")
        return
    fsql, fp = fw(FAC)
    pat = f"%{term.lower()}%"
    items = q_c(f"""SELECT factory_name, sl_no, COALESCE(prod_id,'') AS prod_id, COALESCE(item_name,'') AS item_name,
                    COALESCE(size,'') AS size, COALESCE(serial_no,'') AS serial_no, COALESCE(current_stock,0) AS stock,
                    COALESCE(unit_price,0) AS price, COALESCE(NULLIF(unit_name,''),'Pcs') AS unit
                    FROM inventory WHERE (LOWER(item_name) LIKE %s OR LOWER(COALESCE(prod_id,'')) LIKE %s
                          OR LOWER(COALESCE(serial_no,'')) LIKE %s OR LOWER(COALESCE(size,'')) LIKE %s){fsql}
                    ORDER BY item_name, size LIMIT 100""", [pat, pat, pat, pat] + fp)
    if not items:
        st.warning("Inventory-তে এই নামে আইটেম নেই (মুছে গিয়ে থাকতে পারে)। নিচে শুধু Audit log-এ খোঁজা হলো।")
        arows = q_c("""SELECT id, timestamp, username, action_type, details FROM audit_logs
                       WHERE details ILIKE %s ORDER BY id DESC LIMIT 500""", (f"%{term}%",))
        adf = _ls_audit_frame(arows)
        if adf.empty:
            st.info("Audit log-এও কিছু পাওয়া যায়নি।")
            return
        out = pd.DataFrame({"When": _ls_when_text(adf["when"], adf["timestamp"]),
                            "Action": adf["action_type"].map(lambda a: ("⚠️ " if a in LS_RISKY else "") + LS_ACTIONS.get(a, a)),
                            "Who": adf["username"], "Details": adf["details"]})
        st.dataframe(out, hide_index=True, use_container_width=True, height=420)
        export_buttons(out, "log_sheet_audit_only")
        return
    labels = {f"{r['item_name']} [{r['size'] or '-'}]{_uom_tag(r)} · {r['prod_id'] or '-'} · {short_fac(r['factory_name'])} · SL {r['sl_no']}": r for r in items}
    row = labels[st.selectbox("আইটেম বেছে নিন", list(labels), key="ls_pick")]
    fac, sl = row["factory_name"], int(row["sl_no"])
    name, pid = str(row["item_name"]), str(row["prod_id"]).strip()
    unit = row["unit"]

    tx = qdf_c("""SELECT id, date, time, trans_type, qty, COALESCE(officer_name,'') AS officer, COALESCE(notes,'') AS notes,
                  COALESCE(verification_status,'') AS verif, COALESCE(supplier_name,'') AS supplier,
                  COALESCE(challan_no,'') AS challan, unit_price_at_tx AS rate
                  FROM transactions WHERE factory_name=%s AND sl_no=%s ORDER BY id DESC""", (fac, sl))
    tx_ids = set(int(i) for i in tx["id"]) if not tx.empty else set()
    name_l, pid_l = name.lower(), pid.lower()
    use_pid = bool(pid_l) and not is_blank_code(pid_l) and not pid_l.startswith("temp-")
    params = [f"%{name}%", f"%SL {sl}%"] + ([f"%{pid}%"] if use_pid else [])
    cond = "details ILIKE %s OR details ILIKE %s" + (" OR details ILIKE %s" if use_pid else "")
    arows = q_c(f"""SELECT id, timestamp, username, action_type, details FROM audit_logs
                    WHERE {cond} OR action_type IN %s ORDER BY id DESC LIMIT 4000""", params + [_LS_TX_ACTIONS])
    adf = _ls_audit_frame(arows)
    keep = []
    sl_re = re.compile(rf"\bsl {sl}\b")
    id_re = re.compile(r"(?:transaction(?: id)?|record|receipt|issue #)\s*(\d+)")
    for d_ in adf["details"].astype(str) if not adf.empty else []:
        t_ = d_.lower()
        ok = name_l in t_ or (use_pid and pid_l in t_) or (bool(sl_re.search(t_)) and fac.lower() in t_)
        if not ok:
            ok = any(int(m) in tx_ids for m in id_re.findall(t_))
        keep.append(ok)
    if not adf.empty:
        adf = adf[pd.Series(keep, index=adf.index)]

    # ---- summary
    tx_n = tx.copy()
    if not tx_n.empty:
        tx_n["qty"] = pd.to_numeric(tx_n["qty"], errors="coerce").fillna(0.0)
    rec_q = float(tx_n[tx_n["trans_type"].isin(RECEIPT_TYPES)]["qty"].sum()) if not tx_n.empty else 0.0
    iss_q = float(tx_n[tx_n["trans_type"].isin(ISSUE_TYPES + (ADJ_OUT,))]["qty"].sum()) if not tx_n.empty else 0.0
    risky = adf[adf["action_type"].isin(LS_RISKY)] if not adf.empty else adf
    st.markdown(f"### {html_lib.escape(name)} [{html_lib.escape(str(row['size'] or '-'))}]")
    st.caption(f"{fac} · ERP code {pid or '-'} · SL {sl} · Serial {row['serial_no'] or '-'}")
    m = st.columns(5)
    m[0].metric("এখনকার স্টক", f"{float(row['stock']):g} {unit}")
    m[1].metric("মোট Receipt", f"{rec_q:g}")
    m[2].metric("মোট Issue/Out", f"{iss_q:g}")
    m[3].metric("Transaction", f"{len(tx):,}")
    m[4].metric("⚠️ এডিট/মুছা/বদল", f"{len(risky):,}")
    if len(risky):
        last = risky.sort_values("when", ascending=False).iloc[0]
        st.warning(f"সর্বশেষ সংবেদনশীল পরিবর্তন: {LS_ACTIONS.get(last['action_type'], last['action_type'])} — {last['username']} — "
                   f"{last['when'].strftime('%d-%b-%Y %I:%M %p') if pd.notna(last['when']) else last['timestamp']}")

    # ---- one merged timeline
    rows = []
    if not tx_n.empty:
        d = _parse_dates(tx_n["date"])
        tm = pd.to_datetime(tx_n["time"].astype(str).str.strip(), format="%I:%M %p", errors="coerce")
        miss = tm.isna()
        if miss.any():
            tm.loc[miss] = pd.to_datetime(tx_n["time"].astype(str).str.strip()[miss], format="%H:%M:%S", errors="coerce")
        when = d + pd.to_timedelta(tm.dt.hour.fillna(0) * 3600 + tm.dt.minute.fillna(0) * 60, unit="s")
        for i, r in enumerate(tx_n.to_dict("records")):
            sign = -1.0 if r["trans_type"] in ISSUE_TYPES + (ADJ_OUT,) else (1.0 if r["trans_type"] in RECEIPT_TYPES else 0.0)
            extra = []
            if r["supplier"]:
                extra.append(f"Supplier: {r['supplier']}")
            if r["challan"]:
                extra.append(f"Challan: {r['challan']}")
            if r["rate"] is not None and pd.notna(r["rate"]):
                extra.append(f"Rate: {float(r['rate']):g}")
            if r["verif"]:
                extra.append(f"Verification: {r['verif']}")
            rows.append({"_k": when.iloc[i], "When": f"{r['date']} {r['time']}".strip(), "Source": "Transaction",
                         "Action": TRANS_LABELS.get(r["trans_type"], r["trans_type"]),
                         "Qty": (r["qty"] * sign if sign else r["qty"]), "Who": r["officer"],
                         "Details": " · ".join([f"#{r['id']}"] + ([r["notes"]] if r["notes"] else []) + extra)})
    if not adf.empty:
        for r in adf.to_dict("records"):
            a = r["action_type"]
            rows.append({"_k": r["when"], "When": r["when"].strftime("%d-%b-%Y %I:%M %p") if pd.notna(r["when"]) else r["timestamp"],
                         "Source": "Audit", "Action": ("⚠️ " if a in LS_RISKY else "") + LS_ACTIONS.get(a, a),
                         "Qty": None, "Who": r["username"], "Details": r["details"]})
    if not rows:
        st.info("এই আইটেমের কোনো Transaction বা লগ নেই।")
        return
    flt = st.radio("দেখান", ["সব", "শুধু Transaction", "শুধু পরিবর্তন (এডিট/মুছা/দাম/Category)"], horizontal=True, key="ls_flt")
    tl = pd.DataFrame(rows).sort_values("_k", ascending=False, na_position="last")
    if flt == "শুধু Transaction":
        tl = tl[tl["Source"] == "Transaction"]
    elif flt.startswith("শুধু পরিবর্তন"):
        tl = tl[tl["Action"].str.startswith("⚠️")]
    tl = tl.drop(columns=["_k"])
    st.dataframe(tl, hide_index=True, use_container_width=True, height=460,
                 column_config={"Qty": st.column_config.NumberColumn(format="%+.2f")})
    st.caption("Audit-এর সময় Dhaka সময়ে মেলানো। নামে মিলে গেলে একই নামের অন্য সাইজের আইটেমের লগও আসতে পারে; "
               "আগে মুছে ফেলা Transaction-এর লগে আইটেমের নাম থাকত না — এখন থেকে থাকবে।")
    export_buttons(tl, f"log_sheet_{sl}")


def _ls_all_log():
    st.caption("সব আইটেমের সব পরিবর্তনের লগ। কে কী মুছেছে বা এডিট করেছে খুঁজতে এটা ব্যবহার করুন।")
    today = local_now().date()
    c1, c2, c3 = st.columns([1.2, 1, 1])
    rng = c1.date_input("তারিখ (থেকে – পর্যন্ত)", value=(today - timedelta(days=7), today), key="ls_rng")
    rows = q_c("""SELECT id, timestamp, username, action_type, details FROM audit_logs ORDER BY id DESC LIMIT 8000""")
    adf = _ls_audit_frame(rows)
    if adf.empty:
        st.info("কোনো লগ নেই।")
        return
    users = ["সব"] + sorted(set(adf["username"].astype(str)))
    who = c2.selectbox("কে", users, key="ls_user")
    only_risky = c3.checkbox("শুধু সংবেদনশীল (এডিট/মুছা/বদল)", value=True, key="ls_risky")
    acts = sorted(set(adf["action_type"].astype(str)))
    default = [a for a in acts if a in LS_RISKY] if only_risky else acts
    pick = st.multiselect("কাজের ধরন", acts, default=default, format_func=lambda a: LS_ACTIONS.get(a, a), key=f"ls_acts_{int(only_risky)}")
    txt_f = st.text_input("লেখা খুঁজুন (আইটেমের নাম, code, ইত্যাদি)", key="ls_txt").strip().lower()
    v = adf
    if isinstance(rng, (tuple, list)) and len(rng) == 2:
        d0, d1 = pd.Timestamp(rng[0]), pd.Timestamp(rng[1]) + pd.Timedelta(days=1)
        v = v[(v["when"] >= d0) & (v["when"] < d1)]
    if who != "সব":
        v = v[v["username"].astype(str) == who]
    if pick:
        v = v[v["action_type"].isin(pick)]
    if txt_f:
        v = v[v["details"].astype(str).str.lower().str.contains(txt_f, regex=False)]
    st.caption(f"{len(v):,}টি এন্ট্রি" + (" (সর্বশেষ ৮,০০০টির মধ্যে)" if len(adf) >= 8000 else ""))
    out = pd.DataFrame({"When": _ls_when_text(v["when"], v["timestamp"]),
                        "Action": v["action_type"].map(lambda a: ("⚠️ " if a in LS_RISKY else "") + LS_ACTIONS.get(a, a)),
                        "Who": v["username"], "Details": v["details"]})
    st.dataframe(out, hide_index=True, use_container_width=True, height=460)
    export_buttons(out, "log_sheet_all")


def tab_log_sheet():
    st.title("📒 Log Sheet")
    st.caption("কে কখন কোন আইটেমে কী করেছে — Transaction, এডিট, মুছে ফেলা, দাম ও Category বদল — সব এক জায়গায়।")
    pick = lazy_tab_select(["🔎 একটি আইটেমের পুরো লগ", "🗂 সব পরিবর্তনের লগ"], "lz_ls")
    if pick == 0:
        _ls_item_log()
    else:
        _ls_all_log()


# ============================================================
#  HIGH VALUE STOCK (new page, ADDITIVE ONLY): the expensive items that are still on the books, ranked by money,
#  with how long ago they were last issued - so "used but never issued" stock is easy to spot and check physically.
# ============================================================
NAV_HIGH_VALUE = "💎 High Value Stock"
if NAV_HIGH_VALUE not in TAB_NAMES:
    TAB_NAMES.append(NAV_HIGH_VALUE)


@st.cache_data(ttl=180, show_spinner=False, max_entries=8)
def _hv_tx_stats(fac, ver):
    """Per item: last Issue date, number of Issues, last Receipt date (worked out once, reused until data changes)."""
    fsql, fp = fw(fac)
    tx = qdf_c(f"""SELECT factory_name, sl_no, trans_type, date FROM transactions
                   WHERE trans_type IN ('Issued','Internal Issue','Supplier. Rec','Internal Rec'){fsql}""", fp)
    cols = ["factory_name", "sl_no", "last_issue", "issue_n", "last_receipt"]
    if tx.empty:
        return pd.DataFrame(columns=cols)
    tx["d"] = _parse_dates(tx["date"])
    iss = tx[tx["trans_type"].isin(ISSUE_TYPES)]
    rec = tx[tx["trans_type"].isin(("Supplier. Rec", "Internal Rec"))]
    a = iss.groupby(["factory_name", "sl_no"]).agg(last_issue=("d", "max"), issue_n=("d", "size")).reset_index()
    b = rec.groupby(["factory_name", "sl_no"]).agg(last_receipt=("d", "max")).reset_index()
    out = a.merge(b, on=["factory_name", "sl_no"], how="outer")
    out["issue_n"] = out["issue_n"].fillna(0).astype(int)
    return out[cols]


@st.cache_data(ttl=180, show_spinner=False, max_entries=8)
def _hv_frame(fac, ver, today_s):
    fsql, fp = fw(fac)
    inv = qdf_c(f"""SELECT factory_name, sl_no, COALESCE(prod_id,'') AS prod_id, COALESCE(item_name,'') AS item_name,
                    COALESCE(size,'') AS size, COALESCE(current_stock,0) AS stock, COALESCE(unit_price,0) AS price,
                    COALESCE(NULLIF(unit_name,''),'Pcs') AS unit FROM inventory WHERE 1=1{fsql}""", fp)
    if inv.empty:
        return inv
    for c in ("stock", "price"):
        inv[c] = pd.to_numeric(inv[c], errors="coerce").fillna(0.0)
    inv["value"] = inv["stock"].clip(lower=0) * inv["price"]
    st_ = _hv_tx_stats(fac, ver)
    df = inv.merge(st_, on=["factory_name", "sl_no"], how="left")
    df["issue_n"] = df["issue_n"].fillna(0).astype(int)
    df["last_issue"] = pd.to_datetime(df["last_issue"], errors="coerce")
    df["last_receipt"] = pd.to_datetime(df["last_receipt"], errors="coerce")
    today = pd.Timestamp(today_s)
    df["days_issue"] = (today - df["last_issue"]).dt.days
    df["days_receipt"] = (today - df["last_receipt"]).dt.days
    ranked = df[df["value"] > 0].sort_values("value", ascending=False)
    tot = float(ranked["value"].sum()) or 1.0
    cum = ranked["value"].cumsum() / tot
    df["abc"] = ""
    df.loc[ranked.index, "abc"] = ["A" if c_ - v_ / tot < 0.80 else ("B" if c_ - v_ / tot < 0.95 else "C")
                                   for c_, v_ in zip(cum, ranked["value"])]
    return df


def _hv_flag(r):
    if r["stock"] <= 0:
        return ""
    di, dr = r["days_issue"], r["days_receipt"]
    if pd.isna(di):
        if pd.notna(dr) and dr < 30:
            return "🆕 নতুন এসেছে, এখনো Issue হয়নি"
        return "⛔ কখনো Issue হয়নি — ফিজিক্যালি দেখুন"
    if di >= 90:
        return f"⚠️ {int(di)} দিন Issue নেই — ফিজিক্যালি দেখুন"
    if di >= 30:
        return f"👀 {int(di)} দিন Issue নেই"
    return "✅ সম্প্রতি Issue হয়েছে"


def tab_high_value():
    st.title("💎 High Value Stock")
    st.caption("সফটওয়্যারে যেসব দামি মাল স্টকে দেখানো আছে — টাকার অঙ্কে বড় থেকে ছোট। কত দিন ধরে Issue হয়নি সেটাও দেখাবে, "
               "যাতে যেগুলো আসলে ব্যবহার হয়ে গেছে কিন্তু Issue হয়নি সেগুলো ধরা যায়।")
    today_s = local_now().strftime("%Y-%m-%d")
    try:
        df = _hv_frame(FAC, _data_version(), today_s)
    except Exception as e:
        st.error(f"লোড করা যায়নি: {e}")
        return
    if df is None or df.empty:
        st.info("Inventory খালি।")
        return
    c1, c2, c3 = st.columns([1.1, 1.1, 1.4])
    min_val = c1.number_input("ন্যূনতম স্টক মূল্য (৳)", min_value=0.0, value=20000.0, step=5000.0, key="hv_min",
                              help="স্টক × একক দাম এই অঙ্কের সমান বা বেশি হলে দেখাবে।")
    min_days = c2.number_input("কত দিন Issue নেই (কমপক্ষে)", min_value=0, value=0, step=30, key="hv_days",
                               help="০ রাখলে সব দামি আইটেম দেখাবে। ৯০ দিলে শুধু ৯০+ দিন Issue হয়নি এমন।")
    term = c3.text_input("খুঁজুন (নাম / ERP code)", key="hv_term").strip().lower()

    stocked = df[(df["stock"] > 0)]
    total_val = float(stocked["value"].sum())
    nop = int(((stocked["price"] <= 0)).sum())
    v = df[(df["value"] >= float(min_val)) & (df["stock"] > 0)].copy()
    v["flag"] = pd.Series([_hv_flag(r) for _, r in v.iterrows()], index=v.index, dtype="object")   # safe even when no row matches
    if min_days > 0:
        v = v[(v["days_issue"].isna()) | (v["days_issue"] >= min_days)]
    if term:
        m = v[["item_name", "prod_id", "size"]].astype(str).apply(lambda c: c.str.lower().str.contains(term, regex=False)).any(axis=1)
        v = v[m]
    v = v.sort_values("value", ascending=False)
    susp = v[v["flag"].str.startswith(("⛔", "⚠️"))]

    k = st.columns(4)
    k[0].metric("দামি আইটেম", f"{len(v):,}")
    k[1].metric("এগুলোর মোট মূল্য", f"৳{float(v['value'].sum()):,.0f}",
                f"মোট স্টকের {float(v['value'].sum()) / total_val * 100:.0f}%" if total_val else None, delta_color="off")
    k[2].metric("⚠️ সন্দেহজনক (৯০+ দিন / কখনো Issue নেই)", f"{len(susp):,}")
    k[3].metric("সন্দেহজনকের মূল্য", f"৳{float(susp['value'].sum()):,.0f}")
    if nop:
        st.caption(f"ℹ️ {nop:,}টি আইটেমের একক দাম ০, তাই এদের মূল্য ধরা হয়নি — Data Health → দাম ০ থেকে দাম বসান।")
    if v.empty:
        st.success("এই শর্তে কোনো আইটেম নেই। ন্যূনতম মূল্য বা দিনের সংখ্যা কমিয়ে দেখুন।")
        return

    out = pd.DataFrame({
        "Factory": v["factory_name"].map(short_fac), "ERP Code": v["prod_id"], "Item": v["item_name"], "Size": v["size"],
        "Stock": v["stock"], "UOM": v["unit"], "Unit price (৳)": v["price"], "Stock value (৳)": v["value"], "Class": v["abc"],
        "Last Issue": v["last_issue"].dt.strftime(DATE_FMT).fillna("কখনো না"),
        "Days since Issue": v["days_issue"], "Issues (মোট)": v["issue_n"],
        "Last Receipt": v["last_receipt"].dt.strftime(DATE_FMT).fillna("-"), "Check": v["flag"]})
    if not is_cons_view:
        out = out.drop(columns=["Factory"])
    st.dataframe(out, hide_index=True, use_container_width=True, height=min(90 + 35 * len(out), 560), column_config={
        "Stock": st.column_config.NumberColumn(format="%.2f"),
        "Unit price (৳)": st.column_config.NumberColumn(format="%.2f"),
        "Stock value (৳)": st.column_config.NumberColumn(format="%.0f"),
        "Days since Issue": st.column_config.NumberColumn(format="%d")})
    st.caption("Class A = মোট স্টক মূল্যের প্রথম ৮০% যে আইটেমগুলো গঠন করে (সবচেয়ে গুরুত্বপূর্ণ), B = পরের ১৫%, C = বাকি। "
               "'কখনো Issue হয়নি' বা '৯০+ দিন' মানে নিশ্চিতভাবে ভুল নয় — ফিজিক্যালি গুনে দেখুন।")
    export_buttons(out, "high_value_stock")
    b1, b2, _ = st.columns([1, 1, 2])
    b1.button("📱 Physical Count খুলুন →", key="hv_go_pc", on_click=go_page, args=(NAV_PHYSICAL, None))
    b2.button("📝 Issue করতে Transactions →", key="hv_go_tx", on_click=go_page, args=(NAV_TRANSACTIONS, None))


# ============================================================
#  REQUISITION ISSUE (new page, ADDITIVE ONLY): up to 15 items of ONE store requisition slip issued in one go,
#  all with the same SR No. Nothing in the normal Transactions form was changed.
# ============================================================
NAV_REQ_ISSUE = "🧾 Requisition Issue"
if NAV_REQ_ISSUE not in TAB_NAMES:
    TAB_NAMES.append(NAV_REQ_ISSUE)
RI_MAX_LINES = 15


def _ri_verif_many(fac, sls, tx_dt):
    """Same rule as verification_needed(), but for many items with ONE query: {sl_no: (needed, elapsed_days)}."""
    target = tx_dt.date() if isinstance(tx_dt, datetime) else tx_dt
    rows = q("""SELECT sl_no, date, verification_status FROM transactions
                WHERE factory_name=%s AND sl_no = ANY(%s) AND trans_type IN ('Issued','Internal Issue') AND date IS NOT NULL""",
             (fac, [int(x) for x in sls]))
    by = {}
    for r in rows:
        d = parse_date(r.get("date"))
        if d and d.date() < target:
            by.setdefault(int(r["sl_no"]), []).append((d.date(), str(r.get("verification_status") or "")))
    out = {}
    for sl in sls:
        ev = by.get(int(sl), [])
        phys = [d for d, st_ in ev if st_.startswith("Physically")]
        last_phys = max(phys) if phys else None
        pend = [d for d, st_ in ev if not st_.startswith("Physically") and (last_phys is None or d > last_phys)]
        if not pend:
            out[int(sl)] = (False, 0)
        else:
            el = (target - min(pend)).days
            out[int(sl)] = (el >= VERIFY_AFTER_DAYS, el)
    return out


def stock_asof_many(fac, sls, d, cached=False):
    """{sl_no: stock at the END of day d} = today's stock minus everything that moved AFTER d (receipts, issues, adjustments and
    inter-unit transfers dated later). A receipt or transfer entered / dated later must not count for an earlier date."""
    sls = sorted({int(x) for x in sls})
    if not sls:
        return {}
    if isinstance(d, datetime):
        d = d.date()
    qq = q_c if cached else q
    js = json.dumps(sls)
    inv = qq("""SELECT sl_no, COALESCE(prod_id,'') AS pid, COALESCE(size,'') AS size, COALESCE(current_stock,0) AS stock
                FROM inventory WHERE factory_name=%s AND sl_no = ANY(SELECT jsonb_array_elements_text(%s::jsonb)::int)""", (fac, js))
    net = {}
    for r in qq(f"""SELECT t.sl_no, t.trans_type, SUM(COALESCE(t.qty,0)) AS q FROM transactions t
                    WHERE t.factory_name=%s AND t.sl_no = ANY(SELECT jsonb_array_elements_text(%s::jsonb)::int)
                      AND {_sql_date('t.date')} > %s GROUP BY t.sl_no, t.trans_type""", (fac, js, d)):
        sign = -1.0 if (r["trans_type"] in ISSUE_TYPES or r["trans_type"] == ADJ_OUT) else (1.0 if r["trans_type"] in RECEIPT_TYPES else 0.0)
        net[int(r["sl_no"])] = net.get(int(r["sl_no"]), 0.0) + sign * float(r["q"] or 0)
    try:
        tin = qq(f"""SELECT COALESCE(prod_id,'') AS pid, COALESCE(size,'') AS size, COALESCE(qty,0) AS qty, COALESCE(notes,'') AS notes
                     FROM inter_factory_transfers WHERE dest_factory=%s AND COALESCE(status,'Completed')='Completed'
                       AND {_sql_date('transfer_date')} > %s""", (fac, d))
        tout = qq(f"""SELECT COALESCE(prod_id,'') AS pid, COALESCE(size,'') AS size, COALESCE(qty,0) AS qty, COALESCE(notes,'') AS notes
                      FROM inter_factory_transfers WHERE source_factory=%s AND COALESCE(status,'Completed')='Completed'
                        AND {_sql_date('transfer_date')} > %s""", (fac, d))
    except Exception:
        tin, tout = [], []
    out = {}
    for it in inv:
        sl, pid, size = int(it["sl_no"]), str(it["pid"]).strip(), str(it["size"]).strip().lower()
        n = net.get(sl, 0.0)
        if pid:
            for t in tin:
                if str(t["pid"]).strip() == pid and (not str(t["size"]).strip() or str(t["size"]).strip().lower() == size):
                    n += float(t["qty"] or 0)
            for t in tout:
                if f"[{pid}]" in str(t["notes"]) and (not str(t["size"]).strip() or str(t["size"]).strip().lower() == size):
                    n -= float(t["qty"] or 0)
        out[sl] = max(float(it["stock"] or 0) - n, 0.0)
    return out


@tx
def save_requisition_issue(fac, lines, tx_dt, sr_no, ttype, notes, verified, po_pending=False, section="", machine=None, asof=False):
    """lines = [(sl_no, qty, xfer_ok)]. All-or-nothing: stock is re-read and locked, every line is checked first, then
    ONE update + ONE insert (+ one audit insert) write the whole slip. A line whose qty is above stock is covered by an
    auto-transfer from the other unit (same rule as the Transactions tab) when the user confirmed it."""
    user = st.session_state.get("user", "")
    sls = [int(a[0]) for a in lines]
    qtys = [float(a[1]) for a in lines]
    xfer = {int(a[0]): bool(a[2]) if len(a) > 2 else False for a in lines}
    xconf = {int(a[0]): (float(a[4]) if len(a) > 4 and a[4] else 0.0) for a in lines}      # shortage the officer ticked the transfer for
    rates = {int(a[0]): (float(a[3]) if len(a) > 3 and a[3] else 0.0) for a in lines}
    rows = run("""SELECT sl_no, COALESCE(prod_id,''), COALESCE(item_name,''), COALESCE(current_stock,0), COALESCE(size,''), COALESCE(unit_price,0)
                  FROM inventory WHERE factory_name=%s AND sl_no = ANY(%s) FOR UPDATE""", (fac, sls))
    info = {int(r[0]): (str(r[1]), str(r[2]), float(r[3] or 0), str(r[4])) for r in (rows or [])}
    price0 = {int(r[0]): float(r[5] or 0) for r in (rows or [])}
    if len(info) != len(set(sls)):
        st.error("কিছু আইটেম আর পাওয়া যাচ্ছে না। পেজ রিফ্রেশ করে আবার চেষ্টা করুন।")
        return False
    _pm = pre_opening_msg(fac, sls, tx_dt, {k: v[1] for k, v in info.items()})
    if _pm:
        st.error(_pm + " Kichui save hoy ni.")
        return False
    # ---- shortage lines: need a confirmed auto-transfer from the other unit (checked for ALL lines before anything is written)
    plan, used_other, bad_short = {}, {}, []
    _td = tx_dt.date() if isinstance(tx_dt, datetime) else tx_dt
    _asof = stock_asof_many(fac, sls, _td) if (asof and _td < local_now().date()) else {}    # back-dated slip: stock of THAT day decides if a transfer was needed
    for sl, q_ in zip(sls, qtys):
        pid_, nm_, stk_, size_ = info[sl]
        stk_ = _asof.get(sl, stk_)
        if q_ <= stk_ + 1e-9:
            continue
        shortage = q_ - stk_
        other = find_same_in_other(pid_, nm_, other_factory(fac), size_, need=shortage)
        if other and xfer.get(sl) and abs(xconf.get(sl, 0.0) - shortage) > 1e-6:
            bad_short.append(f"{pid_} (stock {stk_:g}, issue {q_:g}: transfer {xconf.get(sl, 0.0):g} confirm kora hoyechilo kintu ekhon {shortage:g} lagche — abar tick din)")
            continue
        if other and xfer.get(sl):
            okey = (int(other["sl_no"]), other["factory_name"])
            lk = run("SELECT COALESCE(current_stock,0) FROM inventory WHERE sl_no=%s AND factory_name=%s FOR UPDATE", okey)
            o_stock = float(lk[0][0] or 0) if lk else 0.0
            if o_stock - used_other.get(okey, 0.0) >= shortage - 1e-9:
                used_other[okey] = used_other.get(okey, 0.0) + shortage
                plan[sl] = (shortage, other)
                continue
        bad_short.append(f"{pid_} (স্টক {stk_:g}, দিচ্ছেন {q_:g})")
    if bad_short:
        st.error("স্টক কম / ট্রান্সফার সম্ভব নয় বা নিশ্চিত করা হয়নি — কিছুই সংরক্ষণ হয়নি: " + "; ".join(bad_short))
        return False
    no_rate = [info[sl][0] for sl in sls if price0.get(sl, 0) <= 0 and rates.get(sl, 0) <= 0]
    if no_rate:
        st.error("এই আইটেমগুলোর Rate নেই — Rate দিয়ে আবার সংরক্ষণ করুন: " + ", ".join(no_rate))
        return False
    vm = _ri_verif_many(fac, sls, tx_dt)
    need = [info[sl][1] for sl in sls if vm.get(sl, (False, 0))[0]]
    if need and not verified:
        st.error("Physical verification লাগবে (৩ দিন পার হয়েছে): " + ", ".join(need) + " — টিক দিয়ে আবার সংরক্ষণ করুন।")
        return False
    vstat = ["Physically Verified" if (vm.get(sl, (False, 0))[0] and verified) else "Not Required" for sl in sls]
    date_s, time_s = tx_dt.strftime(DATE_FMT), datetime.now().strftime("%I:%M %p")
    line_notes = []
    for n_i, sl in enumerate(sls):
        nt = notes
        if sl in plan:
            shortage, other = plan[sl]
            size_ = info[sl][3]
            ref_no = f"TRF-{datetime.now():%Y%m%d%H%M%S%f}-{n_i}"
            run("UPDATE inventory SET current_stock=current_stock-%s WHERE sl_no=%s AND factory_name=%s",
                (shortage, other["sl_no"], other["factory_name"]))
            run("UPDATE inventory SET current_stock=current_stock+%s WHERE sl_no=%s AND factory_name=%s", (shortage, sl, fac))
            run("""INSERT INTO inter_factory_transfers (transfer_ref, source_factory, dest_factory, prod_id, item_name, qty,
                   transfer_date, transfer_time, initiated_by, status, notes, size) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,'Completed',%s,%s)""",
                (ref_no, other["factory_name"], fac, info[sl][0], info[sl][1], shortage, date_s, time_s, user,
                 f"Auto-transfer for shortage during requisition issue SR {sr_no} (source item: {other['item_name']} [{other['prod_id']}]) | Size: {size_ or '-'}",
                 size_))
            nt = f"{notes} [Auto-transferred {shortage:g} pcs (size {size_ or '-'}) from {other['factory_name']}]".strip()
            audit("AUTO_TRANSFER", f"{shortage:g} pcs from {other['factory_name']} to {fac} for {info[sl][0]} (size {size_ or '-'}) [SR {sr_no}]")
        line_notes.append(nt)
    po_flag, po_date = ("Pending", date_s) if po_pending else ("", None)
    _mc_max = int(run("SELECT COALESCE(MAX(id),0) FROM transactions")[0][0]) if machine else 0   # machine tag: only when a machine was picked
    run("""UPDATE inventory SET current_stock = current_stock - v.q
           FROM (SELECT unnest(%s::int[]) AS sl, unnest(%s::float8[]) AS q) v
           WHERE inventory.factory_name=%s AND inventory.sl_no=v.sl""", (sls, qtys, fac))
    new_price = [(sl, rates[sl]) for sl in sls if price0.get(sl, 0) <= 0 and rates.get(sl, 0) > 0]
    if new_price:   # item had no rate: the rate given now becomes the item's rate (reports / budget pick it up)
        run("""UPDATE inventory SET unit_price = v.p
               FROM (SELECT unnest(%s::int[]) AS sl, unnest(%s::float8[]) AS p) v
               WHERE inventory.factory_name=%s AND inventory.sl_no=v.sl""", ([a for a, _ in new_price], [b for _, b in new_price], fac))
        for sl_, p_ in new_price:
            audit("SET_PRICE", f"{fac}: {info[sl_][1]} unit price 0 -> {p_:g} (Requisition Issue SR {sr_no})")
    run("""INSERT INTO transactions (factory_name, officer_name, sl_no, prod_id, item_name, qty, trans_type, day, notes, date, time,
                  verification_status, erp_grn_status, supplier_name, challan_no, po_pending_flag, po_pending_date,
                  unit_price_at_tx, req_no, section)
           SELECT %s, %s, v.sl, v.pid, v.nm, v.q, %s, %s, v.nt, %s, %s, v.vs, 'Not Required', '', '', %s, %s::text, NULL::float8, %s, %s
           FROM (SELECT unnest(%s::int[]) AS sl, unnest(%s::text[]) AS pid, unnest(%s::text[]) AS nm,
                        unnest(%s::float8[]) AS q, unnest(%s::text[]) AS vs, unnest(%s::text[]) AS nt) v""",
        (fac, user, ttype, tx_dt.day, date_s, time_s, po_flag, po_date, sr_no, section or "",
         sls, [info[sl][0] for sl in sls], [info[sl][1] for sl in sls], qtys, vstat, line_notes))
    if machine:
        _pairs = (list(machine.items()) if isinstance(machine, dict)
                  else ([(x, machine[0]) for x in (machine[1] or [])] if machine[0] else []))
        _by_mid = {}
        for _s, _m in _pairs:
            if _m and int(_s) in info:
                _by_mid.setdefault(int(_m), []).append(int(_s))
        for _m, _sl_list in _by_mid.items():
            run("UPDATE transactions SET machine_id=%s WHERE id > %s AND factory_name=%s AND req_no=%s AND sl_no = ANY(%s) AND machine_id IS NULL",
                (_m, _mc_max, fac, sr_no, _sl_list))
            audit("MACHINE_ISSUE", f"{fac}: SR {sr_no} -> machine id {_m} ({len(_sl_list)} line(s))")
    details = [f"{fac}: {ttype} {q_:g} of {info[sl][0]} ({info[sl][1]}) [SR {sr_no}]" + (f" [Section {section}]" if section else "") + (" [ERP PO Pending ticked]" if po_pending else "")
               + f" [stock before {info[sl][2]:g}" + (f", auto-transfer {plan[sl][0]:g} from {plan[sl][1]['factory_name']} (officer confirmed)" if sl in plan else ", no transfer") + "]"
               for sl, q_ in zip(sls, qtys)]
    st.session_state["_ri_xfer_note"] = "; ".join(f"{info[sl][1]}: {plan[sl][0]:g} pcs {plan[sl][1]['factory_name']} theke" for sl in sls if sl in plan)
    run("""INSERT INTO audit_logs (timestamp, username, action_type, details)
           SELECT %s, %s, 'TRANSACTION', d FROM unnest(%s::text[]) AS d""",
        (datetime.now().strftime("%Y-%m-%d %H:%M:%S"), user or "SYSTEM", details))
    if section:
        run("INSERT INTO ri_sections (factory_name, section_name) VALUES (%s,%s) ON CONFLICT DO NOTHING", (fac, section))
    audit("REQUISITION_ISSUE", f"{fac}: SR {sr_no} - {len(sls)} item line(s) issued in one go" + (f" · Section {section}" if section else ""))
    return len(sls)


@tx
def _ri_set_unit_db(fac, sl, name, old, new):
    run("UPDATE inventory SET unit_name=%s WHERE sl_no=%s AND factory_name=%s", (new, sl, fac))
    audit("EDIT_UOM", f"{fac}: {name}: UOM {old} -> {new} (Requisition Issue)")
    return True


def _unit_of(fac, sl):
    try:
        r = q("SELECT COALESCE(NULLIF(TRIM(unit_name),''),'Pcs') AS u FROM inventory WHERE factory_name=%s AND sl_no=%s", (fac, int(sl)))
        return r[0]["u"] if r else "Pcs"
    except Exception:
        return "Pcs"


def _ri_uom_changed(fac, sl, key, name, lines_key="ri_lines"):
    """Instant, final UOM edit: the moment the unit is changed in the slip it is saved on the item itself."""
    new = st.session_state.get(key)
    lines = st.session_state.get(lines_key, [])
    ln = next((x for x in lines if int(x["sl"]) == int(sl)), None)
    old = (ln or {}).get("unit") or "Pcs"
    if not new or new == old:
        return
    if not guard():
        st.session_state[key] = old
        return
    if _ri_set_unit_db(fac, int(sl), name, old, new):
        if ln:
            ln["unit"] = new
        st.session_state["rr_msg" if lines_key == "rr_lines" else "ri_msg"] = ("ok", f"✅ UOM বদলে গেছে (চূড়ান্ত): {name} → {new}")
    else:
        st.session_state[key] = old


def _ri_section_names(fac):
    try:
        return [r["section_name"] for r in q_c("SELECT section_name FROM ri_sections WHERE factory_name=%s ORDER BY LOWER(section_name)", (fac,))]
    except Exception:
        return []


def _ri_section_pick(key, fac, current=""):
    """Officers only PICK from the list the Store Manager saved (nobody can type a new section here)."""
    NONE = "— Section বাছুন —"
    names = _ri_section_names(fac)
    if current and current not in names:
        names = names + [current]          # an old slip may carry a section that was later removed from the list
    if not names:
        st.warning("এই Unit-এর Section list এখনো সেট করা হয়নি — Store Manager আগে Section list সেভ করুন।")
        return ""
    opts = [NONE] + names
    pick = st.selectbox("🏭 Section (কোন section-এ গেল) *", opts, index=opts.index(current) if current in opts else 0, key=key + "_s")
    return "" if pick == NONE else pick


@tx
def ri_sections_add(facs, names):
    n = 0
    for f in facs:
        have = {x.lower() for x in _ri_section_names(f)}
        for nm in names:
            if nm.lower() not in have:
                run("INSERT INTO ri_sections (factory_name, section_name) VALUES (%s,%s) ON CONFLICT DO NOTHING", (f, nm))
                have.add(nm.lower())
                n += 1
    audit("SECTION_LIST_ADD", f"{', '.join(facs)}: {', '.join(names)}")
    return n or True


@tx
def ri_sections_delete(fac, names):
    run("DELETE FROM ri_sections WHERE factory_name=%s AND section_name = ANY(%s)", (fac, list(names)))
    audit("SECTION_LIST_DELETE", f"{fac}: {', '.join(names)}")
    return True


def _ri_section_manager():
    """Store Manager only: write the factory's section list once; officers pick from it while issuing."""
    if st.session_state.get("role") != "Store Manager":
        return
    fac = FAC
    with _ri_exp(f"⚙️ Section list — {fac} (শুধু Store Manager)"):
        have = _ri_section_names(fac)
        st.caption("এই Unit-এর Section: " + (", ".join(have) if have else "এখনো কিছু নেই"))
        txt = st.text_area("নতুন Section লিখুন (প্রতি লাইনে একটি)", key="rism_txt", height=110, placeholder="Cutting\nSewing\nFinishing")
        all_f = st.checkbox("সব Factory-তে একই Section যোগ করুন", key="rism_all")
        if st.button("💾 Section list-এ যোগ করুন", key="rism_add") and guard():
            names = []
            for ln in txt.splitlines():
                nm = " ".join(ln.split())
                if nm and nm.lower() not in {x.lower() for x in names}:
                    names.append(nm)
            if not names:
                st.error("অন্তত একটি Section লিখুন।")
            elif ri_sections_add(list(FACTORIES) if all_f else [fac], names):
                st.session_state.pop("rism_txt", None)
                done(f"✅ Section list save hoyeche: {', '.join(names)}")
        if have:
            rm = st.multiselect("তালিকা থেকে বাদ দিন", have, key="rism_del",
                                help="আগের Issue-র data-তে Section-এর নাম যেমন আছে তেমনই থাকবে; শুধু নতুন Issue-র dropdown থেকে সরবে।")
            if rm and st.button("🗑 বাদ দিন", key="rism_delbtn") and guard():
                if ri_sections_delete(fac, rm):
                    done(f"✅ Section list theke bad deya hoyeche: {', '.join(rm)}")


@tx
def ri_set_section(fac, sr, section):
    run("UPDATE transactions SET section=%s WHERE factory_name=%s AND req_no=%s AND trans_type = ANY(%s)", (section, fac, sr, list(ISSUE_TYPES)))
    run("INSERT INTO ri_sections (factory_name, section_name) VALUES (%s,%s) ON CONFLICT DO NOTHING", (fac, section))
    audit("REQUISITION_ISSUE_SECTION", f"{fac}: SR {sr} -> Section {section}")
    return True


# ------------------------------------------------------------
#  PENDING ISSUE: a slip line with no stock is NOT saved as a transaction; it waits here until stock arrives
# ------------------------------------------------------------
def ensure_ri_pending_table():
    conn = get_conn()
    try:
        with conn.cursor() as cur:
            cur.execute("""CREATE TABLE IF NOT EXISTS ri_pending_issues (
                id SERIAL PRIMARY KEY, factory_name TEXT, sr_no TEXT, sl_no INTEGER, prod_id TEXT, item_name TEXT, size TEXT,
                unit TEXT, qty REAL, issued_qty REAL DEFAULT 0, rate REAL DEFAULT 0, section TEXT, issue_type TEXT, slip_date TEXT,
                notes TEXT, created_by TEXT, created_at TEXT, status TEXT DEFAULT 'Pending', closed_by TEXT, closed_at TEXT, close_note TEXT)""")
            cur.execute("ALTER TABLE ri_pending_issues ADD COLUMN IF NOT EXISTS machine_id INTEGER")
            cur.execute("CREATE INDEX IF NOT EXISTS idx_ri_pend_fac ON ri_pending_issues (factory_name, status)")
        conn.commit()
    except Exception:
        conn.rollback()
        raise


@tx
def ri_save_pending(fac, sr_no, tx_dt, ttype, section, notes, items):
    """items = [(sl_no, prod_id, name, size, unit, qty, rate, machine_id)]. No stock / transaction is touched - only the waiting list."""
    user = st.session_state.get("user", "")
    now_s = local_now().strftime("%d-%b-%Y %I:%M %p")
    for sl, pid, nm, size, unit, qty, rate, mid in items:
        ex = q("SELECT id FROM ri_pending_issues WHERE factory_name=%s AND sr_no=%s AND sl_no=%s AND status='Pending'", (fac, sr_no, int(sl)))
        if ex:
            run("UPDATE ri_pending_issues SET qty=qty+%s WHERE id=%s", (float(qty), ex[0]["id"]))
        else:
            run("""INSERT INTO ri_pending_issues (factory_name, sr_no, sl_no, prod_id, item_name, size, unit, qty, issued_qty, rate, section,
                   issue_type, slip_date, notes, created_by, created_at, status, machine_id)
                   VALUES (%s,%s,%s,%s,%s,%s,%s,%s,0,%s,%s,%s,%s,%s,%s,%s,'Pending',%s)""",
                (fac, sr_no, int(sl), pid, nm, size or "", unit or "Pcs", float(qty), float(rate or 0), section or "", ttype,
                 tx_dt.strftime(DATE_FMT), notes or "", user, now_s, int(mid) if mid else None))
    audit("RI_PENDING_ADD", f"{fac}: SR {sr_no} - no stock, kept pending (no transaction): "
                            + ", ".join(f"{i[1]} x {float(i[5]):g}" for i in items))
    return len(items)


@tx
def _ri_pending_mark(pid, qty, who_note):
    run("""UPDATE ri_pending_issues SET issued_qty=COALESCE(issued_qty,0)+%s,
           status=CASE WHEN COALESCE(issued_qty,0)+%s >= qty-0.000001 THEN 'Issued' ELSE 'Pending' END,
           closed_by=%s, closed_at=%s WHERE id=%s""",
        (float(qty), float(qty), st.session_state.get("user", ""), local_now().strftime("%d-%b-%Y %I:%M %p"), int(pid)))
    audit("RI_PENDING_ISSUED", f"Pending line {pid}: issued {float(qty):g} {who_note}")
    return True


@tx
def _ri_pending_cancel(pid, note, label):
    run("UPDATE ri_pending_issues SET status='Cancelled', closed_by=%s, closed_at=%s, close_note=%s WHERE id=%s",
        (st.session_state.get("user", ""), local_now().strftime("%d-%b-%Y %I:%M %p"), note, int(pid)))
    audit("RI_PENDING_CANCEL", f"Pending line {pid} cancelled: {label}. {note}")
    return True


def ri_issue_pending(row, qty, rate, verified, xfer=False, xconf=0.0):
    n = save_requisition_issue(row["factory_name"], [(int(row["sl_no"]), float(qty), bool(xfer), float(rate or 0), float(xconf or 0))], date.today(),
                               row["sr_no"], row["issue_type"] or "Issued",
                               f"[Pending issue theke - slip date {row['slip_date']}] {row['notes'] or ''}".strip(),
                               verified, False, row["section"] or "",
                               machine=({int(row["sl_no"]): int(row["machine_id"])} if row.get("machine_id") else None))
    if not n:
        return False
    return bool(_ri_pending_mark(row["id"], qty, f"of {row['prod_id']} (SR {row['sr_no']})"))


def _ri_pending_count(fac):
    try:
        r = q_c("SELECT COUNT(*) AS n FROM ri_pending_issues WHERE factory_name=%s AND status='Pending'", (fac,))
        return int(r[0]["n"]) if r else 0
    except Exception:
        return 0


