# ============================================================
#  REPORTS - read-only ERP report centre
#  Centralised Reports page (16 reports). Every report is built from the live database tables with parameterised,
#  read-only queries, shown as a formal A4 document, and exported as a real PDF (reportlab) and a real .xlsx (openpyxl)
#  from the very same document object - so print, PDF and Excel always match what is on the screen.
#  Nothing here writes to the database. The Hold Bill print / PDF (_hb_html / _hb_pdf) reuse the same renderers.
# ============================================================
NAV_REPORTS = "🧾 Reports"
if NAV_REPORTS not in TAB_NAMES:
    TAB_NAMES.insert(6, NAV_REPORTS)            # first item under "Management"; the six Workspace buttons stay as they were
REPORT_COMPANY = "Windy Group"                   # company / group name printed on every report (same name as the app logo)
RP_ALL_UNITS = "All Units (each unit shown separately)"
RP_NAMES = {"Supplier. Rec": "Supplier Receipt", "Issued": "Issue to Production", "Internal Rec": "Internal Receipt (from other unit)",
            "Internal Issue": "Internal Issue (to other unit)", "Stock Adjustment (+)": "Stock Adjustment (+)",
            "Stock Adjustment (-)": "Stock Adjustment (-)", "Opening Balance": "Opening Balance / Stock Set"}
RP_NUMK = ("i", "q", "r", "a", "p")


class _RpSub(list):
    """A sub-total row inside a report table (bold, shaded). cells[0] is the label and spans the empty cells after it."""


def _rp_span(cells):
    k = 1
    while k < len(cells) and cells[k] is None:
        k += 1
    return k


def _rp_blank(v):
    return v is None or (isinstance(v, float) and math.isnan(v))


def _rp_fmt(v, kind):
    if _rp_blank(v):
        return ""
    if kind == "t":
        return str(v)
    if kind == "d":
        d = parse_date(v)
        return d.strftime(DATE_FMT) if d else str(v)
    try:
        x = float(v)
    except (TypeError, ValueError):
        return str(v)
    if kind == "i":
        return f"{x:,.0f}"
    if kind == "q":
        return f"{x:,.0f}" if abs(x - round(x)) < 1e-9 else f"{x:,.3f}".rstrip("0").rstrip(".")
    if kind == "p":
        return f"{x:,.1f}%"
    return f"{x:,.2f}"


def _rp_pdftxt(s):
    """Text for the PDF: the built-in PDF font cannot draw Bangla letters, so they show as [Bangla] (same as the existing PDFs)."""
    t = "" if s is None else str(s)
    t = re.sub(r"[\u0980-\u09FF]+", "[Bangla]", t)
    return html_lib.escape(t.encode("cp1252", "replace").decode("cp1252"))


def _rp_doc(title, rtype, units, period, filters, orient, blocks, notes=None):
    rows = sum(1 for b in blocks for s in b["sections"] for r in s["rows"] if not isinstance(r, _RpSub))
    return {"title": title, "type": rtype, "company": REPORT_COMPANY, "units": list(units), "period": period,
            "filters": list(filters), "orient": orient, "blocks": blocks, "notes": list(notes or []),
            "generated": local_now().strftime("%d-%b-%Y %I:%M %p"), "rows": rows}


def _rp_filters_text(doc):
    return "; ".join(f"{k}: {v}" for k, v in doc["filters"]) or "None (all records)"


_RP_KPI_CSS = (".kpi{display:flex;gap:8px;margin:8px 0 12px}.kpi>div{flex:1;border:1px solid #1F3A5F;border-left:5px solid #F59E0B;border-radius:6px;padding:6px 9px;background:#F7F9FC;break-inside:avoid}"
               ".kpi .l{font-size:8.5px;text-transform:uppercase;letter-spacing:.04em;color:#475569;font-weight:700}.kpi .v{font-size:18px;font-weight:800;color:#0B1F3A;margin-top:2px}"
               ".kpi .s{font-size:8.5px;color:#555;margin-top:1px}")


# ---------------------------------------------------------------- HTML (preview + print)
def _rp_html(doc, button=True):
    e = html_lib.escape
    land = doc["orient"] == "L"
    units = " | ".join(doc["units"])
    run = f"{doc['company']}  ·  Unit: {units}  ·  {doc['title']}  ·  {doc['period']}"
    foot = re.sub(r'["\\\n]', " ", f"{doc['company']} - {units} - {doc['title']}")
    css = f"""@page{{size:A4 {'landscape' if land else 'portrait'};margin:9mm 9mm 13mm 9mm;
@bottom-right{{content:"Page " counter(page) " of " counter(pages);font:8px Arial,sans-serif;color:#444}}
@bottom-left{{content:"{foot}";font:8px Arial,sans-serif;color:#444}}}}
*{{box-sizing:border-box}}body{{margin:0;background:#E9EDF2;font-family:'Segoe UI','Noto Sans Bengali','Nirmala UI',Arial,sans-serif;color:#111;font-size:{'10.5' if land else '11'}px}}
.bar{{position:sticky;top:0;z-index:5;background:#0B1F3A;color:#fff;padding:8px 14px;display:flex;gap:12px;align-items:center;font-size:12px}}
.bar button{{background:#F59E0B;border:0;border-radius:6px;padding:7px 16px;font-weight:700;cursor:pointer;font-size:13px}}
.paper{{width:{'297' if land else '210'}mm;max-width:100%;margin:12px auto;background:#fff;padding:9mm;box-shadow:0 1px 8px rgba(0,0,0,.25)}}
table.frame{{width:100%;border-collapse:collapse}}table.frame>thead{{display:table-header-group}}table.frame>tbody>tr>td,table.frame>thead>tr>td{{padding:0;border:0}}
.run{{font-size:8.5px;color:#555;border-bottom:1px solid #999;padding-bottom:3px;margin-bottom:6px}}
h1{{text-align:center;margin:0 0 2px;font-size:19px;letter-spacing:.3px}}.co{{text-align:center;font-weight:700;font-size:13px;margin-bottom:6px}}
table.meta{{width:100%;border-collapse:collapse;margin:6px 0 10px}}table.meta td{{border:1px solid #777;padding:3px 6px;vertical-align:top}}
table.meta td.k{{background:#EEF2F7;font-weight:700;width:17%}}
.ub{{background:#0B1F3A;color:#fff;font-weight:700;padding:5px 8px;margin:12px 0 6px;font-size:12.5px}}.ub.brk{{break-before:page}}
.sh{{font-weight:700;font-size:12.5px;margin:12px 0 2px;border-bottom:2px solid #0B1F3A;padding-bottom:2px;break-after:avoid}}
.ss{{color:#333;margin:0 0 4px;break-after:avoid}}.note{{color:#444;font-size:9px;margin:3px 0 4px}}.none{{color:#777;font-style:italic;margin:6px 0}}
table.rt{{width:100%;border-collapse:collapse;margin:3px 0 4px}}table.rt thead{{display:table-header-group}}
table.rt th{{background:#1F3A5F;color:#fff;border:1px solid #444;padding:3px 4px;text-align:left;vertical-align:middle}}
table.rt td{{border:1px solid #666;padding:2.5px 4px;vertical-align:top;word-break:break-word}}table.rt tr{{break-inside:avoid}}
table.rt tbody tr:nth-child(even) td{{background:#F7F9FC}}td.r,th.r{{text-align:right;white-space:nowrap}}td.c,th.c{{text-align:center;white-space:nowrap}}
tr.sub td{{background:#E9EFF7!important;font-weight:700}}tr.tot td{{background:#D5DFEC!important;font-weight:700;border-top:2px solid #111}}
table.sig{{width:100%;border-collapse:collapse;margin-top:18px;break-inside:avoid}}table.sig td{{border:1px solid #777;padding:3px 6px;height:42px;vertical-align:top;font-weight:700}}
.gen{{font-size:8.5px;color:#555;margin-top:6px}}
@media print{{body{{background:#fff}}.noprint{{display:none!important}}.paper{{width:auto;max-width:none;margin:0;padding:0;box-shadow:none}}}}"""
    css += _RP_KPI_CSS
    h = [f"<!doctype html><html><head><meta charset='utf-8'><title>{e(doc['title'])}</title><style>{css}</style></head><body>"]
    if button:
        h.append("<div class='bar noprint'><button onclick='window.print()'>🖨 Print Report</button>"
                 f"<span>A4 {'landscape' if land else 'portrait'} · only this report is printed (menu, filters and buttons are left out)</span></div>")
    h.append(f"<div class='paper'><table class='frame'><thead><tr><td><div class='run'>{e(run)}</div></td></tr></thead><tbody><tr><td>")
    h.append(f"<div class='co'>{e(doc['company'])}</div><h1>{e(doc['title'].upper())}</h1>")
    meta = [("Company", doc["company"]), ("Unit / Factory", units), ("Report Title", doc["title"]), ("Report Type", doc["type"]),
            ("Reporting Period", doc["period"]), ("Generated On", doc["generated"]), ("Filters", _rp_filters_text(doc))]
    h.append("<table class='meta'>")
    for i in range(0, len(meta) - 1, 2):
        h.append(f"<tr><td class='k'>{e(meta[i][0])}</td><td>{e(meta[i][1])}</td><td class='k'>{e(meta[i + 1][0])}</td><td>{e(meta[i + 1][1])}</td></tr>")
    h.append(f"<tr><td class='k'>{e(meta[-1][0])}</td><td colspan='3'>{e(meta[-1][1])}</td></tr></table>")
    if doc.get("kpis"):
        h.append("<div class='kpi'>" + "".join(f"<div><div class='l'>{e(k[1])}</div><div class='v'>{e(k[2])}</div><div class='s'>{e(k[3])}</div></div>" for k in doc["kpis"]) + "</div>")
    for bi, b in enumerate(doc["blocks"]):
        h.append(f"<div class='ub{' brk' if bi else ''}'>UNIT / FACTORY: {e(b['unit'])}</div>")
        if not any(s["rows"] for s in b["sections"]):
            h.append("<div class='none'>No records found for this unit with the selected dates and filters.</div>")
            continue
        for s in b["sections"]:
            if s.get("heading"):
                h.append(f"<div class='sh'>{e(s['heading'])}</div>")
            if s.get("sub"):
                h.append(f"<div class='ss'>{e(s['sub'])}</div>")
            if not s["rows"]:
                h.append(f"<div class='none'>{e(s.get('empty') or 'No records.')}</div>")
                continue
            cols = s["cols"]
            al = ["r" if k in RP_NUMK else ("c" if k == "d" else "") for _, k in cols]
            h.append("<table class='rt'><thead><tr>" + "".join(f"<th class='{a}'>{e(n)}</th>" for (n, _), a in zip(cols, al)) + "</tr></thead><tbody>")
            body = list(s["rows"]) + ([("TOT", s["total"])] if s.get("total") else [])
            for r in body:
                cls, cells = ("tot", r[1]) if isinstance(r, tuple) else (("sub", r) if isinstance(r, _RpSub) else ("", r))
                if cls:
                    k = _rp_span(cells)
                    tds = f"<td colspan='{k}'>{e(_rp_fmt(cells[0], 't'))}</td>" + "".join(
                        f"<td class='{al[j]}'>{e(_rp_fmt(cells[j], cols[j][1]))}</td>" for j in range(k, len(cols)))
                else:
                    tds = "".join(f"<td class='{al[j]}'>{e(_rp_fmt(cells[j], cols[j][1]))}</td>" for j in range(len(cols)))
                h.append(f"<tr class='{cls}'>{tds}</tr>")
            h.append("</tbody></table>")
            if s.get("note"):
                h.append(f"<div class='note'>{e(s['note'])}</div>")
    for n in doc["notes"]:
        h.append(f"<div class='note'>{e(n)}</div>")
    h.append("<table class='sig'><tr><td>Prepared by (Store)</td><td>Checked by</td><td>Approved by</td></tr></table>")
    h.append(f"<div class='gen'>Generated {e(doc['generated'])} · KC &amp; Windy Smart Inventory</div>")
    h.append("</td></tr></tbody></table></div></body></html>")
    return "".join(h)


# ---------------------------------------------------------------- PDF (real, selectable text, A4)
_RP_PDF_FONTS = {}


def _rp_pdf_fonts():
    """(regular, bold, size factor) of a font that is EMBEDDED in the PDF. The built-in Helvetica is not embedded, so some PDF readers
    replace it with another font and the letters get wrong gaps. Liberation Sans (same widths as Arial) -> DejaVu Sans -> Vera (ships with reportlab)."""
    if "v" in _RP_PDF_FONTS:
        return _RP_PDF_FONTS["v"]
    res = ("Helvetica", "Helvetica-Bold", 1.0)
    try:
        import os
        import reportlab
        from reportlab.pdfbase import pdfmetrics
        from reportlab.pdfbase.ttfonts import TTFont
        vd = os.path.join(os.path.dirname(reportlab.__file__), "fonts")
        for name, reg, bd, sc in (("RPLiberation", "/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf", "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf", 1.0),
                                  ("RPDejaVu", "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", 0.92),
                                  ("RPVera", os.path.join(vd, "Vera.ttf"), os.path.join(vd, "VeraBd.ttf"), 0.93)):
            try:
                if os.path.exists(reg) and os.path.exists(bd):
                    pdfmetrics.registerFont(TTFont(name, reg))
                    pdfmetrics.registerFont(TTFont(name + "-B", bd))
                    pdfmetrics.registerFontFamily(name, normal=name, bold=name + "-B", italic=name, boldItalic=name + "-B")
                    res = (name, name + "-B", sc)
                    break
            except Exception:
                continue
    except Exception:
        pass
    _RP_PDF_FONTS["v"] = res
    return res


def _rp_pdf(doc):
    try:
        from reportlab.lib import colors
        from reportlab.lib.enums import TA_CENTER, TA_RIGHT
        from reportlab.lib.pagesizes import A4, landscape
        from reportlab.lib.styles import ParagraphStyle
        from reportlab.pdfgen import canvas as _cv
        from reportlab.platypus import CondPageBreak, PageBreak, Paragraph, SimpleDocTemplate, Spacer, Table, TableStyle
    except ImportError:
        return None
    FN, FB, FSC = _rp_pdf_fonts()
    land = doc["orient"] == "L"
    ps = landscape(A4) if land else A4
    lm = rm = 26
    avail = ps[0] - lm - rm
    fs = (8.2 if "REPAIR & RETURNS" in str(doc.get("title", "")).upper() else (7.3 if land else 7.8)) * FSC
    base = ParagraphStyle("b", fontName=FN, fontSize=fs, leading=fs + 2.4)
    bold = ParagraphStyle("bb", parent=base, fontName=FB)
    hdr = ParagraphStyle("h", parent=bold, textColor=colors.white)
    rgt, ctr = ParagraphStyle("r", parent=base, alignment=TA_RIGHT), ParagraphStyle("c", parent=base, alignment=TA_CENTER)
    rgtb = ParagraphStyle("rb", parent=rgt, fontName=FB)
    P = lambda t, s=base: Paragraph(_rp_pdftxt(t), s)
    units = " | ".join(doc["units"])
    story = [Paragraph(_rp_pdftxt(doc["company"]), ParagraphStyle("co", parent=bold, fontSize=11, alignment=TA_CENTER, spaceAfter=2)),
             Paragraph(_rp_pdftxt(doc["title"].upper()), ParagraphStyle("t", fontName=FB, fontSize=15, leading=18, alignment=TA_CENTER, spaceAfter=6))]
    meta = [("Company", doc["company"]), ("Unit / Factory", units), ("Report Title", doc["title"]), ("Report Type", doc["type"]),
            ("Reporting Period", doc["period"]), ("Generated On", doc["generated"])]
    kw = avail * 0.14
    vw = (avail - 2 * kw) / 2
    mrows = [[P(meta[i][0], bold), P(meta[i][1]), P(meta[i + 1][0], bold), P(meta[i + 1][1])] for i in range(0, 6, 2)]
    mrows.append([P("Filters", bold), P(_rp_filters_text(doc)), "", ""])
    mt = Table(mrows, colWidths=[kw, vw, kw, vw])
    mt.setStyle(TableStyle([("GRID", (0, 0), (-1, -1), 0.4, colors.grey), ("BACKGROUND", (0, 0), (0, -1), colors.HexColor("#EEF2F7")),
                            ("BACKGROUND", (2, 0), (2, -2), colors.HexColor("#EEF2F7")), ("SPAN", (1, -1), (3, -1)), ("VALIGN", (0, 0), (-1, -1), "TOP")]))
    story += [mt, Spacer(1, 6)]
    if doc.get("kpis"):
        _tone = {"blue": "#1D4ED8", "amber": "#F59E0B", "red": "#DC2626", "green": "#16A34A", "slate": "#64748B", "teal": "#0F766E"}
        kn = len(doc["kpis"])
        kc = [[Paragraph(f"<font size='6.6' color='#475569'><b>{_rp_pdftxt(k[1]).upper()}</b></font><br/>"
                         f"<font size='15' color='#0B1F3A'><b>{_rp_pdftxt(k[2])}</b></font><br/>"
                         f"<font size='6.6' color='#555555'>{_rp_pdftxt(k[3])}</font>", ParagraphStyle("kp", parent=base, leading=15)) for k in doc["kpis"]]]
        kt = Table(kc, colWidths=[avail / kn] * kn)
        kst = [("BOX", (0, 0), (-1, -1), 0.4, colors.grey), ("INNERGRID", (0, 0), (-1, -1), 0.4, colors.HexColor("#D5DFEC")),
               ("BACKGROUND", (0, 0), (-1, -1), colors.HexColor("#F7F9FC")), ("VALIGN", (0, 0), (-1, -1), "TOP"),
               ("TOPPADDING", (0, 0), (-1, -1), 4), ("BOTTOMPADDING", (0, 0), (-1, -1), 4)]
        for j, k in enumerate(doc["kpis"]):
            kst.append(("LINEBEFORE", (j, 0), (j, 0), 3, colors.HexColor(_tone.get(k[4], "#1D4ED8"))))
        kt.setStyle(TableStyle(kst))
        story += [kt, Spacer(1, 6)]
    ub = ParagraphStyle("ub", parent=bold, textColor=colors.white, backColor=colors.HexColor("#0B1F3A"), borderPadding=(3, 4, 3, 4), spaceBefore=6, spaceAfter=6, fontSize=fs + 2)
    sh = ParagraphStyle("sh", parent=bold, fontSize=fs + 2.6, spaceBefore=14, spaceAfter=3, keepWithNext=0, textColor=colors.HexColor("#0B1F3A"))
    ss = ParagraphStyle("ss", parent=base, spaceAfter=5, keepWithNext=0, textColor=colors.HexColor("#334155"))
    for bi, b in enumerate(doc["blocks"]):
        if bi:
            story.append(PageBreak())
        story.append(Paragraph(_rp_pdftxt(f"UNIT / FACTORY: {b['unit']}"), ub))
        if not any(s["rows"] for s in b["sections"]):
            story.append(P("No records found for this unit with the selected dates and filters."))
            continue
        for s in b["sections"]:
            if s.get("heading"):
                story.append(CondPageBreak(110))
                story.append(Paragraph(_rp_pdftxt(s["heading"]), sh))
            if s.get("sub"):
                story.append(Paragraph(_rp_pdftxt(s["sub"]), ss))
            if not s["rows"]:
                story.append(P(s.get("empty") or "No records."))
                continue
            cols = s["cols"]
            body = list(s["rows"]) + ([("TOT", s["total"])] if s.get("total") else [])
            wts = []
            for j, (n, k) in enumerate(cols):
                mx = 0
                for r in body[:250]:
                    cells = r[1] if isinstance(r, tuple) else r
                    if isinstance(r, (tuple, _RpSub)) and j < _rp_span(cells):
                        continue
                    mx = max(mx, len(_rp_fmt(cells[j], k)))
                hw = max((len(w) for w in n.split()), default=3) * 1.2 + 2
                w = max(mx + 2, hw, 5)
                if k == "d":
                    w = max(w, 12.5)
                wts.append(min(w, 34) if k == "t" else min(w, 16))
            tot = sum(wts)
            widths = [avail * w / tot for w in wts]
            data = [[Paragraph(_rp_pdftxt(n), hdr) for n, _ in cols]]
            style = [("INNERGRID", (0, 0), (-1, -1), 0.35, colors.HexColor("#CBD5E1")), ("BOX", (0, 0), (-1, -1), 0.8, colors.HexColor("#1F3A5F")),
                     ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#1F3A5F")),
                     ("VALIGN", (0, 0), (-1, -1), "MIDDLE"), ("LEFTPADDING", (0, 0), (-1, -1), 4), ("RIGHTPADDING", (0, 0), (-1, -1), 4),
                     ("TOPPADDING", (0, 0), (-1, -1), 3.2), ("BOTTOMPADDING", (0, 0), (-1, -1), 3.2)]
            for ri, r in enumerate(body, start=1):
                special = isinstance(r, (tuple, _RpSub))
                cells = r[1] if isinstance(r, tuple) else r
                if special:
                    k0 = _rp_span(cells)
                    row = [Paragraph(_rp_pdftxt(_rp_fmt(cells[0], "t")), bold)] + [""] * (k0 - 1)
                    row += [Paragraph(_rp_pdftxt(_rp_fmt(cells[j], cols[j][1])), rgtb if cols[j][1] in RP_NUMK else bold) for j in range(k0, len(cols))]
                    if k0 > 1:
                        style.append(("SPAN", (0, ri), (k0 - 1, ri)))
                    style.append(("BACKGROUND", (0, ri), (-1, ri), colors.HexColor("#D5DFEC" if isinstance(r, tuple) else "#E9EFF7")))
                    if isinstance(r, tuple):
                        style.append(("LINEABOVE", (0, ri), (-1, ri), 1.2, colors.black))
                else:
                    row = [Paragraph(_rp_pdftxt(_rp_fmt(cells[j], cols[j][1])), rgt if cols[j][1] in RP_NUMK else (ctr if cols[j][1] == "d" else base))
                           for j in range(len(cols))]
                    if ri % 2 == 0:
                        style.append(("BACKGROUND", (0, ri), (-1, ri), colors.HexColor("#F7F9FC")))
                    for j_, c_ in enumerate(cells):
                        if isinstance(c_, str) and c_.startswith("OVERDUE"):
                            row[j_] = Paragraph(_rp_pdftxt(c_), ParagraphStyle("od", parent=bold, textColor=colors.HexColor("#991B1B")))
                            style.append(("BACKGROUND", (j_, ri), (j_, ri), colors.HexColor("#FBD5D5")))
                        elif isinstance(c_, str) and c_.startswith("Follow up"):
                            row[j_] = Paragraph(_rp_pdftxt(c_), ParagraphStyle("fu", parent=bold, textColor=colors.HexColor("#92400E")))
                            style.append(("BACKGROUND", (j_, ri), (j_, ri), colors.HexColor("#FDECC0")))
                data.append(row)
            t = Table(data, colWidths=widths, repeatRows=1)
            t.setStyle(TableStyle(style))
            story += [t]
            if s.get("note"):
                story.append(Paragraph(_rp_pdftxt(s["note"]), ParagraphStyle("nt", parent=base, fontSize=fs - 0.8, textColor=colors.HexColor("#444444"), spaceBefore=3)))
            story.append(Spacer(1, 8))
    for n in doc["notes"]:
        story.append(Paragraph(_rp_pdftxt(n), ParagraphStyle("nt2", parent=base, fontSize=fs - 0.6, textColor=colors.HexColor("#444444"), spaceBefore=2)))
    sw = avail / 3
    sig = Table([[P("Prepared by (Store)", bold), P("Checked by", bold), P("Approved by", bold)], ["", "", ""]], colWidths=[sw] * 3, rowHeights=[14, 34])
    sig.setStyle(TableStyle([("BOX", (0, 0), (-1, -1), 0.4, colors.grey), ("INNERGRID", (0, 0), (-1, -1), 0.4, colors.grey)]))
    story += [Spacer(1, 12), sig]

    top = lambda s: re.sub(r"[\u0980-\u09FF]+", "[Bangla]", str(s)).encode("cp1252", "replace").decode("cp1252")
    head_line = top(f"{doc['company']}  |  Unit: {units}  |  {doc['title']}  |  {doc['period']}")
    foot_line = top(f"Generated {doc['generated']}  |  KC & Windy Smart Inventory")

    class _NC(_cv.Canvas):
        def __init__(self, *a, **k):
            super().__init__(*a, **k)
            self._pages = []

        def showPage(self):
            self._pages.append(dict(self.__dict__))
            self._startPage()

        def save(self):
            n = len(self._pages)
            for pg in self._pages:
                self.__dict__.update(pg)
                self.setFont(FN, 7)
                self.setFillGray(0.3)
                self.drawString(lm, ps[1] - 16, head_line[:200])
                self.setLineWidth(0.4)
                self.line(lm, ps[1] - 19, ps[0] - rm, ps[1] - 19)
                self.line(lm, 24, ps[0] - rm, 24)
                self.drawString(lm, 15, foot_line)
                self.drawRightString(ps[0] - rm, 15, f"Page {self._pageNumber} of {n}")
                super().showPage()
            super().save()

    buf = io.BytesIO()
    SimpleDocTemplate(buf, pagesize=ps, leftMargin=lm, rightMargin=rm, topMargin=30, bottomMargin=32, title=doc["title"], author="KC & Windy Smart Inventory"
                      ).build(story, canvasmaker=_NC)
    return buf.getvalue()


# ---------------------------------------------------------------- Excel (real cells)
def _rp_xlsx(doc):
    try:
        from openpyxl import Workbook
        from openpyxl.styles import Alignment, Border, Font, PatternFill, Side
        from openpyxl.utils import get_column_letter
    except ImportError:
        return None
    wb = Workbook()
    ws = wb.active
    ws.title = "Report"
    thin = Side(style="thin", color="888888")
    box = Border(left=thin, right=thin, top=thin, bottom=thin)
    navy, sub_f, tot_f = PatternFill("solid", fgColor="1F3A5F"), PatternFill("solid", fgColor="E9EFF7"), PatternFill("solid", fgColor="D5DFEC")
    units = " | ".join(doc["units"])
    info = [(doc["company"], Font(bold=True, size=14)), (doc["title"].upper(), Font(bold=True, size=13)), (f"Report Type: {doc['type']}", Font(bold=True)),
            (f"Unit / Factory: {units}", Font(bold=True)), (f"Reporting Period: {doc['period']}", Font()), (f"Filters: {_rp_filters_text(doc)}", Font()),
            (f"Generated On: {doc['generated']}", Font())]
    r = 1
    for txt, f in info:
        ws.cell(r, 1, txt).font = f
        r += 1
    r += 1
    widths = {}
    first_hdr = None
    maxcols = max([len(s["cols"]) for b in doc["blocks"] for s in b["sections"]] or [1])
    for b in doc["blocks"]:
        c = ws.cell(r, 1, f"UNIT / FACTORY: {b['unit']}")
        c.font, c.fill = Font(bold=True, color="FFFFFF"), PatternFill("solid", fgColor="0B1F3A")
        for j in range(2, maxcols + 1):
            ws.cell(r, j).fill = PatternFill("solid", fgColor="0B1F3A")
        r += 1
        if not any(s["rows"] for s in b["sections"]):
            ws.cell(r, 1, "No records found for this unit with the selected dates and filters.").font = Font(italic=True)
            r += 2
            continue
        for s in b["sections"]:
            if not s["rows"]:
                continue
            if s.get("heading"):
                ws.cell(r, 1, s["heading"]).font = Font(bold=True, size=12)
                r += 1
            if s.get("sub"):
                ws.cell(r, 1, s["sub"])
                r += 1
            cols = s["cols"]
            for j, (n, k) in enumerate(cols, start=1):
                c = ws.cell(r, j, n)
                c.font, c.fill, c.border = Font(bold=True, color="FFFFFF"), navy, box
                c.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
                widths[j] = max(widths.get(j, 0), min(max((len(w) for w in n.split()), default=4) + 2, 20))
            if first_hdr is None:
                first_hdr = r
            r += 1
            body = list(s["rows"]) + ([("TOT", s["total"])] if s.get("total") else [])
            for row in body:
                special = isinstance(row, (tuple, _RpSub))
                cells = row[1] if isinstance(row, tuple) else row
                k0 = _rp_span(cells) if special else 0
                for j, (n, k) in enumerate(cols, start=1):
                    v = cells[j - 1]
                    if special and j <= k0 and j > 1:
                        ws.cell(r, j).border = box
                        continue
                    if _rp_blank(v):
                        v = None
                    elif k == "d":
                        d = parse_date(v)
                        v = d if d else str(v)
                    elif k in RP_NUMK:
                        try:
                            v = float(v)
                        except (TypeError, ValueError):
                            v = str(v)
                    else:
                        v = str(v)
                    c = ws.cell(r, j, v)
                    c.border = box
                    if isinstance(v, float):
                        c.number_format = ("0.0\"%\"" if k == "p" else ("#,##0" if (k == "i" or (k == "q" and abs(v - round(v)) < 1e-9)) else "#,##0.00"))
                        c.alignment = Alignment(horizontal="right", vertical="top")
                    elif k == "d" and not isinstance(v, str):
                        c.number_format = "DD-MMM-YYYY"
                        c.alignment = Alignment(horizontal="center", vertical="top")
                    else:
                        c.alignment = Alignment(vertical="top", wrap_text=(k == "t"))
                    if special:
                        c.font, c.fill = Font(bold=True), (tot_f if isinstance(row, tuple) else sub_f)
                    shown = len(str(v)) if isinstance(v, str) else 12
                    if not (special and j <= k0):
                        widths[j] = max(widths.get(j, 0), min(shown + 2, 46))
                if special and k0 > 1:
                    ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=k0)
                r += 1
            if s.get("note"):
                ws.cell(r, 1, s["note"]).font = Font(italic=True, size=9)
                r += 1
            r += 1
        r += 1
    for n in doc["notes"]:
        ws.cell(r, 1, n).font = Font(italic=True, size=9)
        r += 1
    for j, w in widths.items():
        ws.column_dimensions[get_column_letter(j)].width = max(w, 7)
    ws.page_setup.paperSize = ws.PAPERSIZE_A4
    ws.page_setup.orientation = "landscape" if doc["orient"] == "L" else "portrait"
    ws.page_setup.fitToWidth, ws.page_setup.fitToHeight = 1, 0
    ws.sheet_properties.pageSetUpPr.fitToPage = True
    ws.page_margins.left = ws.page_margins.right = 0.35
    ws.oddHeader.center.text = f"{doc['company']} - {units} - {doc['title']}"
    ws.oddFooter.left.text = f"Generated {doc['generated']}"
    ws.oddFooter.right.text = "Page &P of &N"
    if first_hdr:
        ws.print_title_rows = f"{first_hdr}:{first_hdr}"
    buf = io.BytesIO()
    wb.save(buf)
    return buf.getvalue()


# ---------------------------------------------------------------- data helpers (all read-only, parameterised)
def _rpn(df, *cols):
    for c in cols:
        df[c] = pd.to_numeric(df[c], errors="coerce").fillna(0.0)
    return df


def _rp_uom_note(d, qcol, ucol="uom"):
    g = d.groupby(ucol)[qcol].sum()
    return "Quantity by UOM: " + "; ".join(f"{u}: {_rp_fmt(v, 'q')}" for u, v in g.items())


def _rp_qty_tot(d, qcol, ucol="uom"):
    """Quantities of different UOMs (Pcs, Kg ...) are never added together: a total is shown only when one UOM is present."""
    return float(d[qcol].sum()) if d[ucol].nunique() <= 1 else None


def _rp_inv_where(P, a=""):
    s, p = "", []
    if P.get("bcat"):
        s += f" AND {a}category=%s"
        p.append(P["bcat"])
    if P.get("pcat"):
        s += f" AND COALESCE({a}product_category,'')=%s"
        p.append(P["pcat"])
    if P.get("item"):
        s += f" AND ({a}item_name ILIKE %s OR COALESCE({a}prod_id,'') ILIKE %s)"
        p += [f"%{P['item']}%"] * 2
    return s, p


def _rp_sec(cols, rows, total=None, heading=None, sub=None, note=None, empty=None):
    return {"heading": heading, "sub": sub, "cols": cols, "rows": rows, "total": total, "note": note, "empty": empty}


def _rp_blocks(P, build):
    return [{"unit": u, "sections": build(u)} for u in P["units"]]


def _rp_stock_df(P):
    isql, ip = _rp_inv_where(P)
    st_sql = ""
    if P.get("status") == "In stock (quantity above zero)":
        st_sql = " AND COALESCE(current_stock,0)>0"
    elif P.get("status") == "Zero or negative stock":
        st_sql = " AND COALESCE(current_stock,0)<=0"
    df = qdf(f"""SELECT factory_name, sl_no, COALESCE(prod_id,'') AS code, item_name, COALESCE(size,'') AS size,
                        COALESCE(NULLIF(TRIM(category),''),'(No budget category)') AS bcat,
                        COALESCE(NULLIF(TRIM(product_category),''),'(No product category)') AS pcat,
                        COALESCE(NULLIF(unit_name,''),'Pcs') AS uom, COALESCE(current_stock,0) AS stock, COALESCE(erp_stock,0) AS erp,
                        COALESCE(unit_price,0) AS price, COALESCE(min_stock,0) AS min_stock, COALESCE(preferred_supplier,'') AS pref_sup
                 FROM inventory WHERE factory_name = ANY(%s){isql}{st_sql} ORDER BY factory_name, sl_no""", tuple([P["units"]] + ip))
    return _rpn(df, "stock", "erp", "price", "min_stock")


def _rp_norate_note(d):
    n = int((d["price"] <= 0).sum())
    return f"{n} item(s) have no stock rate recorded; their value is not shown and is not included in the totals." if n else None


def rp_current_stock(P):
    df = _rp_stock_df(P)
    cols = [("SL", "i"), ("Item Code", "t"), ("Item Name", "t"), ("Size", "t"), ("Product Category", "t"), ("UOM", "t"),
            ("Stock Qty", "q"), ("Stock Rate (Tk)", "r"), ("Stock Value (Tk)", "a")]

    def build(u):
        d = df[df["factory_name"] == u]
        if d.empty:
            return []
        rows, n = [], 0
        for pc, g in d.sort_values(["pcat", "sl_no"]).groupby("pcat", sort=True):
            for r in g.itertuples():
                n += 1
                hv = r.price > 0
                rows.append([n, r.code, r.item_name, r.size, pc, r.uom, r.stock, r.price if hv else None, r.stock * r.price if hv else None])
            rows.append(_RpSub([f"Sub-total: {pc} ({len(g)} items)", None, None, None, None, None, _rp_qty_tot(g, "stock"), None,
                                float((g["stock"] * g["price"]).where(g["price"] > 0, 0).sum())]))
        tot = [f"TOTAL - {u} ({len(d)} items)", None, None, None, None, None, _rp_qty_tot(d, "stock"), None,
               float((d["stock"] * d["price"]).where(d["price"] > 0, 0).sum())]
        notes = [x for x in (_rp_uom_note(d, "stock") if d["uom"].nunique() > 1 else None, _rp_norate_note(d)) if x]
        return [_rp_sec(cols, rows, tot, note=" ".join(notes) or None)]
    return _rp_blocks(P, build), []


def rp_stock_qty_value(P):
    df = _rp_stock_df(P)
    cols = [("SL", "i"), ("Item Code", "t"), ("Item Name", "t"), ("Size", "t"), ("UOM", "t"), ("Rate (Tk)", "r"), ("ERP Qty", "q"),
            ("Physical Qty", "q"), ("Variance", "q"), ("ERP Value (Tk)", "a"), ("Physical Value (Tk)", "a"), ("Status", "t")]

    def vsum(g, col):
        return float((g[col] * g["price"]).where(g["price"] > 0, 0).sum())

    def build(u):
        d = df[df["factory_name"] == u]
        if d.empty:
            return []
        rows, n = [], 0
        for bc, g in d.sort_values(["bcat", "sl_no"]).groupby("bcat", sort=True):
            for r in g.itertuples():
                n += 1
                var = r.stock - r.erp
                hv = r.price > 0
                rows.append([n, r.code, r.item_name, r.size, r.uom, r.price if hv else None, r.erp, r.stock, var,
                             r.erp * r.price if hv else None, r.stock * r.price if hv else None,
                             "Match" if abs(var) < 1e-9 else ("Excess" if var > 0 else "Shortage")])
            one = g["uom"].nunique() <= 1
            rows.append(_RpSub([f"Sub-total: {bc} ({len(g)} items)", None, None, None, None, None, float(g["erp"].sum()) if one else None,
                                float(g["stock"].sum()) if one else None, float((g["stock"] - g["erp"]).sum()) if one else None,
                                vsum(g, "erp"), vsum(g, "stock"), None]))
        one = d["uom"].nunique() <= 1
        tot = [f"TOTAL - {u} ({len(d)} items)", None, None, None, None, None, float(d["erp"].sum()) if one else None,
               float(d["stock"].sum()) if one else None, float((d["stock"] - d["erp"]).sum()) if one else None,
               vsum(d, "erp"), vsum(d, "stock"), None]
        notes = [x for x in (_rp_uom_note(d, "stock") if not one else None, _rp_norate_note(d)) if x]
        return [_rp_sec(cols, rows, tot, note=" ".join(notes) or None)]
    return _rp_blocks(P, build), ["Variance = Physical Qty - ERP Qty. Values = quantity x stock rate. Quantities of different UOMs are not added together."]


def rp_unit_stock(P):
    df = _rp_stock_df(P)
    cols = [("Budget Category", "t"), ("Items", "i"), ("Items In Stock", "i"), ("Zero / Negative Stock", "i"), ("Stock Value (Tk)", "a")]

    def build(u):
        d = df[df["factory_name"] == u]
        if d.empty:
            return []
        d = d.assign(val=(d["stock"] * d["price"]).where(d["price"] > 0, 0.0))
        rows = []
        for bc, g in d.sort_values("bcat").groupby("bcat", sort=True):
            rows.append([bc, len(g), int((g["stock"] > 0).sum()), int((g["stock"] <= 0).sum()), float(g["val"].sum())])
        tot = [f"TOTAL - {u}", len(d), int((d["stock"] > 0).sum()), int((d["stock"] <= 0).sum()), float(d["val"].sum())]
        return [_rp_sec(cols, rows, tot, note=_rp_norate_note(d))]
    return _rp_blocks(P, build), ["Each unit is reported separately; stock of different units is never added together."]


def rp_item_stock(P):
    df = _rp_stock_df(P)
    cols = [("SL", "i"), ("Item Code", "t"), ("Item Name", "t"), ("Size", "t"), ("UOM", "t"), ("Stock Qty", "q"), ("Minimum Stock", "q"),
            ("Stock Position", "t"), ("Preferred Supplier", "t"), ("Stock Rate (Tk)", "r"), ("Stock Value (Tk)", "a")]

    def build(u):
        d = df[df["factory_name"] == u].sort_values(["item_name", "size"])
        if d.empty:
            return []
        rows = []
        for n, r in enumerate(d.itertuples(), 1):
            pos = "No minimum set" if r.min_stock <= 0 else ("Below minimum" if r.stock < r.min_stock else "OK")
            hv = r.price > 0
            rows.append([n, r.code, r.item_name, r.size, r.uom, r.stock, r.min_stock if r.min_stock > 0 else None, pos, r.pref_sup,
                         r.price if hv else None, r.stock * r.price if hv else None])
        tot = [f"TOTAL - {u} ({len(d)} items)", None, None, None, None, None, None, f"{sum(1 for x in rows if x[7] == 'Below minimum')} below minimum", None, None,
               float((d["stock"] * d["price"]).where(d["price"] > 0, 0).sum())]
        return [_rp_sec(cols, rows, tot, note=_rp_norate_note(d))]
    return _rp_blocks(P, build), []


def rp_pcat_stock(P):
    df = _rp_stock_df(P)
    cols = [("Product Category", "t"), ("Items", "i"), ("Stock Quantity (by UOM)", "t"), ("Stock Value (Tk)", "a")]

    def build(u):
        d = df[df["factory_name"] == u]
        if d.empty:
            return []
        d = d.assign(val=(d["stock"] * d["price"]).where(d["price"] > 0, 0.0))
        rows = []
        for pc, g in d.sort_values("pcat").groupby("pcat", sort=True):
            rows.append([pc, len(g), "; ".join(f"{_rp_fmt(v, 'q')} {k}" for k, v in g.groupby("uom")["stock"].sum().items()), float(g["val"].sum())])
        tot = [f"TOTAL - {u}", len(d), None, float(d["val"].sum())]
        return [_rp_sec(cols, rows, tot, note=_rp_norate_note(d))]
    return _rp_blocks(P, build), []


# ---------------------------------------------------------------- transaction based reports
def _rp_tx(P, types):
    psql, pp = period_sql("t.date", P["d1"], P["d2"])
    isql, ip = _rp_inv_where(P, "i.")
    ssql, sp = ("", [])
    if P.get("sup_raw"):
        ssql, sp = " AND TRIM(COALESCE(t.supplier_name,'')) = ANY(%s)", [P["sup_raw"]]
    secsql, secp = "", []
    if P.get("section"):
        secsql, secp = " AND TRIM(COALESCE(t.section,'')) = %s", [P["section"]]
    df = qdf(f"""SELECT t.id, t.factory_name, t.date, t.time, t.trans_type, COALESCE(t.qty,0) AS qty,
                        COALESCE(NULLIF(t.prod_id,''), i.prod_id, '') AS code, COALESCE(NULLIF(t.item_name,''), i.item_name, '') AS item,
                        COALESCE(i.size,'') AS size, COALESCE(NULLIF(i.unit_name,''),'Pcs') AS uom, COALESCE(i.unit_price,0) AS price,
                        COALESCE(NULLIF(TRIM(i.category),''),'(No budget category)') AS bcat, COALESCE(t.officer_name,'') AS officer,
                        COALESCE(NULLIF(TRIM(t.supplier_name),''),'') AS supplier, COALESCE(t.challan_no,'') AS challan,
                        COALESCE(t.req_no,'') AS req_no, COALESCE(TRIM(t.section),'') AS section, t.unit_price_at_tx AS tx_rate
                 FROM transactions t LEFT JOIN inventory i ON i.sl_no=t.sl_no AND i.factory_name=t.factory_name
                 WHERE t.factory_name = ANY(%s) AND t.trans_type = ANY(%s){psql}{isql}{ssql}{secsql}
                 ORDER BY t.factory_name, {_sql_date('t.date')} NULLS LAST, t.id""", tuple([P["units"], list(types)] + pp + ip + sp + secp))
    return _rpn(df, "qty", "price", "tx_rate").assign(tx_rate=lambda x: x["tx_rate"].where(x["tx_rate"] > 0))


def _rp_rate(r, recv):
    """Receipts: the purchase rate saved with the receipt. Issues: the item's current stock rate (same as the Budget / Ledger pages)."""
    if recv:
        return None if pd.isna(r.tx_rate) else float(r.tx_rate)
    return float(r.price) if r.price > 0 else None


def rp_supplier(P):
    df = _rp_tx(P, ["Supplier. Rec"])
    cols = [("SL", "i"), ("Date", "d"), ("Challan No", "t"), ("Item Code", "t"), ("Item Name", "t"), ("Size", "t"), ("UOM", "t"),
            ("Qty", "q"), ("Rate (Tk)", "r"), ("Amount (Tk)", "a")]

    def build(u):
        d = df[df["factory_name"] == u].copy()
        if d.empty:
            return []
        d["skey"] = d["supplier"].map(_hb_norm)
        disp = d[d["skey"] != ""].groupby("skey")["supplier"].agg(lambda x: x.value_counts().index[0])
        d["sdisp"] = d["skey"].map(disp).fillna("(Supplier not recorded)")
        secs, grand, miss = [], 0.0, 0
        for sd, g in sorted(d.groupby("sdisp"), key=lambda kv: (kv[0].startswith("("), kv[0].lower())):
            rows, amt = [], 0.0
            for n, r in enumerate(g.itertuples(), 1):
                rt = _rp_rate(r, True)
                a = r.qty * rt if rt else None
                miss += 0 if rt else 1
                amt += a or 0.0
                rows.append([n, r.date, r.challan, r.code, r.item, r.size, r.uom, r.qty, rt, a])
            grand += amt
            tot = [f"Sub-total: {sd} ({len(g)} receipts)", None, None, None, None, None, None, _rp_qty_tot(g, "qty"), None, amt]
            secs.append(_rp_sec(cols, rows, tot, heading=f"SUPPLIER: {sd}", note=_rp_uom_note(g, "qty") if g["uom"].nunique() > 1 else None))
        secs.append(_rp_sec([("Summary", "t"), ("Receipts", "i"), ("Total Amount (Tk)", "a")], [[f"All suppliers - {u}", len(d), grand]],
                            note=f"{miss} receipt(s) have no purchase rate recorded; their amount is not included." if miss else None, heading="UNIT TOTAL"))
        return secs
    return _rp_blocks(P, build), []


def rp_receive(P):
    df = _rp_tx(P, P.get("ttypes") or ["Supplier. Rec", "Internal Rec"])
    cols = [("SL", "i"), ("Date", "d"), ("Txn Ref", "t"), ("Type", "t"), ("Supplier", "t"), ("Challan No", "t"), ("Item Code", "t"),
            ("Item Name", "t"), ("Size", "t"), ("UOM", "t"), ("Qty", "q"), ("Rate (Tk)", "r"), ("Amount (Tk)", "a")]

    def build(u):
        d = df[df["factory_name"] == u]
        if d.empty:
            return []
        rows, amt, miss = [], 0.0, 0
        for n, r in enumerate(d.itertuples(), 1):
            rt = _rp_rate(r, r.trans_type == "Supplier. Rec")
            a = r.qty * rt if rt else None
            miss += 0 if rt else 1
            amt += a or 0.0
            rows.append([n, r.date, f"TX-{r.id}", RP_NAMES.get(r.trans_type, r.trans_type), r.supplier, r.challan, r.code, r.item, r.size, r.uom, r.qty, rt, a])
        tot = [f"TOTAL - {u} ({len(d)} receipts)", None, None, None, None, None, None, None, None, None, _rp_qty_tot(d, "qty"), None, amt]
        note = " ".join(x for x in (_rp_uom_note(d, "qty") if d["uom"].nunique() > 1 else None,
                                    f"{miss} line(s) have no purchase rate recorded (rate is saved only with Supplier Receipts); their amount is not included." if miss else None) if x)
        return [_rp_sec(cols, rows, tot, note=note or None)]
    return _rp_blocks(P, build), []


def rp_issue(P):
    df = _rp_tx(P, P.get("ttypes") or list(ISSUE_TYPES))
    by_sec = P.get("group") == "Section"
    cols = [("SL", "i"), ("Date", "d"), ("Txn Ref", "t"), ("SR / Req No", "t"), ("Section", "t"), ("Item Code", "t"), ("Item Name", "t"), ("Size", "t"),
            ("UOM", "t"), ("Issued Qty", "q"), ("Rate (Tk)", "r"), ("Amount (Tk)", "a"), ("Issued By", "t")]

    def build(u):
        d = df[df["factory_name"] == u]
        if d.empty:
            return []
        d = d.assign(grp=d["section"].where(d["section"] != "", "(Section not set)") if by_sec else d["bcat"])
        rows, n, grand, miss = [], 0, 0.0, 0
        for bc, g in d.sort_values("grp", kind="stable").groupby("grp", sort=True):
            amt = 0.0
            for r in g.itertuples():
                n += 1
                rt = _rp_rate(r, False)
                a = r.qty * rt if rt else None
                miss += 0 if rt else 1
                amt += a or 0.0
                rows.append([n, r.date, f"TX-{r.id}", r.req_no, r.section or "-", r.code, r.item, r.size, r.uom, r.qty, rt, a, r.officer])
            grand += amt
            rows.append(_RpSub([f"Sub-total: {bc} ({len(g)} issues)", None, None, None, None, None, None, None, None, _rp_qty_tot(g, "qty"), None, amt, None]))
        tot = [f"TOTAL - {u} ({len(d)} issues)", None, None, None, None, None, None, None, None, _rp_qty_tot(d, "qty"), None, grand, None]
        note = " ".join(x for x in (_rp_uom_note(d, "qty") if d["uom"].nunique() > 1 else None,
                                    f"{miss} issue(s) have no stock rate; their amount is not included." if miss else None) if x)
        return [_rp_sec(cols, rows, tot, note=note or None)]
    return _rp_blocks(P, build), [f"Issue amount = issued quantity x the item's stock rate (same basis as the Budget page). Grouped by {'Section' if by_sec else 'Budget Category'}."]


def rp_tx_history(P):
    df = _rp_tx(P, P.get("ttypes") or list(RP_NAMES))
    cols = [("SL", "i"), ("Date", "d"), ("Time", "t"), ("Txn Ref", "t"), ("Type", "t"), ("Item Code", "t"), ("Item Name", "t"), ("UOM", "t"),
            ("Received Qty", "q"), ("Issued Qty", "q"), ("Opening / Set Qty", "q"), ("Supplier", "t"), ("Challan / SR No", "t"), ("Officer", "t")]

    def build(u):
        d = df[df["factory_name"] == u]
        if d.empty:
            return []
        rows = []
        for n, r in enumerate(d.itertuples(), 1):
            rc = r.qty if r.trans_type in RP_RECV_T else None
            isu = r.qty if r.trans_type in RP_ISSUE_T else None
            op = r.qty if r.trans_type == "Opening Balance" else None
            rows.append([n, r.date, r.time, f"TX-{r.id}", RP_NAMES.get(r.trans_type, r.trans_type), r.code, r.item, r.uom, rc, isu, op,
                         r.supplier, r.challan or r.req_no, r.officer])
        one = d["uom"].nunique() <= 1
        sm = lambda t: float(d.loc[d["trans_type"].isin(t), "qty"].sum()) if one else None
        tot = [f"TOTAL - {u} ({len(d)} transactions)", None, None, None, None, None, None, None, sm(RP_RECV_T), sm(RP_ISSUE_T), sm(("Opening Balance",)), None, None, None]
        return [_rp_sec(cols, rows, tot, note=_rp_uom_note(d, "qty") if not one else None)]
    return _rp_blocks(P, build), ["Received = Supplier / Internal Receipt and Stock Adjustment (+). Issued = Issue, Internal Issue and Stock Adjustment (-)."]


RP_RECV_T = ("Supplier. Rec", "Internal Rec", "Stock Adjustment (+)")
RP_ISSUE_T = ("Issued", "Internal Issue", "Stock Adjustment (-)")


def rp_ledger(P):
    df = _rp_tx(P, P.get("ttypes") or list(RP_NAMES))
    cols = [("Date", "d"), ("Txn Ref", "t"), ("Type", "t"), ("Supplier / SR No", "t"), ("Officer", "t"), ("Received", "q"), ("Issued", "q"), ("Value (Tk)", "a")]

    def build(u):
        d = df[df["factory_name"] == u].copy()
        if d.empty:
            return []
        d["ik"] = d["code"].astype(str) + "|" + d["item"].astype(str) + "|" + d["size"].astype(str)
        secs = []
        for _, g in sorted(d.groupby("ik", sort=False), key=lambda kv: str(kv[1].iloc[0]["item"]).lower()):
            r0 = g.iloc[0]
            rows, rc, isu, val = [], 0.0, 0.0, 0.0
            for r in g.itertuples():
                recv, iss = r.trans_type in RP_RECV_T, r.trans_type in RP_ISSUE_T
                rt = _rp_rate(r, r.trans_type == "Supplier. Rec") if (recv or iss) else None
                v = r.qty * rt if rt else None
                rc += r.qty if recv else 0.0
                isu += r.qty if iss else 0.0
                val += v or 0.0
                rows.append([r.date, f"TX-{r.id}", RP_NAMES.get(r.trans_type, r.trans_type), r.supplier or r.req_no, r.officer,
                             r.qty if recv else None, r.qty if iss else None, v])
            tot = [f"Item total ({len(g)} entries)", None, None, None, None, rc, isu, val]
            secs.append(_rp_sec(cols, rows, tot, heading=f"{r0['item']}  [{r0['size'] or '-'}]  -  Code {r0['code'] or '-'}  -  UOM {r0['uom']}"))
        return secs
    return _rp_blocks(P, build), ["Item-wise ledger of the transactions in the period. Opening Balance entries are listed without Received / Issued quantity "
                                  "because they set the stock instead of moving it."]


def rp_movement(P):
    """Opening Qty + Received + Adjustment(+) - Issued - Adjustment(-) = Closing Qty, for the chosen period.
    Closing = today's stock minus every stock-moving entry dated AFTER the period; Opening = Closing minus the period's movement."""
    d1, d2 = P["d1"], P["d2"]
    isql, ip = _rp_inv_where(P, "i.")
    dt = _sql_date("t.date")
    per = f"{dt} BETWEEN %s AND %s" if d1 else "TRUE"
    aft = f"{dt} > %s" if d1 else "FALSE"
    pp = [d1, d2] if d1 else []
    ap = [d2] if d1 else []
    IN_, OUT_ = "('Supplier. Rec','Internal Rec','Stock Adjustment (+)')", "('Issued','Internal Issue','Stock Adjustment (-)')"
    sql = f"""SELECT i.factory_name, i.sl_no, COALESCE(i.prod_id,'') AS code, COALESCE(i.item_name,'') AS item, COALESCE(i.size,'') AS size,
                     COALESCE(NULLIF(i.unit_name,''),'Pcs') AS uom, COALESCE(i.current_stock,0) AS stock,
                     COALESCE(SUM(CASE WHEN t.trans_type IN ('Supplier. Rec','Internal Rec') AND {per} THEN t.qty ELSE 0 END),0) AS recv,
                     COALESCE(SUM(CASE WHEN t.trans_type='Stock Adjustment (+)' AND {per} THEN t.qty ELSE 0 END),0) AS adj_p,
                     COALESCE(SUM(CASE WHEN t.trans_type IN ('Issued','Internal Issue') AND {per} THEN t.qty ELSE 0 END),0) AS iss,
                     COALESCE(SUM(CASE WHEN t.trans_type='Stock Adjustment (-)' AND {per} THEN t.qty ELSE 0 END),0) AS adj_m,
                     COALESCE(SUM(CASE WHEN t.trans_type IN {IN_} AND {aft} THEN t.qty
                                       WHEN t.trans_type IN {OUT_} AND {aft} THEN -t.qty ELSE 0 END),0) AS after_net
              FROM inventory i
              LEFT JOIN transactions t ON t.sl_no=i.sl_no AND t.factory_name=i.factory_name AND t.trans_type IN ('Supplier. Rec','Internal Rec','Stock Adjustment (+)','Issued','Internal Issue','Stock Adjustment (-)')
              WHERE i.factory_name = ANY(%s){isql}
              GROUP BY i.factory_name, i.sl_no, i.prod_id, i.item_name, i.size, i.unit_name, i.current_stock
              ORDER BY i.factory_name, LOWER(i.item_name), i.size"""
    params = tuple(pp * 4 + ap * 2 + [P["units"]] + ip)
    df = qdf(sql, params)
    _rpn(df, "stock", "recv", "adj_p", "iss", "adj_m", "after_net")
    if not df.empty:
        df["closing"] = df["stock"] - df["after_net"]
        df["opening"] = df["closing"] - (df["recv"] + df["adj_p"] - df["iss"] - df["adj_m"])
        df = df[(df["recv"] != 0) | (df["adj_p"] != 0) | (df["iss"] != 0) | (df["adj_m"] != 0) | (df["opening"].abs() > 1e-9) | (df["closing"].abs() > 1e-9)]
    cols = [("SL", "i"), ("Item Code", "t"), ("Item Name", "t"), ("Size", "t"), ("UOM", "t"), ("Opening Qty", "q"), ("Received", "q"),
            ("Adjustment (+)", "q"), ("Issued", "q"), ("Adjustment (-)", "q"), ("Closing Qty", "q")]

    def build(u):
        d = df[df["factory_name"] == u] if not df.empty else df
        if d.empty:
            return []
        rows = [[n, r.code, r.item, r.size, r.uom, r.opening, r.recv, r.adj_p, r.iss, r.adj_m, r.closing] for n, r in enumerate(d.itertuples(), 1)]
        one = d["uom"].nunique() <= 1
        sm = lambda c: float(d[c].sum()) if one else None
        tot = [f"TOTAL - {u} ({len(d)} items)", None, None, None, None, sm("opening"), sm("recv"), sm("adj_p"), sm("iss"), sm("adj_m"), sm("closing")]
        return [_rp_sec(cols, rows, tot, note=("Items with different UOMs are not added together, so column totals are left blank for this unit." if not one else None))]
    return _rp_blocks(P, build), ["Opening Qty + Received + Adjustment (+) - Issued - Adjustment (-) = Closing Qty. Closing Qty is the stock at the end of the period's last day; "
                                  "Opening Qty is the stock at the start of its first day.",
                                  "Items with no stock and no movement in the period are not listed. Stock-set / opening-balance entries that were made without a transaction are included in Opening Qty."]


# ---------------------------------------------------------------- hold bills (also used by the existing Hold Bill print / PDF)
def _rp_hb_enrich(d):
    d = d.copy()
    for c, f in (("qty", 0.0), ("rate", 0.0), ("total_value", 0.0), ("issued_qty", 0.0)):
        d[c] = pd.to_numeric(d[c], errors="coerce").fillna(f)
    if "days_held" not in d.columns:
        d["days_held"] = [age_days(a, b or None) for a, b in zip(d["received_date"], d["resolved_date"])]
    d["in_store_qty"] = (d["qty"] - d["issued_qty"]).clip(lower=0)
    d["physical"] = [_hb_phys(a, b) for a, b in zip(d["qty"], d["issued_qty"])]
    _hb_add_supplier_cols(d)
    return d


def _rp_hb_load(P):
    psql, pp = period_sql("h.received_date", P["d1"], P["d2"])
    st_sql = " AND COALESCE(h.status,'Open')=%s" if P.get("status") in ("Open", "Resolved") else ""
    sp = [P["status"]] if st_sql else []
    ssql, sup = ("", [])
    if P.get("sup_raw"):
        ssql, sup = " AND TRIM(COALESCE(h.supplier_name,'')) = ANY(%s)", [P["sup_raw"]]
    df = qdf(f"""SELECT h.id, h.factory_name, h.received_date, h.challan_no, h.invoice_no, h.supplier_name, h.item_name,
                        COALESCE(h.qty,0) AS qty, COALESCE(h.rate,0) AS rate, COALESCE(h.total_value,0) AS total_value,
                        COALESCE(h.problem_type,'') AS problem_type, COALESCE(h.dept_to,'') AS dept_to, COALESCE(h.remarks,'') AS remarks,
                        COALESCE(h.status,'Open') AS status, COALESCE(h.resolved_date,'') AS resolved_date,
                        COALESCE(h.erp_grn,'Pending') AS erp_grn, COALESCE(h.responsible,'') AS responsible,
                        COALESCE(x.iq,0) AS issued_qty, COALESCE(x.txt,'') AS issue_text
                 FROM hold_bills h
                 LEFT JOIN (SELECT bill_id, SUM(qty) AS iq,
                                   STRING_AGG(COALESCE(issue_date,'') || ' | SR ' || COALESCE(NULLIF(req_no,''),'-') || ' | '
                                              || COALESCE(department,'-') || ' | ' || qty::text, '; ' ORDER BY id) AS txt
                            FROM hold_bill_issues GROUP BY bill_id) x ON x.bill_id=h.id
                 WHERE h.factory_name = ANY(%s){psql}{st_sql}{ssql} ORDER BY h.factory_name, h.id""", tuple([P["units"]] + pp + sp + sup))
    return df


RP_HB_DET = [("SL", "i"), ("Bill Date", "d"), ("Challan No", "t"), ("Invoice No", "t"), ("Item Name", "t"), ("Qty", "q"), ("Rate (Tk)", "r"),
             ("Amount (Tk)", "a"), ("Issued Qty", "q"), ("In Store Qty", "q"), ("Bill Status", "t"), ("Days Held", "i"), ("Physical Stock", "t"),
             ("Problem", "t"), ("Issue details (date | SR | dept | qty)", "t"), ("Remarks", "t")]


def _rp_hb_row(n, r):
    dh = r.days_held
    return [n, r.received_date, r.challan_no, r.invoice_no, r.item_name, r.qty, r.rate if r.rate > 0 else None, r.total_value, r.issued_qty,
            r.in_store_qty, r.status, None if dh is None or pd.isna(dh) else float(dh), r.physical, r.problem_type, r.issue_text, r.remarks]


def _rp_hb_supplier_blocks(df, units):
    """Layout of the supplied Excel example: a supplier summary (Supplier | Total Item | Issued Qty | In Store Balance | Total Value |
    Oldest days | Responsible), then every supplier named in its own heading with the bill / item lines underneath and a sub-total."""
    sumcols = [("Supplier", "t"), ("Total Item", "i"), ("Issued Qty", "q"), ("In Store Balance", "q"), ("Total Value (Tk)", "a"),
               ("Oldest (Days)", "i"), ("Responsible", "t")]
    blocks = []
    for u in units:
        d = df[df["factory_name"] == u] if len(df) else df
        if d.empty:
            blocks.append({"unit": u, "sections": []})
            continue
        d = _rp_hb_enrich(d)
        order = d.groupby("supplier_key")["total_value"].sum().sort_values(ascending=False).index.tolist()
        srows = []
        for k in order:
            g = d[d["supplier_key"] == k]
            who = ", ".join(sorted({str(v).strip() for v in g["responsible"] if str(v).strip()})) or "-"
            old = g["days_num"].max()
            srows.append([g["supplier_disp"].iloc[0], len(g), float(g["issued_qty"].sum()), float(g["in_store_qty"].sum()), float(g["total_value"].sum()),
                          None if pd.isna(old) else float(old), who])
        old_all = d["days_num"].max()
        stot = [f"GRAND TOTAL - {u}", len(d), float(d["issued_qty"].sum()), float(d["in_store_qty"].sum()), float(d["total_value"].sum()),
                None if pd.isna(old_all) else float(old_all), None]
        secs = [_rp_sec(sumcols, srows, stot, heading="SUMMARY - SUPPLIER WISE",
                        note="Total Item = number of held bill lines. Issued Qty = quantity already issued in the factory. In Store Balance = Qty - Issued Qty. "
                             "Oldest = days held of the oldest bill of that supplier.")]
        for k in order:
            g = d[d["supplier_key"] == k].copy()
            g["_dt"] = _parse_dates(g["received_date"])
            g = g.sort_values(["challan_key", "_dt", "id"])
            who = ", ".join(sorted({str(v).strip() for v in g["responsible"] if str(v).strip()})) or "not assigned"
            rows = [_rp_hb_row(n, r) for n, r in enumerate(g.itertuples(), 1)]
            tot = [f"Sub-total: {g['supplier_disp'].iloc[0]}", None, None, None, None, float(g["qty"].sum()), None, float(g["total_value"].sum()),
                   float(g["issued_qty"].sum()), float(g["in_store_qty"].sum()), None, None, None, None, None, None]
            secs.append(_rp_sec(RP_HB_DET, rows, tot, heading=f"SUPPLIER: {g['supplier_disp'].iloc[0]}",
                                sub=f"{len(g)} item line(s) in {g['challan_key'].nunique()} challan/invoice(s) - Total value Tk {float(g['total_value'].sum()):,.2f} - Responsible: {who}"))
        blocks.append({"unit": u, "sections": secs})
    return blocks


def rp_hold_bill(P):
    df = _rp_hb_load(P)
    cols = [("SL", "i"), ("Bill Date", "d"), ("Supplier", "t"), ("Challan No", "t"), ("Invoice No", "t"), ("Item Name", "t"), ("Qty", "q"), ("Rate (Tk)", "r"),
            ("Amount (Tk)", "a"), ("Issued Qty", "q"), ("In Store Qty", "q"), ("Bill Status", "t"), ("Days Held", "i"), ("Physical Stock", "t"),
            ("Problem", "t"), ("Responsible", "t"), ("Remarks", "t")]

    def build(u):
        d = df[df["factory_name"] == u] if len(df) else df
        if d.empty:
            return []
        d = _rp_hb_enrich(d)
        d["_dt"] = _parse_dates(d["received_date"])
        d = d.sort_values(["_dt", "id"])
        rows = []
        for n, r in enumerate(d.itertuples(), 1):
            dh = r.days_held
            rows.append([n, r.received_date, r.supplier_name, r.challan_no, r.invoice_no, r.item_name, r.qty, r.rate if r.rate > 0 else None, r.total_value,
                         r.issued_qty, r.in_store_qty, r.status, None if dh is None or pd.isna(dh) else float(dh), r.physical, r.problem_type, r.responsible, r.remarks])
        tot = [f"TOTAL - {u} ({len(d)} lines)", None, None, None, None, None, float(d["qty"].sum()), None, float(d["total_value"].sum()),
               float(d["issued_qty"].sum()), float(d["in_store_qty"].sum()), None, None, None, None, None, None]
        return [_rp_sec(cols, rows, tot)]
    return _rp_blocks(P, build), ["Physical Stock: 'NIL - issued' means the item was already issued in the factory; 'In store' means nothing issued yet."]


def rp_hold_bill_supplier(P):
    return _rp_hb_supplier_blocks(_rp_hb_load(P), P["units"]), ["Hold bill records are shown exactly as saved in Hold Bill in Store; nothing was changed to create this report."]


def _rp_hb_doc_from_df(df, title, sub):
    """Existing Hold Bill page -> same supplier-wise A4 document (the page's own filters were already applied to df)."""
    units = [u for u in sorted(df["factory_name"].dropna().unique())] if len(df) else ["-"]
    m = re.match(r"\s*Period:\s*(.*?)\s*\|", sub or "")
    period = m.group(1) if m else "All dates"
    blocks = _rp_hb_supplier_blocks(df, units)
    return _rp_doc("HOLD BILL REPORT — SUPPLIER WISE", "Hold Bill in Store", units, period,
                   [("Selection", "as filtered on the Hold Bill page (period, status, problem, department, responsible, search)")], "L", blocks,
                   notes=[sub or ""] if sub else None)


# ---------------------------------------------------------------- budget / requisition / transfers
def rp_budget(P):
    fsql = " AND category_name=%s" if P.get("bcat") else ""
    bud = qdf(f"""SELECT factory_name, department_name, category_name, COALESCE(allocated_budget,0) AS b FROM category_budgets
                  WHERE factory_name = ANY(%s){fsql} ORDER BY factory_name, department_name, category_name""",
              tuple([P["units"]] + ([P["bcat"]] if fsql else [])))
    psql, pp = period_sql("t.date", P["d1"], P["d2"])
    cost = qdf(f"""SELECT t.factory_name, i.category, SUM(t.qty*i.unit_price) AS cost
                   FROM transactions t JOIN inventory i ON t.sl_no=i.sl_no AND t.factory_name=i.factory_name
                   WHERE t.trans_type IN ('Issued','Internal Issue') AND t.factory_name = ANY(%s){psql} GROUP BY t.factory_name, i.category""",
               tuple([P["units"]] + pp))
    cm = {(r.factory_name, r.category): float(r.cost or 0) for r in cost.itertuples()}
    cols = [("SL", "i"), ("Department", "t"), ("Budget Category", "t"), ("Budget (Tk)", "a"), ("Issued Value (Tk)", "a"), ("Remaining (Tk)", "a"),
            ("Used %", "p"), ("Status", "t")]

    def build(u):
        d = bud[bud["factory_name"] == u]
        rows, n, tb, tu = [], 0, 0.0, 0.0
        for r in d.itertuples():
            b, c = float(r.b), cm.get((u, r.category_name), 0.0)
            stt = "SAFE" if b - c >= 0 else "OVER BUDGET"
            if P.get("status") in ("SAFE", "OVER BUDGET") and stt != P["status"]:
                continue
            n += 1
            tb, tu = tb + b, tu + c
            rows.append([n, r.department_name, r.category_name, b, c, b - c, (c / b * 100) if b > 0 else (100.0 if c > 0 else 0.0), stt])
        if not rows:
            return []
        tot = [f"TOTAL - {u}", None, None, tb, tu, tb - tu, (tu / tb * 100) if tb > 0 else (100.0 if tu > 0 else 0.0), None]
        return [_rp_sec(cols, rows, tot)]
    notes = ["Issued Value = issued quantity x item stock rate, per Budget Category (same calculation as the Budget page)."]
    if P["d1"] and (P["d1"].year, P["d1"].month) != (P["d2"].year, P["d2"].month):
        notes.append("Budget amounts are monthly allocations; for a period longer than one month, Used % compares the whole period's issues with one month's budget.")
    return _rp_blocks(P, build), notes


def rp_section_budget(P):
    try:
        mc_schema()
    except Exception:
        pass
    all_dates = not P["d1"]
    d1 = P["d1"] or date(2000, 1, 1)
    d2 = P["d2"] or local_now().date()
    months = 1 if all_dates else max(1, (d2.year - d1.year) * 12 + d2.month - d1.month + 1)
    units = list(P["units"])
    used_df = _sb_used_df(units, d1, d2)
    lims = qdf_c("SELECT factory_name, section_name, monthly_limit FROM section_budget_limits WHERE factory_name = ANY(%s)", (units,))
    lim_map = {(r["factory_name"], r["section_name"]): float(r["monthly_limit"] or 0) for _, r in lims.iterrows()} if not lims.empty else {}
    used_map = {(r["factory_name"], r["section"]): float(r["used"]) for _, r in used_df.iterrows()} if not used_df.empty else {}
    cols = [("SL", "i"), ("Section", "t"), ("Monthly Limit (Tk)", "a"), ("Period Limit (Tk)", "a"), ("Issued Value (Tk)", "a"),
            ("Remaining (Tk)", "a"), ("Used %", "p"), ("Status", "t")]
    _ord = {"OVER LIMIT": 0, "WARNING": 1, "SAFE": 2, "NO LIMIT SET": 3}

    itemwise = bool(P.get("itemwise"))
    idf = _rp_tx(P, list(ISSUE_TYPES)) if itemwise else pd.DataFrame()   # item lines are read only when "Item-wise details" is ticked
    cols_it = [("SL", "i"), ("Item Code", "t"), ("Item Name", "t"), ("Size", "t"), ("UOM", "t"), ("No. of Issues", "i"),
               ("Issued Qty", "q"), ("Avg Rate (Tk)", "r"), ("Issued Value (Tk)", "a"), ("% of Section", "p")]

    def build(u):
        names = {s for (f, s) in lim_map if f == u} | {s for (f, s) in used_map if f == u}
        items = []
        for s in names:
            ml, used = lim_map.get((u, s), 0.0), used_map.get((u, s), 0.0)
            if ml <= 0 and used <= 0:
                continue
            if P.get("section") and s != P["section"]:
                continue
            pl = ml * months
            pct = (used / pl * 100) if pl > 0 else None
            stt = "NO LIMIT SET" if pct is None else ("OVER LIMIT" if pct >= SB_RED_PCT else ("WARNING" if pct >= SB_YELLOW_PCT else "SAFE"))
            if P.get("status") in _ord and stt != P["status"]:
                continue
            items.append((s or "(Section not given)", ml, pl, used, (pl - used) if pl > 0 else None, pct, stt))
        if not items:
            return []
        items.sort(key=lambda x: (_ord[x[6]], -x[3], x[0].lower()))
        rows = [[i + 1] + list(x) for i, x in enumerate(items)]
        tm, tp, tu = sum(x[1] for x in items), sum(x[2] for x in items), sum(x[3] for x in items)
        tot = [f"TOTAL - {u}", None, tm, tp, tu, (tp - tu) if tp > 0 else None, (tu / tp * 100) if tp > 0 else None, None]
        secs = [_rp_sec(cols, rows, tot, heading="SECTION-WISE BUDGET")]
        d_it = idf[idf["factory_name"] == u].copy() if (itemwise and not idf.empty) else idf
        if itemwise and not d_it.empty:
            d_it["sec_disp"] = d_it["section"].where(d_it["section"] != "", "(Section not given)")
            for x in items:                         # same order as the summary table above
                g = d_it[d_it["sec_disp"] == x[0]].copy()
                if g.empty:
                    continue
                g["eff"] = g["tx_rate"].where(g["tx_rate"] > 0, g["price"].where(g["price"] > 0))
                g["val"] = (g["qty"] * g["eff"]).fillna(0.0)
                g["pq"] = g["qty"].where(g["eff"].notna(), 0.0)
                g["no_rate"] = g["eff"].isna().astype(int)
                agg = (g.groupby(["code", "item", "size", "uom"], as_index=False)
                        .agg(n=("qty", "size"), qty=("qty", "sum"), pq=("pq", "sum"), val=("val", "sum"), miss=("no_rate", "sum"))
                        .sort_values(["val", "qty"], ascending=False, kind="stable"))
                sec_val = float(agg["val"].sum())
                irows = []
                for k, r in enumerate(agg.itertuples(), 1):
                    irows.append([k, r.code, r.item, r.size, r.uom, int(r.n), float(r.qty),
                                  (r.val / r.pq) if r.pq > 0 and r.val > 0 else None, float(r.val),
                                  (r.val / sec_val * 100) if sec_val > 0 else None])
                itot = [f"Total - {x[0]} ({len(agg)} item(s))", None, None, None, None, int(agg["n"].sum()), _rp_qty_tot(g, "qty"),
                        None, sec_val, 100.0 if sec_val > 0 else None]
                lim_txt = f"Period limit {x[2]:,.0f} Tk · {x[6]}" if x[2] > 0 else "No limit set"
                miss = int(agg["miss"].sum())
                nt = " ".join(t for t in (_rp_uom_note(g, "qty") if g["uom"].nunique() > 1 else None,
                                          f"{miss} issue line(s) have no rate; their value is not included." if miss else None) if t)
                secs.append(_rp_sec(cols_it, irows, itot, heading=f"ITEMS ISSUED - SECTION: {x[0]}",
                                    sub=f"{lim_txt} · Issued value {x[3]:,.0f} Tk", note=nt or None))
        return secs
    notes = ["Issued Value = issued quantity x item rate, per Section (same calculation as the Section Budget page).",
             ("Item-wise details are included: one table per Section shows which items were issued to it (highest value first)." if itemwise
              else "Section-wise summary only. Tick “Item-wise details” in the filters to also list the items issued to each Section."),
             f"Status: WARNING = {SB_YELLOW_PCT:g}% or more of the limit used, OVER LIMIT = {SB_RED_PCT:g}% or more."]
    if all_dates:
        notes.append("All dates selected: Used % compares all issues with ONE month's limit. Pick a From/To date for a month-wise comparison.")
    elif months > 1:
        notes.append(f"Period covers {months} calendar months, so Period Limit = Monthly Limit x {months}.")
    return _rp_blocks(P, build), notes


def rp_dept_requisition(P):
    sel = ("id, factory_name, req_no, department, req_date, item_name, req_qty, audit_approved_qty AS aud_qty, actual_received_qty AS rec_qty, "
           "po_date, received_date, COALESCE(prod_id,'') AS prod_id, COALESCE(size,'') AS size, COALESCE(uom,'') AS uom, "
           "COALESCE(sourcing_manager,'') AS sourcing_manager, COALESCE(handover_date,'') AS handover_date, "
           "COALESCE(supplier_name,'') AS supplier_name, COALESCE(order_date,'') AS order_date, COALESCE(order_note,'') AS order_note")

    def _load():
        return q_c(f"SELECT {sel} FROM requisition_tracking WHERE factory_name = ANY(%s) ORDER BY id", (list(P["units"]),))
    try:
        raw = _load()
    except psycopg2.errors.UndefinedColumn:
        ensure_req_tracker_schema()
        _bump_data_version()
        raw = _load()
    NODEP = "(Department not given)"
    d1, d2, term, stf, dsel = P["d1"], P["d2"], (P.get("item") or "").lower(), P.get("status"), P.get("dept")
    keep = []
    for r in (req_calc(dict(x)) for x in raw):
        r["_dep"] = (r["department"] or "").strip() or NODEP
        if dsel and r["_dep"] != dsel:
            continue
        if d1 and d2:
            d = parse_date(r["req_date"])
            if not d or not (d1 <= d.date() <= d2):
                continue
        if term and term not in f"{r['item_name']} {r['req_no']} {r['prod_id']} {r['size']}".lower():
            continue
        if stf == "Pending (balance > 0)" and r["pending"] <= 1e-9:
            continue
        if stf == "Fully Received" and r["calc_status"] != "Fully Received":
            continue
        if stf == "Audit not approved" and not (r["aud_qty"] <= 0 and r["rec_qty"] <= 0):
            continue
        keep.append(r)
    itemwise = bool(P.get("itemwise"))

    def pc(rec, base):
        return min(rec / base * 100.0, 100.0) if base > 0 else 0.0
    c_sum = [("SL", "i"), ("Department", "t"), ("Requisitions", "i"), ("Item Lines", "i"), ("Requested", "q"), ("Audit Approved", "q"),
             ("Received", "q"), ("Pending", "q"), ("Received %", "p")]
    c_req = [("SL", "i"), ("Req No", "t"), ("Req Date", "d"), ("Item Lines", "i"), ("Requested", "q"), ("Audit Approved", "q"),
             ("Received", "q"), ("Pending", "q"), ("Received %", "p"), ("Status", "t")]
    c_itm = [("SL", "i"), ("Req No", "t"), ("Req Date", "d"), ("Item", "t"), ("Size", "t"), ("ERP Code", "t"), ("Requested", "q"),
             ("Audit Approved", "q"), ("Received", "q"), ("Pending", "q"), ("Status", "t")]

    def build(u):
        rs = [r for r in keep if r["factory_name"] == u]
        if not rs:
            return []
        deps = {}
        for r in rs:
            deps.setdefault(r["_dep"], []).append(r)
        order = sorted(deps, key=lambda k: (-sum(x["pending"] for x in deps[k]), k.lower()))
        srows = []
        for n, dn in enumerate(order, 1):
            ls = deps[dn]
            srows.append([n, dn, len({str(x["req_no"]).strip() for x in ls}), len(ls), sum(x["req_qty"] for x in ls), sum(x["aud_qty"] for x in ls),
                          sum(x["rec_qty"] for x in ls), sum(x["pending"] for x in ls), pc(sum(x["rec_qty"] for x in ls), sum(x["base"] for x in ls))])
        stot = [f"TOTAL - {u}", None, len({(str(x["req_no"]).strip()) for x in rs}), len(rs), sum(x["req_qty"] for x in rs), sum(x["aud_qty"] for x in rs),
                sum(x["rec_qty"] for x in rs), sum(x["pending"] for x in rs), pc(sum(x["rec_qty"] for x in rs), sum(x["base"] for x in rs))]
        secs = [_rp_sec(c_sum, srows, stot, heading="DEPARTMENT-WISE SUMMARY")]
        for dn in order:
            ls = deps[dn]
            if itemwise:
                irows = [[n, x["req_no"], x["req_date"], x["item_name"], x["size"], x["prod_id"], x["req_qty"], x["aud_qty"], x["rec_qty"],
                          x["pending"], x["calc_status"]] for n, x in enumerate(sorted(ls, key=lambda z: (str(z["req_no"]), z["id"])), 1)]
                itot = [f"Total - {dn} ({len(ls)} item line(s))", None, None, None, None, None, sum(x["req_qty"] for x in ls),
                        sum(x["aud_qty"] for x in ls), sum(x["rec_qty"] for x in ls), sum(x["pending"] for x in ls), None]
                secs.append(_rp_sec(c_itm, irows, itot, heading=f"DEPARTMENT: {dn} - ITEM-WISE"))
            else:
                g = {}
                for x in ls:
                    g.setdefault(str(x["req_no"] or "").strip(), []).append(x)
                rrows = []
                for n, (rn, lg) in enumerate(sorted(g.items(), key=lambda kv: -max(z["id"] for z in kv[1])), 1):
                    dts = [parse_date(z["req_date"]) for z in lg if parse_date(z["req_date"])]
                    rec = sum(z["rec_qty"] for z in lg)
                    rrows.append([n, rn, min(dts).strftime(DATE_FMT) if dts else lg[0]["req_date"], len(lg), sum(z["req_qty"] for z in lg),
                                  sum(z["aud_qty"] for z in lg), rec, sum(z["pending"] for z in lg), pc(rec, sum(z["base"] for z in lg)), _rq_status_of(lg)])
                rtot = [f"Total - {dn} ({len(g)} requisition(s))", None, None, len(ls), sum(x["req_qty"] for x in ls), sum(x["aud_qty"] for x in ls),
                        sum(x["rec_qty"] for x in ls), sum(x["pending"] for x in ls), None, None]
                secs.append(_rp_sec(c_req, rrows, rtot, heading=f"DEPARTMENT: {dn} - REQUISITION-WISE"))
        return secs
    return _rp_blocks(P, build), ["Pending = Audit Approved qty (Requested qty if not yet approved) minus Received qty. Quantities of different items / UOMs are added only to show the overall movement.",
                                  "Dates filter the Requisition date." + ("" if itemwise else " Tick “Item-wise details” to list every item line of each department.")]


def rp_requisition(P):
    psql, pp = period_sql("req_date", P["d1"], P["d2"])
    st_sql = " AND status=%s" if P.get("status") not in (None, "All") else ""
    item_sql, ip = "", []
    if P.get("item"):
        item_sql, ip = " AND (item_name ILIKE %s OR COALESCE(prod_id,'') ILIKE %s)", [f"%{P['item']}%"] * 2
    rq = qdf(f"""SELECT factory_name, req_no, department, req_date, item_name, COALESCE(prod_id,'') AS code, COALESCE(req_qty,0) AS req_qty,
                        COALESCE(audit_approved_qty,0) AS appr, COALESCE(actual_received_qty,0) AS recv, po_date, received_date, status,
                        COALESCE(po_delay_days,0) AS delay
                 FROM requisition_tracking WHERE factory_name = ANY(%s){psql}{st_sql}{item_sql}
                 ORDER BY factory_name, {_sql_date('req_date')} NULLS LAST, req_no, id""",
             tuple([P["units"]] + pp + ([P["status"]] if st_sql else []) + ip))
    p2, pp2 = period_sql("t.date", P["d1"], P["d2"])
    i2, ip2 = _rp_inv_where({"item": P.get("item")}, "t.")
    iss = qdf(f"""SELECT t.factory_name, t.date, t.req_no, COALESCE(NULLIF(t.prod_id,''), i.prod_id, '') AS code, COALESCE(NULLIF(t.item_name,''), i.item_name, '') AS item,
                         COALESCE(NULLIF(i.unit_name,''),'Pcs') AS uom, COALESCE(t.qty,0) AS qty, COALESCE(t.officer_name,'') AS officer
                  FROM transactions t LEFT JOIN inventory i ON i.sl_no=t.sl_no AND i.factory_name=t.factory_name
                  WHERE t.factory_name = ANY(%s) AND t.trans_type = ANY(%s) AND COALESCE(t.req_no,'')<>''{p2}{i2}
                  ORDER BY t.factory_name, {_sql_date('t.date')} NULLS LAST, t.id""", tuple([P["units"], list(ISSUE_TYPES)] + pp2 + ip2))
    _rpn(rq, "req_qty", "appr", "recv", "delay")
    _rpn(iss, "qty")
    c1 = [("SL", "i"), ("Req No", "t"), ("Req Date", "d"), ("Department", "t"), ("Item Code", "t"), ("Item Name", "t"), ("Req Qty", "q"),
          ("Audit Approved", "q"), ("Received Qty", "q"), ("PO Date", "d"), ("Received Date", "d"), ("PO Delay (days)", "i"), ("Status", "t")]
    c2 = [("SL", "i"), ("Issue Date", "d"), ("SR / Req No", "t"), ("Item Code", "t"), ("Item Name", "t"), ("UOM", "t"), ("Issued Qty", "q"), ("Issued By", "t")]

    def build(u):
        secs = []
        d = rq[rq["factory_name"] == u]
        if not d.empty:
            rows = [[n, r.req_no, r.req_date, r.department, r.code, r.item_name, r.req_qty, r.appr, r.recv, r.po_date, r.received_date, r.delay, r.status]
                    for n, r in enumerate(d.itertuples(), 1)]
            secs.append(_rp_sec(c1, rows, [f"TOTAL - {u}: {len(d)} requisition line(s) in {d['req_no'].nunique()} requisition(s)"] + [None] * 12,
                                heading="REQUISITION TRACKING", note="Quantities are not added up because the lines are different items / UOMs."))
        g = iss[iss["factory_name"] == u]
        if not g.empty:
            rows = [[n, r.date, r.req_no, r.code, r.item, r.uom, r.qty, r.officer] for n, r in enumerate(g.itertuples(), 1)]
            secs.append(_rp_sec(c2, rows, [f"TOTAL - {u}: {len(g)} issue line(s) against {g['req_no'].nunique()} SR / requisition number(s)"] + [None] * 7,
                                heading="ISSUES MADE AGAINST REQUISITION / SR NUMBERS", note=_rp_uom_note(g, "qty") if g["uom"].nunique() > 1 else None))
        return secs
    return _rp_blocks(P, build), []


def rp_transfer(P):
    psql, pp = period_sql("t.transfer_date", P["d1"], P["d2"])
    st_sql = " AND t.status=%s" if P.get("status") not in (None, "All") else ""
    item_sql, ip = "", []
    if P.get("item"):
        item_sql, ip = " AND (t.item_name ILIKE %s OR COALESCE(t.prod_id,'') ILIKE %s)", [f"%{P['item']}%"] * 2
    df = qdf(f"""SELECT t.transfer_ref, t.source_factory, t.dest_factory, COALESCE(t.prod_id,'') AS code, t.item_name, COALESCE(t.size,'') AS size,
                        COALESCE(t.qty,0) AS qty, t.transfer_date, COALESCE(t.initiated_by,'') AS by, COALESCE(t.status,'') AS status, COALESCE(t.notes,'') AS notes,
                        COALESCE((SELECT NULLIF(i.unit_name,'') FROM inventory i WHERE i.prod_id=t.prod_id AND i.factory_name=t.source_factory LIMIT 1),'') AS uom
                 FROM inter_factory_transfers t
                 WHERE (t.source_factory = ANY(%s) OR t.dest_factory = ANY(%s)){psql}{st_sql}{item_sql}
                 ORDER BY {_sql_date('t.transfer_date')} NULLS LAST, t.id""", tuple([P["units"], P["units"]] + pp + ([P["status"]] if st_sql else []) + ip))
    _rpn(df, "qty")
    cols = [("SL", "i"), ("Date", "d"), ("Transfer Ref", "t"), ("Item Code", "t"), ("Item Name", "t"), ("Size", "t"), ("UOM", "t"), ("Qty", "q"),
            ("From Unit", "t"), ("To Unit", "t"), ("Initiated By", "t"), ("Status", "t"), ("Notes", "t")]

    def part(g, head, u):
        rows = [[n, r.transfer_date, r.transfer_ref, r.code, r.item_name, r.size, r.uom, r.qty, r.source_factory, r.dest_factory, r.by, r.status, r.notes]
                for n, r in enumerate(g.itertuples(), 1)]
        gg = g.assign(uom=g["uom"].replace("", "(UOM not recorded)"))
        tot = [f"TOTAL - {head} ({len(g)} transfers)", None, None, None, None, None, None, _rp_qty_tot(gg, "qty")] + [None] * 5
        return _rp_sec(cols, rows, tot, heading=head, note=_rp_uom_note(gg, "qty") if gg["uom"].nunique() > 1 else None)

    def build(u):
        secs = []
        out, inn = df[df["source_factory"] == u], df[df["dest_factory"] == u]
        if not out.empty:
            secs.append(part(out, f"TRANSFERS OUT OF {u}", u))
        if not inn.empty:
            secs.append(part(inn, f"TRANSFERS INTO {u}", u))
        return secs
    return _rp_blocks(P, build), ["A transfer between the two units appears under 'OUT' of the sending unit and under 'INTO' of the receiving unit; it is not counted twice inside one unit."]


# ---------------------------------------------------------------- registry + page
# ---------------- Reports: M/C Wise Cost Report ----------------
def rp_machine_cost(P):
    df = _mc_tx_df(P["units"], P["d1"], P["d2"])
    cols = [("SL", "i"), ("Date", "d"), ("SR / Req No", "t"), ("Item Code", "t"), ("Item Name", "t"), ("Size", "t"), ("UOM", "t"),
            ("Qty", "q"), ("Rate (Tk)", "r"), ("Amount (Tk)", "a"), ("Issued By", "t")]

    def build(u):
        if df.empty:
            return []
        d = df[df["factory_name"] == u]
        if d.empty:
            return []
        d = d.sort_values(["machine", "dt", "id"], kind="stable")
        total = float(d["amount"].sum())
        miss = int((d["rate"] <= 0).sum())
        summ = []
        for mname, g in d.groupby("machine", sort=True):
            summ.append([mname, len(g), int(g["sl_no"].nunique()), float(g["amount"].sum()),
                         f"{(float(g['amount'].sum()) / total * 100):.1f}%" if total else "-"])
        summ.sort(key=lambda x: -x[3])
        secs = [_rp_sec([("M/C", "t"), ("Issue lines", "i"), ("Different items", "i"), ("Total Cost (Tk)", "a"), ("% of cost", "t")], summ,
                        [f"TOTAL - {u} ({len(summ)} machine(s))", len(d), None, total, "100%" if total else "-"], heading="M/C WISE COST SUMMARY")]
        for mname, g in sorted(d.groupby("machine"), key=lambda kv: -float(kv[1]["amount"].sum())):
            rows = []
            for n, r in enumerate(g.itertuples(), 1):
                rows.append([n, r.date, r.req_no, r.code, r.item, r.size, r.uom, r.qty, r.rate if r.rate > 0 else None,
                             r.amount if r.rate > 0 else None, r.officer])
            tot = [f"Sub-total: {mname} ({len(g)} issues)", None, None, None, None, None, None, _rp_qty_tot(g, "qty"), None,
                   float(g["amount"].sum()), None]
            secs.append(_rp_sec(cols, rows, tot, heading=f"M/C: {mname}", note=_rp_uom_note(g, "qty") if g["uom"].nunique() > 1 else None))
        return secs
    note = ["Cost = issued quantity x the issue rate (rate saved with the issue, else the item's stock rate). Only issues tagged with an M/C No. "
            "in the Requisition Issue slip are included."]
    if not df.empty and int((df["rate"] <= 0).sum()):
        note.append(f"{int((df['rate'] <= 0).sum())} issue line(s) have no rate; their amount is not included.")
    return _rp_blocks(P, build), note


RP_STOCK_STATUS = ["All items", "In stock (quantity above zero)", "Zero or negative stock"]
def _rp_gp_pct(part, whole):
    return (float(part) / float(whole) * 100.0) if whole and float(whole) > 1e-9 else None


def _rp_gp_status(issued, balance):
    return "Fully consumed" if balance <= 1e-9 else ("Partly consumed" if issued > 1e-9 else "In store")


def rp_gate_pass(P):
    """Management report: every gate pass received, what it was worth, how much has been consumed (oldest stock first),
    what is still in the store - and WHERE it was spent (requisition / SR no., date, section). Read-only."""
    try:
        run_once_per_process("gate_pass_table", ensure_gate_pass_table)
    except Exception:
        pass
    isql, ip = _rp_inv_where(P, "i.")
    df = qdf(f"""SELECT g.id, g.factory_name, g.gate_pass_no, COALESCE(g.source_place,'') AS source_place, g.rec_date, g.sl_no,
                        COALESCE(g.prod_id,'') AS code, COALESCE(g.item_name,'') AS item, COALESCE(g.size,'') AS size,
                        COALESCE(g.qty,0) AS qty, COALESCE(g.stock_before,0) AS stock_before,
                        COALESCE(NULLIF(i.unit_name,''),'Pcs') AS uom, COALESCE(i.unit_price,0) AS price
                 FROM gate_pass_receipts g LEFT JOIN inventory i ON i.sl_no=g.sl_no AND i.factory_name=g.factory_name
                 WHERE g.factory_name = ANY(%s){isql} ORDER BY g.factory_name, g.id""", tuple([P["units"]] + ip))
    empty = (_rp_blocks(P, lambda u: []), [], [])
    if df.empty:
        return empty
    df = _rpn(df, "qty", "stock_before", "price")
    issued, alloc = _gp_compute(df.to_dict("records"))    # FIFO runs on every lot of the chosen items; filters below only choose what is shown
    df["issued"] = df["id"].map(lambda i: float(issued.get(int(i), 0.0)))
    df["basis"] = _gp_basis_col(df, issued)
    df["issued"] = df[["issued", "basis"]].min(axis=1)
    df["balance"] = (df["basis"] - df["issued"]).clip(lower=0)
    df["rv"], df["iv"], df["bv"] = df["qty"] * df["price"], df["issued"] * df["price"], df["balance"] * df["price"]
    df["dt"] = _parse_dates(df["rec_date"])
    df = period_filter_df(df, "rec_date", P["d1"], P["d2"])
    if P.get("status") == "Balance still in store":
        df = df[df["balance"] > 1e-9]
    elif P.get("status") == "Fully consumed":
        df = df[df["balance"] <= 1e-9]
    if df.empty:
        return empty
    keep = {int(i) for i in df["id"]}
    al = pd.DataFrame([a for a in alloc if int(a["lot_id"]) in keep])
    has_al = not al.empty
    if has_al:
        al = al.merge(df[["id", "factory_name", "gate_pass_no", "source_place", "code", "item", "size", "uom", "price"]],
                      left_on="lot_id", right_on="id", how="left")
        al["amt"] = al["qty"] * al["price"]
        al["dt"] = _parse_dates(al["date"])
        al["srk"] = al.apply(lambda r: str(r["req_no"]).strip() or ("(Internal Issue - no SR no.)" if r["type"] == "Internal Issue" else "(SR no. not recorded)"), axis=1)
        al["sec"] = al["section"].where(al["section"].astype(str).str.strip() != "", "(Section not recorded)")
    K = {"gp": 0, "lines": 0, "rv": 0.0, "iv": 0.0, "bv": 0.0, "sr": 0, "noprice": 0}

    def build(u):
        d = df[df["factory_name"] == u].sort_values(["dt", "id"], kind="stable")
        if d.empty:
            return []
        a = al[al["factory_name"] == u] if has_al else al
        rv, iv, bv = float(d["rv"].sum()), float(d["iv"].sum()), float(d["bv"].sum())
        n_gp = int(d["gate_pass_no"].nunique())
        n_sr = int(a.loc[~a["srk"].str.startswith("("), "srk"].nunique()) if (has_al and not a.empty) else 0
        miss = int((d["price"] <= 0).sum())
        K["gp"] += n_gp; K["lines"] += len(d); K["rv"] += rv; K["iv"] += iv; K["bv"] += bv; K["sr"] += n_sr; K["noprice"] += miss
        secs = []
        # 1. management summary
        secs.append(_rp_sec([("Particulars", "t"), ("Gate Passes", "i"), ("Item Lines", "i"), ("Received Value (Tk)", "a"), ("Consumed Value (Tk)", "a"),
                             ("Balance in Store (Tk)", "a"), ("Consumed %", "p"), ("Requisitions (SR) Served", "i")],
                            [[f"All gate passes - {u}", n_gp, len(d), rv, iv, bv, _rp_gp_pct(iv, rv), n_sr]],
                            heading="1. MANAGEMENT SUMMARY",
                            note=f"{miss} item line(s) have no unit price in inventory; their value is shown as zero." if miss else None))
        # 2. source-wise
        rows, T = [], [0, 0, 0.0, 0.0, 0.0]
        for sp, g in sorted(d.groupby("source_place"), key=lambda kv: kv[0].lower()):
            r_, i_, b_ = float(g["rv"].sum()), float(g["iv"].sum()), float(g["bv"].sum())
            rows.append([sp or "(Source not recorded)", int(g["gate_pass_no"].nunique()), len(g), r_, i_, b_, _rp_gp_pct(i_, r_)])
            T = [T[0] + rows[-1][1], T[1] + len(g), T[2] + r_, T[3] + i_, T[4] + b_]
        secs.append(_rp_sec([("Received From", "t"), ("Gate Passes", "i"), ("Item Lines", "i"), ("Received Value (Tk)", "a"), ("Consumed Value (Tk)", "a"),
                             ("Balance in Store (Tk)", "a"), ("Consumed %", "p")], rows,
                            [f"TOTAL - {u}", T[0], T[1], T[2], T[3], T[4], _rp_gp_pct(T[3], T[2])], heading="2. SOURCE-WISE SUMMARY"))
        # 3. gate pass-wise statement
        keys = ["gate_pass_no", "source_place", "rec_date"]
        rows = []
        for n, ((no, sp, rd), g) in enumerate(d.groupby(keys, sort=False), 1):
            r_, i_, b_ = float(g["rv"].sum()), float(g["iv"].sum()), float(g["bv"].sum())
            rows.append([n, rd, no, sp, len(g), r_, i_, b_, _rp_gp_pct(i_, r_), _rp_gp_status(float(g["issued"].sum()), float(g["balance"].sum()))])
        secs.append(_rp_sec([("SL", "i"), ("Received On", "d"), ("Gate Pass No", "t"), ("Received From", "t"), ("Item Lines", "i"), ("Received Value (Tk)", "a"),
                             ("Consumed Value (Tk)", "a"), ("Balance in Store (Tk)", "a"), ("Consumed %", "p"), ("Status", "t")], rows,
                            [f"TOTAL - {u} ({len(rows)} gate pass)", None, None, None, len(d), rv, iv, bv, _rp_gp_pct(iv, rv), None],
                            heading="3. GATE PASS-WISE STATEMENT"))
        # 4. item detail of every gate pass
        icols = [("SL", "i"), ("Item Code", "t"), ("Item Name", "t"), ("Size", "t"), ("UOM", "t"), ("Received", "q"), ("Consumed", "q"), ("Balance", "q"),
                 ("Rate (Tk)", "r"), ("Received (Tk)", "a"), ("Consumed (Tk)", "a"), ("Balance (Tk)", "a"), ("Status", "t")]
        for (no, sp, rd), g in d.groupby(keys, sort=False):
            rows = [[n, r.code, r.item, r.size, r.uom, r.qty, r.issued, r.balance, (r.price if r.price > 0 else None), r.rv, r.iv, r.bv,
                     _rp_gp_status(r.issued, r.balance)] for n, r in enumerate(g.itertuples(), 1)]
            tot = [f"Gate Pass total ({len(g)} item)", None, None, None, None, _rp_qty_tot(g, "qty"), _rp_qty_tot(g, "issued"), _rp_qty_tot(g, "balance"),
                   None, float(g["rv"].sum()), float(g["iv"].sum()), float(g["bv"].sum()), None]
            secs.append(_rp_sec(icols, rows, tot, heading=f"{'4. ITEM DETAIL  -  ' if no == d.iloc[0]['gate_pass_no'] and rd == d.iloc[0]['rec_date'] else ''}GATE PASS {no}  |  From: {sp or '-'}  |  Received: {_rp_fmt(rd, 'd')}"))
        # 5-7. where it was spent
        if a is None or a.empty:
            secs.append(_rp_sec([("Info", "t")], [], heading="5. WHERE IT WAS SPENT (REQUISITION / SR WISE)", empty="Nothing has been issued from these gate passes yet."))
            return secs
        a = a.sort_values(["dt", "tx_id"], kind="stable")
        rows, tq, ta = [], 0, 0.0
        for n, (sr, g) in enumerate(sorted(a.groupby("srk"), key=lambda kv: (kv[0].startswith("("), kv[1]["dt"].min(), kv[0])), 1):
            gps = ", ".join(sorted({str(x) for x in g["gate_pass_no"]}))
            secs_ = ", ".join(sorted({str(x) for x in g["sec"]}))
            rows.append([n, sr, g["date"].iloc[0], secs_, gps, int(g["tx_id"].nunique()), float(g["amt"].sum())])
            ta += float(g["amt"].sum())
        secs.append(_rp_sec([("SL", "i"), ("SR / Req No", "t"), ("Issue Date", "d"), ("Section", "t"), ("From Gate Pass", "t"), ("Issue Lines", "i"), ("Consumed Value (Tk)", "a")],
                            rows, [f"TOTAL - {u} ({len(rows)} requisition / SR)", None, None, None, None, int(a["tx_id"].nunique()), ta],
                            heading="5. WHERE IT WAS SPENT - REQUISITION (SR) WISE SUMMARY"))
        rows = []
        for sc, g in sorted(a.groupby("sec"), key=lambda kv: (kv[0].startswith("("), kv[0].lower())):
            rows.append([sc, int(g.loc[~g["srk"].str.startswith("("), "srk"].nunique()), float(g["amt"].sum()), _rp_gp_pct(float(g["amt"].sum()), ta)])
        secs.append(_rp_sec([("Section", "t"), ("Requisitions (SR)", "i"), ("Consumed Value (Tk)", "a"), ("Share of Consumption", "p")], rows,
                            [f"TOTAL - {u}", None, ta, 100.0 if ta > 0 else None], heading="6. SECTION-WISE CONSUMPTION"))
        dcols = [("Issue Date", "d"), ("Section", "t"), ("Gate Pass", "t"), ("Item Code", "t"), ("Item Name", "t"), ("Size", "t"), ("UOM", "t"),
                 ("Qty", "q"), ("Rate (Tk)", "r"), ("Amount (Tk)", "a"), ("Issued By", "t")]
        rows = []
        for sr, g in sorted(a.groupby("srk"), key=lambda kv: (kv[0].startswith("("), kv[1]["dt"].min(), kv[0])):
            rows.append(_RpSub([f"SR / Req No: {sr}  ({len(g)} line)", None, None, None, None, None, None, None, None, float(g["amt"].sum()), None]))
            for r in g.itertuples():
                rows.append([r.date, r.sec, r.gate_pass_no, r.code, r.item, r.size, r.uom, r.qty, (r.price if r.price > 0 else None), r.amt,
                             r.officer + (" (Internal Issue)" if r.type == "Internal Issue" else "")])
        secs.append(_rp_sec(dcols, rows, [f"TOTAL CONSUMED - {u}", None, None, None, None, None, None, None, None, ta, None],
                            heading="7. CONSUMPTION TRAIL - EXACTLY WHICH SR / REQUISITION TOOK WHICH GATE PASS ITEM"))
        return secs

    blocks = _rp_blocks(P, build)
    kpis = [("🚪", "Gate Passes Received", f"{K['gp']:,}", f"{K['lines']:,} item line(s)", "teal"),
            ("📥", "Received Value", _dbx_tk(K["rv"]), "Value of all gate-pass items", "blue"),
            ("📤", "Consumed Value", _dbx_tk(K["iv"]), f"{(_rp_gp_pct(K['iv'], K['rv']) or 0):.1f}% of received", "amber"),
            ("📦", "Balance in Store", _dbx_tk(K["bv"]), f"{(_rp_gp_pct(K['bv'], K['rv']) or 0):.1f}% still unused", "green"),
            ("🧾", "Requisitions (SR) Served", f"{K['sr']:,}", "Issue slips that used these items", "violet")]
    notes = ["Value = quantity x the item's current unit price in inventory.",
             "Consumed = quantity issued from gate-pass stock, counted oldest stock first (FIFO), up to the date this report is generated "
             "(issues made after the selected receiving period are included).",
             "Requisition / SR number is the Issue slip number entered when the item was issued."]
    if K["noprice"]:
        notes.append(f"{K['noprice']} item line(s) have no unit price in inventory, so their value is zero in this report.")
    return blocks, notes, kpis



RP_REPAIR_STATUS = ["All", "Pending Return", "Overdue (over 30 days)", "Returned", "Closed"]


def _rp_rr_load(P):
    df = qdf("""SELECT id, factory_name, COALESCE(tracking_code,'') AS track, COALESCE(gate_pass_no,'') AS gate, COALESCE(item_name,'') AS item,
                       COALESCE(qty,0) AS qty, COALESCE(NULLIF(TRIM(source_type),''),'Other') AS stype,
                       COALESCE(NULLIF(TRIM(return_type),''),'-') AS rtype, COALESCE(NULLIF(TRIM(supplier_name),''),'(Supplier not given)') AS supplier,
                       sent_date, return_date, COALESCE(status,'') AS status, COALESCE(approved_by,'') AS approved,
                       COALESCE(gatepass_carrier,'') AS carrier, COALESCE(officer_name,'') AS officer
                FROM repair_returns WHERE factory_name = ANY(%s) ORDER BY factory_name, id""", (list(P["units"]),))
    if df.empty:
        return df
    df = period_filter_df(df, "sent_date", P["d1"], P["d2"])
    if P.get("item") and not df.empty:
        df = df[df["item"].str.contains(P["item"], case=False, regex=False)]
    if df.empty:
        return df
    df = df.copy()
    df["qty"] = pd.to_numeric(df["qty"], errors="coerce").fillna(0.0)

    def _days(r):
        if r["status"] == "Pending Return":
            return age_days(r["sent_date"])
        return age_days(r["sent_date"], r["return_date"]) if parse_date(r["return_date"]) else None
    df["days"] = df.apply(_days, axis=1)
    df["overdue"] = (df["status"] == "Pending Return") & (pd.to_numeric(df["days"], errors="coerce").fillna(0) > _RPX_OVERDUE_DAYS)
    st_ = P.get("status")
    if st_ == "Pending Return":
        df = df[df["status"] == "Pending Return"]
    elif st_ == "Overdue (over 30 days)":
        df = df[df["overdue"]]
    elif st_ in ("Returned", "Closed"):
        df = df[df["status"] == st_]
    df["_sd"] = _parse_dates(df["sent_date"])
    return df.sort_values(["factory_name", "_sd", "id"], na_position="last")


def rp_repair_returns(P):
    df = _rp_rr_load(P)
    try:
        ir = qdf("""SELECT factory_name, item_name, COALESCE(qty,0) AS qty, COALESCE(original_qty,0) AS oq, return_date,
                           COALESCE(reason,'') AS reason, COALESCE(returned_by,'') AS who
                    FROM issue_returns WHERE factory_name = ANY(%s) ORDER BY id""", (list(P["units"]),))
        if not ir.empty:
            ir = period_filter_df(ir, "return_date", P["d1"], P["d2"])
            if P.get("item") and not ir.empty:
                ir = ir[ir["item_name"].astype(str).str.contains(P["item"], case=False, regex=False)]
    except Exception:
        ir = pd.DataFrame()
    show_ir = P.get("status") in (None, "All")
    NR = "Not recorded"

    def _alert(d):
        if d is None or pd.isna(d):
            return "-"
        d = float(d)
        return f"OVERDUE ({d:.0f} days)" if d > _RPX_OVERDUE_DAYS else (f"Follow up ({d:.0f} days)" if d >= 15 else "On time")

    def build(u):
        d = df[df["factory_name"] == u] if not df.empty else df
        secs = []
        if not d.empty:
            pend = d[d["status"] == "Pending Return"].copy()
            pend["_dd"] = pd.to_numeric(pend["days"], errors="coerce").fillna(-1)
            pend = pend.sort_values("_dd", ascending=False)
            settled = d[d["status"] != "Pending Return"]
            # 1. at a glance
            c1 = [("Purpose", "t"), ("Items Sent Out", "i"), ("Returned / Closed", "i"), ("Still Outside", "i"), ("Qty Still Outside", "q"), ("Longest Outside (days)", "i")]
            r1 = []
            for k, g in d.groupby("stype", sort=True):
                p_ = g[g["status"] == "Pending Return"]
                old = pd.to_numeric(p_["days"], errors="coerce").max() if len(p_) else None
                r1.append([k, len(g), int((g["status"] != "Pending Return").sum()), len(p_), float(p_["qty"].sum()),
                           None if old is None or pd.isna(old) else float(old)])
            oldest = pend["_dd"].max() if len(pend) else None
            t1 = [f"TOTAL - {u}", len(d), len(settled), len(pend), float(pend["qty"].sum()), None if oldest is None or oldest < 0 else float(oldest)]
            if len(pend):
                top = pend.iloc[0]
                sub1 = (f"{len(pend)} item(s) (qty {float(pend['qty'].sum()):g}) are still outside the factory. The longest is {top['item']} "
                        f"with {top['supplier']} - {int(top['_dd'])} day(s) since {top['sent_date']}." if top["_dd"] >= 0 else
                        f"{len(pend)} item(s) (qty {float(pend['qty'].sum()):g}) are still outside the factory.")
            else:
                sub1 = "No item is outside the factory - everything sent out has come back or is closed."
            secs.append(_rp_sec(c1, r1, t1, heading="1. AT A GLANCE", sub=sub1))
            # 2. items still outside
            if len(pend):
                c2 = [("SL", "i"), ("Ref / Gate Pass", "t"), ("Item", "t"), ("Purpose", "t"), ("Sent To", "t"), ("Qty", "q"),
                      ("Sent Date", "d"), ("Days Out", "i"), ("Permission Given By", "t"), ("Gate Pass Brought To Store By", "t"),
                      ("Approved By (Store Officer)", "t"), ("Status", "t")]
                r2 = []
                for n, r in enumerate(pend.itertuples(), 1):
                    ref = r.track + (f" / GP {r.gate}" if r.gate else "")
                    r2.append([n, ref, r.item, r.stype, r.supplier, r.qty, r.sent_date, None if pd.isna(r.days) else float(r.days),
                               r.approved or NR, r.carrier or NR, r.officer or NR, _alert(r.days)])
                secs.append(_rp_sec(c2, r2, [f"TOTAL STILL OUTSIDE - {u} ({len(pend)} item)", None, None, None, None, float(pend["qty"].sum()),
                                             None, None, None, None, None, f"{int(d['overdue'].sum())} overdue"],
                                    heading="2. ITEMS STILL OUTSIDE - FOLLOW UP (oldest first)",
                                    note=f"Status: On time = up to 14 days outside; Follow up = 15 to {_RPX_OVERDUE_DAYS} days; OVERDUE = more than {_RPX_OVERDUE_DAYS} days."))
                # 3. party wise
                r3 = []
                for k, g in pend.groupby("supplier", sort=False):
                    od = g["sent_date"].map(parse_date).dropna()
                    mx = g["_dd"].max()
                    r3.append([k, len(g), float(g["qty"].sum()), od.min().strftime(DATE_FMT) if len(od) else None,
                               None if mx < 0 else float(mx), int(g["overdue"].sum())])
                r3.sort(key=lambda x: (-(x[4] or 0), x[0]))
                secs.append(_rp_sec([("Supplier / Party", "t"), ("Items With Them", "i"), ("Qty", "q"), ("Oldest Sent Date", "d"), ("Longest Outside (days)", "i"),
                                     ("Overdue Items", "i")], r3,
                                    [f"TOTAL - {u}", len(pend), float(pend["qty"].sum()), None, None, int(d["overdue"].sum())],
                                    heading="3. WHO HOLDS OUR ITEMS (party-wise)"))
            # 4. already settled
            c4 = [("SL", "i"), ("Ref / Gate Pass", "t"), ("Item", "t"), ("Purpose", "t"), ("Supplier / Party", "t"), ("Qty", "q"),
                  ("Sent Date", "d"), ("Returned Date", "d"), ("Days Taken", "i"), ("Result", "t"), ("Permission Given By", "t"), ("Gate Pass Brought To Store By", "t"), ("Approved By (Store Officer)", "t")]
            r4 = [[n, r.track + (f" / GP {r.gate}" if r.gate else ""), r.item, r.stype, r.supplier, r.qty, r.sent_date, r.return_date or None,
                   None if pd.isna(r.days) else float(r.days), "Returned" if r.status == "Returned" else r.status, r.approved or NR, r.carrier or NR, r.officer or NR]
                  for n, r in enumerate(settled.itertuples(), 1)]
            secs.append(_rp_sec(c4, r4, [f"TOTAL - {u} ({len(settled)} item)", None, None, None, None, float(settled["qty"].sum()), None, None, None, None, None, None, None] if len(settled) else None,
                                heading="4. ALREADY RETURNED / CLOSED", empty="No item has come back or been closed in this period."))
        if show_ir and not ir.empty:
            x = ir[ir["factory_name"] == u]
            if not x.empty:
                c5 = [("Return Date", "d"), ("Item", "t"), ("Returned Qty", "q"), ("Original Issue Qty", "q"), ("Reason", "t"), ("Returned By", "t")]
                r5 = [[r.return_date, r.item_name, float(r.qty), float(r.oq), r.reason, r.who] for r in x.itertuples()]
                secs.append(_rp_sec(c5, r5, [f"TOTAL - {u} ({len(x)} return)", None, float(pd.to_numeric(x["qty"], errors="coerce").sum()), None, None, None],
                                    heading="5. ISSUED MATERIAL RETURNED TO STORE (came back into stock)"))
        return secs

    blocks = _rp_blocks(P, build)
    n = len(df) if not df.empty else 0
    pend = df[df["status"] == "Pending Return"] if n else df
    ir_n = int(len(ir)) if show_ir and not ir.empty else 0
    pdays = pd.to_numeric(pend["days"], errors="coerce").max() if n and len(pend) else None
    kpis = [("🛠", "Items Sent Out", f"{n:,}", f"Qty {float(df['qty'].sum()) if n else 0:,.0f}", "blue"),
            ("⏳", "Still Outside", f"{len(pend):,}", f"Qty {float(pend['qty'].sum()) if n else 0:,.0f}", "amber"),
            ("📅", "Longest Outside", "-" if pdays is None or pd.isna(pdays) else f"{int(pdays)} days", "Oldest pending item", "slate"),
            ("🚨", f"Overdue > {_RPX_OVERDUE_DAYS} days", f"{int(df['overdue'].sum()) if n else 0:,}", "Need urgent follow up", "red"),
            ("✅", "Returned / Closed", f"{int((df['status'] != 'Pending Return').sum()) if n else 0:,}", "Already settled", "green"),
            ("↩️", "Returned to Store", f"{ir_n:,}", "Issued material taken back", "teal")]
    notes = ["This report lists every item that left the factory on a Gate Pass for repair, warranty or rejected return. 'Still Outside' = not yet returned.",
             "Days Outside = Sent Date to today for pending items; Days Taken = Sent Date to Returned Date for settled items.",
             "Permission Given By = who allowed the item to go out. Gate Pass Brought To Store By = the person (e.g. from the Maintenance department) who brought the Gate Pass to the store to request approval. "
             "Approved By (Store Officer) = the store officer who recorded and approved the Gate Pass entry.",
             "Quantities are shown as entered; items with different units are not converted. The period filters on Sent Date - tick 'All dates' to see every pending item."]
    return blocks, notes, kpis


def rp_audit_stock(P):
    """AUDIT STOCK REPORT (read-only): per item  Opening Qty | Received | Issue | Internal Issue | Internal Received | Total | Closing Stock | Closing Value.
    Same stock arithmetic as the Stock Movement Report: Closing = today's stock minus every stock-moving entry dated AFTER the period;
    Opening = Closing minus the period's movement.  Total = Opening + Received + Internal Received (+/- Stock Adjustment);  Closing = Total - Issue - Internal Issue."""
    d1, d2 = P["d1"], P["d2"]
    isql, ip = _rp_inv_where(P, "i.")
    dt = _sql_date("t.date")
    per = f"{dt} BETWEEN %s AND %s" if d1 else "TRUE"
    aft = f"{dt} > %s" if d1 else "FALSE"
    pp = [d1, d2] if d1 else []
    ap = [d2] if d1 else []
    IN_, OUT_ = "('Supplier. Rec','Internal Rec','Stock Adjustment (+)')", "('Issued','Internal Issue','Stock Adjustment (-)')"
    sql = f"""SELECT i.factory_name, i.sl_no, COALESCE(i.item_name,'') AS item, COALESCE(i.size,'') AS size,
                     COALESCE(NULLIF(i.unit_name,''),'Pcs') AS uom, COALESCE(i.current_stock,0) AS stock, COALESCE(i.unit_price,0) AS price,
                     COALESCE(SUM(CASE WHEN t.trans_type='Supplier. Rec' AND {per} THEN t.qty ELSE 0 END),0) AS recv,
                     COALESCE(SUM(CASE WHEN t.trans_type='Internal Rec' AND {per} THEN t.qty ELSE 0 END),0) AS int_rec,
                     COALESCE(SUM(CASE WHEN t.trans_type='Stock Adjustment (+)' AND {per} THEN t.qty ELSE 0 END),0) AS adj_p,
                     COALESCE(SUM(CASE WHEN t.trans_type='Issued' AND {per} THEN t.qty ELSE 0 END),0) AS iss,
                     COALESCE(SUM(CASE WHEN t.trans_type='Internal Issue' AND {per} THEN t.qty ELSE 0 END),0) AS int_iss,
                     COALESCE(SUM(CASE WHEN t.trans_type='Stock Adjustment (-)' AND {per} THEN t.qty ELSE 0 END),0) AS adj_m,
                     COALESCE(SUM(CASE WHEN t.trans_type IN {IN_} AND {aft} THEN t.qty
                                       WHEN t.trans_type IN {OUT_} AND {aft} THEN -t.qty ELSE 0 END),0) AS after_net
              FROM inventory i
              LEFT JOIN transactions t ON t.sl_no=i.sl_no AND t.factory_name=i.factory_name AND t.trans_type IN ('Supplier. Rec','Internal Rec','Stock Adjustment (+)','Issued','Internal Issue','Stock Adjustment (-)')
              WHERE i.factory_name = ANY(%s){isql}
              GROUP BY i.factory_name, i.sl_no, i.item_name, i.size, i.unit_name, i.current_stock, i.unit_price
              ORDER BY i.factory_name, LOWER(i.item_name), i.size"""
    df = qdf(sql, tuple(pp * 6 + ap * 2 + [P["units"]] + ip))
    _rpn(df, "stock", "price", "recv", "int_rec", "adj_p", "iss", "int_iss", "adj_m", "after_net")
    if not df.empty:
        df["adj"] = df["adj_p"] - df["adj_m"]
        df["closing"] = df["stock"] - df["after_net"]
        df["opening"] = df["closing"] - (df["recv"] + df["int_rec"] + df["adj"] - df["iss"] - df["int_iss"])
        df["total"] = df["opening"] + df["recv"] + df["int_rec"] + df["adj"]
        df["cval"] = (df["closing"] * df["price"]).where(df["price"] > 0, 0.0)
        df = df[(df[["recv", "int_rec", "adj_p", "iss", "int_iss", "adj_m"]] != 0).any(axis=1) | (df["opening"].abs() > 1e-9) | (df["closing"].abs() > 1e-9)]
    has_adj = bool((not df.empty) and (df["adj"].abs() > 1e-9).any())
    cols = [("SL No", "i"), ("Product Name", "t"), ("Size", "t"), ("Price (Tk)", "r"), ("Opening Qty", "q"), ("Received Qty", "q"), ("Issue Qty", "q"),
            ("Internal Issue", "q"), ("Internal Received", "q")] + ([("Stock Adjust (+/-)", "q")] if has_adj else []) + \
           [("Total", "q"), ("Closing Stock", "q"), ("Closing Stock Value (Tk)", "a")]

    def build(u):
        d = df[df["factory_name"] == u] if not df.empty else df
        if d.empty:
            return []
        rows = []
        for n, r in enumerate(d.itertuples(), 1):
            hv = r.price > 0
            rows.append([n, r.item, r.size, r.price if hv else None, r.opening, r.recv, r.iss, r.int_iss, r.int_rec] + ([r.adj] if has_adj else [])
                        + [r.total, r.closing, r.cval if hv else None])
        one = d["uom"].nunique() <= 1
        sm = lambda c: float(d[c].sum()) if one else None
        tot = [f"TOTAL - {u} ({len(d)} items)", None, None, None, sm("opening"), sm("recv"), sm("iss"), sm("int_iss"), sm("int_rec")] + ([sm("adj")] if has_adj else []) \
              + [sm("total"), sm("closing"), float(d["cval"].sum())]
        notes = [x for x in ("Items with different UOMs are not added together, so quantity totals are left blank for this unit." if not one else None, _rp_norate_note(d)) if x]
        return [_rp_sec(cols, rows, tot, note=" ".join(notes) or None)]
    blocks = _rp_blocks(P, build)
    notes = ["Opening Qty = stock at the start of the first day; Closing Stock = stock at the end of the last day of the period. "
             "Received Qty = supplier receipts; Issue Qty = issued to production; Internal Issue / Internal Received = transfers to / from the other unit.",
             "Total = Opening Qty + Received Qty + Internal Received" + (" +/- Stock Adjust" if has_adj else "") + ".  Closing Stock = Total - Issue Qty - Internal Issue.  "
             "Closing Stock Value = Closing Stock x Price (the item's current stock rate).",
             "Items with no stock and no movement in the period are not listed. Stock-set / opening-balance entries made without a transaction are included in Opening Qty."]
    kpis = None
    if len(P["units"]) == 1 and not df.empty:
        n_noprice = int((df["price"] <= 0).sum())
        kpis = [("📋", "Items Listed", f"{len(df):,}", "with stock or movement", "blue"),
                ("💰", "Closing Stock Value", _dbx_tk(float(df["cval"].sum())), "Closing Stock x Price", "green"),
                ("📦", "Items In Stock", f"{int((df['closing'] > 1e-9).sum()):,}", "closing stock above zero", "teal"),
                ("⚠️", "Zero / Negative", f"{int((df['closing'] <= 1e-9).sum()):,}", "closing stock zero or below", "red"),
                ("🏷", "No Rate Recorded", f"{n_noprice:,}", "value not included", "amber")]
    return blocks, notes, kpis


