_IA_TYPE = {"Supplier. Rec": ("Receipt", "g"), "Internal Rec": ("Internal Rec", "g"), "Stock Adjustment (+)": ("Adjust +", "p"),
            "Issued": ("Issue", "r"), "Internal Issue": ("Internal Issue", "r"), "Stock Adjustment (-)": ("Adjust −", "p"),
            "Opening Balance": ("Opening", "b")}


def _ia_e(v):
    return html_lib.escape("" if v is None else str(v))


def _ia_g(x):
    return f"{float(x or 0):g}"


def _ia_table(cols, rows, height=470):
    """rows = [(row_class, [already-escaped cell html, ...])]. One line of HTML (no blank lines) so markdown keeps it as HTML."""
    head = "".join(f"<th>{_ia_e(c)}</th>" for c in cols)
    body = "".join(f'<tr class="{cls}">' + "".join(f"<td>{c}</td>" for c in cells) + "</tr>" for cls, cells in rows)
    st.markdown(f'<div class="ia-wrap" style="max-height:{int(height)}px"><table><thead><tr>{head}</tr></thead>'
                f"<tbody>{body}</tbody></table></div>", unsafe_allow_html=True)


def _ia_analyze(tx, trf, stock, size):
    """Pure calculation (no Streamlit): the opening, the rows dated BEFORE it, and a ledger check against the current stock."""
    tx = tx.copy()
    tx["qty"] = pd.to_numeric(tx["qty"], errors="coerce").fillna(0.0)
    d = _parse_dates(tx["date"]) if not tx.empty else pd.Series(dtype="datetime64[ns]")
    tx["_d"] = d
    op = tx[tx["trans_type"] == OPENING_TYPE].sort_values(["_d", "id"])
    od, open_q = (None, 0.0)
    if not op.empty and pd.notna(op.iloc[-1]["_d"]):
        od, open_q = op.iloc[-1]["_d"], float(op.iloc[-1]["qty"])
    tx["pre"] = False
    if od is not None:
        tx["pre"] = (tx["trans_type"] != OPENING_TYPE) & tx["_d"].notna() & (tx["_d"] < od)
    live = tx[(~tx["pre"]) & (tx["trans_type"] != OPENING_TYPE)]
    rec_q = float(live[live["trans_type"].isin(RECEIPT_TYPES)]["qty"].sum())
    iss_q = float(live[live["trans_type"].isin(ISSUE_TYPES + (ADJ_OUT,))]["qty"].sum())
    pre = tx[tx["pre"]]
    pre_net = float(pre[pre["trans_type"].isin(RECEIPT_TYPES)]["qty"].sum()) - float(pre[pre["trans_type"].isin(ISSUE_TYPES + (ADJ_OUT,))]["qty"].sum())
    t_in = t_out = 0.0
    if trf is not None and not trf.empty:
        trf = trf.copy()
        trf["_d"] = _parse_dates(trf["transfer_date"])
        for r in trf.to_dict("records"):
            _m = re.match(r"TRF-(\d{8})", str(r.get("transfer_ref") or ""))
            rd = pd.to_datetime(_m.group(1), format="%Y%m%d", errors="coerce") if _m else pd.NaT
            if pd.isna(rd):
                rd = r["_d"]
            if od is not None and pd.notna(rd) and rd < od:
                continue
            if r["_in"]:
                t_in += float(r["qty"] or 0)
            else:
                t_out += float(r["qty"] or 0)
    ledger = open_q + rec_q - iss_q + t_in - t_out
    return {"tx": tx, "od": od, "open_q": open_q, "rec": rec_q, "iss": iss_q, "t_in": t_in, "t_out": t_out,
            "pre_n": int(len(pre)), "pre_net": pre_net, "ledger": ledger, "diff": float(stock) - ledger}


def _ia_load_transfers(fac, pid, name, size):
    use_pid = bool(pid) and not is_blank_code(pid) and not str(pid).lower().startswith("temp-")
    cond, par = ("prod_id=%s", [pid]) if use_pid else ("LOWER(item_name)=LOWER(%s)", [name])
    try:
        t = qdf_c(f"""SELECT id, transfer_ref, source_factory, dest_factory, qty, transfer_date, transfer_time,
                      COALESCE(initiated_by,'') AS by, COALESCE(notes,'') AS notes
                      FROM inter_factory_transfers WHERE (source_factory=%s OR dest_factory=%s) AND {cond} ORDER BY id""",
                  [fac, fac] + par)
    except Exception:
        return pd.DataFrame()
    if t.empty:
        return t
    keep = []
    for n in t["notes"].astype(str):
        m = re.search(r"Size:\s*(.+?)\s*$", n)
        ts = norm_size(m.group(1)) if m and m.group(1).strip() != "-" else ""
        keep.append(not (ts and norm_size(size) and ts != norm_size(size)))
    t = t[pd.Series(keep, index=t.index)].copy()
    t["_in"] = t["dest_factory"] == fac
    return t


def _ia_pending_rows(fac, sl):
    try:
        return q_c("""SELECT sr_no, qty, COALESCE(issued_qty,0) AS issued_qty, section, slip_date, created_by, created_at
                      FROM ri_pending_issues WHERE factory_name=%s AND sl_no=%s AND status='Pending' ORDER BY id""", (fac, int(sl)))
    except Exception:
        return []


def _ia_tx_section(item, an, tx_show, gen):
    fac, sl, stock = item["factory_name"], int(item["sl_no"]), float(item["stock"])
    rows = []
    for r in tx_show.to_dict("records"):
        lab, col = _IA_TYPE.get(r["trans_type"], (r["trans_type"], "a"))
        sign = -1.0 if r["trans_type"] in ISSUE_TYPES + (ADJ_OUT,) else (1.0 if r["trans_type"] in RECEIPT_TYPES else 0.0)
        qc, qt = ("ia-q-n", _ia_g(r["qty"])) if r["trans_type"] == OPENING_TYPE else (
            ("ia-q-p", f"+{_ia_g(r['qty'])}") if sign > 0 else ("ia-q-m", f"−{_ia_g(r['qty'])}"))
        sr = f'<span class="ia-b a">SR {_ia_e(r["req_no"])}</span>' if r["req_no"] else '<span class="ia-sm">—</span>'
        extra = []
        if r["supplier"]:
            extra.append(f"Supplier: {r['supplier']}")
        if r["challan"]:
            extra.append(f"Challan: {r['challan']}")
        note = _ia_e(" · ".join(([r["notes"]] if r["notes"] else []) + extra))
        if r["pre"]:
            note = '<span class="ia-b r">⛔ Opening-er age-r tarikh</span> ' + note
        rows.append(("ia-pre" if r["pre"] else ("ia-open" if r["trans_type"] == OPENING_TYPE else ""),
                     [f"#{int(r['id'])}", _ia_e(r["date"]), f'<span class="ia-sm">{_ia_e(r["time"])}</span>',
                      f'<span class="ia-b {col}">{_ia_e(lab)}</span>', f'<span class="{qc}">{qt}</span>', sr,
                      _ia_e(r["section"]), _ia_e(r["officer"]), f'<span class="ia-sm">{_ia_e(r["verif"])}</span>', note]))
    _ia_table(["ID", "Date", "Time", "Type", "Qty", "SR No", "Section", "Officer", "Verification", "Notes"], rows, 480)

    # ---- delete wrong entries
    st.markdown("#### 🗑 ভুল এন্ট্রি মুছুন")
    st.caption("যে এন্ট্রি ভুল তা বাছুন। Delete করলে ওই এন্ট্রির stock effect উল্টে যাবে (Issue মুছলে stock বাড়বে, Receipt মুছলে কমবে)। "
               "Store Manager password আর confirm টিক লাগবে।")
    opts = {int(r["id"]): f"#{int(r['id'])} · {r['date']} · {_IA_TYPE.get(r['trans_type'], (r['trans_type'],))[0]} {_ia_g(r['qty'])}"
                          + (f" · SR {r['req_no']}" if r["req_no"] else "") + (" · ⛔ Opening-er age" if r["pre"] else "")
            for r in tx_show.to_dict("records")}
    pre_ids = [int(r["id"]) for r in tx_show.to_dict("records") if r["pre"]]
    sel = st.multiselect("মুছবেন যেগুলো", list(opts), format_func=lambda i: opts[i], key=f"ia_sel_{sl}_{gen}",
                         placeholder="এন্ট্রি বাছুন…")
    if pre_ids:
        if st.checkbox(f"⛔ Opening-er age-r {len(pre_ids)}টি এন্ট্রিই বাছুন", key=f"ia_pre_{sl}_{gen}"):
            sel = list(dict.fromkeys(list(sel) + pre_ids))
    if not sel:
        return
    byid = {int(r["id"]): r for r in tx_show.to_dict("records")}
    delta, warn = 0.0, []
    for i in sel:
        r = byid[i]
        if r["trans_type"] in RECEIPT_TYPES:
            delta -= float(r["qty"])
        elif r["trans_type"] in ISSUE_TYPES + (ADJ_OUT,):
            delta += float(r["qty"])
        elif r["trans_type"] == OPENING_TYPE:
            warn.append(f"#{i} Opening Balance: row মুছবে কিন্তু stock বদলাবে না।")
        if "Auto-transferred" in (r["notes"] or ""):
            warn.append(f"#{i}: auto-transfer জড়িত — transfer থেকে যাবে, দরকার হলে Transfer History থেকে আলাদা ঠিক করুন।")
    after = stock + delta
    st.markdown(f'<div class="ia-note {"bad" if after < -1e-9 else "info"}">নির্বাচিত <b>{len(sel)}</b>টি এন্ট্রি মুছলে stock '
                f'<b>{_ia_g(stock)} → {_ia_g(after)}</b> ({delta:+g}) হবে।' + "".join(f"<br>⚠️ {_ia_e(w)}" for w in warn) + "</div>",
                unsafe_allow_html=True)
    reason = st.text_input("কারণ (audit log-এ থাকবে)", key=f"ia_why_{sl}_{gen}", placeholder="যেমন: opening-er age-r tarikhe vul entry")
    pw_ok = mgr_check(f"ia_pw_{sl}_{gen}")
    conf = confirm_box(f"ia_cf_{sl}_{gen}", f"⚠️ আমি confirm করছি — {len(sel)}টি transaction মুছবে ও stock revert হবে।")
    if st.button("🗑 মুছুন ও stock ফেরত দিন", type="primary", key=f"ia_del_{sl}_{gen}"):
        if not pw_ok:
            st.error("Manager password ঠিক নেই।")
        elif not conf:
            st.error("Confirm টিক দিন।")
        elif after < -1e-9:
            st.error(f"মুছলে stock নেগেটিভ ({after:g}) হয়ে যাবে — কিছু মোছা হয়নি।")
        elif guard():
            ok = 0
            for i in sel:
                if delete_transaction(int(i)):
                    ok += 1
            if reason.strip():
                run("INSERT INTO audit_logs (timestamp, username, action_type, details) VALUES (%s,%s,%s,%s)",
                    (datetime.now().strftime("%Y-%m-%d %H:%M:%S"), st.session_state.get("user") or "SYSTEM", "DELETE_TRANS",
                     f"{fac}: Item Audit delete reason ({item['item_name']}, SL {sl}, transaction {', '.join('#' + str(i) for i in sel)}): {reason.strip()}"))
                get_conn().commit()
            st.session_state["ia_gen"] = gen + 1
            done(f"✅ {ok}টি transaction মুছে stock ঠিক করা হয়েছে।")


# ---- Item Audit > SR / Requisition: per-SR "Audit OK" tick (so an item that was already checked is not checked again) ----
def _ia_ok_create():
    conn = get_conn()
    try:
        with conn.cursor() as cur:
            cur.execute("""CREATE TABLE IF NOT EXISTS item_sr_audit_ok (id SERIAL PRIMARY KEY, factory_name TEXT, sl_no INTEGER, sr_no TEXT,
                           signature TEXT, ok_by TEXT, ok_at TEXT, UNIQUE (factory_name, sl_no, sr_no))""")
        conn.commit()
    except Exception:
        conn.rollback()
        raise


def _ia_ok_map(fac, sl):
    try:
        run_once_per_process("ia_sr_ok_v1", _ia_ok_create)
        return {r["sr_no"]: r for r in q("SELECT sr_no, signature, ok_by, ok_at FROM item_sr_audit_ok WHERE factory_name=%s AND sl_no=%s",
                                         (fac, int(sl)))}
    except Exception:
        return {}


def _ia_sr_sig(g):
    """Fingerprint of one SR's issue lines (transaction id + qty + date). If any of them changes later, the OK is shown as 'changed'."""
    return ",".join(f"{int(i)}:{float(qv):g}:{d}" for i, qv, d in sorted(zip(g["id"], g["qty"], g["date"].astype(str)), key=lambda x: int(x[0])))


def _ia_ok_badge(row, sig):
    if not row:
        return '<span class="ia-sm">—</span>'
    if row["signature"] == sig:
        return f'<span class="ia-b g">✅ OK</span> <span class="ia-sm">{_ia_e(row["ok_by"])} · {_ia_e(row["ok_at"])}</span>'
    return '<span class="ia-b a">🔄 Change hoyeche — abar check</span>'


@tx
def _ia_ok_save(fac, sl, name, on, off):
    me = st.session_state.get("user", "")
    now_s = local_now().strftime("%d-%b-%Y %I:%M %p")
    for sr, sig in on:
        run("""INSERT INTO item_sr_audit_ok (factory_name, sl_no, sr_no, signature, ok_by, ok_at) VALUES (%s,%s,%s,%s,%s,%s)
               ON CONFLICT (factory_name, sl_no, sr_no) DO UPDATE SET signature=EXCLUDED.signature, ok_by=EXCLUDED.ok_by, ok_at=EXCLUDED.ok_at""",
            (fac, int(sl), str(sr), sig, me, now_s))
    for sr in off:
        run("DELETE FROM item_sr_audit_ok WHERE factory_name=%s AND sl_no=%s AND sr_no=%s", (fac, int(sl), str(sr)))
    audit("ITEM_SR_AUDIT_OK", f"{fac}: Item Audit - {name} (SL {int(sl)}): SR marked OK: {', '.join(str(s) for s, _ in on) or '-'}"
                              f"; OK removed: {', '.join(str(s) for s in off) or '-'}")
    return True


def _ia_sr_section(item, an):
    tx = an["tx"]
    iss = tx[tx["trans_type"].isin(ISSUE_TYPES)].copy()
    st.markdown('<div class="ia-note info">এখানে দেখুন কোন <b>SR (Requisition) নম্বরের</b> নিচে এই item <b>Issue</b> হয়েছে। '
                'SR মানে slip অনুযায়ী production-এ দেওয়া — এটা Receipt নয়, তাই stock-এ কিছু যোগ করে না।</div>', unsafe_allow_html=True)
    if iss.empty:
        st.info("এই item-এর কোনো Issue নেই।")
    else:
        iss["sr"] = iss["req_no"].astype(str).str.strip().replace("", "—")
        ok_map = _ia_ok_map(item["factory_name"], item["sl_no"])
        sr_info = []
        rows = []
        for sr, g in sorted(iss.groupby("sr"), key=lambda kv: kv[1]["_d"].max() if kv[1]["_d"].notna().any() else pd.Timestamp.min, reverse=True):
            dts = g["_d"].dropna()
            sig = _ia_sr_sig(g)
            rng = (dts.min().strftime("%d-%b-%Y") + (" → " + dts.max().strftime("%d-%b-%Y") if dts.min() != dts.max() else "")) if len(dts) else "-"
            flag = '<span class="ia-b r">⛔ Opening-er age</span>' if bool(g["pre"].any()) else ""
            rows.append(("ia-pre" if bool(g["pre"].any()) else "",
                         [f'<span class="ia-b a">SR {_ia_e(sr)}</span>' if sr != "—" else '<span class="ia-sm">SR নেই</span>',
                          str(len(g)), f'<span class="ia-q-m">−{_ia_g(g["qty"].sum())}</span>', _ia_e(rng),
                          _ia_e(", ".join(sorted(set(g["officer"])))), _ia_e(", ".join(sorted(set(x for x in g["section"] if x)))), flag, _ia_ok_badge(ok_map.get(sr), sig),
                          _ia_e(", ".join(f"#{int(i)}" for i in g["id"]))]))
            sr_info.append((sr, sig, rng, len(g), float(g["qty"].sum())))
        _ia_table(["SR No", "Lines", "Total Issue", "Date", "Officer", "Section", "Check", "Audit OK", "Transaction IDs"], rows, 420)

        fac_, sl_ = item["factory_name"], int(item["sl_no"])
        is_ok = lambda sr_, sig_: bool(ok_map.get(sr_)) and ok_map[sr_]["signature"] == sig_
        n_ok = sum(1 for s_ in sr_info if is_ok(s_[0], s_[1]))
        n_chg = sum(1 for s_ in sr_info if ok_map.get(s_[0]) and not is_ok(s_[0], s_[1]))
        st.markdown(f"##### ✅ Audit OK — {n_ok} / {len(sr_info)} SR check kora" + (f" · 🔄 {n_chg} ti change hoyeche" if n_chg else ""))
        st.caption("SR number, date ar issue qty thik thakle **OK ✔** tick diye Save korun — porer bar ei item-e eta abar check korte hobe na. "
                   "Pore oi SR-er kono transaction (qty / date / notun entry) change hole 'Change hoyeche — abar check' dekhabe. Tick tule dile OK soriye jabe.")
        can_ok = bool(st.session_state.get("user")) and st.session_state.get("role") not in NEW_RO_ROLES
        df_ok = pd.DataFrame({"SR No": [s_[0] for s_ in sr_info], "Date": [s_[2] for s_ in sr_info], "Lines": [s_[3] for s_ in sr_info],
                              "Total Issue": [s_[4] for s_ in sr_info],
                              "Status": ["✅ OK" if is_ok(s_[0], s_[1]) else ("🔄 Change hoyeche" if ok_map.get(s_[0]) else "") for s_ in sr_info],
                              "OK ✔": [is_ok(s_[0], s_[1]) for s_ in sr_info]})
        gen_ok = st.session_state.get("ia_ok_gen", 0)
        edited = st.data_editor(df_ok, hide_index=True, use_container_width=True, height=min(80 + 36 * len(df_ok), 380),
                                key=f"ia_ok_ed_{sl_}_{gen_ok}",
                                disabled=([c for c in df_ok.columns if c != "OK ✔"] if can_ok else True),
                                column_config={"OK ✔": st.column_config.CheckboxColumn("OK ✔ (thik ache)"),
                                               "Total Issue": st.column_config.NumberColumn(format="%g")})
        new_ok = edited["OK ✔"].astype(bool).tolist()
        on = [(sr_info[i][0], sr_info[i][1]) for i in range(len(sr_info)) if new_ok[i] and not df_ok["OK ✔"].iloc[i]]
        off = [sr_info[i][0] for i in range(len(sr_info)) if not new_ok[i] and df_ok["OK ✔"].iloc[i]]
        b1, b2 = st.columns([2, 1])
        if b1.button(f"💾 Save OK ({len(on)} OK, {len(off)} OK soranor)", key=f"ia_ok_save_{sl_}", type="primary",
                     disabled=(not can_ok or not (on or off)), use_container_width=True) and guard():
            if _ia_ok_save(fac_, sl_, str(item["item_name"]), on, off):
                st.session_state["ia_ok_gen"] = gen_ok + 1
                done(f"✅ Audit OK save hoyeche: {len(on)} SR OK" + (f", {len(off)} OK soranor" if off else "") + ".")
        all_on = [(s_[0], s_[1]) for s_ in sr_info if not is_ok(s_[0], s_[1])]
        if b2.button(f"☑ Baki {len(all_on)} SR-i OK", key=f"ia_ok_all_{sl_}", disabled=(not can_ok or not all_on),
                     use_container_width=True) and guard():
            if _ia_ok_save(fac_, sl_, str(item["item_name"]), all_on, []):
                st.session_state["ia_ok_gen"] = gen_ok + 1
                done(f"✅ Audit OK save hoyeche: {len(all_on)} SR OK.")
    pend = _ia_pending_rows(item["factory_name"], item["sl_no"])
    if pend:
        st.markdown("##### ⏳ Pending SR (stock ছিল না — এখনও issue হয়নি)")
        _ia_table(["SR No", "Pending Qty", "Slip Date", "Section", "Entry by"],
                  [("", [f'<span class="ia-b a">SR {_ia_e(p["sr_no"])}</span>', _ia_g(float(p["qty"] or 0) - float(p["issued_qty"] or 0)),
                         _ia_e(p["slip_date"]), _ia_e(p["section"]), _ia_e(p["created_by"])]) for p in pend], 260)


def _ia_transfer_section(item, trf):
    st.markdown('<div class="ia-note info">Issue-এর সময় stock কম থাকলে অন্য unit থেকে <b>auto-transfer</b> হয় — এতে Receipt ছাড়াই '
                'এই unit-এর stock বাড়ে। তাই “Receipt করিনি অথচ stock এল” হলে এখানে দেখুন।</div>', unsafe_allow_html=True)
    if trf is None or trf.empty:
        st.success("এই item-এর কোনো inter-unit transfer নেই।")
        return
    rows = []
    for r in trf.sort_values("id", ascending=False).to_dict("records"):
        inn = bool(r["_in"])
        rows.append(("", [_ia_e(r["transfer_date"]), f'<span class="ia-sm">{_ia_e(r["transfer_time"])}</span>',
                          f'<span class="ia-b {"g" if inn else "r"}">{"⬅ IN from " + _ia_e(short_fac(r["source_factory"])) if inn else "➡ OUT to " + _ia_e(short_fac(r["dest_factory"]))}</span>',
                          f'<span class="{"ia-q-p" if inn else "ia-q-m"}">{"+" if inn else "−"}{_ia_g(r["qty"])}</span>',
                          _ia_e(r["by"]), f'<span class="ia-sm">{_ia_e(r["transfer_ref"])}</span>', _ia_e(r["notes"])]))
    _ia_table(["Date", "Time", "Direction", "Qty", "By", "Ref", "Notes"], rows, 380)


def _ia_audit_section(item, tx_ids):
    fac, sl, name, pid = item["factory_name"], int(item["sl_no"]), str(item["item_name"]), str(item["prod_id"] or "").strip()
    use_pid = bool(pid) and not is_blank_code(pid) and not pid.lower().startswith("temp-")
    params = [f"%{name}%", f"%SL {sl}%"] + ([f"%{pid}%"] if use_pid else [])
    cond = "details ILIKE %s OR details ILIKE %s" + (" OR details ILIKE %s" if use_pid else "")
    arows = q_c(f"SELECT id, timestamp, username, action_type, details FROM audit_logs WHERE {cond} OR action_type IN %s ORDER BY id DESC LIMIT 3000",
                params + [_LS_TX_ACTIONS])
    adf = _ls_audit_frame(arows)
    if adf.empty:
        st.info("Audit log-এ কিছু নেই।")
        return
    sl_re, id_re = re.compile(rf"\bsl {sl}\b"), re.compile(r"(?:transaction(?: id)?|record|receipt|issue #)\s*(\d+)")
    keep = []
    for d_ in adf["details"].astype(str):
        t_ = d_.lower()
        same_fac = fac.lower() in t_
        ok = same_fac and (name.lower() in t_ or (use_pid and pid.lower() in t_) or bool(sl_re.search(t_)))
        if not ok and same_fac:
            ok = any(int(m) in tx_ids for m in id_re.findall(t_))
        keep.append(ok)
    adf = adf[pd.Series(keep, index=adf.index)].sort_values("when", ascending=False).head(300)
    st.caption("শুধু এই unit-এর লগ দেখানো হচ্ছে (অন্য unit-এর একই নামের item-এর লগ বাদ)।")
    if adf.empty:
        st.info("এই item-এর audit লগ পাওয়া যায়নি।")
        return
    wt = _ls_when_text(adf["when"], adf["timestamp"])
    rows = [("", [f'<span class="ia-sm">{_ia_e(w)}</span>', _ia_e(r["username"]),
                  f'<span class="ia-b {"r" if r["action_type"] in LS_RISKY else "t"}">{_ia_e(LS_ACTIONS.get(r["action_type"], r["action_type"]))}</span>',
                  _ia_e(r["details"])]) for w, r in zip(wt, adf.to_dict("records"))]
    _ia_table(["When", "Who", "Action", "Details"], rows, 460)


def _ia_scan_compute(fac):
    """Ledger check for EVERY item of one unit: Opening + Receipt - Issue +/- Transfer (from the latest Opening) vs current stock."""
    inv = qdf("SELECT sl_no, COALESCE(prod_id,'') AS prod_id, COALESCE(item_name,'') AS item_name, COALESCE(size,'') AS size, "
              "COALESCE(current_stock,0) AS stock FROM inventory WHERE factory_name=%s", (fac,))
    tx = qdf("SELECT id, sl_no, date, trans_type, qty FROM transactions WHERE factory_name=%s", (fac,))
    meta = {"checked": 0, "pre_rows": 0, "multi_open": 0, "unmatched_trf": 0}
    if inv.empty or tx.empty:
        return pd.DataFrame(), meta
    tx["qty"] = pd.to_numeric(tx["qty"], errors="coerce").fillna(0.0)
    tx["_d"] = _parse_dates(tx["date"])
    op = tx[tx["trans_type"] == OPENING_TYPE].sort_values(["_d", "id"])
    n_open = op.groupby("sl_no").size()
    last = op.dropna(subset=["_d"]).drop_duplicates("sl_no", keep="last").set_index("sl_no")[["_d", "qty"]]
    last = last.rename(columns={"_d": "od", "qty": "oq"})
    if last.empty:
        return pd.DataFrame(), meta
    non = tx[tx["trans_type"] != OPENING_TYPE].join(last, on="sl_no")
    non = non[non["od"].notna()].copy()
    non["pre"] = non["_d"].notna() & (non["_d"] < non["od"])
    non["eff"] = non["qty"] * non["trans_type"].map(lambda t: 1.0 if t in RECEIPT_TYPES else (-1.0 if t in ISSUE_TYPES + (ADJ_OUT,) else 0.0))
    live_net = non[~non["pre"]].groupby("sl_no")["eff"].sum()
    pre_n = non[non["pre"]].groupby("sl_no").size()
    odmap = last["od"].to_dict()
    by_pid = {}
    for r in inv.to_dict("records"):
        by_pid.setdefault(str(r["prod_id"]).strip(), []).append(r)
    t_net = {}
    try:
        trf = qdf("SELECT transfer_ref, source_factory, dest_factory, prod_id, qty, transfer_date, COALESCE(notes,'') AS notes "
                  "FROM inter_factory_transfers WHERE source_factory=%s OR dest_factory=%s", (fac, fac))
    except Exception:
        trf = pd.DataFrame()
    for r in (trf.to_dict("records") if not trf.empty else []):
        cands = by_pid.get(str(r["prod_id"]).strip(), [])
        m = re.search(r"Size:\s*(.+?)\s*$", r["notes"])
        ts = norm_size(m.group(1)) if m and m.group(1).strip() != "-" else ""
        if ts:
            cands = [c for c in cands if norm_size(c["size"]) == ts] or [c for c in cands if not norm_size(c["size"])]
        if len(cands) != 1:
            meta["unmatched_trf"] += 1
            continue
        sl = int(cands[0]["sl_no"])
        od = odmap.get(sl)
        if od is None:
            continue
        _m = re.match(r"TRF-(\d{8})", str(r.get("transfer_ref") or ""))
        rd = pd.to_datetime(_m.group(1), format="%Y%m%d", errors="coerce") if _m else pd.NaT
        if pd.isna(rd):
            rd = _parse_dates(pd.Series([r["transfer_date"]])).iloc[0]
        if pd.notna(rd) and rd < od:
            continue
        t_net[sl] = t_net.get(sl, 0.0) + (float(r["qty"] or 0) if r["dest_factory"] == fac else -float(r["qty"] or 0))
    rows = []
    invd = inv.set_index("sl_no")
    for sl, o in last.iterrows():
        if sl not in invd.index:
            continue
        it = invd.loc[sl]
        ledger = float(o["oq"]) + float(live_net.get(sl, 0.0)) + float(t_net.get(sl, 0.0))
        diff = float(it["stock"]) - ledger
        rows.append({"sl": int(sl), "item": it["item_name"], "size": it["size"], "code": it["prod_id"], "od": o["od"], "oq": float(o["oq"]),
                     "stock": float(it["stock"]), "ledger": ledger, "diff": diff, "pre": int(pre_n.get(sl, 0)), "nopen": int(n_open.get(sl, 1))})
    df = pd.DataFrame(rows)
    meta["checked"] = len(df)
    meta["pre_rows"] = int(pre_n.sum()) if len(pre_n) else 0
    meta["multi_open"] = int((df["nopen"] > 1).sum()) if not df.empty else 0
    bad = df[(df["diff"].abs() > 1e-6) | (df["pre"] > 0)].copy() if not df.empty else df
    if not bad.empty:
        bad["_a"] = bad["diff"].abs()
        bad = bad.sort_values(["_a", "pre"], ascending=False).drop(columns="_a")
    return bad, meta


def _ia_scan():
    st.markdown('<div class="ia-note info">এই unit-এর <b>সব item</b> একবারে মেলানো হয়: Opening + Receipt − Issue ± Transfer = stock? '
                'যেগুলো মেলে না বা Opening-er age-r tarikh-er entry আছে সেগুলো নিচে আসবে। কোনো কিছু বদলায় না — শুধু দেখায়।</div>', unsafe_allow_html=True)
    if is_cons_view:
        st.warning("ওপর থেকে একটি Factory বাছুন (CONSOLIDATED-এ scan হয় না)।")
        return
    fac = FAC
    if st.button("🧮 Scan চালান", type="primary", key="ia_scan_go"):
        st.session_state["ia_scan_res"] = (fac, _ia_scan_compute(fac), local_now().strftime("%d-%b-%Y %I:%M %p"))
    res = st.session_state.get("ia_scan_res")
    if not res or res[0] != fac:
        st.info("Scan চালাতে ওপরের বোতাম চাপুন।")
        return
    bad, meta = res[1]
    st.caption(f"Scan করা হয়েছে: {res[2]}")
    st.markdown('<div class="ia-kpis">'
                f'<div class="ia-k t"><div class="l">Opening আছে এমন item</div><div class="v">{meta["checked"]:,}</div></div>'
                f'<div class="ia-k {"a" if len(bad) else "g"}"><div class="l">হিসাব মেলেনি / সমস্যা</div><div class="v">{len(bad):,}</div></div>'
                f'<div class="ia-k r"><div class="l">Opening-er age-r entry</div><div class="v">{meta["pre_rows"]:,}</div></div>'
                f'<div class="ia-k x"><div class="l">একাধিক Opening-ওয়ালা item</div><div class="v">{meta["multi_open"]:,}</div></div></div>', unsafe_allow_html=True)
    if meta["unmatched_trf"]:
        st.caption(f"{meta['unmatched_trf']}টি transfer কোন item-এর তা নিশ্চিত মেলানো যায়নি — ওগুলো হিসাবে ধরা হয়নি।")
    if bad.empty:
        st.success("✅ সব item-এর হিসাব মিলছে।")
        return
    rows = []
    for r in bad.head(400).to_dict("records"):
        dcol = "ia-q-m" if r["diff"] < 0 else "ia-q-p"
        rows.append(("ia-pre" if r["pre"] else "", [
            _ia_e(r["item"]), _ia_e(r["size"] or "-"), _ia_e(r["code"] or "-"), str(r["sl"]),
            f'{_ia_g(r["oq"])} <span class="ia-sm">@ {_ia_e(r["od"].strftime("%d-%b-%Y"))}</span>',
            _ia_g(r["stock"]), _ia_g(r["ledger"]),
            (f'<span class="{dcol}">{r["diff"]:+g}</span>' if abs(r["diff"]) > 1e-6 else '<span class="ia-sm">মিলেছে</span>'),
            (f'<span class="ia-b r">⛔ {r["pre"]}</span>' if r["pre"] else ""), str(r["nopen"])]))
    _ia_table(["Item", "Size", "ERP", "SL", "Opening", "Stock", "Ledger", "পার্থক্য", "Opening-er age", "#Opening"], rows, 520)
    exp = pd.DataFrame({"SL": bad["sl"], "Item": bad["item"], "Size": bad["size"], "ERP": bad["code"], "Opening Date": bad["od"].dt.strftime("%d-%b-%Y"),
                        "Opening Qty": bad["oq"], "Stock": bad["stock"], "Ledger": bad["ledger"], "Diff": bad["diff"],
                        "Pre-opening rows": bad["pre"], "Openings": bad["nopen"]})
    export_buttons(exp, "item_audit_scan")
    st.caption("কোনো item খুলে দেখতে: ওপরের “🔎 একটি Item” ট্যাবে SL নম্বর লিখুন।")


def _ia_fix_panel(item, an, diff_ok, gen):
    fac, sl, stock = item["factory_name"], int(item["sl_no"]), float(item["stock"])
    with st.expander("⚖️ Stock সংশোধন — physical গুনে সঠিক সংখ্যা বসান", expanded=not diff_ok):
        st.caption("আগে shelf-এ গুনে নিন। এখানে সংখ্যা বসালে stock সেই সংখ্যা হবে এবং একটি Stock Adjustment transaction লেখা থাকবে "
                   "(কে, কখন, কেন) — কোনো পুরোনো এন্ট্রি মোছে না, তাই report-এর history ঠিক থাকে।")
        want = st.number_input("Physical stock (গুনে পাওয়া)", min_value=0.0, value=float(max(an["ledger"], 0.0)), step=1.0,
                               key=f"ia_fix_q_{sl}_{gen}", help="ডিফল্টে ledger-এর হিসাব বসানো আছে — গুনে মিলিয়ে নিন।")
        reason = st.text_input("কারণ (বাধ্যতামূলক)", key=f"ia_fix_r_{sl}_{gen}", placeholder="যেমন: duplicate opening / back-dated SR-এর কারণে stock ভুল ছিল")
        st.markdown(f'<div class="ia-note info">Software stock <b>{_ia_g(stock)}</b> → <b>{_ia_g(want)}</b> ({want - stock:+g})</div>', unsafe_allow_html=True)
        pw_ok = mgr_check(f"ia_fix_pw_{sl}_{gen}")
        conf = confirm_box(f"ia_fix_cf_{sl}_{gen}", "⚠️ আমি shelf-এ গুনে দেখেছি — এই সংখ্যাই সঠিক।")
        if st.button("✅ Stock ঠিক করুন", type="primary", key=f"ia_fix_go_{sl}_{gen}"):
            if not reason.strip():
                st.error("কারণ লিখুন।")
            elif not pw_ok:
                st.error("Manager password ঠিক নেই।")
            elif not conf:
                st.error("Confirm টিক দিন।")
            elif abs(want - stock) < 1e-9:
                st.warning("Stock আগে থেকেই এই সংখ্যা।")
            elif guard() and pc_adjust_to_count(fac, sl, float(want), "ItemAudit", reason.strip()):
                st.session_state["ia_gen"] = gen + 1
                done(f"✅ Stock {_ia_g(stock)} → {_ia_g(want)} করা হয়েছে (Stock Adjustment হিসেবে লেখা আছে)।")


# ============================================================
#  ITEM AUDIT - PACK -> PCS SETUP (NEW, ADDITIVE ONLY; lives inside Item Audit, nothing else in the app was changed)
#  Example: Sheet Protector File was received as 1 Pkt (challan = 1 Pkt) but is issued in Pcs. Set "1 Pkt = 100 Pcs" here and
#  this ONE item is converted to Pcs: stock, ERP stock, minimum stock, every old Receipt / Issue / Opening qty (x100) and the rate (/100).
#  The old Pkt quantity stays visible in each row's notes ("[Pack x100: 1->100]") so it still matches the challan. After that every
#  normal Issue page accepts Pcs (10 Pcs, 25 Pcs ...) and the stock reaches 0 when the last Pcs of the packet is issued.
#  Every change is logged in item_pack_conversions + audit log and can be reverted (only while no newer transaction exists).
# ============================================================
_IA_PACK_MARK = " [Pack ×"


def _ia_pack_schema():
    if st.session_state.get("_ia_pack_ready"):
        return
    conn = get_conn()
    try:
        with conn.cursor() as cur:
            cur.execute("""CREATE TABLE IF NOT EXISTS item_pack_conversions (
                id SERIAL PRIMARY KEY, factory_name TEXT, sl_no INTEGER, prod_id TEXT, item_name TEXT, size TEXT,
                pack_name TEXT, old_unit TEXT, new_unit TEXT, factor DOUBLE PRECISION, old_price DOUBLE PRECISION,
                status TEXT DEFAULT 'Active', reason TEXT, converted_by TEXT, converted_at TEXT, reverted_by TEXT, reverted_at TEXT)""")
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    st.session_state["_ia_pack_ready"] = True


def _ia_has_table(name):
    return bool(run("SELECT to_regclass(%s) IS NOT NULL", (name,))[0][0])


@tx
def ia_pack_convert(fac, sl, pack_name, factor, new_unit, reason):
    f = float(factor)
    if f <= 1:
        st.error("Pack size 1-er cheye boro hote hobe.")
        return False
    inv = q("""SELECT prod_id, item_name, COALESCE(size,'') AS size, COALESCE(unit_name,'') AS unit, COALESCE(unit_price,0) AS price,
               COALESCE(current_stock,0) AS stock FROM inventory WHERE sl_no=%s AND factory_name=%s FOR UPDATE""", (sl, fac))
    if not inv:
        st.error("Inventory item paoa jay nai.")
        return False
    inv = inv[0]
    if q("SELECT 1 AS x FROM item_pack_conversions WHERE factory_name=%s AND sl_no=%s AND status='Active'", (fac, sl)):
        st.error("এই item-এ আগে থেকেই Pack setup করা আছে।")
        return False
    if not _ia_load_transfers(fac, inv["prod_id"], inv["item_name"], inv["size"]).empty:
        st.error("এই item-এর Inter-factory transfer আছে — দুই factory-র unit আলাদা হয়ে যাবে, তাই এখানে convert করা যাবে না।")
        return False
    new_unit = _pk_ensure_uom(new_unit)
    r6 = lambda x: round(float(x), 6)
    run("""UPDATE inventory SET current_stock=COALESCE(current_stock,0)*%s, erp_stock=COALESCE(erp_stock,0)*%s,
           min_stock=COALESCE(min_stock,0)*%s, moq=COALESCE(moq,0)*%s, unit_price=COALESCE(unit_price,0)/%s, unit_name=%s
           WHERE sl_no=%s AND factory_name=%s""", (f, f, f, f, f, new_unit, sl, fac))
    n_tx = 0
    for r in q("SELECT id, qty, notes, unit_price_at_tx FROM transactions WHERE factory_name=%s AND sl_no=%s ORDER BY id FOR UPDATE", (fac, sl)):
        oq = float(r["qty"] or 0)
        nq = r6(oq * f)
        note = ((r["notes"] or "") + f"{_IA_PACK_MARK}{f:g}: {oq:g}→{nq:g}]").strip()
        up = r["unit_price_at_tx"]
        run("UPDATE transactions SET qty=%s, notes=%s, unit_price_at_tx=%s WHERE id=%s",
            (nq, note, None if up is None else r6(float(up) / f), r["id"]))
        n_tx += 1
    run("UPDATE issue_returns SET qty=COALESCE(qty,0)*%s, original_qty=COALESCE(original_qty,0)*%s WHERE factory_name=%s AND sl_no=%s", (f, f, fac, sl))
    if _ia_has_table("ri_pending_issues"):
        run("""UPDATE ri_pending_issues SET qty=COALESCE(qty,0)*%s, issued_qty=COALESCE(issued_qty,0)*%s, rate=COALESCE(rate,0)/%s, unit=%s
               WHERE factory_name=%s AND sl_no=%s""", (f, f, f, new_unit, fac, sl))
    if _ia_has_table("gate_pass_receipts"):
        run("UPDATE gate_pass_receipts SET qty=COALESCE(qty,0)*%s, stock_before=COALESCE(stock_before,0)*%s WHERE factory_name=%s AND sl_no=%s", (f, f, fac, sl))
    run("""INSERT INTO item_pack_conversions (factory_name, sl_no, prod_id, item_name, size, pack_name, old_unit, new_unit, factor, old_price,
           status, reason, converted_by, converted_at) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,'Active',%s,%s,%s)""",
        (fac, sl, inv["prod_id"], inv["item_name"], inv["size"], pack_name, inv["unit"], new_unit, f, float(inv["price"]),
         reason, st.session_state.get("user") or "SYSTEM", _now_s()))
    audit("PACK_CONVERT", f"{fac}: {inv['prod_id']} ({inv['item_name']}) SL {sl}: 1 {pack_name} = {f:g} {new_unit}; stock {float(inv['stock']):g} -> "
                          f"{float(inv['stock']) * f:g}; {n_tx} transaction row(s) converted; rate {float(inv['price']):g} -> {float(inv['price']) / f:g}. Reason: {reason}")
    return True


@tx
def ia_pack_revert(cid, fac, sl):
    c = q("SELECT * FROM item_pack_conversions WHERE id=%s AND status='Active' FOR UPDATE", (cid,))
    if not c:
        st.error("Active Pack setup paoa jay nai.")
        return False
    c = c[0]
    f = float(c["factor"])
    txr = q("SELECT id, qty, notes, unit_price_at_tx FROM transactions WHERE factory_name=%s AND sl_no=%s ORDER BY id FOR UPDATE", (fac, sl))
    late = [int(r["id"]) for r in txr if _IA_PACK_MARK not in (r["notes"] or "")]
    if late:
        st.error(f"Pack setup-er পরে {len(late)}টি নতুন transaction হয়েছে ({', '.join('#' + str(i) for i in late[:8])}) — "
                 "সেগুলো Pcs-এ লেখা, তাই Pkt-এ ফেরানো যাবে না।")
        return False
    if _ia_has_table("ri_pending_issues") and q("SELECT 1 AS x FROM ri_pending_issues WHERE factory_name=%s AND sl_no=%s AND created_at>%s LIMIT 1",
                                                 (fac, sl, c["converted_at"] or "")):
        st.error("Pack setup-er পরে এই item-এ নতুন pending issue লেখা হয়েছে — Pkt-এ ফেরানো যাবে না।")
        return False
    r6 = lambda x: round(float(x), 6)
    run("""UPDATE inventory SET current_stock=COALESCE(current_stock,0)/%s, erp_stock=COALESCE(erp_stock,0)/%s, min_stock=COALESCE(min_stock,0)/%s,
           moq=COALESCE(moq,0)/%s, unit_price=%s, unit_name=%s WHERE sl_no=%s AND factory_name=%s""",
        (f, f, f, f, float(c["old_price"] or 0), c["old_unit"] or "Pcs", sl, fac))
    for r in txr:
        note = re.sub(r"\s*\[Pack ×[0-9.eE+-]+: [^\]]*\]", "", r["notes"] or "")
        up = r["unit_price_at_tx"]
        run("UPDATE transactions SET qty=%s, notes=%s, unit_price_at_tx=%s WHERE id=%s",
            (r6(float(r["qty"] or 0) / f), note, None if up is None else r6(float(up) * f), r["id"]))
    run("UPDATE issue_returns SET qty=COALESCE(qty,0)/%s, original_qty=COALESCE(original_qty,0)/%s WHERE factory_name=%s AND sl_no=%s", (f, f, fac, sl))
    if _ia_has_table("ri_pending_issues"):
        run("""UPDATE ri_pending_issues SET qty=COALESCE(qty,0)/%s, issued_qty=COALESCE(issued_qty,0)/%s, rate=COALESCE(rate,0)*%s, unit=%s
               WHERE factory_name=%s AND sl_no=%s""", (f, f, f, c["old_unit"] or "Pcs", fac, sl))
    if _ia_has_table("gate_pass_receipts"):
        run("UPDATE gate_pass_receipts SET qty=COALESCE(qty,0)/%s, stock_before=COALESCE(stock_before,0)/%s WHERE factory_name=%s AND sl_no=%s", (f, f, fac, sl))
    run("UPDATE item_pack_conversions SET status='Reverted', reverted_by=%s, reverted_at=%s WHERE id=%s",
        (st.session_state.get("user") or "SYSTEM", _now_s(), cid))
    audit("PACK_REVERT", f"{fac}: {c['prod_id']} ({c['item_name']}) SL {sl}: Pack setup (1 {c['pack_name']} = {f:g} {c['new_unit']}) reverted to {c['old_unit']}")
    return True


# ============================================================
#  ITEM AUDIT - UNIT LABEL CHANGE (NEW, ADDITIVE). The item's Unit label is wrong (e.g. YDS) while every Receipt / Issue / Opening qty was
#  really entered in another unit (e.g. KG). Only the label changes - no qty is multiplied or divided - in this unit and, optionally,
#  in the matching item of the other unit. Optionally the stock can be set right afterwards (recorded as a Stock Adjustment).
# ============================================================
@tx
def ia_unit_relabel(rows, new_unit, reason):
    """rows = [(factory, sl_no)]. Label only: inventory.unit_name (+ the unit text of still-pending SR lines)."""
    new_unit = _pk_ensure_uom(new_unit)
    has_pend = _ia_has_table("ri_pending_issues")
    for f_, s_ in rows:
        old = q("SELECT COALESCE(unit_name,'') AS u, item_name, prod_id FROM inventory WHERE factory_name=%s AND sl_no=%s FOR UPDATE", (f_, int(s_)))
        if not old:
            continue
        old = old[0]
        run("UPDATE inventory SET unit_name=%s WHERE factory_name=%s AND sl_no=%s", (new_unit, f_, int(s_)))
        if has_pend:
            run("UPDATE ri_pending_issues SET unit=%s WHERE factory_name=%s AND sl_no=%s", (new_unit, f_, int(s_)))
        audit("ITEM_UNIT_RELABEL", f"{f_}: {old['prod_id']} ({old['item_name']}) SL {int(s_)}: Unit {old['u'] or '-'} -> {new_unit} "
                                   f"(label only, no qty changed). Reason: {reason}")
    return True


def _ia_unit_panel(item, an, trf, gen):
    fac, sl = item["factory_name"], int(item["sl_no"])
    stock, unit = float(item["stock"]), item["unit"]
    with st.expander(f"🔤 Unit change (label only) — {unit} → KG, duita unit-e", expanded=False):
        st.caption("Jodi ei item-er sob Receipt / Issue / Opening qty already onno unit-e (jemon KG) likha thake, kintu item-er **Unit label** bhul (jemon YDS) thake, "
                   "ekhane label ta thik korun. **Kono qty gun / bhag hoy na** — shudhu Unit-er nam bodlay (ager SR slip-er qty jemon ache temon thakbe). "
                   "Qty-ke ek unit theke onno unit-e convert korte hole 'Pack → Pcs setup' bebohar korun.")
        ulist = list(get_uoms())
        nunit = st.selectbox("Notun Unit", ulist, index=ulist.index("Kg") if "Kg" in ulist else 0, key=f"ia_un_u_{sl}_{gen}")
        ofac = other_factory(fac)
        other = None
        try:
            other = find_same_in_other(item["prod_id"], item["item_name"], ofac, item["size"])
        except Exception:
            other = None
        both = False
        if other:
            ounit = _unit_of(ofac, other["sl_no"])
            both = st.checkbox(f"🏭 {short_fac(ofac)}-er matching item-eo Unit '{nunit}' korun — {other['item_name']} [{other['size'] or '-'}] · {other['prod_id']} "
                               f"· ekhon unit {ounit} · stock {float(other['stock'] or 0):g} (stock qty bodlabe na)", value=True, key=f"ia_un_b_{sl}_{gen}")
        else:
            st.caption(f"{short_fac(ofac)}-e matching item paoa jayni — shudhu ei unit-er item-er Unit bodlabe.")
        st.markdown(f'<div class="ia-note info">Ei unit: Unit <b>{_ia_e(unit)}</b> → <b>{_ia_e(nunit)}</b> · stock {_ia_g(stock)} (label chhara kichu bodlabe na)'
                    + (f' · {_ia_e(short_fac(ofac))}: Unit <b>{_ia_e(_unit_of(ofac, other["sl_no"]))}</b> → <b>{_ia_e(nunit)}</b>' if both else "") + '</div>',
                    unsafe_allow_html=True)
        base_q = max(float(an["open_q"]) + float(an["rec"]) - float(an["iss"]), 0.0)
        setq = st.checkbox(f"⚖️ Ei unit-er stock-o ekhon {nunit}-te set korun (Stock Adjustment hishebe lekha thakbe — ager entry mochha hobe na)", key=f"ia_un_s_{sl}_{gen}")
        want = stock
        if setq:
            st.caption(f"Transaction hishab: Opening {_ia_g(an['open_q'])} + Receipt {_ia_g(an['rec'])} − Issue {_ia_g(an['iss'])} = {_ia_g(base_q)} · "
                       f"Transfer IN {_ia_g(an['t_in'])} / OUT {_ia_g(an['t_out'])} (Transfers tab-e dekhun). Shelf-e ja pawa jay seta likhun.")
            want = st.number_input(f"Physical stock ({nunit})", min_value=0.0, value=float(base_q), step=0.1, format="%g", key=f"ia_un_q_{sl}_{gen}")
        reason = st.text_input("Karon (badhyotamulok)", key=f"ia_un_r_{sl}_{gen}", placeholder="jemon: item KG-te receive / issue hoy, label bhul YDS chhilo")
        pw_ok = mgr_check(f"ia_un_pw_{sl}_{gen}")
        conf = confirm_box(f"ia_un_cf_{sl}_{gen}", f"⚠️ Ami nishchit — ei item-er ager sob qty already {nunit} hishabei lekha (convert korar dorkar nei).")
        if st.button("🔤 Unit change korun", type="primary", key=f"ia_un_go_{sl}_{gen}"):
            if str(nunit).strip().lower() == str(unit).strip().lower() and not both and not (setq and abs(want - stock) > 1e-9):
                st.warning("Unit ager-i ei; kichu bodlanor nei.")
            elif not reason.strip():
                st.error("Karon likhun.")
            elif not pw_ok:
                st.error("Manager password thik nei.")
            elif not conf:
                st.error("Confirm tick din.")
            elif guard():
                rows_ = [(fac, sl)] + ([(ofac, int(other["sl_no"]))] if both and other else [])
                if ia_unit_relabel(rows_, nunit, reason.strip()):
                    msg = f"✅ Unit {unit} → {nunit} hoyeche" + (f" ({short_fac(fac)} + {short_fac(ofac)})" if len(rows_) > 1 else "") + "; kono qty bodlayni."
                    if setq and abs(want - stock) > 1e-9:
                        if pc_adjust_to_count(fac, sl, float(want), "ItemAudit", f"Unit change to {nunit}: {reason.strip()}"):
                            msg += f" Stock {_ia_g(stock)} → {_ia_g(want)} {nunit} (Stock Adjustment)."
                    st.session_state["ia_gen"] = gen + 1
                    done(msg)


def _ia_pack_panel(item, an, trf, gen):
    fac, sl = item["factory_name"], int(item["sl_no"])
    stock, unit = float(item["stock"]), item["unit"]
    try:
        _ia_pack_schema()
        act = q("SELECT * FROM item_pack_conversions WHERE factory_name=%s AND sl_no=%s AND status='Active' ORDER BY id DESC LIMIT 1", (fac, sl))
    except Exception as e:
        st.error(f"Pack setup load hoyni: {e}")
        return
    act = act[0] if act else None
    with st.expander("📦 Pack → Pcs setup — Pkt-এ receive, Pcs-এ issue", expanded=False):
        if act:
            f = float(act["factor"])
            st.markdown(f'<div class="ia-note ok">✅ Pack setup চালু: <b>1 {_ia_e(act["pack_name"])} = {f:g} {_ia_e(act["new_unit"])}</b>. '
                        f'এখনকার stock <b>{_ia_g(stock)} {_ia_e(unit)}</b> = {stock / f:,.2f} {_ia_e(act["pack_name"])}. '
                        f'পুরোনো Receipt/Issue-র Notes-এ <i>[Pack ×{f:g}: আগের→এখনকার]</i> লেখা আছে, তাই challan-এর {_ia_e(act["pack_name"])} qty-র সাথে মিলিয়ে দেখা যাবে। '
                        f'এখন যেকোনো Issue page-এ Pcs দিন — stock Pcs-এ কমবে, শেষ Pcs issue হলে 0 হবে।</div>', unsafe_allow_html=True)
            st.caption(f"Setup করেছেন: {act['converted_by']} · {act['converted_at']} · কারণ: {act['reason'] or '-'}")
            pw_ok = mgr_check(f"ia_pk_rpw_{sl}_{gen}")
            conf = confirm_box(f"ia_pk_rcf_{sl}_{gen}", "⚠️ আমি Pack setup বাতিল করে আবার আগের unit-এ ফিরতে চাই।")
            if st.button("↩️ Pack setup বাতিল করুন", key=f"ia_pk_rev_{sl}_{gen}"):
                if not pw_ok:
                    st.error("Manager password ঠিক নেই।")
                elif not conf:
                    st.error("Confirm টিক দিন।")
                elif guard() and ia_pack_revert(int(act["id"]), fac, sl):
                    st.session_state["ia_gen"] = gen + 1
                    done("✅ Pack setup বাতিল হয়েছে — আগের unit ও qty ফিরে এসেছে।")
            return
        st.caption("একটা item যদি Packet-এ receive হয় (challan: 1 Pkt) কিন্তু issue হয় Pcs-এ, এখানে 1 Pkt = কত Pcs বলে দিন। শুধু এই একটি item Pcs-এ convert হবে: "
                   "stock, ERP stock, Minimum stock ও আগের সব Receipt/Issue/Opening qty × pack size, আর rate ÷ pack size (মোট টাকার মূল্য একই থাকে)। "
                   "অন্য কোনো item বা page বদলায় না।")
        c1, c2, c3 = st.columns(3)
        pname = c1.text_input("Pack-এর নাম", value="Pkt", key=f"ia_pk_n_{sl}_{gen}", max_chars=20).strip() or "Pkt"
        size = c2.number_input(f"1 {pname} = কত?", min_value=2, value=100, step=1, key=f"ia_pk_s_{sl}_{gen}")
        ulist = list(get_uoms())
        ulist += [x for x in ("Yds",) if x.upper() not in {u.upper() for u in ulist}]
        nunit = c3.selectbox("নতুন Unit", ulist, index=ulist.index("Pcs") if "Pcs" in ulist else 0, key=f"ia_pk_u_{sl}_{gen}")
        f = float(size)
        n_tx = int(len(an["tx"]))
        st.markdown(f'<div class="ia-note info">Stock <b>{_ia_g(stock)} {_ia_e(unit)}</b> → <b>{_ia_g(stock * f)} {_ia_e(nunit)}</b> · '
                    f'ERP {_ia_g(item["erp"])} → {_ia_g(float(item["erp"]) * f)} · rate ৳{float(item["price"]):,.2f} → ৳{float(item["price"]) / f:,.4f} per {_ia_e(nunit)} · '
                    f'{n_tx}টি transaction-এর qty ×{f:g} হবে।</div>', unsafe_allow_html=True)
        if trf is not None and not trf.empty:
            st.markdown('<div class="ia-note bad">⛔ এই item-এর Inter-factory transfer আছে — দুই factory-র unit মিলবে না, তাই এখানে convert করা যাবে না।</div>', unsafe_allow_html=True)
            return
        reason = st.text_input("কারণ (বাধ্যতামূলক)", key=f"ia_pk_r_{sl}_{gen}", placeholder=f"যেমন: challan-এ 1 {pname} = {int(f)} Pcs, issue হয় Pcs-এ")
        pw_ok = mgr_check(f"ia_pk_pw_{sl}_{gen}")
        conf = confirm_box(f"ia_pk_cf_{sl}_{gen}", f"⚠️ আমি নিশ্চিত — এই item-এর আগের সব Receipt/Issue/Opening qty {pname} হিসেবেই লেখা ছিল (Pcs হিসেবে নয়)।")
        if st.button("📦 Pack setup করুন", type="primary", key=f"ia_pk_go_{sl}_{gen}"):
            if not reason.strip():
                st.error("কারণ লিখুন।")
            elif not pw_ok:
                st.error("Manager password ঠিক নেই।")
            elif not conf:
                st.error("Confirm টিক দিন।")
            elif guard() and ia_pack_convert(fac, sl, pname, f, nunit, reason.strip()):
                st.session_state["ia_gen"] = gen + 1
                done(f"✅ Pack setup হয়েছে: 1 {pname} = {f:g} {nunit}। এখন Pcs-এ issue করতে পারবেন।")


# ============================================================
#  RECEIVE-TIME PACK PROMPT (NEW, ADDITIVE): when an item whose unit is Pkt / Box / Carton / Roll ... is received, the receipt form asks
#  "is it physically issued in Pcs (Roll: in Yds)?". If yes, the store officer gives the conversion (1 Pkt = 100 Pcs, or the total Yds
#  of the Rolls) and the stock goes in as Pcs / Yds. The first time, the item is converted (same routine as Item Audit > Pack setup);
#  afterwards the saved setup pre-fills the factor. Notes keep "[Pack ×100: 1→100]" so the challan quantity can still be matched, and the
#  requisition's Received qty still gets the ORIGINAL pack count.
# ============================================================
_PK_UNITS = {"pkt", "packet", "pack", "box", "carton", "ctn", "roll", "bundle"}


def _pk_is_pack(unit):
    return str(unit or "").strip().lower() in _PK_UNITS


def _pk_target(unit):
    return "Yds" if str(unit or "").strip().lower() == "roll" else "Pcs"


def _pk_ensure_uom(name):
    name = (name or "").strip() or "Pcs"
    for u in get_uoms():
        if u.upper() == name.upper():
            return u
    run("""INSERT INTO uom_master (uom_name) SELECT %s
           WHERE NOT EXISTS (SELECT 1 FROM uom_master WHERE UPPER(TRIM(uom_name))=UPPER(%s))""", (name, name))
    return name


def _pk_states(fac, sls):
    """{sl_no: {unit, stock, n_tx, conv}} for the given items in ONE query. conv = the Active pack setup or None."""
    sls = sorted({int(x) for x in sls})
    if not sls:
        return {}
    try:
        _ia_pack_schema()
        rows = q("""SELECT i.sl_no, COALESCE(NULLIF(i.unit_name,''),'Pcs') AS unit, COALESCE(i.current_stock,0) AS stock,
                    c.factor, c.pack_name, c.new_unit,
                    (SELECT COUNT(*) FROM transactions t WHERE t.factory_name=i.factory_name AND t.sl_no=i.sl_no) AS n_tx
                    FROM inventory i LEFT JOIN item_pack_conversions c
                      ON c.factory_name=i.factory_name AND c.sl_no=i.sl_no AND c.status='Active'
                    WHERE i.factory_name=%s AND i.sl_no = ANY(%s)""", (fac, sls))
    except Exception:
        return {}
    return {int(r["sl_no"]): {"unit": r["unit"], "stock": float(r["stock"] or 0), "n_tx": int(r["n_tx"] or 0),
                              "conv": ({"factor": float(r["factor"]), "pack_name": r["pack_name"], "new_unit": r["new_unit"]}
                                       if r["factor"] else None)} for r in rows}


def _pk_ui(k, sti, qty):
    """Renders the pack question under a receipt line. Returns (pack, bad): pack = dict for the save step (or None = receive as typed),
    bad = True while the officer still has to decide / fill something (the Save button must stay blocked)."""
    if not sti:
        return None, False
    unit, conv = sti["unit"], sti["conv"]
    if conv is None and not _pk_is_pack(unit):
        return None, False
    pk = conv["pack_name"] if conv else unit
    tgt = conv["new_unit"] if conv else _pk_target(unit)
    is_roll = pk.strip().lower() == "roll" or tgt.strip().lower() in ("yds", "yd", "yard", "yards")
    with st.container(border=True):
        if conv:
            st.markdown(f"📦 **Pack setup আছে:** 1 {html_lib.escape(str(pk))} = {conv['factor']:g} {html_lib.escape(str(tgt))} — stock {html_lib.escape(str(tgt))}-এ জমা হয়।")
            opts = [f"{pk} দিচ্ছি → {tgt}-এ জমা হবে", f"আমি নিজেই {tgt}-এ qty দিচ্ছি"]
            pick = st.selectbox("Stock কীভাবে বাড়বে?", opts, key=k + "_ch")
            convert = opts.index(pick) == 0
        else:
            st.warning(f"📦 এই item-এর unit **{unit}**। Physically কি **{tgt}**-এ issue হয়?")
            opts = ["— বাছুন —", f"✅ হ্যাঁ — {tgt}-এ issue হয় (convert করব)", f"❌ না — {unit}-ই থাকুক"]
            pick = st.selectbox("Issue-র unit", opts, key=k + "_ch")
            if opts.index(pick) == 0:
                return None, True
            convert = opts.index(pick) == 1
        if not convert:
            return None, False
        c1, c2 = st.columns(2)
        f = c1.number_input(f"1 {pk} = কত {tgt}?", min_value=0.0, step=1.0, format="%g",
                            value=float(conv["factor"]) if conv else 0.0, key=k + "_f")
        alt = False
        if is_roll:
            alt = c2.checkbox(f"Roll-এর দৈর্ঘ্য আলাদা — মোট {tgt} নিজে দেব", key=k + "_alt")
        total = float(qty) * float(f)
        if alt:
            total = float(c2.number_input(f"মোট {tgt} (এই receipt-এ)", min_value=0.0, step=1.0, format="%g", key=k + "_t"))
        first = conv is None
        if (first and f <= 1) or (not first and not alt and f <= 0) or (alt and total <= 0):
            st.error(f"1 {pk} = কত {tgt} সেটা দিন।" if not alt or (first and f <= 1) else f"মোট {tgt} দিন।")
            return None, True
        st.caption(f"{qty:g} {pk} → **{total:g} {tgt}** জমা হবে" + (f" · আগের stock {sti['stock']:g} {unit} → {sti['stock'] * f:g} {tgt}" if first and sti["stock"] else ""))
        if first and (sti["n_tx"] or sti["stock"]):
            if not st.checkbox(f"⚠️ নিশ্চিত — এই item-এর আগের সব Receipt/Issue/Opening qty আর stock {pk} হিসেবেই ছিল; সব ×{f:g} হয়ে {tgt}-এ যাবে।", key=k + "_cf"):
                return None, True
        return {"factor": float(f), "pack_name": pk, "tgt": tgt, "total": float(total), "orig_qty": float(qty), "first": first}, False


def _pk_apply(fac, sl, qty, rate, notes, pack):
    """Runs INSIDE the caller's transaction. Converts the item the first time, then returns (qty in Pcs/Yds, rate per Pcs/Yds, notes)."""
    if pack["first"]:
        ok = ia_pack_convert.__wrapped__(fac, int(sl), pack["pack_name"], float(pack["factor"]), pack["tgt"],
                                         f"Receive-er somoy Pack setup: 1 {pack['pack_name']} = {pack['factor']:g} {pack['tgt']}")
        if not ok:
            raise ValueError("Pack setup hoyni — receipt save kora hoyni.")
    qty, total = float(qty), round(float(pack["total"]), 6)
    new_rate = (float(rate) * qty / total) if rate else rate
    note = ((notes or "") + f"{_IA_PACK_MARK}{total / qty:g}: {qty:g}→{total:g}]").strip()
    return total, new_rate, note


def tab_item_audit():
    st.markdown(_IA_CSS, unsafe_allow_html=True)
    st.title("🔬 Item Audit")
    st.caption("একটা item খুঁজুন — stock কোথা থেকে এল, কোন SR-এ কত Issue হলো, কে কী করেছে সব এক জায়গায়। ভুল এন্ট্রি এখান থেকেই মুছতে পারবেন।")
    if lazy_tab_select(["🔎 একটি Item", "🧮 সব Item scan"], "lz_ia_top") == 1:
        _ia_scan()
        return
    term = st.text_input("🔍 Item খুঁজুন (নাম / ERP code / serial / size / SL)", key="ia_search", placeholder="যেমন: Soap Mini").strip()
    if not term:
        st.info("ওপরের বক্সে item-এর নাম, ERP code বা SL লিখুন।")
        return
    fsql, fp = fw(FAC)
    pat = f"%{term.lower()}%"
    sl_clause, sl_par = ("", [])
    if term.isdigit():
        sl_clause, sl_par = " OR sl_no=%s", [int(term)]
    items = q_c(f"""SELECT factory_name, sl_no, COALESCE(prod_id,'') AS prod_id, COALESCE(item_name,'') AS item_name,
                    COALESCE(size,'') AS size, COALESCE(serial_no,'') AS serial_no, COALESCE(current_stock,0) AS stock,
                    COALESCE(erp_stock,0) AS erp, COALESCE(unit_price,0) AS price, COALESCE(NULLIF(unit_name,''),'Pcs') AS unit
                    FROM inventory WHERE (LOWER(item_name) LIKE %s OR LOWER(COALESCE(prod_id,'')) LIKE %s
                          OR LOWER(COALESCE(serial_no,'')) LIKE %s OR LOWER(COALESCE(size,'')) LIKE %s{sl_clause}){fsql}
                    ORDER BY item_name, size LIMIT 80""", [pat, pat, pat, pat] + sl_par + fp)
    if not items:
        st.warning("এই নামে কোনো item পাওয়া যায়নি।")
        return
    labels = {f"{r['item_name']} [{r['size'] or '-'}]{_uom_tag(r)} · {r['prod_id'] or '-'} · {short_fac(r['factory_name'])} · SL {r['sl_no']}": r for r in items}
    pick = st.selectbox(f"{len(items)}টি item পাওয়া গেছে — একটি বাছুন", list(labels), key="ia_pick")
    item = labels[pick]
    fac, sl = item["factory_name"], int(item["sl_no"])
    gen = st.session_state.get("ia_gen", 0)

    tx = qdf_c("""SELECT id, date, time, trans_type, qty, COALESCE(officer_name,'') AS officer, COALESCE(req_no,'') AS req_no,
                  COALESCE(section,'') AS section, COALESCE(notes,'') AS notes, COALESCE(verification_status,'') AS verif,
                  COALESCE(supplier_name,'') AS supplier, COALESCE(challan_no,'') AS challan
                  FROM transactions WHERE factory_name=%s AND sl_no=%s ORDER BY id""", (fac, sl))
    trf = _ia_load_transfers(fac, item["prod_id"], item["item_name"], item["size"])
    an = _ia_analyze(tx, trf, item["stock"], item["size"])
    txa = an["tx"]
    stock, unit = float(item["stock"]), item["unit"]

    od_txt = an["od"].strftime("%d-%b-%Y") if an["od"] is not None else "নেই"
    st.markdown(f'<div class="ia-hero"><div class="t">{_ia_e(item["item_name"])}</div>'
                f'<div class="s">{_ia_e(fac)} · SL {sl}</div>'
                f'<span class="ia-chip">ERP {_ia_e(item["prod_id"] or "-")}</span><span class="ia-chip">Size {_ia_e(item["size"] or "-")}</span>'
                f'<span class="ia-chip">Serial {_ia_e(item["serial_no"] or "-")}</span><span class="ia-chip">Unit {_ia_e(unit)}</span>'
                f'<span class="ia-chip">৳ {float(item["price"]):,.2f}</span><span class="ia-chip">Opening: {_ia_e(od_txt)}</span></div>',
                unsafe_allow_html=True)

    diff_ok = abs(an["diff"]) < 1e-6
    chk_cls = "g" if diff_ok else "a"
    chk_txt = "✅ মিলেছে" if diff_ok else "⚠️ " + format(an["diff"], "+g")
    st.markdown('<div class="ia-kpis">'
                f'<div class="ia-k t"><div class="l">এখনকার স্টক</div><div class="v">{_ia_g(stock)}</div><div class="d">ERP: {_ia_g(item["erp"])} {_ia_e(unit)}</div></div>'
                f'<div class="ia-k b"><div class="l">Opening</div><div class="v">{_ia_g(an["open_q"])}</div><div class="d">{_ia_e(od_txt)}</div></div>'
                f'<div class="ia-k g"><div class="l">Receipt</div><div class="v">+{_ia_g(an["rec"])}</div><div class="d">Opening-er por</div></div>'
                f'<div class="ia-k r"><div class="l">Issue / Out</div><div class="v">−{_ia_g(an["iss"])}</div><div class="d">Opening-er por</div></div>'
                f'<div class="ia-k x"><div class="l">Transfer (net)</div><div class="v">{an["t_in"] - an["t_out"]:+g}</div><div class="d">IN {_ia_g(an["t_in"])} · OUT {_ia_g(an["t_out"])}</div></div>'
                f'<div class="ia-k {chk_cls}"><div class="l">Ledger check</div><div class="v">{chk_txt}</div>'
                f'<div class="d">হিসাব: {_ia_g(an["ledger"])}</div></div></div>', unsafe_allow_html=True)

    if an["pre_n"]:
        eff = -an["pre_net"]
        st.markdown(f'<div class="ia-note bad"><b>⛔ {an["pre_n"]}টি এন্ট্রি Opening Balance ({_ia_e(od_txt)})-এর <u>আগের</u> তারিখে</b> বসানো আছে '
                    f'(নিট {an["pre_net"]:+g}). Opening বসার <i>পরে</i> এগুলো save হওয়ায় stock থেকে {_ia_g(abs(eff))} কেটে/যোগ হয়ে গেছে। '
                    f'নিচের Transactions ট্যাবে লাল সারিগুলো দেখে ভুল হলে মুছে দিন — stock নিজে থেকে ঠিক হয়ে যাবে।</div>', unsafe_allow_html=True)
    if not diff_ok:
        st.markdown(f'<div class="ia-note bad">Ledger হিসাব (Opening {_ia_g(an["open_q"])} + Receipt − Issue ± Transfer = {_ia_g(an["ledger"])}) '
                    f'আর এখনকার stock {_ia_g(stock)}-এর মধ্যে পার্থক্য <b>{an["diff"]:+g}</b>। '
                    'Opening-er age-r entry, manual stock edit বা Physical Count দিয়ে stock বদলালে এমন হয়।</div>', unsafe_allow_html=True)
    else:
        st.markdown('<div class="ia-note ok">✅ Opening + Receipt − Issue ± Transfer = এখনকার stock — হিসাব মিলছে।</div>', unsafe_allow_html=True)

    _ia_fix_panel(item, an, diff_ok, gen)
    _ia_pack_panel(item, an, trf, gen)
    _ia_unit_panel(item, an, trf, gen)
    sec = lazy_tab_select(["🧾 Transactions", "📑 SR / Requisition", "🔁 Transfers", "🕵️ Audit trail"], "lz_ia")
    if sec == 0:
        if txa.empty:
            st.info("এই item-এর কোনো transaction নেই।")
        else:
            show = txa.sort_values(["_d", "id"], ascending=[False, False], na_position="last")
            _ia_tx_section(item, an, show, gen)
            exp = pd.DataFrame({"ID": show["id"], "Date": show["date"], "Time": show["time"], "Type": show["trans_type"], "Qty": show["qty"],
                                "SR No": show["req_no"], "Section": show["section"], "Officer": show["officer"], "Notes": show["notes"]})
            export_buttons(exp, f"item_audit_{sl}")
    elif sec == 1:
        _ia_sr_section(item, an)
    elif sec == 2:
        _ia_transfer_section(item, trf)
    else:
        _ia_audit_section(item, set(int(i) for i in txa["id"]) if not txa.empty else set())



